--@@ 45 funcao conv_private.admin_alert_data(p_profile uuid)
CREATE OR REPLACE FUNCTION conv_private.admin_alert_data(p_profile uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_prev_claims text; v_prev_sub text; v_err text; v_out jsonb; v_prefs jsonb;
  v_today date := (now() at time zone 'America/Fortaleza')::date; v_days int;
begin
  if not exists (select 1 from conv_private.admin_alert_targets() t where t.profile_id = p_profile) then
    return conv_private.vfail('NOT_A_RECIPIENT', 'Esse administrador não recebe alertas.');
  end if;
  v_prefs := conv_private.admin_prefs_json(p_profile);
  v_days := (v_prefs->>'overdue_days')::int;
  v_prev_claims := current_setting('request.jwt.claims', true);
  v_prev_sub := current_setting('request.jwt.claim.sub', true);
  perform set_config('request.jwt.claims', jsonb_build_object('sub', p_profile, 'role', 'authenticated')::text, true);
  perform set_config('request.jwt.claim.sub', p_profile::text, true);
  begin
    select jsonb_build_object(
      'today', v_today, 'overdue_days', v_days, 'min_balance_cents', v_prefs->'min_balance_cents',
      'total_cents', coalesce((select sum(b.balance_cents) from public.fin_account_balances(v_today) b where b.active), 0),
      'overdue', (select jsonb_build_object('count', count(*), 'cents', coalesce(sum(st.total_due), 0), 'members', count(distinct c.profile_id))
                  from public.fin_member_charges c cross join lateral fin_private.charge_statement(c.id, v_today) st
                  where c.status in ('open', 'partial') and c.due_date <= v_today - v_days and st.total_due > 0),
      'receipts_waiting', (select jsonb_build_object('count', count(*)) from public.fin_receipt_submissions r
                           where r.status in ('submitted', 'in_review') and r.created_at < now() - interval '24 hours'),
      'payables', (select jsonb_build_object('overdue_cents', coalesce(p.payable_overdue_cents, 0), 'overdue_count', coalesce(p.payable_overdue_count, 0))
                   from public.fin_payables_summary(v_today) p))
    into v_out;
  exception when others then
    v_err := sqlerrm;
  end;
  perform set_config('request.jwt.claims', coalesce(v_prev_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(v_prev_sub, ''), true);
  if v_err is not null then return conv_private.vfail('ALERTS_FAILED', 'Não consegui checar os alertas agora.'); end if;
  return jsonb_build_object('ok', true, 'data', v_out);
end $function$;
--@@ 45 funcao conv_private.admin_alert_targets()
CREATE OR REPLACE FUNCTION conv_private.admin_alert_targets()
 RETURNS TABLE(profile_id uuid, name text, conversation_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select r.profile_id, p.name, cv.id
  from public.conv_admin_briefing_recipients r
  join public.profiles p on p.id = r.profile_id and p.role::text = 'admin' and coalesce(p.is_active, true)
  join public.conv_contacts c on c.profile_id = r.profile_id and c.merged_into is null and c.link_status in ('linked', 'manual') and not c.opt_out
  join lateral (select v.id from public.conv_conversations v where v.contact_id = c.id and v.kind = 'direct' and v.merged_into is null
                order by v.last_message_at desc nulls last limit 1) cv on true
  left join public.conv_admin_prefs pr on pr.profile_id = r.profile_id
  where r.enabled and coalesce(pr.alerts_enabled, true)
$function$;
--@@ 45 funcao conv_private.admin_briefing_data(p_profile uuid)
CREATE OR REPLACE FUNCTION conv_private.admin_briefing_data(p_profile uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v jsonb := conv_private.admin_briefing_data_base(p_profile);
begin
  if coalesce((v->>'ok')::boolean, false) then
    v := jsonb_set(v, '{data}', (v->'data') || jsonb_build_object('style', conv_private.admin_prefs_json(p_profile)->>'briefing_style'));
  end if;
  return v;
end $function$;
--@@ 45 funcao conv_private.admin_briefing_data_base(p_profile uuid)
CREATE OR REPLACE FUNCTION conv_private.admin_briefing_data_base(p_profile uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_prev_claims text; v_prev_sub text; v_err text; v_out jsonb;
  v_today date := (now() at time zone 'America/Fortaleza')::date;
begin
  if not exists (select 1 from conv_private.admin_briefing_targets() t where t.profile_id = p_profile) then
    return conv_private.vfail('NOT_A_RECIPIENT', 'Esse administrador não recebe o resumo.');
  end if;
  v_prev_claims := current_setting('request.jwt.claims', true);
  v_prev_sub := current_setting('request.jwt.claim.sub', true);
  perform set_config('request.jwt.claims', jsonb_build_object('sub', p_profile, 'role', 'authenticated')::text, true);
  perform set_config('request.jwt.claim.sub', p_profile::text, true);
  begin
    select jsonb_build_object(
      'today', v_today,
      'accounts', coalesce((select jsonb_agg(jsonb_build_object('name', b.name, 'balance_cents', b.balance_cents) order by b.name)
                            from public.fin_account_balances(v_today) b where b.active), '[]'::jsonb),
      'total_cents', coalesce((select sum(b.balance_cents) from public.fin_account_balances(v_today) b where b.active), 0),
      'yesterday', (select jsonb_build_object('inflow_cents', coalesce(sum(inflow_cents), 0), 'outflow_cents', coalesce(sum(outflow_cents), 0))
                    from public.fin_cash_flow(v_today - 1, v_today - 1, 'day', null)),
      'month', (select jsonb_build_object('inflow_cents', coalesce(sum(inflow_cents), 0), 'outflow_cents', coalesce(sum(outflow_cents), 0), 'net_cents', coalesce(sum(net_cents), 0))
                from public.fin_cash_flow(date_trunc('month', v_today)::date, v_today, 'month', null)),
      'receivables', (select to_jsonb(r) from public.fin_receivables_summary(v_today) r),
      'payables', (select to_jsonb(p) from public.fin_payables_summary(v_today) p),
      'receipts', (select jsonb_build_object('total', coalesce(max(total_count), 0), 'oldest_at', min(created_at)) from public.fin_receipt_queue('pending', 100, 0)),
      'access', (select jsonb_build_object('total', count(*)) from public.access_requests where status = 'pending'),
      'signatures', coalesce((select jsonb_agg(jsonb_build_object('title', title, 'recipients', recipients, 'signed', signed, 'due_at', due_at) order by published_at desc)
                              from public.sig_documents_overview where status = 'published' and signed < recipients), '[]'::jsonb),
      'reservations', (select jsonb_build_object('total', coalesce(sum(n), 0), 'by_type', coalesce(jsonb_object_agg(t, n) filter (where t is not null), '{}'::jsonb))
                       from (select r.type t, count(*) n from public.reservations r
                             where r.date = v_today and coalesce(r.status::text, 'active') = 'active' group by r.type) x))
    into v_out;
  exception when others then
    v_err := sqlerrm;
  end;
  perform set_config('request.jwt.claims', coalesce(v_prev_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(v_prev_sub, ''), true);
  if v_err is not null then return conv_private.vfail('BRIEFING_FAILED', 'Não consegui montar o resumo agora.'); end if;
  return jsonb_build_object('ok', true, 'data', v_out);
end $function$;
--@@ 45 funcao conv_private.admin_briefing_targets()
CREATE OR REPLACE FUNCTION conv_private.admin_briefing_targets()
 RETURNS TABLE(profile_id uuid, name text, conversation_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select r.profile_id, p.name, cv.id
  from public.conv_admin_briefing_recipients r
  join public.profiles p on p.id = r.profile_id and p.role::text = 'admin' and coalesce(p.is_active, true)
  join public.conv_contacts c on c.profile_id = r.profile_id and c.merged_into is null and c.link_status in ('linked', 'manual') and not c.opt_out
  join lateral (select v.id from public.conv_conversations v where v.contact_id = c.id and v.kind = 'direct' and v.merged_into is null
                order by v.last_message_at desc nulls last limit 1) cv on true
  left join public.conv_admin_prefs pr on pr.profile_id = r.profile_id
  where r.enabled and coalesce(pr.briefing_enabled, true)
$function$;
--@@ 45 funcao conv_private.admin_prefs_json(p_profile uuid)
CREATE OR REPLACE FUNCTION conv_private.admin_prefs_json(p_profile uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'briefing_enabled', coalesce(p.briefing_enabled, true), 'briefing_style', coalesce(p.briefing_style, 'completo'),
    'alerts_enabled', coalesce(p.alerts_enabled, true), 'min_balance_cents', p.min_balance_cents,
    'overdue_days', coalesce(p.overdue_days, 7), 'default_account', a.name)
  from (select 1) d left join public.conv_admin_prefs p on p.profile_id = p_profile left join public.fin_accounts a on a.id = p.default_account_id $function$;
--@@ 45 funcao conv_private.ai_active_settings()
CREATE OR REPLACE FUNCTION conv_private.ai_active_settings()
 RETURNS conv_ai_settings
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select s from public.conv_ai_settings s where s.active order by s.version desc limit 1 $function$;
--@@ 45 funcao conv_private.ai_admin_access_propose(p_session uuid, p jsonb)
CREATE OR REPLACE FUNCTION conv_private.ai_admin_access_propose(p_session uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  sess public.conv_ai_sessions%rowtype; s public.conv_ai_settings%rowtype; fs public.fin_settings%rowtype;
  v_admin uuid; v_action text := p->>'action'; v_id uuid; v_payload jsonb; v_today date := conv_private.today();
  v_req_id uuid; v_n int; v_list text; v_name text; v_phone text; v_email text; v_amount bigint; v_reason text := nullif(trim(coalesce(p->>'reason', '')), '');
  v_prof record; v_sub record; v_payee text; v_paid_on date; v_acc_id uuid; v_acc_name text; v_acc_n int; v_acc_list text; v_reactivate boolean := false;
begin
  select * into sess from public.conv_ai_sessions where id = p_session and status = 'open' for update;
  if not found then return conv_private.vfail('SESSION_CLOSED', 'Atendimento encerrado.'); end if;
  v_admin := conv_private.ai_admin_requester(p_session);
  if v_admin is null then
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;
  if v_action not in ('fin_member_create', 'fin_access_approve', 'adm_access_reject') then
    return conv_private.vfail('INVALID_ACTION', 'Ação inválida.');
  end if;

  -- Pedido de acesso pendente (aprovar/recusar), por nome; sem nome vale o único pendente.
  if v_action in ('fin_access_approve', 'adm_access_reject') then
    select count(*) into v_n from public.access_requests a
    where a.status = 'pending' and (nullif(trim(coalesce(p->>'name', '')), '') is null
      or fin_private.fold_text(a.name) like '%' || fin_private.fold_text(p->>'name') || '%');
    if v_n = 0 then return conv_private.vfail('ACCESS_NOT_FOUND', 'Não achei pedido de acesso pendente' ||
      case when nullif(trim(coalesce(p->>'name', '')), '') is null then '.' else ' com esse nome.' end); end if;
    if v_n > 1 then
      select string_agg(a.name, ', ' order by a.created_at) into v_list from (
        select a0.name, a0.created_at from public.access_requests a0 where a0.status = 'pending' and (nullif(trim(coalesce(p->>'name', '')), '') is null
          or fin_private.fold_text(a0.name) like '%' || fin_private.fold_text(p->>'name') || '%') order by a0.created_at limit 8) a;
      return conv_private.vfail('ACCESS_AMBIGUOUS', 'Tem mais de um pedido pendente: ' || v_list || '. Qual deles?');
    end if;
    select a.id, a.name, conv_private.br_local_phone(a.phone_normalized), nullif(trim(coalesce(a.email, '')), '')
      into v_req_id, v_name, v_phone, v_email from public.access_requests a
    where a.status = 'pending' and (nullif(trim(coalesce(p->>'name', '')), '') is null
      or fin_private.fold_text(a.name) like '%' || fin_private.fold_text(p->>'name') || '%');
  else
    v_name := trim(coalesce(p->>'name', ''));
    v_phone := conv_private.br_local_phone(p->>'phone');
    v_email := lower(nullif(trim(coalesce(p->>'email', '')), ''));
  end if;

  if v_action = 'adm_access_reject' then
    v_payload := jsonb_strip_nulls(jsonb_build_object('request_id', v_req_id, 'name', v_name, 'phone', v_phone, 'reason', v_reason));
  else
    if length(v_name) < 3 then return conv_private.vfail('INVALID_NAME', 'Qual o nome completo do sócio?'); end if;
    if length(v_phone) not between 10 and 11 then return conv_private.vfail('INVALID_PHONE', 'Qual o telefone com DDD? (ex.: 88 99999-9999)'); end if;
    if v_email is not null and v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then return conv_private.vfail('INVALID_EMAIL', 'Esse e-mail não parece válido. Qual o e-mail certo, ou deixo sem?'); end if;
    v_amount := nullif(p->>'amount_cents', '')::bigint;
    if v_amount is null or v_amount <= 0 or v_amount > 100000000 then return conv_private.vfail('INVALID_AMOUNT', 'Qual o valor da mensalidade dele?'); end if;

    -- Telefone já cadastrado: só reativa quem já é sócio; outro papel (professor, admin) fica no painel.
    select pr.id, pr.name, pr.role::text role, pr.is_active into v_prof from public.profiles pr where pr.phone = v_phone limit 1;
    if v_prof.id is not null then
      if v_prof.role <> 'socio' then
        return conv_private.vfail('PHONE_BELONGS', 'Esse telefone já é de ' || v_prof.name || ' (' || v_prof.role || '). Isso eu não mudo por aqui; use o painel.');
      end if;
      if v_prof.is_active then return conv_private.vfail('MEMBER_EXISTS', v_prof.name || ' já é sócio ativo.'); end if;
      if exists (select 1 from public.fin_member_plans where profile_id = v_prof.id and status <> 'ended') then
        return conv_private.vfail('PLAN_EXISTS', v_prof.name || ' já tem plano de sócio. Reative e acerte a mensalidade pelo painel.');
      end if;
      v_reactivate := true;
    end if;

    -- Comprovante da mensalidade: imagem que o administrador mandou nesta conversa nas últimas horas e ainda não foi usada.
    select r.id, r.declared_amount_cents, r.declared_paid_on, r.ocr, r.created_at into v_sub from public.fin_receipt_submissions r
    join public.conv_messages m on m.id = r.source_message_id
    where m.conversation_id = sess.conversation_id and r.profile_id = v_admin and r.status in ('submitted', 'in_review')
      and r.created_at > now() - interval '6 hours'
    order by r.created_at desc limit 1;
    if v_sub.id is null then
      return conv_private.vfail('RECEIPT_REQUIRED', 'Para cadastrar o sócio preciso do comprovante de pagamento da mensalidade deste mês. Mande a imagem ou o PDF aqui e me diga para continuar.');
    end if;
    if v_sub.declared_amount_cents is not null and v_sub.declared_amount_cents <> v_amount then
      return conv_private.vfail('RECEIPT_AMOUNT_MISMATCH', 'O comprovante mostra R$ ' || replace(trim(to_char(v_sub.declared_amount_cents::numeric / 100, 'FM999999990D00')), '.', ',')
        || ', mas a mensalidade informada é R$ ' || replace(trim(to_char(v_amount::numeric / 100, 'FM999999990D00')), '.', ',') || '. Qual vale?');
    end if;
    select * into fs from public.fin_settings where id;
    v_payee := nullif(trim(coalesce(v_sub.ocr->>'payee', '')), '');
    if v_payee is not null and not fin_private.payee_matches(v_payee, fs.payee_names) then
      return conv_private.vfail('RECEIPT_PAYEE', 'O favorecido do comprovante (' || v_payee || ') não bate com o clube. Confira a imagem; se estiver certo, cadastre pelo painel.');
    end if;
    v_paid_on := coalesce(v_sub.declared_paid_on, v_today);
    if v_paid_on > v_today then return conv_private.vfail('INVALID_DATE', 'A data do pagamento no comprovante é futura. Confira a imagem.'); end if;

    -- Conta que recebeu: a padrão de recebimentos (ou a única ativa), como na aprovação de comprovante.
    select string_agg(a.name, ', ' order by a.position, a.name) into v_acc_list from public.fin_accounts a where a.active;
    if nullif(trim(coalesce(p->>'account_name', '')), '') is not null then
      select count(*), min(a.id::text)::uuid into v_acc_n, v_acc_id from public.fin_accounts a
      where a.active and fin_private.fold_text(a.name) like '%' || fin_private.fold_text(p->>'account_name') || '%';
    else
      select count(*), min(a.id::text)::uuid into v_acc_n, v_acc_id from public.fin_accounts a where a.active and a.is_default_receipts;
      if v_acc_n <> 1 then select count(*), min(a.id::text)::uuid into v_acc_n, v_acc_id from public.fin_accounts a where a.active; end if;
    end if;
    if v_acc_n <> 1 then return conv_private.vfail('ACCOUNT_REQUIRED', 'Em qual conta entrou? Contas: ' || coalesce(v_acc_list, '(nenhuma ativa)') || '.'); end if;
    select name into v_acc_name from public.fin_accounts where id = v_acc_id;

    v_payload := jsonb_strip_nulls(jsonb_build_object('request_id', v_req_id, 'name', v_name, 'phone', v_phone, 'email', v_email,
      'amount_cents', v_amount, 'submission_id', v_sub.id, 'paid_on', v_paid_on, 'account_id', v_acc_id, 'account_name', v_acc_name,
      'month', date_trunc('month', v_today::timestamp)::date, 'amount_read', v_sub.declared_amount_cents is not null, 'reactivate', v_reactivate));
  end if;

  select * into s from public.conv_ai_settings where active order by version desc limit 1;
  update public.conv_booking_proposals set status = 'canceled' where session_id = p_session and status = 'open';
  insert into public.conv_booking_proposals(conversation_id, session_id, requester_contact_id, requester_profile_id, action, payload, expires_at)
  values (sess.conversation_id, p_session, sess.requester_contact_id, v_admin, v_action, v_payload,
    now() + make_interval(mins => coalesce(s.proposal_ttl_minutes, 20)))
  returning id into v_id;
  return jsonb_build_object('ok', true, 'proposal_id', v_id, 'action', v_action, 'summary', v_payload);
exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow or numeric_value_out_of_range then
  return conv_private.vfail('INVALID_DATA', 'Algum dado veio num formato que não entendi.');
end $function$;
--@@ 45 funcao conv_private.ai_admin_adm_propose(p_session uuid, p jsonb)
CREATE OR REPLACE FUNCTION conv_private.ai_admin_adm_propose(p_session uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  sess public.conv_ai_sessions%rowtype; s public.conv_ai_settings%rowtype;
  v_admin uuid; v_action text := p->>'action'; v_payload jsonb; v_id uuid;
  v_today date := (now() at time zone 'America/Fortaleza')::date;
  v_title text; v_msg text; v_n int; v_list text; v_active boolean; v_profile uuid; v_pname text; v_role text; v_cur boolean;
  v_id2 uuid; v_status text; v_date date; v_start time; v_court text;
begin
  select * into sess from public.conv_ai_sessions where id = p_session and status = 'open' for update;
  if not found then return conv_private.vfail('SESSION_CLOSED', 'Atendimento encerrado.'); end if;
  v_admin := conv_private.ai_admin_requester(p_session);
  if v_admin is null then
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;

  if v_action = 'adm_announcement_create' then
    v_title := trim(coalesce(p->>'title', '')); v_msg := trim(coalesce(p->>'message', ''));
    if length(v_title) not between 3 and 80 then return conv_private.vfail('INVALID_TITLE', 'Qual o título do aviso? (até 80 caracteres)'); end if;
    if length(v_msg) not between 5 and 600 then return conv_private.vfail('INVALID_MESSAGE', 'Qual o texto do aviso? (até 600 caracteres)'); end if;
    if nullif(p->>'expires_on', '')::date < v_today then return conv_private.vfail('INVALID_DATE', 'A validade do aviso não pode ser no passado.'); end if;
    v_payload := jsonb_strip_nulls(jsonb_build_object('title', v_title, 'message', v_msg, 'expires_on', nullif(p->>'expires_on', '')::date,
      'show_once', coalesce((p->>'show_once')::boolean, false)));

  elsif v_action = 'adm_announcement_deactivate' then
    select count(*), min(a.id::text)::uuid, min(a.title), string_agg(a.title, '; ' order by a.created_at desc)
      into v_n, v_id2, v_title, v_list from public.announcements a
    where coalesce(a.is_active, true) and (a.expires_at is null or a.expires_at > now())
      and fin_private.fold_text(a.title) like '%' || fin_private.fold_text(coalesce(p->>'title', '')) || '%';
    if v_n = 0 then return conv_private.vfail('ANNOUNCEMENT_NOT_FOUND', 'Não achei aviso ativo com esse título.'); end if;
    if v_n > 1 then return conv_private.vfail('ANNOUNCEMENT_AMBIGUOUS', 'Achei mais de um aviso ativo: ' || v_list || '. Qual deles?'); end if;
    v_payload := jsonb_build_object('announcement_id', v_id2, 'title', v_title);

  elsif v_action = 'adm_student_status' then
    v_status := p->>'status';
    if v_status not in ('active', 'paused') then return conv_private.vfail('INVALID_DATA', 'É para pausar ou reativar o aluno?'); end if;
    select count(*), min(x.id::text)::uuid, min(x.name), string_agg(x.name, ', ' order by x.name) into v_n, v_id2, v_pname, v_list from (
      select sp.id, coalesce(pr.name, ns.name) name from public.student_profiles sp
      left join public.profiles pr on pr.id = sp.profile_id left join public.non_socio_students ns on ns.id = sp.non_socio_student_id
      where fin_private.fold_text(coalesce(pr.name, ns.name)) like '%' || fin_private.fold_text(coalesce(p->>'student_name', '')) || '%') x;
    if nullif(trim(coalesce(p->>'student_name', '')), '') is null or v_n = 0 then
      return conv_private.vfail('STUDENT_NOT_FOUND', 'Não achei esse aluno. Qual o nome completo?');
    end if;
    if v_n > 1 then return conv_private.vfail('STUDENT_AMBIGUOUS', 'Achei mais de um: ' || v_list || '. Qual deles?'); end if;
    select (student_status = 'active') into v_cur from public.student_profiles where id = v_id2;
    if (v_status = 'active') = coalesce(v_cur, false) then
      return conv_private.vfail('ALREADY_SET', case when v_status = 'active' then 'Esse aluno já está ativo.' else 'Esse aluno já está pausado.' end);
    end if;
    v_payload := jsonb_build_object('student_profile_id', v_id2, 'student_name', v_pname, 'status', v_status);

  elsif v_action = 'adm_member_status' then
    -- O sócio é achado pelo nome entre TODOS os cadastros (reativar precisa achar quem está inativo).
    v_active := (p->>'active')::boolean;
    if v_active is null then return conv_private.vfail('INVALID_DATA', 'É para inativar ou reativar?'); end if;
    if nullif(trim(coalesce(p->>'member_name', '')), '') is null then return conv_private.vfail('MEMBER_NOT_FOUND', 'Qual sócio?'); end if;
    select count(*), min(x.id::text)::uuid, string_agg(x.name, ', ' order by x.name) into v_n, v_profile, v_list from (
      select pr.id, pr.name from public.profiles pr
      where fin_private.fold_text(pr.name) like '%' || fin_private.fold_text(p->>'member_name') || '%') x;
    if v_n = 0 then return conv_private.vfail('MEMBER_NOT_FOUND', 'Não achei esse sócio. Qual o nome completo?'); end if;
    if v_n > 1 then return conv_private.vfail('MEMBER_AMBIGUOUS', 'Achei mais de um: ' || v_list || '. Qual deles?'); end if;
    select name, role::text, coalesce(is_active, true) into v_pname, v_role, v_cur from public.profiles where id = v_profile;
    if v_role = 'admin' then return conv_private.vfail('ADMIN_PROTECTED', 'Administrador não é alterado por aqui. Isso é pelo painel (Sócios).'); end if;
    if v_cur = v_active then
      return conv_private.vfail('ALREADY_SET', case when v_active then 'Esse sócio já está ativo.' else 'Esse sócio já está inativo.' end);
    end if;
    v_payload := jsonb_build_object('profile_id', v_profile, 'member_name', v_pname, 'active', v_active);

  elsif v_action = 'adm_signature_resend' then
    select count(*), min(d.id::text)::uuid, min(d.title), string_agg(d.title, '; ' order by d.published_at desc)
      into v_n, v_id2, v_title, v_list from public.sig_documents_overview d
    where d.status = 'published' and fin_private.fold_text(d.title) like '%' || fin_private.fold_text(coalesce(p->>'title', '')) || '%';
    if v_n = 0 then return conv_private.vfail('DOCUMENT_NOT_FOUND', 'Não achei documento publicado com esse nome.'); end if;
    if v_n > 1 then return conv_private.vfail('DOCUMENT_AMBIGUOUS', 'Achei mais de um: ' || v_list || '. Qual deles?'); end if;
    select d.notifications_failed into v_n from public.sig_documents_overview d where d.id = v_id2;
    if coalesce(v_n, 0) = 0 then return conv_private.vfail('NOTHING_TO_RESEND', 'Esse documento não tem aviso com falha para reenviar.'); end if;
    v_payload := jsonb_build_object('document_id', v_id2, 'title', v_title, 'failed_count', v_n);

  elsif v_action = 'adm_reservation_cancel' then
    v_date := nullif(p->>'date', '')::date; v_start := nullif(p->>'start', '')::time; v_court := nullif(trim(coalesce(p->>'court_label', '')), '');
    if v_date is null or v_start is null then return conv_private.vfail('INVALID_DATA', 'Qual dia e horário de início da reserva?'); end if;
    select count(*), min(r.id::text)::uuid into v_n, v_id2 from public.reservations r join public.courts c on c.id = r.court_id
    where r.date = v_date and r.start_time = v_start and coalesce(r.status::text, 'active') = 'active'
      and (v_court is null or fin_private.fold_text(c.name) like '%' || fin_private.fold_text(v_court) || '%')
      and (nullif(trim(coalesce(p->>'by_name', '')), '') is null or exists (
        select 1 from public.profiles pr where pr.id = r.creator_id and fin_private.fold_text(pr.name) like '%' || fin_private.fold_text(p->>'by_name') || '%')
        or fin_private.fold_text(coalesce(r.guest_name, '')) like '%' || fin_private.fold_text(coalesce(p->>'by_name', '')) || '%');
    if v_n = 0 then return conv_private.vfail('RESERVATION_NOT_FOUND', 'Não achei reserva ativa nesse dia e horário.'); end if;
    if v_n > 1 then return conv_private.vfail('RESERVATION_AMBIGUOUS', 'Há ' || v_n || ' reservas nesse horário. Me diga a quadra ou quem reservou.'); end if;
    select jsonb_build_object('reservation_id', r.id, 'court', c.name, 'date', r.date, 'start', to_char(r.start_time, 'HH24:MI'),
      'end', to_char(r.end_time, 'HH24:MI'), 'type', r.type, 'by', coalesce(pr.name, r.guest_name),
      'reason', nullif(trim(coalesce(p->>'reason', '')), ''))
      into v_payload from public.reservations r join public.courts c on c.id = r.court_id left join public.profiles pr on pr.id = r.creator_id
    where r.id = v_id2;
    v_payload := jsonb_strip_nulls(v_payload);
  else
    return conv_private.vfail('INVALID_ACTION', 'Ação inválida.');
  end if;

  select * into s from public.conv_ai_settings where active order by version desc limit 1;
  update public.conv_booking_proposals set status = 'canceled' where session_id = p_session and status = 'open';
  insert into public.conv_booking_proposals(conversation_id, session_id, requester_contact_id, requester_profile_id, action, payload, expires_at)
  values (sess.conversation_id, p_session, sess.requester_contact_id, v_admin, v_action, v_payload,
    now() + make_interval(mins => coalesce(s.proposal_ttl_minutes, 20)))
  returning id into v_id;
  return jsonb_build_object('ok', true, 'proposal_id', v_id, 'action', v_action, 'summary', v_payload);
exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow or numeric_value_out_of_range then
  return conv_private.vfail('INVALID_DATA', 'Algum dado veio num formato que não entendi (data, hora ou valor).');
end $function$;
--@@ 45 funcao conv_private.ai_admin_briefing_propose(p_session uuid, p jsonb)
CREATE OR REPLACE FUNCTION conv_private.ai_admin_briefing_propose(p_session uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  sess public.conv_ai_sessions%rowtype; s public.conv_ai_settings%rowtype; v_admin uuid; v_id uuid; v_payload jsonb;
  v_profile uuid := nullif(p->>'profile_id', '')::uuid; v_on boolean := coalesce((p->>'enabled')::boolean, true); pr public.profiles%rowtype;
begin
  select * into sess from public.conv_ai_sessions where id = p_session and status = 'open' for update;
  if not found then return conv_private.vfail('SESSION_CLOSED', 'Atendimento encerrado.'); end if;
  v_admin := conv_private.ai_admin_requester(p_session);
  if v_admin is null then
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;
  select * into pr from public.profiles where id = v_profile and coalesce(is_active, true);
  if pr.id is null then return conv_private.vfail('MEMBER_NOT_FOUND', 'Não achei essa pessoa ativa no cadastro.'); end if;
  if pr.role::text <> 'admin' then
    return conv_private.vfail('NOT_ADMIN', pr.name || ' não é da diretoria no sistema, e o resumo traz dados financeiros só para administradores. Se for o caso, ele precisa antes virar administrador pelo painel.');
  end if;
  if v_on and not exists (select 1 from public.conv_contacts c join public.conv_conversations v on v.contact_id = c.id and v.kind = 'direct'
                          where c.profile_id = pr.id and c.link_status in ('linked', 'manual') and not c.opt_out) then
    return conv_private.vfail('NO_CONVERSATION', pr.name || ' ainda não tem conversa direta comigo no WhatsApp. Peça para ele me mandar um "oi" e eu incluo em seguida.');
  end if;
  if v_on = exists (select 1 from public.conv_admin_briefing_recipients r where r.profile_id = pr.id and r.enabled) then
    return conv_private.vfail('NO_CHANGE', pr.name || (case when v_on then ' já recebe' else ' já não recebe' end) || ' o resumo das 8h.');
  end if;
  v_payload := jsonb_build_object('profile_id', pr.id, 'name', pr.name, 'enabled', v_on, 'list_after', conv_private.briefing_list_names(pr.id, v_on));
  select * into s from public.conv_ai_settings where active order by version desc limit 1;
  update public.conv_booking_proposals set status = 'canceled' where session_id = p_session and status = 'open';
  insert into public.conv_booking_proposals(conversation_id, session_id, requester_contact_id, requester_profile_id, action, payload, expires_at)
  values (sess.conversation_id, p_session, sess.requester_contact_id, v_admin, 'adm_briefing_recipient', v_payload,
    now() + make_interval(mins => coalesce(s.proposal_ttl_minutes, 20)))
  returning id into v_id;
  return jsonb_build_object('ok', true, 'proposal_id', v_id, 'action', 'adm_briefing_recipient', 'summary', v_payload);
end $function$;
--@@ 45 funcao conv_private.ai_admin_broadcast_propose(p_session uuid, p jsonb
CREATE OR REPLACE FUNCTION conv_private.ai_admin_broadcast_propose(p_session uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  sess public.conv_ai_sessions%rowtype; s public.conv_ai_settings%rowtype; v_admin uuid; v_id uuid; v_payload jsonb;
  v_body text := trim(coalesce(p->>'body', '')); v_at timestamptz; v_rec jsonb; v_n int; v_skipped int;
begin
  select * into sess from public.conv_ai_sessions where id = p_session and status = 'open' for update;
  if not found then return conv_private.vfail('SESSION_CLOSED', 'Atendimento encerrado.'); end if;
  v_admin := conv_private.ai_admin_requester(p_session);
  if v_admin is null then
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;
  if length(v_body) not between 10 and 3500 then return conv_private.vfail('INVALID_BODY', 'Qual o texto do comunicado?'); end if;
  v_at := coalesce(nullif(p->>'send_at', '')::timestamptz, now());
  if v_at < now() then v_at := now(); end if;
  if v_at > now() + interval '7 days' then return conv_private.vfail('INVALID_DATE', 'Só consigo agendar até 7 dias à frente.'); end if;
  select coalesce(jsonb_agg(jsonb_build_object('profile_id', x.id, 'name', x.name, 'phone', x.ph) order by x.name), '[]'::jsonb), count(*)
    into v_rec, v_n
  from (select pr.id, pr.name, conv_private.phone_e164(pr.phone) ph from public.profiles pr
        where coalesce(pr.is_active, true) and pr.role::text in ('socio', 'admin') and pr.id <> v_admin) x
  where x.ph is not null and length(x.ph) >= 12
    and not exists (select 1 from public.conv_contacts c where c.phone = x.ph and c.opt_out);
  if v_n = 0 then return conv_private.vfail('NO_RECIPIENTS', 'Não achei sócio com telefone válido para receber.'); end if;
  select count(*) into v_skipped from public.profiles pr
    where coalesce(pr.is_active, true) and pr.role::text in ('socio', 'admin') and pr.id <> v_admin;
  v_skipped := v_skipped - v_n;
  v_payload := jsonb_build_object('body', v_body, 'send_at', v_at, 'count', v_n, 'skipped', v_skipped, 'recipients', v_rec);
  select * into s from public.conv_ai_settings where active order by version desc limit 1;
  update public.conv_booking_proposals set status = 'canceled' where session_id = p_session and status = 'open';
  insert into public.conv_booking_proposals(conversation_id, session_id, requester_contact_id, requester_profile_id, action, payload, expires_at)
  values (sess.conversation_id, p_session, sess.requester_contact_id, v_admin, 'adm_broadcast_send', v_payload,
    now() + make_interval(mins => greatest(coalesce(s.proposal_ttl_minutes, 20), 30)))
  returning id into v_id;
  return jsonb_build_object('ok', true, 'proposal_id', v_id, 'action', 'adm_broadcast_send', 'summary', v_payload - 'recipients');
end $function$;
--@@ 45 funcao conv_private.ai_admin_dependent_propose(p_session uuid, p jsonb
CREATE OR REPLACE FUNCTION conv_private.ai_admin_dependent_propose(p_session uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  sess public.conv_ai_sessions%rowtype; s public.conv_ai_settings%rowtype; v_admin uuid; v_id uuid; v_payload jsonb;
  v_profile uuid := nullif(p->>'profile_id', '')::uuid; v_name text; v_dep text := regexp_replace(trim(coalesce(p->>'dependent_name', '')), '\s+', ' ', 'g');
  v_rel text := lower(coalesce(p->>'relationship', '')); v_phone text := regexp_replace(coalesce(p->>'phone', ''), '\D', '', 'g');
begin
  select * into sess from public.conv_ai_sessions where id = p_session and status = 'open' for update;
  if not found then return conv_private.vfail('SESSION_CLOSED', 'Atendimento encerrado.'); end if;
  v_admin := conv_private.ai_admin_requester(p_session);
  if v_admin is null then
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;
  select name into v_name from public.profiles where id = v_profile and role::text in ('socio', 'admin') and coalesce(is_active, true);
  if v_name is null then return conv_private.vfail('MEMBER_NOT_FOUND', 'Não achei esse sócio ativo para ser o responsável.'); end if;
  if length(v_dep) < 3 or length(v_dep) > 120 then return conv_private.vfail('INVALID_NAME', 'Qual o nome completo do dependente?'); end if;
  if v_rel not in ('filho', 'filha', 'esposo', 'esposa', 'outro') then
    return conv_private.vfail('INVALID_RELATIONSHIP', 'Qual o parentesco com ' || v_name || ': esposa, esposo, filho, filha ou outro?');
  end if;
  if v_phone <> '' and length(v_phone) not between 10 and 13 then
    return conv_private.vfail('INVALID_PHONE', 'O telefone precisa ter DDD. Pode conferir? (O telefone é opcional.)');
  end if;
  if exists (select 1 from public.non_socio_students n where n.responsible_socio_id = v_profile and n.student_type = 'dependent'
             and coalesce(n.is_active, true) and fin_private.fold_text(n.name) = fin_private.fold_text(v_dep)) then
    return conv_private.vfail('DEPENDENT_EXISTS', v_dep || ' já está cadastrado(a) como dependente de ' || v_name || '.');
  end if;
  v_payload := jsonb_strip_nulls(jsonb_build_object('profile_id', v_profile, 'member_name', v_name, 'dependent_name', v_dep,
    'relationship', v_rel, 'phone', nullif(v_phone, '')));
  select * into s from public.conv_ai_settings where active order by version desc limit 1;
  update public.conv_booking_proposals set status = 'canceled' where session_id = p_session and status = 'open';
  insert into public.conv_booking_proposals(conversation_id, session_id, requester_contact_id, requester_profile_id, action, payload, expires_at)
  values (sess.conversation_id, p_session, sess.requester_contact_id, v_admin, 'adm_dependent_create', v_payload,
    now() + make_interval(mins => coalesce(s.proposal_ttl_minutes, 20)))
  returning id into v_id;
  return jsonb_build_object('ok', true, 'proposal_id', v_id, 'action', 'adm_dependent_create', 'summary', v_payload);
end $function$;
--@@ 45 funcao conv_private.ai_admin_file_lookup(p_session uuid, p jsonb)
CREATE OR REPLACE FUNCTION conv_private.ai_admin_file_lookup(p_session uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_admin uuid; v_kind text := coalesce(p->>'kind', ''); v_profile uuid := nullif(p->>'profile_id', '')::uuid;
  v_today date := (now() at time zone 'America/Fortaleza')::date; v_from date; v_to date;
  v_text text := nullif(trim(coalesce(p->>'text', '')), ''); v_files jsonb;
begin
  v_admin := conv_private.ai_admin_requester(p_session);
  if v_admin is null then
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador pede, e só na conversa privada comigo.');
  end if;
  begin
    v_from := coalesce(nullif(p->>'from', '')::date, v_today - 90);
    v_to := coalesce(nullif(p->>'to', '')::date, v_today);
  exception when others then
    return conv_private.vfail('INVALID_DATA', 'Não entendi o período. Pode dizer as datas?');
  end;
  if v_kind = 'comprovante' then
    select coalesce(jsonb_agg(f order by f.at desc), '[]'::jsonb) into v_files from (
      select jsonb_build_object('bucket', 'fin-receipts', 'path', s.storage_path, 'name', coalesce(s.file_name, 'comprovante'),
               'mime', coalesce(s.content_type, 'application/octet-stream'),
               'label', 'Comprovante de ' || coalesce(pr.name, 'sócio')
                 || case when s.declared_amount_cents is not null then ' (R$ ' || replace(to_char(s.declared_amount_cents / 100.0, 'FM999G990D00'), '.', ',') || ')' else '' end
                 || ' de ' || to_char(coalesce(s.declared_paid_on, (s.created_at at time zone 'America/Fortaleza')::date), 'DD/MM/YYYY')) f,
             s.created_at at
      from public.fin_receipt_submissions s left join public.profiles pr on pr.id = s.profile_id
      where s.status <> 'superseded' and s.storage_path is not null
        and (v_profile is null or s.profile_id = v_profile)
        and (s.created_at at time zone 'America/Fortaleza')::date between v_from and v_to
      order by s.created_at desc limit 5) x(f, at);
  elsif v_kind = 'despesa_anexo' then
    select coalesce(jsonb_agg(f order by f.at desc), '[]'::jsonb) into v_files from (
      select jsonb_build_object('bucket', 'fin-docs', 'path', a.storage_path, 'name', coalesce(a.file_name, 'anexo'),
               'mime', coalesce(a.content_type, 'application/octet-stream'),
               'label', 'Anexo de «' || coalesce(e.description, 'lançamento') || '»') f, a.uploaded_at at
      from public.fin_attachments a join public.fin_entries e on e.id = a.entry_id
      where a.removed_at is null and (v_text is null or e.description ilike '%' || v_text || '%' or e.supplier ilike '%' || v_text || '%')
        and (a.uploaded_at at time zone 'America/Fortaleza')::date between v_from and v_to
      order by a.uploaded_at desc limit 5) x(f, at);
  elsif v_kind = 'documento' then
    select coalesce(jsonb_agg(f order by f.at desc), '[]'::jsonb) into v_files from (
      select jsonb_build_object('bucket', 'sig-docs', 'path', d.storage_path, 'name', coalesce(d.file_name, d.title || '.pdf'),
               'mime', 'application/pdf', 'label', 'Documento «' || d.title || '»') f, d.created_at at
      from public.sig_documents d
      where d.archived_at is null and (v_text is null or d.title ilike '%' || v_text || '%')
      order by d.created_at desc limit 3) x(f, at);
  else
    return conv_private.vfail('INVALID_KIND', 'Esse tipo de arquivo eu não sei buscar.');
  end if;
  if jsonb_array_length(v_files) = 0 then
    return conv_private.vfail('NO_FILE', 'Não achei nenhum arquivo com esses dados. Quer tentar outro período ou nome?');
  end if;
  perform conv_private.audit('ai_admin_file', 'conv_ai_sessions', p_session::text, null,
    jsonb_build_object('kind', v_kind, 'count', jsonb_array_length(v_files)),
    jsonb_build_object('actor', 'ai', 'source', 'whatsapp', 'requester_profile_id', v_admin), v_admin);
  return jsonb_build_object('ok', true, 'files', v_files);
end $function$;
--@@ 45 funcao conv_private.ai_admin_finance_propose(p_session uuid, p jsonb)
CREATE OR REPLACE FUNCTION conv_private.ai_admin_finance_propose(p_session uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ select conv_private.ai_admin_finance_propose_w6(p_session, p) $function$;
--@@ 45 funcao conv_private.ai_admin_finance_propose_ext(p_session uuid, p jso
CREATE OR REPLACE FUNCTION conv_private.ai_admin_finance_propose_ext(p_session uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  sess public.conv_ai_sessions%rowtype; s public.conv_ai_settings%rowtype; ch public.fin_member_charges%rowtype;
  v_admin uuid; v_action text := p->>'action'; v_payload jsonb; v_id uuid; v_today date := conv_private.today();
  v_name text; v_reason text := trim(coalesce(p->>'reason', '')); v_amount bigint; v_total bigint; v_fees bigint; v_rem bigint;
  v_kind text; v_profile uuid; v_pay_id uuid; v_pay_charge uuid; v_pay_amount bigint; v_pay_on date; v_sub record; v_n int; v_date date; v_desc text; v_status text; v_due date; v_paid_on date;
  v_acc_id uuid; v_acc_name text; v_acc_n int; v_acc_list text; v_cat_id uuid; v_cat_name text; v_cat_n int; v_cat_list text; v_entry text;
begin
  select * into sess from public.conv_ai_sessions where id = p_session and status = 'open' for update;
  if not found then return conv_private.vfail('SESSION_CLOSED', 'Atendimento encerrado.'); end if;
  v_admin := conv_private.ai_admin_requester(p_session);
  if v_admin is null then
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;

  if v_action in ('fin_charge_cancel', 'fin_charge_adjust', 'fin_payment_reverse') then
    if length(v_reason) < 5 then return conv_private.vfail('REASON_REQUIRED', 'Qual o motivo? Preciso de uma frase curta para o registro.'); end if;
    if v_action = 'fin_payment_reverse' and nullif(p->>'charge_id', '') is null then
      -- "Estorna o último pagamento do Beto": o mais recente ainda efetivo entre as pendências dele.
      select e.id, e.charge_id, e.amount_cents, e.paid_on into v_pay_id, v_pay_charge, v_pay_amount, v_pay_on
      from fin_private.charge_payments_effective e join public.fin_member_charges c on c.id = e.charge_id
      where c.profile_id = nullif(p->>'profile_id', '')::uuid and c.charge_type = 'member_pendency' and e.kind = 'payment'
        and not exists (select 1 from public.fin_charge_payments r where r.reverses_payment_id = e.id)
      order by e.paid_on desc, e.created_at desc limit 1;
      if v_pay_id is null then return conv_private.vfail('PAYMENT_NOT_FOUND', 'Não achei pagamento desse sócio para estornar.'); end if;
      select * into ch from public.fin_member_charges where id = v_pay_charge;
    elsif nullif(p->>'charge_id', '') is not null then
      select * into ch from public.fin_member_charges where id = (p->>'charge_id')::uuid and charge_type = 'member_pendency';
    end if;
    if ch.id is null then return conv_private.vfail('PENDENCY_NOT_FOUND', 'Não achei essa pendência.'); end if;
    select name into v_name from public.profiles where id = ch.profile_id;
    select st.total_due, st.fees_due, st.principal_remaining into v_total, v_fees, v_rem from fin_private.charge_statement(ch.id, v_today) st;
    v_payload := jsonb_build_object('charge_id', ch.id, 'profile_id', ch.profile_id, 'member_name', v_name, 'description', ch.description,
      'due_date', ch.due_date, 'total_due_cents', v_total, 'reason', v_reason);

    if v_action = 'fin_charge_cancel' then
      if ch.status = 'canceled' then return conv_private.vfail('CHARGE_CANCELED', 'Essa pendência já está cancelada.'); end if;
      if exists (select 1 from fin_private.charge_payments_effective where charge_id = ch.id) then
        return conv_private.vfail('CHARGE_HAS_PAYMENTS', 'Essa pendência já tem pagamento. Dá para ajustar com desconto, ou estornar o pagamento antes.');
      end if;
      v_payload := v_payload || jsonb_build_object('amount_cents', v_total);

    elsif v_action = 'fin_charge_adjust' then
      if ch.status = 'canceled' then return conv_private.vfail('CHARGE_CANCELED', 'Essa pendência está cancelada.'); end if;
      v_kind := p->>'adjust_kind';
      if v_kind not in ('discount', 'increase', 'fee_waiver') then
        return conv_private.vfail('INVALID_ADJUSTMENT', 'É desconto, acréscimo ou perdão de juros/multa?');
      end if;
      v_amount := nullif(p->>'amount_cents', '')::bigint;
      if v_amount is null or v_amount <= 0 or v_amount > 1000000000 then return conv_private.vfail('INVALID_AMOUNT', 'Qual o valor do ajuste?'); end if;
      if v_kind = 'discount' and v_amount > v_rem then
        return conv_private.vfail('DISCOUNT_EXCEEDS_BALANCE', 'O desconto passa do valor em aberto (' || trim(to_char(v_rem::numeric / 100, 'FM999999990D00')) || ').');
      end if;
      if v_kind = 'fee_waiver' and v_amount > v_fees then
        return conv_private.vfail('WAIVER_EXCEEDS_FEES', 'Os juros/multa dessa pendência somam menos que isso.');
      end if;
      v_payload := v_payload || jsonb_build_object('adjust_kind', v_kind, 'amount_cents', v_amount);

    else
      if v_pay_id is null then
        select e.id, e.charge_id, e.amount_cents, e.paid_on into v_pay_id, v_pay_charge, v_pay_amount, v_pay_on
        from fin_private.charge_payments_effective e
        where e.charge_id = ch.id and e.kind = 'payment'
          and not exists (select 1 from public.fin_charge_payments r where r.reverses_payment_id = e.id)
        order by e.paid_on desc, e.created_at desc limit 1;
        if v_pay_id is null then return conv_private.vfail('PAYMENT_NOT_FOUND', 'Essa pendência não tem pagamento para estornar.'); end if;
      end if;
      v_payload := v_payload || jsonb_build_object('payment_id', v_pay_id, 'amount_cents', v_pay_amount, 'paid_on', v_pay_on);
    end if;

  elsif v_action = 'fin_receipt_reject' then
    if length(v_reason) < 5 then return conv_private.vfail('REASON_REQUIRED', 'Qual o motivo da recusa? Vai no registro e o sócio pode ver.'); end if;
    v_profile := nullif(p->>'profile_id', '')::uuid;
    v_date := nullif(p->>'receipt_date', '')::date;
    select count(*) into v_n from public.fin_receipt_submissions r
    where r.profile_id = v_profile and r.status in ('submitted', 'in_review')
      and (v_date is null or (r.created_at at time zone 'America/Fortaleza')::date = v_date);
    if v_n = 0 then return conv_private.vfail('RECEIPT_NOT_FOUND', 'Não achei comprovante pendente desse sócio.'); end if;
    if v_n > 1 then
      return conv_private.vfail('RECEIPT_AMBIGUOUS', 'Esse sócio tem ' || v_n || ' comprovantes pendentes. De qual dia é o que você quer recusar?');
    end if;
    select r.id, r.declared_amount_cents, r.created_at, r.declared_paid_on into v_sub from public.fin_receipt_submissions r
    where r.profile_id = v_profile and r.status in ('submitted', 'in_review')
      and (v_date is null or (r.created_at at time zone 'America/Fortaleza')::date = v_date);
    select name into v_name from public.profiles where id = v_profile;
    v_payload := jsonb_strip_nulls(jsonb_build_object('submission_id', v_sub.id, 'profile_id', v_profile, 'member_name', v_name,
      'amount_cents', v_sub.declared_amount_cents, 'sent_on', (v_sub.created_at at time zone 'America/Fortaleza')::date,
      'paid_on', v_sub.declared_paid_on, 'reason', v_reason));

  elsif v_action = 'fin_entry_create' then
    v_entry := p->>'entry_kind';
    if v_entry not in ('expense', 'revenue') then return conv_private.vfail('INVALID_ENTRY', 'É despesa ou receita?'); end if;
    v_desc := trim(coalesce(p->>'description', ''));
    if length(v_desc) not between 2 and 140 then return conv_private.vfail('INVALID_DESCRIPTION', 'Qual a descrição do lançamento?'); end if;
    v_amount := nullif(p->>'amount_cents', '')::bigint;
    if v_amount is null or v_amount <= 0 or v_amount > 100000000000 then return conv_private.vfail('INVALID_AMOUNT', 'Qual o valor?'); end if;
    v_status := coalesce(nullif(p->>'entry_status', ''), 'paid');
    if v_status not in ('paid', 'pending') then v_status := 'paid'; end if;
    v_due := nullif(p->>'due_date', '')::date;
    if v_status = 'pending' and v_due is null then return conv_private.vfail('DUE_DATE_REQUIRED', 'Qual o vencimento?'); end if;
    v_paid_on := case when v_status = 'paid' then coalesce(nullif(p->>'paid_on', '')::date, v_today) end;
    if v_paid_on > v_today then return conv_private.vfail('INVALID_DATE', 'A data do pagamento não pode ser no futuro.'); end if;
    -- Categoria pelo nome (só categorias ativas do tipo certo; nome ambíguo ou ausente pergunta).
    select count(*), min(c.id::text)::uuid, min(c.name) into v_cat_n, v_cat_id, v_cat_name from public.fin_categories c
    where c.active and c.kind = v_entry and c.parent_id is not null and c.system_key is null
      and nullif(trim(coalesce(p->>'category_name', '')), '') is not null
      and fin_private.fold_text(c.name) like '%' || fin_private.fold_text(p->>'category_name') || '%';
    if v_cat_n <> 1 then
      select string_agg(c.name, ', ' order by c.position, c.name) into v_cat_list from (
        select * from public.fin_categories c0 where c0.active and c0.kind = v_entry and c0.parent_id is not null and c0.system_key is null
        order by c0.position, c0.name limit 14) c;
      return conv_private.vfail('CATEGORY_REQUIRED', 'Em qual categoria? ' || coalesce(v_cat_list, '(nenhuma ativa)') || '.');
    end if;
    -- Conta pelo nome; sem nome vale a conta única/padrão.
    select string_agg(a.name, ', ' order by a.position, a.name) into v_acc_list from public.fin_accounts a where a.active;
    if nullif(trim(coalesce(p->>'account_name', '')), '') is not null then
      select count(*), min(a.id::text)::uuid into v_acc_n, v_acc_id from public.fin_accounts a
      where a.active and fin_private.fold_text(a.name) like '%' || fin_private.fold_text(p->>'account_name') || '%';
    else
      select count(*), min(a.id::text)::uuid into v_acc_n, v_acc_id from public.fin_accounts a where a.active and a.is_default_receipts;
      if v_acc_n <> 1 then select count(*), min(a.id::text)::uuid into v_acc_n, v_acc_id from public.fin_accounts a where a.active; end if;
    end if;
    if v_acc_n <> 1 then
      return conv_private.vfail('ACCOUNT_REQUIRED', 'Em qual conta? Contas: ' || coalesce(v_acc_list, '(nenhuma ativa)') || '.');
    end if;
    select name into v_acc_name from public.fin_accounts where id = v_acc_id;
    v_payload := jsonb_strip_nulls(jsonb_build_object('entry_kind', v_entry, 'description', v_desc, 'amount_cents', v_amount,
      'entry_status', v_status, 'due_date', v_due, 'paid_on', v_paid_on, 'category_id', v_cat_id, 'category_name', v_cat_name,
      'account_id', v_acc_id, 'account_name', v_acc_name, 'supplier', nullif(trim(coalesce(p->>'supplier', '')), '')));
  else
    return conv_private.vfail('INVALID_ACTION', 'Ação inválida.');
  end if;

  select * into s from public.conv_ai_settings where active order by version desc limit 1;
  update public.conv_booking_proposals set status = 'canceled' where session_id = p_session and status = 'open';
  insert into public.conv_booking_proposals(conversation_id, session_id, requester_contact_id, requester_profile_id, action, payload, expires_at)
  values (sess.conversation_id, p_session, sess.requester_contact_id, v_admin, v_action, v_payload,
    now() + make_interval(mins => coalesce(s.proposal_ttl_minutes, 20)))
  returning id into v_id;
  return jsonb_build_object('ok', true, 'proposal_id', v_id, 'action', v_action, 'summary', v_payload);
exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow or numeric_value_out_of_range then
  return conv_private.vfail('INVALID_DATA', 'Algum dado veio num formato que não entendi (data ou valor).');
end $function$;
--@@ 45 funcao conv_private.ai_admin_finance_propose_pendency(p_session uuid, 
CREATE OR REPLACE FUNCTION conv_private.ai_admin_finance_propose_pendency(p_session uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  sess public.conv_ai_sessions%rowtype; s public.conv_ai_settings%rowtype; ch public.fin_member_charges%rowtype;
  v_admin uuid; v_action text := coalesce(p->>'action', ''); v_payload jsonb; v_id uuid; v_today date := conv_private.today();
  v_profile uuid; v_name text; v_desc text; v_amount bigint; v_due date; v_kind text; v_enabled boolean;
  v_total bigint; v_open int; v_paid_on date; v_method text; v_acc_id uuid; v_acc_name text; v_acc_n int; v_acc_list text;
begin
  select * into sess from public.conv_ai_sessions where id = p_session and status = 'open' for update;
  if not found then return conv_private.vfail('SESSION_CLOSED', 'Atendimento encerrado.'); end if;
  v_admin := conv_private.ai_admin_requester(p_session);
  if v_admin is null then
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;
  if v_action not in ('fin_pendency_create', 'fin_pendency_collection', 'fin_pendency_send', 'fin_payment') then
    return conv_private.vfail('INVALID_ACTION', 'Ação inválida.');
  end if;

  if v_action = 'fin_pendency_create' then
    v_profile := nullif(p->>'profile_id', '')::uuid;
    if v_profile is null or not fin_private.is_active_member(v_profile) then
      return conv_private.vfail('MEMBER_NOT_ACTIVE', 'Não achei esse sócio ativo no cadastro.');
    end if;
    select name into v_name from public.profiles where id = v_profile;
    v_desc := trim(coalesce(p->>'description', ''));
    if length(v_desc) not between 3 and 300 then return conv_private.vfail('INVALID_DESCRIPTION', 'Qual é a descrição da pendência?'); end if;
    v_amount := nullif(p->>'amount_cents', '')::bigint;
    if v_amount is null or v_amount <= 0 or v_amount > 1000000000 then return conv_private.vfail('INVALID_AMOUNT', 'Qual é o valor?'); end if;
    v_due := coalesce(nullif(p->>'due_date', '')::date, v_today);
    v_kind := coalesce(nullif(p->>'pendency_kind', ''), 'outros');
    if v_kind not in ('day_card', 'consumo', 'evento', 'multa', 'dano_reposicao', 'outros') then v_kind := 'outros'; end if;
    v_payload := jsonb_strip_nulls(jsonb_build_object(
      'profile_id', v_profile, 'member_name', v_name, 'description', v_desc, 'amount_cents', v_amount,
      'due_date', v_due, 'competence_month', date_trunc('month', v_due)::date, 'pendency_kind', v_kind,
      'guest_name', nullif(trim(coalesce(p->>'guest_name', '')), ''), 'guest_date', nullif(p->>'guest_date', '')::date,
      'collection_enabled', true, 'send_now', coalesce((p->>'send_now')::boolean, false)));

  elsif v_action in ('fin_pendency_collection', 'fin_pendency_send', 'fin_payment') then
    -- Pendência pela referência (id) ou, para cobrar, pelo sócio: a mais antiga em aberto com cobrança ligada.
    if nullif(p->>'charge_id', '') is not null then
      select * into ch from public.fin_member_charges where id = (p->>'charge_id')::uuid and charge_type = 'member_pendency';
    elsif v_action = 'fin_pendency_send' and nullif(p->>'profile_id', '') is not null then
      select * into ch from public.fin_member_charges
      where profile_id = (p->>'profile_id')::uuid and charge_type = 'member_pendency' and status in ('open', 'partial') and collection_enabled
      order by due_date, created_at limit 1;
    end if;
    if ch.id is null then return conv_private.vfail('PENDENCY_NOT_FOUND', 'Não achei essa pendência.'); end if;
    if ch.status not in ('open', 'partial') then return conv_private.vfail('PENDENCY_NOT_OPEN', 'Essa pendência não está em aberto.'); end if;
    select name into v_name from public.profiles where id = ch.profile_id;
    select st.total_due into v_total from fin_private.charge_statement(ch.id, v_today) st;
    v_payload := jsonb_build_object('charge_id', ch.id, 'profile_id', ch.profile_id, 'member_name', v_name,
      'description', ch.description, 'due_date', ch.due_date, 'total_due_cents', v_total);

    if v_action = 'fin_pendency_collection' then
      v_enabled := (p->>'enabled')::boolean;
      if v_enabled is null then return conv_private.vfail('INVALID_DATA', 'Quer pausar ou retomar a cobrança?'); end if;
      if ch.collection_enabled = v_enabled then
        return conv_private.vfail('ALREADY_SET', case when v_enabled then 'A cobrança dessa pendência já está ativa.' else 'A cobrança dessa pendência já está pausada.' end);
      end if;
      v_payload := v_payload || jsonb_build_object('enabled', v_enabled);

    elsif v_action = 'fin_pendency_send' then
      if not ch.collection_enabled then return conv_private.vfail('COLLECTION_PAUSED', 'A cobrança dessa pendência está pausada. Quer retomar antes?'); end if;
      select count(*), coalesce(sum(st.total_due), 0) into v_open, v_total
      from public.fin_member_charges c cross join lateral fin_private.charge_statement(c.id, v_today) st
      where c.profile_id = ch.profile_id and c.charge_type = 'member_pendency' and c.status in ('open', 'partial') and c.collection_enabled;
      v_payload := v_payload || jsonb_build_object('open_count', v_open, 'member_total_due_cents', v_total);

    else
      v_amount := nullif(p->>'amount_cents', '')::bigint;
      if v_amount is null or v_amount <= 0 or v_amount > 1000000000 then return conv_private.vfail('INVALID_AMOUNT', 'Qual valor foi pago?'); end if;
      v_paid_on := coalesce(nullif(p->>'paid_on', '')::date, v_today);
      if v_paid_on > v_today then return conv_private.vfail('INVALID_DATE', 'A data do pagamento não pode ser no futuro.'); end if;
      v_method := coalesce(nullif(p->>'method', ''), 'pix');
      if v_method not in ('pix', 'transfer', 'cash', 'card', 'other') then v_method := 'other'; end if;
      select string_agg(a.name, ', ' order by a.position, a.name) into v_acc_list from public.fin_accounts a where a.active;
      if nullif(trim(coalesce(p->>'account_name', '')), '') is not null then
        select count(*), min(a.id::text)::uuid into v_acc_n, v_acc_id from public.fin_accounts a
        where a.active and fin_private.fold_text(a.name) like '%' || fin_private.fold_text(p->>'account_name') || '%';
      else
        select count(*), min(a.id::text)::uuid into v_acc_n, v_acc_id from public.fin_accounts a where a.active and a.is_default_receipts;
        if v_acc_n <> 1 then select count(*), min(a.id::text)::uuid into v_acc_n, v_acc_id from public.fin_accounts a where a.active; end if;
      end if;
      if v_acc_n <> 1 then
        return conv_private.vfail('ACCOUNT_REQUIRED', 'Em qual conta entrou o dinheiro? Contas: ' || coalesce(v_acc_list, '(nenhuma ativa)') || '.');
      end if;
      select name into v_acc_name from public.fin_accounts where id = v_acc_id;
      v_payload := v_payload || jsonb_build_object('amount_cents', v_amount, 'paid_on', v_paid_on, 'method', v_method,
        'account_id', v_acc_id, 'account_name', v_acc_name, 'excess_cents', greatest(v_amount - coalesce(v_total, 0), 0));
    end if;
  end if;

  select * into s from public.conv_ai_settings where active order by version desc limit 1;
  update public.conv_booking_proposals set status = 'canceled' where session_id = p_session and status = 'open';
  insert into public.conv_booking_proposals(conversation_id, session_id, requester_contact_id, requester_profile_id, action, payload, expires_at)
  values (sess.conversation_id, p_session, sess.requester_contact_id, v_admin, v_action, v_payload,
    now() + make_interval(mins => coalesce(s.proposal_ttl_minutes, 20)))
  returning id into v_id;
  return jsonb_build_object('ok', true, 'proposal_id', v_id, 'action', v_action, 'summary', v_payload);
exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow or numeric_value_out_of_range then
  return conv_private.vfail('INVALID_DATA', 'Algum dado veio num formato que não entendi (data ou valor).');
end $function$;
--@@ 45 funcao conv_private.ai_admin_finance_propose_w2(p_session uuid, p json
CREATE OR REPLACE FUNCTION conv_private.ai_admin_finance_propose_w2(p_session uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select case when coalesce(p->>'action', '') in ('fin_charge_cancel', 'fin_charge_adjust', 'fin_payment_reverse', 'fin_receipt_reject', 'fin_entry_create')
    then conv_private.ai_admin_finance_propose_ext(p_session, p)
    else conv_private.ai_admin_finance_propose_pendency(p_session, p) end
$function$;
--@@ 45 funcao conv_private.ai_admin_finance_propose_w6(p_session uuid, p json
CREATE OR REPLACE FUNCTION conv_private.ai_admin_finance_propose_w6(p_session uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  sess public.conv_ai_sessions%rowtype; s public.conv_ai_settings%rowtype; v_admin uuid; v_action text := p->>'action';
  v_payload jsonb; v_id uuid; v_today date := conv_private.today(); v_profile uuid; v_date date; v_n int; v_sub record; v_name text;
  v_paid_on date; v_method text; v_acc_id uuid; v_acc_name text; v_acc_n int; v_acc_list text;
  v_left bigint; v_take bigint; v_total bigint := 0; v_alloc jsonb := '[]'::jsonb; v_open bigint := 0; ch record; v_due bigint;
begin
  select * into sess from public.conv_ai_sessions where id = p_session and status = 'open' for update;
  if not found then return conv_private.vfail('SESSION_CLOSED', 'Atendimento encerrado.'); end if;
  v_admin := conv_private.ai_admin_requester(p_session);
  if v_admin is null then
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;

  if v_action = 'fin_receipt_approve' then
    v_profile := nullif(p->>'profile_id', '')::uuid;
    v_date := nullif(p->>'receipt_date', '')::date;
    select count(*) into v_n from public.fin_receipt_submissions r
    where r.profile_id = v_profile and r.status in ('submitted', 'in_review')
      and (v_date is null or (r.created_at at time zone 'America/Fortaleza')::date = v_date);
    if v_n = 0 then return conv_private.vfail('RECEIPT_NOT_FOUND', 'Não achei comprovante pendente desse sócio.'); end if;
    if v_n > 1 then
      return conv_private.vfail('RECEIPT_AMBIGUOUS', 'Esse sócio tem ' || v_n || ' comprovantes pendentes. De qual dia é o que você quer aprovar?');
    end if;
    select r.id, r.declared_amount_cents, r.declared_paid_on, r.created_at into v_sub from public.fin_receipt_submissions r
    where r.profile_id = v_profile and r.status in ('submitted', 'in_review')
      and (v_date is null or (r.created_at at time zone 'America/Fortaleza')::date = v_date);
    if v_sub.declared_amount_cents is null or v_sub.declared_amount_cents <= 0 then
      return conv_private.vfail('RECEIPT_AMOUNT_UNKNOWN', 'Não consegui ler o valor desse comprovante. Aprove pelo painel (Financeiro), onde você confere a imagem.');
    end if;
    select name into v_name from public.profiles where id = v_profile;
    v_paid_on := coalesce(nullif(p->>'paid_on', '')::date, v_sub.declared_paid_on, v_today);
    if v_paid_on > v_today then return conv_private.vfail('INVALID_DATE', 'A data do pagamento não pode ser no futuro.'); end if;
    v_method := coalesce(nullif(p->>'method', ''), 'pix');
    if v_method not in ('pix', 'transfer', 'cash', 'card', 'other') then v_method := 'pix'; end if;

    -- Conta pelo nome; sem nome vale a conta padrão de recebimentos (ou a única ativa).
    select string_agg(a.name, ', ' order by a.position, a.name) into v_acc_list from public.fin_accounts a where a.active;
    if nullif(trim(coalesce(p->>'account_name', '')), '') is not null then
      select count(*), min(a.id::text)::uuid into v_acc_n, v_acc_id from public.fin_accounts a
      where a.active and fin_private.fold_text(a.name) like '%' || fin_private.fold_text(p->>'account_name') || '%';
    else
      select count(*), min(a.id::text)::uuid into v_acc_n, v_acc_id from public.fin_accounts a where a.active and a.is_default_receipts;
      if v_acc_n <> 1 then select count(*), min(a.id::text)::uuid into v_acc_n, v_acc_id from public.fin_accounts a where a.active; end if;
    end if;
    if v_acc_n <> 1 then
      return conv_private.vfail('ACCOUNT_REQUIRED', 'Em qual conta entrou? Contas: ' || coalesce(v_acc_list, '(nenhuma ativa)') || '.');
    end if;
    select name into v_acc_name from public.fin_accounts where id = v_acc_id;

    -- Distribuição: cobranças em aberto do sócio, da mais antiga para a mais nova, pelo saldo na data do pagamento.
    v_left := v_sub.declared_amount_cents;
    for ch in select c.id, c.description, c.due_date from public.fin_member_charges c
              where c.profile_id = v_profile and c.status in ('open', 'partial') order by c.due_date, c.created_at loop
      select st.total_due into v_due from fin_private.charge_statement(ch.id, v_paid_on) st;
      if coalesce(v_due, 0) <= 0 then continue; end if;
      v_open := v_open + v_due;
      if v_left > 0 then
        v_take := least(v_left, v_due);
        v_alloc := v_alloc || jsonb_build_array(jsonb_build_object('charge_id', ch.id, 'amount_cents', v_take,
          'description', coalesce(ch.description, 'Mensalidade'), 'due_date', ch.due_date));
        v_left := v_left - v_take; v_total := v_total + v_take;
      end if;
    end loop;
    if jsonb_array_length(v_alloc) = 0 then
      return conv_private.vfail('NO_OPEN_CHARGES', 'Esse sócio não tem cobrança em aberto para receber esse comprovante. Veja no painel (Financeiro).');
    end if;
    if v_left > 0 then
      return conv_private.vfail('RECEIPT_EXCEEDS_OPEN', 'O comprovante (R$ ' || replace(trim(to_char(v_sub.declared_amount_cents::numeric / 100, 'FM999999990D00')), '.', ',')
        || ') passa do que esse sócio tem em aberto (R$ ' || replace(trim(to_char(v_open::numeric / 100, 'FM999999990D00')), '.', ',')
        || '). A sobra é tratada no painel (Financeiro).');
    end if;
    v_payload := jsonb_strip_nulls(jsonb_build_object('submission_id', v_sub.id, 'profile_id', v_profile, 'member_name', v_name,
      'amount_cents', v_total, 'paid_on', v_paid_on, 'method', v_method, 'account_id', v_acc_id, 'account_name', v_acc_name,
      'sent_on', (v_sub.created_at at time zone 'America/Fortaleza')::date, 'allocations', v_alloc));

  elsif v_action = 'fin_charges_generate' then
    select count(*) into v_n from public.fin_member_plans where status = 'active';
    if v_n = 0 then return conv_private.vfail('NO_ACTIVE_PLANS', 'Não há plano de sócio ativo para gerar cobrança.'); end if;
    v_payload := jsonb_build_object('plans_count', v_n);
  else
    return conv_private.ai_admin_finance_propose_w2(p_session, p);
  end if;

  select * into s from public.conv_ai_settings where active order by version desc limit 1;
  update public.conv_booking_proposals set status = 'canceled' where session_id = p_session and status = 'open';
  insert into public.conv_booking_proposals(conversation_id, session_id, requester_contact_id, requester_profile_id, action, payload, expires_at)
  values (sess.conversation_id, p_session, sess.requester_contact_id, v_admin, v_action, v_payload,
    now() + make_interval(mins => coalesce(s.proposal_ttl_minutes, 20)))
  returning id into v_id;
  return jsonb_build_object('ok', true, 'proposal_id', v_id, 'action', v_action, 'summary', v_payload);
exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow or numeric_value_out_of_range then
  return conv_private.vfail('INVALID_DATA', 'Algum dado veio num formato que não entendi (data ou valor).');
end $function$;
--@@ 45 funcao conv_private.ai_admin_members(p_session uuid)
CREATE OR REPLACE FUNCTION conv_private.ai_admin_members(p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_admin uuid;
begin
  v_admin := conv_private.ai_admin_requester(p_session);
  if v_admin is null then
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador consulta, e só na conversa privada comigo.');
  end if;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object('members',
    coalesce((select jsonb_agg(jsonb_build_object('name', p.name, 'role', p.role::text) order by p.name)
              from public.profiles p where coalesce(p.is_active, true) and p.role::text in ('socio', 'admin')), '[]'::jsonb)));
end $function$;
--@@ 45 funcao conv_private.ai_admin_memories(p_session uuid, p_subject text)
CREATE OR REPLACE FUNCTION conv_private.ai_admin_memories(p_session uuid, p_subject text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_admin uuid; v_s text := nullif(trim(coalesce(p_subject, '')), '');
begin
  v_admin := conv_private.ai_admin_requester(p_session);
  if v_admin is null then
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador consulta, e só na conversa privada comigo.');
  end if;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object('subject', v_s,
    'items', coalesce((select jsonb_agg(jsonb_build_object('subject_name', m.subject_name, 'kind', m.kind, 'content', m.content) order by m.subject_name, m.created_at)
                       from (select * from public.conv_ai_memory_candidates c where c.status = 'approved'
                             and (v_s is null or lower(c.subject_name) like '%' || lower(v_s) || '%' or lower(v_s) like lower(split_part(c.subject_name, ' ', 1)) || '%')
                             order by c.created_at desc limit 30) m), '[]'::jsonb)));
end $function$;
--@@ 45 funcao conv_private.ai_admin_memory_forget_propose(p_session uuid, p j
CREATE OR REPLACE FUNCTION conv_private.ai_admin_memory_forget_propose(p_session uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  sess public.conv_ai_sessions%rowtype; s public.conv_ai_settings%rowtype; v_admin uuid; v_id uuid; v_payload jsonb;
  v_subject text := nullif(trim(coalesce(p->>'subject', '')), ''); v_text text := nullif(trim(coalesce(p->>'text', '')), ''); v_items jsonb;
begin
  select * into sess from public.conv_ai_sessions where id = p_session and status = 'open' for update;
  if not found then return conv_private.vfail('SESSION_CLOSED', 'Atendimento encerrado.'); end if;
  v_admin := conv_private.ai_admin_requester(p_session);
  if v_admin is null then
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;
  if v_subject is null then return conv_private.vfail('SUBJECT_REQUIRED', 'Sobre quem é a memória que devo esquecer?'); end if;
  select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'subject_name', m.subject_name, 'content', m.content) order by m.created_at), '[]'::jsonb) into v_items
  from (select * from public.conv_ai_memory_candidates c where c.status = 'approved'
        and (lower(c.subject_name) like '%' || lower(v_subject) || '%' or lower(v_subject) like lower(split_part(c.subject_name, ' ', 1)) || '%')
        and (v_text is null or lower(c.content) like '%' || lower(v_text) || '%') order by c.created_at desc limit 10) m;
  if jsonb_array_length(v_items) = 0 then
    return conv_private.vfail('NOTHING_TO_FORGET', 'Não tenho nenhuma memória guardada ' || case when v_text is null then 'sobre ' || v_subject else 'sobre ' || v_subject || ' com "' || v_text || '"' end || '.');
  end if;
  v_payload := jsonb_build_object('subject', v_subject, 'items', v_items);
  select * into s from public.conv_ai_settings where active order by version desc limit 1;
  update public.conv_booking_proposals set status = 'canceled' where session_id = p_session and status = 'open';
  insert into public.conv_booking_proposals(conversation_id, session_id, requester_contact_id, requester_profile_id, action, payload, expires_at)
  values (sess.conversation_id, p_session, sess.requester_contact_id, v_admin, 'adm_memory_forget', v_payload,
    now() + make_interval(mins => coalesce(s.proposal_ttl_minutes, 20)))
  returning id into v_id;
  return jsonb_build_object('ok', true, 'proposal_id', v_id, 'action', 'adm_memory_forget', 'summary', v_payload);
end $function$;
--@@ 45 funcao conv_private.ai_admin_message_propose(p_session uuid, p jsonb)
CREATE OR REPLACE FUNCTION conv_private.ai_admin_message_propose(p_session uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  sess public.conv_ai_sessions%rowtype; s public.conv_ai_settings%rowtype; v_admin uuid; v_id uuid; v_payload jsonb;
  v_profile uuid := nullif(p->>'profile_id', '')::uuid; pr public.profiles%rowtype; v_body text := trim(coalesce(p->>'body', ''));
  v_phone text;
begin
  select * into sess from public.conv_ai_sessions where id = p_session and status = 'open' for update;
  if not found then return conv_private.vfail('SESSION_CLOSED', 'Atendimento encerrado.'); end if;
  v_admin := conv_private.ai_admin_requester(p_session);
  if v_admin is null then
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;
  select * into pr from public.profiles where id = v_profile and coalesce(is_active, true);
  if pr.id is null then return conv_private.vfail('MEMBER_NOT_FOUND', 'Não achei esse sócio ativo.'); end if;
  v_phone := conv_private.phone_e164(pr.phone);
  if v_phone is null or length(v_phone) < 12 then
    return conv_private.vfail('NO_PHONE', pr.name || ' não tem telefone válido no cadastro, então não consigo chamar no WhatsApp.');
  end if;
  if exists (select 1 from public.conv_contacts c where c.phone = v_phone and c.opt_out) then
    return conv_private.vfail('OPT_OUT', pr.name || ' pediu para não receber mensagens por aqui.');
  end if;
  if length(v_body) not between 3 and 1000 then return conv_private.vfail('INVALID_BODY', 'Qual o texto da mensagem?'); end if;
  v_payload := jsonb_build_object('profile_id', pr.id, 'member_name', pr.name, 'phone', v_phone, 'body', v_body);
  select * into s from public.conv_ai_settings where active order by version desc limit 1;
  update public.conv_booking_proposals set status = 'canceled' where session_id = p_session and status = 'open';
  insert into public.conv_booking_proposals(conversation_id, session_id, requester_contact_id, requester_profile_id, action, payload, expires_at)
  values (sess.conversation_id, p_session, sess.requester_contact_id, v_admin, 'adm_message_send', v_payload,
    now() + make_interval(mins => coalesce(s.proposal_ttl_minutes, 20)))
  returning id into v_id;
  return jsonb_build_object('ok', true, 'proposal_id', v_id, 'action', 'adm_message_send', 'summary', v_payload);
end $function$;
--@@ 45 funcao conv_private.ai_admin_prefs(p_session uuid)
CREATE OR REPLACE FUNCTION conv_private.ai_admin_prefs(p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_admin uuid := conv_private.ai_admin_requester(p_session);
begin
  if v_admin is null then return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador consulta, e só na conversa privada comigo.'); end if;
  return jsonb_build_object('ok', true, 'prefs', conv_private.admin_prefs_json(v_admin));
end $function$;
--@@ 45 funcao conv_private.ai_admin_read(p_session uuid, p_domain text, p_arg
CREATE OR REPLACE FUNCTION conv_private.ai_admin_read(p_session uuid, p_domain text, p_args jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_admin uuid; v_prev_claims text; v_prev_sub text; v_err text; v_out jsonb;
  v_today date := (now() at time zone 'America/Fortaleza')::date;
  v_from date; v_to date; v_day date;
begin
  v_admin := conv_private.ai_admin_requester(p_session);
  if v_admin is null then
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador consulta, e só na conversa privada comigo.');
  end if;
  begin
    v_from := coalesce(nullif(p_args->>'from', '')::date, date_trunc('month', v_today)::date);
    v_to := coalesce(nullif(p_args->>'to', '')::date, v_today);
    v_day := coalesce(nullif(p_args->>'date', '')::date, v_today);
  exception when others then
    return conv_private.vfail('INVALID_DATA', 'Não entendi o período. Pode dizer as datas?');
  end;
  if v_to < v_from or v_to - v_from > 731 then
    return conv_private.vfail('INVALID_DATA', 'Esse período não vale (início depois do fim, ou mais de 2 anos).');
  end if;

  v_prev_claims := current_setting('request.jwt.claims', true);
  v_prev_sub := current_setting('request.jwt.claim.sub', true);
  perform set_config('request.jwt.claims', jsonb_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
  perform set_config('request.jwt.claim.sub', v_admin::text, true);
  begin
    if p_domain = 'caixa' then
      select jsonb_build_object('from', v_from, 'to', v_to,
        'opening_cents', (array_agg(opening_cents order by bucket_start))[1],
        'inflow_cents', coalesce(sum(inflow_cents), 0), 'outflow_cents', coalesce(sum(outflow_cents), 0),
        'net_cents', coalesce(sum(net_cents), 0),
        'closing_cents', (array_agg(closing_cents order by bucket_start desc))[1])
      into v_out from public.fin_cash_flow(v_from, v_to, 'month', null);
    elsif p_domain = 'receber_pagar' then
      select jsonb_build_object('receivables', (select to_jsonb(r) from public.fin_receivables_summary(v_today) r),
                                'payables', (select to_jsonb(p) from public.fin_payables_summary(v_today) p))
      into v_out;
    elsif p_domain = 'dre' then
      -- fin_dre_lines devolve o período pedido ('current') e o anterior de mesma duração ('previous'); valores sempre positivos.
      select jsonb_build_object('from', v_from, 'to', v_to,
        'by_line', coalesce((select jsonb_agg(jsonb_build_object('line', line, 'amount_cents', amt) order by line)
                             from (select line, sum(amount_cents)::bigint amt from public.fin_dre_lines(v_from, v_to) where period = 'current' group by line) x), '[]'::jsonb),
        'previous_by_line', coalesce((select jsonb_agg(jsonb_build_object('line', line, 'amount_cents', amt) order by line)
                             from (select line, sum(amount_cents)::bigint amt from public.fin_dre_lines(v_from, v_to) where period = 'previous' group by line) w), '[]'::jsonb),
        'top', coalesce((select jsonb_agg(jsonb_build_object('line', line, 'name', name, 'amount_cents', amt) order by amt desc)
                         from (select line, name, sum(amount_cents)::bigint amt from public.fin_dre_lines(v_from, v_to)
                               where period = 'current' group by line, name having sum(amount_cents) <> 0 order by sum(amount_cents) desc limit 12) y), '[]'::jsonb))
      into v_out;
    elsif p_domain = 'comparativo' then
      -- Período pedido x anterior de mesma duração (fin_dre_lines), por categoria, para explicar o que mudou.
      select jsonb_build_object('from', v_from, 'to', v_to,
        'by_line', coalesce((select jsonb_agg(jsonb_build_object('line', line, 'amount_cents', amt) order by line)
                             from (select line, sum(amount_cents)::bigint amt from public.fin_dre_lines(v_from, v_to) where period = 'current' group by line) x), '[]'::jsonb),
        'previous_by_line', coalesce((select jsonb_agg(jsonb_build_object('line', line, 'amount_cents', amt) order by line)
                             from (select line, sum(amount_cents)::bigint amt from public.fin_dre_lines(v_from, v_to) where period = 'previous' group by line) w), '[]'::jsonb),
        'changes', coalesce((select jsonb_agg(jsonb_build_object('line', line, 'name', name, 'current_cents', cur, 'previous_cents', prev, 'delta_cents', cur - prev) order by abs(cur - prev) desc)
                             from (select line, name,
                                          coalesce(sum(amount_cents) filter (where period = 'current'), 0)::bigint cur,
                                          coalesce(sum(amount_cents) filter (where period = 'previous'), 0)::bigint prev
                                   from public.fin_dre_lines(v_from, v_to) group by line, name
                                   having coalesce(sum(amount_cents) filter (where period = 'current'), 0) <> coalesce(sum(amount_cents) filter (where period = 'previous'), 0)
                                   order by abs(coalesce(sum(amount_cents) filter (where period = 'current'), 0) - coalesce(sum(amount_cents) filter (where period = 'previous'), 0)) desc limit 10) c), '[]'::jsonb))
      into v_out;
    elsif p_domain = 'followups' then
      select jsonb_build_object('items', coalesce(jsonb_agg(jsonb_build_object('who', x.who, 'note', x.note, 'due_at', x.due_at, 'sends', x.sends) order by x.due_at), '[]'::jsonb))
      into v_out from (
        select coalesce(pr.name, g.name, ct.name, 'Conversa') who, f.note, f.due_at, f.send_body is not null sends
        from public.conv_followups f join public.conv_conversations cv on cv.id = f.conversation_id
        left join public.conv_contacts ct on ct.id = cv.contact_id left join public.profiles pr on pr.id = ct.profile_id
        left join public.conv_groups g on g.id = cv.group_id
        where f.status = 'pending' order by f.due_at limit 15) x;
    elsif p_domain = 'preferencias' then
      v_out := conv_private.admin_prefs_json(v_admin);
    elsif p_domain = 'receita_alunos' then
      select jsonb_build_object('from', v_from, 'to', v_to, 'count', count(*), 'total_cents', coalesce(sum(amount_cents), 0),
        'by_category', coalesce((select jsonb_agg(jsonb_build_object('name', coalesce(category_name, 'Sem categoria'), 'amount_cents', amt) order by amt desc)
                                 from (select category_name, sum(amount_cents)::bigint amt from public.fin_student_revenue(v_from, v_to) group by category_name) z), '[]'::jsonb))
      into v_out from public.fin_student_revenue(v_from, v_to);
    elsif p_domain = 'comprovantes' then
      select jsonb_build_object('total', coalesce(max(total_count), 0),
        'items', coalesce(jsonb_agg(jsonb_build_object('member', profile_name, 'status', status, 'declared_amount_cents', declared_amount_cents,
          'declared_paid_on', declared_paid_on, 'possible_duplicate', possible_duplicate, 'created_at', created_at) order by created_at), '[]'::jsonb))
      into v_out from public.fin_receipt_queue('pending', 15, 0);
    elsif p_domain = 'acessos' then
      select jsonb_build_object('total', count(*),
        'items', coalesce(jsonb_agg(jsonb_build_object('name', name, 'created_at', created_at) order by created_at) filter (where rn <= 15), '[]'::jsonb))
      into v_out from (select name, created_at, row_number() over (order by created_at) rn from public.access_requests where status = 'pending') a;
    elsif p_domain = 'assinaturas' then
      select jsonb_build_object('documents', coalesce(jsonb_agg(jsonb_build_object('title', title, 'version', version, 'due_at', due_at,
        'recipients', recipients, 'signed', signed, 'notifications_failed', notifications_failed, 'no_phone', no_phone) order by published_at desc), '[]'::jsonb))
      into v_out from public.sig_documents_overview where status = 'published';
    elsif p_domain = 'ocupacao' then
      select jsonb_build_object('date', v_day, 'items', coalesce(jsonb_agg(jsonb_build_object('court', c.name, 'start', to_char(r.start_time, 'HH24:MI'),
        'end', to_char(r.end_time, 'HH24:MI'), 'type', r.type, 'by', coalesce(p.name, r.guest_name)) order by c.name, r.start_time), '[]'::jsonb))
      into v_out from public.reservations r join public.courts c on c.id = r.court_id left join public.profiles p on p.id = r.creator_id
      where r.date = v_day and coalesce(r.status::text, 'active') = 'active';
    else
      v_err := 'UNKNOWN_DOMAIN';
    end if;
  exception when others then
    v_err := sqlerrm;
  end;
  perform set_config('request.jwt.claims', coalesce(v_prev_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(v_prev_sub, ''), true);

  if v_err is not null then
    return conv_private.vfail(case when v_err ~ '^[A-Z][A-Z_]+$' then v_err else 'READ_FAILED' end,
      'Não consegui consultar isso agora.');
  end if;
  perform conv_private.audit('ai_admin_read', 'conv_ai_sessions', p_session::text, null,
    jsonb_build_object('domain', p_domain, 'from', v_from, 'to', v_to),
    jsonb_build_object('actor', 'ai', 'source', 'whatsapp', 'requester_profile_id', v_admin), v_admin);
  return jsonb_build_object('ok', true, 'domain', p_domain, 'data', v_out);
end $function$;
--@@ 45 funcao conv_private.ai_admin_read_more(p_session uuid, p_domain text, 
CREATE OR REPLACE FUNCTION conv_private.ai_admin_read_more(p_session uuid, p_domain text, p_args jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_admin uuid; v_out jsonb; v_today date := (now() at time zone 'America/Fortaleza')::date;
  v_from date; v_to date; v_profile uuid := nullif(p_args->>'profile_id', '')::uuid; v_days int;
begin
  v_admin := conv_private.ai_admin_requester(p_session);
  if v_admin is null then
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador consulta, e só na conversa privada comigo.');
  end if;
  begin
    v_from := coalesce(nullif(p_args->>'from', '')::date, date_trunc('month', v_today)::date);
    v_to := coalesce(nullif(p_args->>'to', '')::date, v_today);
    v_days := least(greatest(coalesce(nullif(p_args->>'days', '')::int, 30), 1), 120);
  exception when others then
    return conv_private.vfail('INVALID_DATA', 'Não entendi o período. Pode dizer as datas?');
  end;
  if v_to < v_from or v_to - v_from > 731 then
    return conv_private.vfail('INVALID_DATA', 'Esse período não vale (início depois do fim, ou mais de 2 anos).');
  end if;

  if p_domain = 'inadimplentes' then
    select jsonb_build_object('as_of', v_today,
      'total_cents', coalesce(sum(t.total), 0), 'members', count(*),
      'items', coalesce(jsonb_agg(jsonb_build_object('name', t.name, 'total_cents', t.total, 'charges', t.n, 'days_late', t.late) order by t.total desc) filter (where t.rk <= 30), '[]'::jsonb))
    into v_out from (
      select r.profile_name name, sum(r.total_due_cents)::bigint total, count(*)::int n, max(r.days_late)::int late,
             row_number() over (order by sum(r.total_due_cents) desc) rk
      from fin_private.charge_rows(null, null, '{}'::jsonb, v_today, 5000, 0) r where r.overdue and r.total_due_cents > 0
      group by r.profile_id, r.profile_name) t;
  elsif p_domain = 'pagamentos' then
    select jsonb_build_object('from', v_from, 'to', v_to, 'total_cents', coalesce(sum(t.paid), 0), 'members', count(*),
      'items', coalesce(jsonb_agg(jsonb_build_object('name', t.name, 'paid_cents', t.paid, 'last', t.last) order by t.last desc, t.name) filter (where t.rk <= 40), '[]'::jsonb))
    into v_out from (
      select r.profile_name name, sum(r.principal_paid_cents)::bigint paid, max(r.last_payment_on) last,
             row_number() over (order by max(r.last_payment_on) desc, r.profile_name) rk
      from fin_private.charge_rows(null, null, '{}'::jsonb, v_today, 5000, 0) r
      where r.last_payment_on between v_from and v_to and r.principal_paid_cents > 0
      group by r.profile_id, r.profile_name) t;
  elsif p_domain = 'socio_ficha' then
    if v_profile is null then return conv_private.vfail('MEMBER_REQUIRED', 'De qual sócio?'); end if;
    select jsonb_build_object('name', p.name, 'role', p.role::text, 'active', coalesce(p.is_active, true), 'phone', p.phone,
      'since', p.created_at::date,
      'overdue_cents', coalesce((select sum(r.total_due_cents) from fin_private.charge_rows(v_profile, null, '{}'::jsonb, v_today, 500, 0) r where r.overdue), 0),
      'open_cents', coalesce((select sum(r.total_due_cents) from fin_private.charge_rows(v_profile, null, '{}'::jsonb, v_today, 500, 0) r where r.display_status in ('open', 'overdue', 'partial')), 0),
      'next_due', (select min(r.due_date) from fin_private.charge_rows(v_profile, null, '{}'::jsonb, v_today, 500, 0) r where r.display_status in ('open', 'overdue', 'partial', 'forecast') and r.principal_remaining_cents > 0),
      'last_payment', (select max(r.last_payment_on) from fin_private.charge_rows(v_profile, null, '{}'::jsonb, v_today, 500, 0) r),
      'dependents', coalesce((select jsonb_agg(d.name order by d.name) from public.non_socio_students d where d.responsible_socio_id = p.id and coalesce(d.is_active, true)), '[]'::jsonb))
    into v_out from public.profiles p where p.id = v_profile;
    if v_out is null then return conv_private.vfail('MEMBER_NOT_FOUND', 'Não achei esse sócio.'); end if;
  elsif p_domain = 'vencimentos' then
    select jsonb_build_object('until', v_today + v_days, 'payable_cents', coalesce(sum(e.amount_cents) filter (where e.kind = 'expense'), 0),
      'receivable_cents', coalesce(sum(e.amount_cents) filter (where e.kind = 'revenue'), 0),
      'items', coalesce(jsonb_agg(jsonb_build_object('kind', e.kind, 'description', e.description, 'supplier', e.supplier, 'due_date', e.due_date, 'amount_cents', e.amount_cents, 'late', e.due_date < v_today) order by e.due_date, e.amount_cents desc), '[]'::jsonb))
    into v_out from (select * from public.fin_entries x where x.status = 'pending' and x.due_date <= v_today + v_days order by x.due_date limit 30) e;
  elsif p_domain = 'alunos' then
    select jsonb_build_object('regular', count(*) filter (where s.student_type = 'regular'), 'dependent', count(*) filter (where s.student_type = 'dependent'),
      'items', coalesce(jsonb_agg(jsonb_build_object('name', s.name, 'type', s.student_type, 'plan', s.plan_type, 'expires', s.master_expiration_date) order by s.name) filter (where s.student_type = 'regular'), '[]'::jsonb))
    into v_out from public.non_socio_students s where coalesce(s.is_active, true) and s.plan_status = 'active';
  elsif p_domain = 'movimentos' then
    select jsonb_build_object('items', coalesce(jsonb_agg(jsonb_build_object('kind', e.kind, 'description', e.description, 'amount_cents', e.amount_cents, 'on', e.settled_on) order by e.settled_on desc, e.created_at desc), '[]'::jsonb))
    into v_out from (select * from public.fin_entries x where x.status = 'paid' and x.settled_on is not null order by x.settled_on desc, x.created_at desc limit 15) e;
  else
    return conv_private.vfail('INVALID_DOMAIN', 'Essa consulta eu ainda não sei fazer.');
  end if;
  perform conv_private.audit('ai_admin_read', 'conv_ai_sessions', p_session::text, null,
    jsonb_build_object('domain', p_domain), jsonb_build_object('actor', 'ai', 'source', 'whatsapp', 'requester_profile_id', v_admin), v_admin);
  return jsonb_build_object('ok', true, 'domain', p_domain, 'data', v_out);
end $function$;
--@@ 45 funcao conv_private.ai_admin_receipt(p_session uuid, p_message uuid)
CREATE OR REPLACE FUNCTION conv_private.ai_admin_receipt(p_session uuid, p_message uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sess public.conv_ai_sessions%rowtype; r public.fin_receipt_submissions%rowtype; fs public.fin_settings%rowtype; v_payee text;
begin
  select * into sess from public.conv_ai_sessions where id = p_session and status = 'open';
  if not found or conv_private.ai_admin_requester(p_session) is null then
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;
  select r2.* into r from public.fin_receipt_submissions r2
    join public.conv_messages m on m.id = r2.source_message_id
   where r2.source_message_id = p_message and m.conversation_id = sess.conversation_id;
  if not found then return jsonb_build_object('ok', true, 'found', false); end if;
  select * into fs from public.fin_settings where id;
  v_payee := nullif(trim(coalesce(r.ocr->>'payee', '')), '');
  return jsonb_build_object('ok', true, 'found', true, 'status', r.status, 'ocr_status', r.ocr_status,
    'amount_cents', r.declared_amount_cents, 'paid_on', r.declared_paid_on, 'payee', v_payee,
    'payee_ok', case when v_payee is null then null else fin_private.payee_matches(v_payee, fs.payee_names) end,
    'duplicate', r.possible_duplicate);
end $function$;
--@@ 45 funcao conv_private.ai_admin_requester(p_session uuid)
CREATE OR REPLACE FUNCTION conv_private.ai_admin_requester(p_session uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select c.profile_id
  from public.conv_ai_sessions s
  join public.conv_conversations cv on cv.id = s.conversation_id and cv.kind = 'direct'
  join public.conv_contacts c on c.id = s.requester_contact_id and c.link_status in ('linked', 'manual')
  join public.profiles p on p.id = c.profile_id and p.role::text = 'admin' and coalesce(p.is_active, true)
  where s.id = p_session
$function$;
--@@ 45 funcao conv_private.ai_admin_wave8_propose(p_session uuid, p jsonb)
CREATE OR REPLACE FUNCTION conv_private.ai_admin_wave8_propose(p_session uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  sess public.conv_ai_sessions%rowtype; s public.conv_ai_settings%rowtype; v_admin uuid; v_action text := p->>'action';
  v_id uuid; v_payload jsonb; v_now timestamp := now() at time zone 'America/Fortaleza';
  v_prof record; v_n int; v_list text; v_conv uuid; v_name text; v_date date; v_time time; v_due timestamptz; v_note text; v_send text;
  v_fu record; v_court record; v_start int; v_dur int; v_end int; v_pref text := p->>'pref'; v_val text := nullif(trim(coalesce(p->>'value', '')), '');
  v_active boolean; v_amount bigint; v_acc record; v_who text;
begin
  select * into sess from public.conv_ai_sessions where id = p_session and status = 'open' for update;
  if not found then return conv_private.vfail('SESSION_CLOSED', 'Atendimento encerrado.'); end if;
  v_admin := conv_private.ai_admin_requester(p_session);
  if v_admin is null then
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;
  v_active := case when p ? 'active' and jsonb_typeof(p->'active') = 'boolean' then (p->>'active')::boolean end;

  if v_action in ('adm_followup_create', 'adm_followup_done') then
    -- Sem nome vale a própria conversa do administrador (lembrete para si).
    if nullif(trim(coalesce(p->>'member_name', '')), '') is null then
      v_conv := sess.conversation_id; v_name := null;
    else
      select count(*) into v_n from public.profiles pr where coalesce(pr.is_active, true) and fin_private.fold_text(pr.name) like '%' || fin_private.fold_text(p->>'member_name') || '%';
      if v_n = 0 then return conv_private.vfail('MEMBER_NOT_FOUND', 'Não achei "' || (p->>'member_name') || '" entre os cadastros.'); end if;
      if v_n > 1 then
        select string_agg(x.name, ', ') into v_list from (select pr.name from public.profiles pr where coalesce(pr.is_active, true)
          and fin_private.fold_text(pr.name) like '%' || fin_private.fold_text(p->>'member_name') || '%' order by pr.name limit 8) x;
        return conv_private.vfail('MEMBER_AMBIGUOUS', 'Tenho mais de um "' || (p->>'member_name') || '": ' || v_list || '. Qual deles?');
      end if;
      select pr.id, pr.name into v_prof from public.profiles pr where coalesce(pr.is_active, true) and fin_private.fold_text(pr.name) like '%' || fin_private.fold_text(p->>'member_name') || '%';
      v_name := v_prof.name;
      select cv.id into v_conv from public.conv_contacts c join public.conv_conversations cv on cv.contact_id = c.id and cv.kind = 'direct' and cv.merged_into is null
      where c.profile_id = v_prof.id and c.merged_into is null order by cv.last_message_at desc nulls last limit 1;
      if v_conv is null then return conv_private.vfail('NO_CONVERSATION', v_name || ' ainda não tem conversa comigo, então não dá para ligar um retorno a ela.'); end if;
    end if;
    v_who := coalesce(v_name, 'você');

    if v_action = 'adm_followup_create' then
      v_note := nullif(trim(coalesce(p->>'note', '')), '');
      v_send := nullif(trim(coalesce(p->>'send_body', '')), '');
      if v_note is null and v_send is null then return conv_private.vfail('FOLLOWUP_EMPTY', 'O que é para lembrar? Me diga a anotação do retorno.'); end if;
      v_date := nullif(p->>'date', '')::date;
      if v_date is null then return conv_private.vfail('INVALID_DATA', 'Para quando? Me diga o dia (e a hora, se quiser; senão uso 09h).'); end if;
      v_time := coalesce(nullif(p->>'start', '')::time, time '09:00');
      v_due := ((v_date::text || ' ' || v_time::text || '-03')::timestamptz);
      if v_due <= now() then return conv_private.vfail('INVALID_DUE_DATE', 'Esse horário já passou. Para quando então?'); end if;
      if v_name is null and v_send is null then v_send := 'Lembrete: ' || v_note; end if;
      v_payload := jsonb_strip_nulls(jsonb_build_object('conversation_id', v_conv, 'member_name', v_name, 'due_at', v_due, 'note', v_note, 'send_body', v_send, 'self', v_name is null));
    else
      select count(*) into v_n from public.conv_followups f where f.conversation_id = v_conv and f.status = 'pending'
        and (nullif(p->>'date', '') is null or (f.due_at at time zone 'America/Fortaleza')::date = (p->>'date')::date);
      if v_n = 0 then return conv_private.vfail('FOLLOWUP_NOT_FOUND', 'Não achei retorno pendente' || case when v_name is null then ' seu.' else ' de ' || v_name || '.' end); end if;
      if v_n > 1 then
        select string_agg(to_char(x.due_at at time zone 'America/Fortaleza', 'DD/MM HH24:MI') || coalesce(' (' || x.note || ')', ''), '; ' order by x.due_at) into v_list
        from (select f.due_at, f.note from public.conv_followups f where f.conversation_id = v_conv and f.status = 'pending' order by f.due_at limit 6) x;
        return conv_private.vfail('FOLLOWUP_AMBIGUOUS', 'Há ' || v_n || ' retornos pendentes: ' || v_list || '. De qual dia é o que você quer?');
      end if;
      select f.id, f.note, f.due_at into v_fu from public.conv_followups f where f.conversation_id = v_conv and f.status = 'pending'
        and (nullif(p->>'date', '') is null or (f.due_at at time zone 'America/Fortaleza')::date = (p->>'date')::date);
      v_payload := jsonb_strip_nulls(jsonb_build_object('followup_id', v_fu.id, 'member_name', v_name, 'note', v_fu.note, 'due_at', v_fu.due_at,
        'new_status', case when v_active is false then 'canceled' else 'done' end));
    end if;

  elsif v_action = 'adm_court_block' then
    if nullif(trim(coalesce(p->>'court_label', '')), '') is null then return conv_private.vfail('COURT_REQUIRED', 'Qual quadra?'); end if;
    select count(*) into v_n from public.courts c where coalesce(c.is_active, true) and fin_private.fold_text(c.name) like '%' || fin_private.fold_text(p->>'court_label') || '%';
    if v_n = 0 then return conv_private.vfail('COURT_NOT_FOUND', 'Não achei a quadra "' || (p->>'court_label') || '".'); end if;
    if v_n > 1 then
      select string_agg(c.name, ', ' order by c.name) into v_list from public.courts c where coalesce(c.is_active, true) and fin_private.fold_text(c.name) like '%' || fin_private.fold_text(p->>'court_label') || '%';
      return conv_private.vfail('COURT_AMBIGUOUS', 'Qual destas quadras: ' || v_list || '?');
    end if;
    select c.id, c.name into v_court from public.courts c where coalesce(c.is_active, true) and fin_private.fold_text(c.name) like '%' || fin_private.fold_text(p->>'court_label') || '%';
    v_date := nullif(p->>'date', '')::date; v_time := nullif(p->>'start', '')::time;
    if v_date is null or v_time is null then return conv_private.vfail('INVALID_DATA', 'Qual o dia e o horário de início do bloqueio?'); end if;
    v_dur := nullif(p->>'duration', '')::int;
    if v_dur is null or v_dur < 30 or v_dur > 720 or v_dur % 30 <> 0 then return conv_private.vfail('INVALID_DURATION', 'Por quanto tempo? (de 30 em 30 minutos, até 12 horas)'); end if;
    v_start := extract(hour from v_time)::int * 60 + extract(minute from v_time)::int; v_end := v_start + v_dur;
    if v_end > 1440 then return conv_private.vfail('INVALID_DURATION', 'O bloqueio passa da meia-noite. Faça até 24h e outro no dia seguinte.'); end if;
    if (v_date::timestamp + make_interval(mins => v_end)) <= v_now then return conv_private.vfail('INVALID_DATA', 'Esse horário já passou.'); end if;
    if conv_private.court_busy(v_court.id, v_date, v_start, v_end) then
      select string_agg(to_char(r.start_time, 'HH24:MI') || '-' || to_char(r.end_time, 'HH24:MI') || ' ' || r.type || ' (' || coalesce(pr.name, r.guest_name, 'sem nome') || ')', '; ' order by r.start_time) into v_list
      from public.reservations r left join public.profiles pr on pr.id = r.creator_id
      where r.court_id = v_court.id and r.date = v_date and r.status::text <> 'cancelled'
        and (extract(hour from r.start_time)::int * 60 + extract(minute from r.start_time)::int) < v_end
        and (case when r.end_time = time '00:00' then 1440 else extract(hour from r.end_time)::int * 60 + extract(minute from r.end_time)::int end) > v_start;
      return conv_private.vfail('SLOT_TAKEN', 'Já há reserva nesse horário: ' || v_list || '. Cancele antes (posso fazer) e depois bloqueio.');
    end if;
    v_payload := jsonb_strip_nulls(jsonb_build_object('court_id', v_court.id, 'court', v_court.name, 'date', v_date, 'start', to_char(v_time, 'HH24:MI'),
      'end', conv_private.min_to_hhmm(v_end), 'duration', v_dur, 'reason', nullif(trim(coalesce(p->>'reason', '')), '')));

  elsif v_action = 'adm_pref_set' then
    if v_pref not in ('resumo', 'estilo', 'alertas', 'saldo_minimo', 'dias_atraso', 'conta_padrao') then
      return conv_private.vfail('INVALID_PREF', 'Posso ajustar: resumo da manhã (liga/desliga), estilo do resumo (curto ou completo), alertas, saldo mínimo, dias de atraso ou conta padrão.');
    end if;
    if v_pref in ('resumo', 'alertas') then
      if v_active is null then return conv_private.vfail('INVALID_PREF', 'É para ligar ou desligar?'); end if;
      v_payload := jsonb_build_object('pref', v_pref, 'active', v_active);
    elsif v_pref = 'estilo' then
      if v_val not in ('curto', 'completo') then return conv_private.vfail('INVALID_PREF', 'O resumo pode ser "curto" ou "completo". Qual?'); end if;
      v_payload := jsonb_build_object('pref', v_pref, 'value', v_val);
    elsif v_pref = 'saldo_minimo' then
      if v_active is false then v_payload := jsonb_build_object('pref', v_pref, 'cents', null, 'active', false);
      else
        v_amount := nullif(p->>'amount_cents', '')::bigint;
        if v_amount is null or v_amount <= 0 or v_amount > 100000000000 then return conv_private.vfail('INVALID_AMOUNT', 'Abaixo de quanto devo avisar do caixa?'); end if;
        v_payload := jsonb_build_object('pref', v_pref, 'cents', v_amount);
      end if;
    elsif v_pref = 'dias_atraso' then
      if v_val is null or v_val !~ '^\d{1,2}$' or v_val::int not between 1 and 90 then return conv_private.vfail('INVALID_PREF', 'Avisar a partir de quantos dias de atraso? (de 1 a 90)'); end if;
      v_payload := jsonb_build_object('pref', v_pref, 'value', v_val::int);
    else
      if v_active is false then v_payload := jsonb_build_object('pref', v_pref, 'active', false);
      else
        select count(*), min(a.id::text)::uuid into v_n, v_id from public.fin_accounts a where a.active and fin_private.fold_text(a.name) like '%' || fin_private.fold_text(coalesce(p->>'account_name', '')) || '%'
          and nullif(trim(coalesce(p->>'account_name', '')), '') is not null;
        if v_n <> 1 then
          select string_agg(a.name, ', ' order by a.position, a.name) into v_list from public.fin_accounts a where a.active;
          return conv_private.vfail('ACCOUNT_REQUIRED', 'Qual conta fica como padrão? Contas: ' || coalesce(v_list, '(nenhuma ativa)') || '.');
        end if;
        select a.id, a.name into v_acc from public.fin_accounts a where a.id = v_id;
        v_payload := jsonb_build_object('pref', v_pref, 'account_id', v_acc.id, 'account_name', v_acc.name);
      end if;
    end if;
  else
    return conv_private.vfail('INVALID_ACTION', 'Ação inválida.');
  end if;

  select * into s from public.conv_ai_settings where active order by version desc limit 1;
  update public.conv_booking_proposals set status = 'canceled' where session_id = p_session and status = 'open';
  insert into public.conv_booking_proposals(conversation_id, session_id, requester_contact_id, requester_profile_id, action, payload, expires_at)
  values (sess.conversation_id, p_session, sess.requester_contact_id, v_admin, v_action, v_payload,
    now() + make_interval(mins => coalesce(s.proposal_ttl_minutes, 20)))
  returning id into v_id;
  return jsonb_build_object('ok', true, 'proposal_id', v_id, 'action', v_action, 'summary', v_payload);
exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow or numeric_value_out_of_range then
  return conv_private.vfail('INVALID_DATA', 'Algum dado veio num formato que não entendi (data, hora ou valor).');
end $function$;
--@@ 45 funcao conv_private.ai_agenda(p_profile uuid)
CREATE OR REPLACE FUNCTION conv_private.ai_agenda(p_profile uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_member boolean := false; v_admin boolean := false; v_now timestamp := now() at time zone 'America/Fortaleza';
begin
  if p_profile is null then return '[]'::jsonb; end if;
  select (p.role::text in ('socio', 'admin') and coalesce(p.is_active, true)), p.role::text = 'admin' into v_member, v_admin
    from public.profiles p where p.id = p_profile;
  return coalesce((
    select jsonb_agg(e || jsonb_build_object('ref', 'a' || rn) order by rn) from (
      select row_number() over (order by x.date, x.start_time) rn,
        jsonb_build_object(
          'id', x.id, 'type', x.type, 'date', x.date, 'start', to_char(x.start_time, 'HH24:MI'), 'end', to_char(x.end_time, 'HH24:MI'),
          'court', (select c.name from public.courts c where c.id = x.court_id),
          'people', conv_private.game_people(x.id),
          'guest', case when x.type = 'Play' then nullif(trim(coalesce(x.guest_name, '')), '') end,
          'spots_left', case when x.type = 'Play' then greatest(8 - (jsonb_array_length(conv_private.game_people(x.id))
                                + case when nullif(trim(coalesce(x.guest_name, '')), '') is null then 0 else 1 end), 0) end,
          'mine', x.mine,
          'can', jsonb_build_object(
            'leave', x.type = 'Play' and x.in_game,
            'people', x.type = 'Play' and v_member and (x.date + x.start_time) > v_now,
            'edit', x.type in ('Play', 'Aula') and (v_admin or (x.creator_id = p_profile)) and (x.date + x.start_time) > v_now,
            'cancel', x.type in ('Play', 'Aula') and (v_admin or (x.creator_id = p_profile)) and (x.date + x.start_time) > v_now)) e
      from (
        select r.*, (r.creator_id = p_profile or p_profile = any (coalesce(r.participant_ids, '{}'))) as mine,
               (p_profile = any (coalesce(r.participant_ids, '{}')) or r.creator_id = p_profile) as in_game
        from public.reservations r
        where r.status::text = 'active' and r.type in ('Play', 'Aula', 'Campeonato')
          and (r.date + (case when r.end_time = time '00:00' then time '23:59:59' else r.end_time end)) > v_now
          and r.date <= conv_private.today() + 60
          and (r.date <= conv_private.today() + 4 or r.creator_id = p_profile or p_profile = any (coalesce(r.participant_ids, '{}')))
        order by r.date, r.start_time limit 40) x
    ) y), '[]'::jsonb);
end $function$;
--@@ 45 funcao conv_private.ai_approved_memories()
CREATE OR REPLACE FUNCTION conv_private.ai_approved_memories()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('subject_name', x.subject_name, 'kind', x.kind, 'content', x.content)
                            order by x.confidence desc, x.created_at desc), '[]'::jsonb)
  from (select c.subject_name, c.kind, c.content, c.confidence, c.created_at
        from public.conv_ai_memory_candidates c
        where c.status = 'approved' and c.kind <> 'role_title'
        order by c.confidence desc, c.created_at desc
        limit 60) x $function$;
--@@ 45 funcao conv_private.ai_audio_transcripts(p_ids text[])
CREATE OR REPLACE FUNCTION conv_private.ai_audio_transcripts(p_ids text[])
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'transcription', m.meta->'transcription')), '[]'::jsonb)
  from public.conv_messages m
  where m.id in (
      select x::uuid from unnest(coalesce(p_ids, '{}')) x
      where x ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' limit 50)
    and m.kind in ('audio', 'ptt') and m.deleted_at is null;
$function$;
--@@ 45 funcao conv_private.ai_cancel_proposal(p_session uuid)
CREATE OR REPLACE FUNCTION conv_private.ai_cancel_proposal(p_session uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
