--@@ 45 funcao conv_private.ai_club_roster()
CREATE OR REPLACE FUNCTION conv_private.ai_club_roster()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
with cycle as (
  select public.get_ranking_cycle_start() as starts_at
), eligible_matches as (
  select m.*
  from public.matches m cross join cycle c
  where m.type in ('Desafio', 'Desafio Ranking', 'SuperSet')
    and m.status::text = 'finished'
    and (
      c.starts_at is null
      or coalesce(m.updated_at, m.created_at, (m.date::timestamp at time zone 'America/Fortaleza')) >= c.starts_at
    )
), match_players as (
  select m.player_a_id as profile_id,
         case when m.winner_id = m.player_a_id then 1 else 0 end as wins,
         coalesce((
           select count(*)::int
           from generate_subscripts(coalesce(m.score_a, '{}'::integer[]), 1) i
           where m.score_a[i] > coalesce(m.score_b[i], -1)
         ), 0) as sets_won
  from eligible_matches m
  where m.player_a_id is not null
  union all
  select m.player_b_id as profile_id,
         case when m.winner_id = m.player_b_id then 1 else 0 end as wins,
         coalesce((
           select count(*)::int
           from generate_subscripts(coalesce(m.score_b, '{}'::integer[]), 1) i
           where m.score_b[i] > coalesce(m.score_a[i], -1)
         ), 0) as sets_won
  from eligible_matches m
  where m.player_b_id is not null
), current_stats as (
  select profile_id, coalesce(sum(wins),0)::int as wins, coalesce(sum(sets_won),0)::int as sets_won
  from match_players
  group by profile_id
), base as (
  select p.id, p.name, p.category,
         coalesce(p.legacy_points,0)::int as points,
         (coalesce(p.legacy_wins,0) + coalesce(cs.wins,0))::int as total_wins,
         (coalesce(p.legacy_sets_won,0) + coalesce(cs.sets_won,0))::int as total_sets_won,
         coalesce(p.is_professor,false) as is_professor,
         coalesce(mc.aliases, '{}'::text[]) as aliases,
         nullif(mc.social_context, '') as social_context
  from public.profiles p
  left join current_stats cs on cs.profile_id = p.id
  left join public.conv_ai_member_context mc on mc.profile_id = p.id
  where coalesce(p.is_active, true) and p.role::text in ('socio','admin')
), ranked as (
  select b.*,
         row_number() over (
           partition by coalesce(b.category, 'Sem Classe')
           order by b.points desc, b.total_wins desc, b.total_sets_won desc, b.name
         )::int as category_position,
         row_number() over (
           order by
             case b.category when '4ª Classe' then 1 when '5ª Classe' then 2 when '6ª Classe' then 3 else 9 end,
             b.points desc, b.total_wins desc, b.total_sets_won desc, b.name
         )::int as global_position
  from base b
)
select coalesce(jsonb_agg(
  jsonb_build_object(
    'name', r.name,
    'category', coalesce(r.category, 'Sem Classe'),
    'points', r.points,
    'category_position', r.category_position,
    'global_position', r.global_position,
    'is_professor', r.is_professor,
    'aliases', to_jsonb(r.aliases),
    'social_context', r.social_context
  )
  order by r.global_position
), '[]'::jsonb)
from ranked r
$function$;
--@@ 45 funcao conv_private.ai_confirm(p_proposal uuid, p_message uuid)
CREATE OR REPLACE FUNCTION conv_private.ai_confirm(p_proposal uuid, p_message uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  bp public.conv_booking_proposals%rowtype; m public.conv_messages%rowtype; v_admin uuid;
  v_prev_claims text; v_prev_sub text; v_pay uuid; v_exp date; v_paid_on date; v_amount bigint; v_sub uuid; v_name text;
begin
  select * into bp from public.conv_booking_proposals where id = p_proposal for update;
  if not found or bp.action <> 'student_card_renew' then return conv_private.ai_confirm_before_student_card(p_proposal, p_message); end if;
  if bp.status = 'confirmed' then return jsonb_build_object('ok', true, 'replayed', true, 'action', bp.action, 'summary', bp.payload); end if;
  if bp.status <> 'open' then return conv_private.vfail('PROPOSAL_CLOSED', 'Essa proposta não está mais aberta.'); end if;
  if bp.expires_at <= now() then
    update public.conv_booking_proposals set status = 'expired' where id = bp.id;
    return conv_private.vfail('PROPOSAL_EXPIRED', 'A proposta venceu. Posso montar outra.');
  end if;
  select * into m from public.conv_messages where id = p_message and direction = 'inbound' and conversation_id = bp.conversation_id;
  if not found or m.created_at <= bp.created_at then
    return conv_private.vfail('CONFIRMATION_NOT_AFTER_PROPOSAL', 'A confirmação precisa vir depois da proposta.');
  end if;
  if m.kind <> 'text' or not (conv_private.is_confirmation(m.body) or conv_private.is_semantic_acceptance(m.body, false)) then
    return conv_private.vfail('NOT_EXPLICIT', 'Não entendi como confirmação clara.');
  end if;
  if m.sender_contact_id is distinct from bp.requester_contact_id then
    return conv_private.vfail('NOT_AUTHORIZED_TO_CONFIRM', 'Só o administrador que pediu pode confirmar.');
  end if;
  v_admin := conv_private.ai_admin_requester(bp.session_id);
  if v_admin is null or v_admin <> bp.requester_profile_id then
    update public.conv_booking_proposals set status = 'failed', failure_code = 'ADMIN_ONLY_PRIVATE' where id = bp.id;
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;

  v_name := bp.payload->>'student_name';
  v_paid_on := (bp.payload->>'paid_on')::date;
  v_exp := (bp.payload->>'new_valid_until')::date;
  v_amount := (bp.payload->>'amount_cents')::bigint;
  v_sub := nullif(bp.payload#>>'{receipt,id}', '')::uuid;
  if exists (select 1 from public.student_payments x where x.student_id = (bp.payload->>'student_id')::uuid and x.status = 'active'
             and (x.payment_date at time zone 'America/Fortaleza')::date = v_paid_on and round(x.amount * 100) = v_amount) then
    update public.conv_booking_proposals set status = 'failed', failure_code = 'ALREADY_RECORDED' where id = bp.id;
    return conv_private.vfail('ALREADY_RECORDED', 'Esse pagamento já foi registrado. Não duplico.');
  end if;

  -- Executa como o administrador: a trilha de auditoria da tabela enxerga quem aprovou.
  v_prev_claims := current_setting('request.jwt.claims', true);
  v_prev_sub := current_setting('request.jwt.claim.sub', true);
  perform set_config('request.jwt.claims', jsonb_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
  perform set_config('request.jwt.claim.sub', v_admin::text, true);

  insert into public.student_payments(student_id, amount, payment_date, valid_until, approved_by, status)
  values ((bp.payload->>'student_id')::uuid, v_amount / 100.0,
          ((v_paid_on::timestamp + time '12:00') at time zone 'America/Fortaleza'),
          ((v_exp::timestamp + time '23:59:59') at time zone 'America/Fortaleza'), v_admin, 'active')
  returning id into v_pay;
  update public.non_socio_students set plan_status = 'active', master_expiration_date = v_exp
   where id = (bp.payload->>'student_id')::uuid;
  if v_sub is not null then
    update public.fin_receipt_submissions
       set status = 'approved', reviewed_at = now(), reviewed_by = v_admin,
           decision_reason = 'Renovação do Card Mensal de ' || left(v_name, 80) || ' pelo João (WhatsApp)'
     where id = v_sub and status in ('submitted', 'in_review');
  end if;

  perform set_config('request.jwt.claims', coalesce(v_prev_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(v_prev_sub, ''), true);

  update public.conv_booking_proposals set status = 'confirmed', confirmed_at = now(), confirmed_message_id = m.id,
    confirmed_by_contact_id = m.sender_contact_id, payload = bp.payload || jsonb_build_object('result', jsonb_build_object('payment_id', v_pay)) where id = bp.id;
  perform conv_private.audit('ai_admin_student_card', 'student_payments', v_pay::text, null,
    jsonb_build_object('action', bp.action, 'amount_cents', v_amount, 'student_id', bp.payload->'student_id', 'new_valid_until', v_exp),
    jsonb_build_object('actor', 'ai', 'source', 'whatsapp', 'conversation_id', bp.conversation_id, 'proposal_id', bp.id,
      'requester_profile_id', bp.requester_profile_id),
    bp.requester_profile_id);
  return jsonb_build_object('ok', true, 'action', bp.action, 'summary', bp.payload || jsonb_build_object('result', jsonb_build_object('payment_id', v_pay)));
end $function$;
--@@ 45 funcao conv_private.ai_confirm_before_student_card(p_proposal uuid, p_
CREATE OR REPLACE FUNCTION conv_private.ai_confirm_before_student_card(p_proposal uuid, p_message uuid)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select conv_private.ai_confirm_single_step(p_proposal, p_message)
$function$;
--@@ 45 funcao conv_private.ai_confirm_booking(p_proposal uuid, p_message uuid
CREATE OR REPLACE FUNCTION conv_private.ai_confirm_booking(p_proposal uuid, p_message uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  bp public.conv_booking_proposals%rowtype; m public.conv_messages%rowtype; sender_admin boolean := false;
  v_val jsonb; n jsonb; v_res uuid; v_old public.reservations%rowtype; v_in jsonb; v_student_type text; v_obs text;
  v_socio uuid[]; v_students uuid[]; v_court uuid; v_date date; v_conv public.conv_conversations%rowtype;
begin
  select * into bp from public.conv_booking_proposals where id = p_proposal for update;
  if not found then return conv_private.vfail('PROPOSAL_NOT_FOUND', 'Proposta não encontrada.'); end if;
  if bp.status = 'confirmed' then
    return jsonb_build_object('ok', true, 'replayed', true, 'reservation_id', coalesce(bp.reservation_id, nullif(bp.payload->>'reservation_id', '')::uuid), 'action', bp.action, 'summary', bp.payload);
  end if;
  if bp.status <> 'open' then return conv_private.vfail('PROPOSAL_CLOSED', 'Essa proposta não está mais aberta.'); end if;
  if bp.expires_at <= now() then
    update public.conv_booking_proposals set status = 'expired' where id = bp.id;
    return conv_private.vfail('PROPOSAL_EXPIRED', 'A proposta venceu. Posso montar outra.');
  end if;

  select * into m from public.conv_messages where id = p_message and direction = 'inbound' and conversation_id = bp.conversation_id;
  if not found or m.created_at <= bp.created_at then
    return conv_private.vfail('CONFIRMATION_NOT_AFTER_PROPOSAL', 'A confirmação precisa vir depois da proposta.');
  end if;
  if m.kind <> 'text' or not (conv_private.is_confirmation(m.body) or conv_private.is_semantic_acceptance(m.body, bp.action = 'cancel' or coalesce((bp.payload->>'cancel_all')::boolean, false))) then
    return conv_private.vfail('NOT_EXPLICIT', 'Não entendi como confirmação clara.');
  end if;
  select exists (select 1 from public.conv_contacts c join public.profiles p on p.id = c.profile_id
    where c.id = m.sender_contact_id and p.role::text = 'admin' and c.link_status in ('linked', 'manual')) into sender_admin;
  if m.sender_contact_id is distinct from bp.requester_contact_id and not sender_admin then
    return conv_private.vfail('NOT_AUTHORIZED_TO_CONFIRM', 'Só quem pediu a reserva (ou um administrador) pode confirmar.');
  end if;
  select * into v_conv from public.conv_conversations where id = bp.conversation_id;

  -- Mexer nos atletas: trava a reserva, revalida tudo e aplica (sair/retirar/adicionar/convidado; último atleta = cancela a reserva).
  if bp.action = 'participants' then
    select * into v_old from public.reservations where id = (bp.payload->>'reservation_id')::uuid for update;
    v_val := conv_private.participants_check((bp.payload->>'reservation_id')::uuid, bp.requester_profile_id,
      array(select x::uuid from jsonb_array_elements_text(coalesce(bp.payload->'add_ids', '[]'::jsonb)) x),
      array(select x::uuid from jsonb_array_elements_text(coalesce(bp.payload->'remove_ids', '[]'::jsonb)) x),
      nullif(trim(coalesce(bp.payload->>'add_guest', '')), ''), coalesce((bp.payload->>'remove_guest')::boolean, false));
    if not (v_val->>'ok')::boolean then
      update public.conv_booking_proposals set status = 'failed', failure_code = v_val->>'code' where id = bp.id;
      return v_val;
    end if;
    n := v_val->'change';
    update public.reservations set
      participant_ids = array(select x from unnest(coalesce(participant_ids, '{}')) with ordinality t(x, o)
                              where not (x::text in (select jsonb_array_elements_text(n->'remove_ids'))) order by o)
                        || array(select jsonb_array_elements_text(n->'add_ids')::uuid),
      guest_name = case when (n->>'guest_after') is null then null else n->>'guest_after' end,
      guest_responsible_id = case when (n->>'guest_after') is null then null
                                  when (n->>'guest_after') is distinct from nullif(trim(coalesce(guest_name, '')), '') then bp.requester_profile_id
                                  else guest_responsible_id end,
      status = case when coalesce((n->>'cancel_all')::boolean, false) then 'cancelled' else status end,
      updated_at = now()
      where id = v_old.id;
    update public.conv_booking_proposals set status = 'confirmed', confirmed_at = now(), confirmed_message_id = m.id,
      confirmed_by_contact_id = m.sender_contact_id, payload = n where id = bp.id;
    perform conv_private.audit(case when coalesce((n->>'cancel_all')::boolean, false) then 'ai_reservation_canceled' else 'ai_reservation_participants_changed' end,
      'reservations', v_old.id::text,
      jsonb_build_object('participants', coalesce(cardinality(v_old.participant_ids), 0)),
      jsonb_build_object('added', jsonb_array_length(n->'add_ids'), 'removed', jsonb_array_length(n->'remove_ids'), 'cancel_all', coalesce((n->>'cancel_all')::boolean, false)),
      jsonb_build_object('actor', 'ai', 'source', 'whatsapp', 'conversation_id', bp.conversation_id, 'group_id', v_conv.group_id,
        'requester_profile_id', bp.requester_profile_id, 'proposal_id', bp.id,
        'confirmed_by_admin', sender_admin and m.sender_contact_id is distinct from bp.requester_contact_id),
      bp.requester_profile_id);
    return jsonb_build_object('ok', true, 'action', 'participants', 'reservation_id', v_old.id, 'summary', n);
  end if;

  -- Entrar no jogo: trava a reserva, revalida (vaga, jogo ativo, sócio, ainda não participa) e acrescenta o solicitante.
  -- A proposta NÃO grava reservation_id (o índice único da tabela vale para uma reserva criada, e vários sócios podem entrar no mesmo jogo).
  if bp.action = 'join' then
    select * into v_old from public.reservations where id = (bp.payload->>'reservation_id')::uuid for update;
    v_val := conv_private.join_party_check((bp.payload->>'reservation_id')::uuid, bp.requester_profile_id,
      array(select x::uuid from jsonb_array_elements_text(coalesce(bp.payload->'add_ids', '[]'::jsonb)) x where x::uuid <> bp.requester_profile_id),
      nullif(trim(coalesce(bp.payload->>'guest_name', '')), ''));
    if not (v_val->>'ok')::boolean then
      update public.conv_booking_proposals set status = 'failed', failure_code = v_val->>'code' where id = bp.id;
      return v_val;
    end if;
    update public.reservations set
      participant_ids = coalesce(participant_ids, '{}') || array(select x::uuid from jsonb_array_elements_text(v_val->'game'->'add_ids') x),
      guest_name = coalesce(guest_name, nullif(v_val->'game'->>'guest_name', '')),
      guest_responsible_id = case when nullif(v_val->'game'->>'guest_name', '') is not null then bp.requester_profile_id else guest_responsible_id end,
      updated_at = now()
      where id = v_old.id;
    n := conv_private.game_summary(v_old.id) || jsonb_build_object('added', (v_val->'game'->>'adding')::int);
    update public.conv_booking_proposals set status = 'confirmed', confirmed_at = now(), confirmed_message_id = m.id,
      confirmed_by_contact_id = m.sender_contact_id, payload = n where id = bp.id;
    perform conv_private.audit('ai_reservation_joined', 'reservations', v_old.id::text,
      jsonb_build_object('participants', coalesce(cardinality(v_old.participant_ids), 0)),
      jsonb_build_object('participants', coalesce(cardinality(v_old.participant_ids), 0) + (v_val->'game'->>'adding')::int),
      jsonb_build_object('actor', 'ai', 'source', 'whatsapp', 'conversation_id', bp.conversation_id, 'group_id', v_conv.group_id,
        'requester_profile_id', bp.requester_profile_id, 'proposal_id', bp.id,
        'confirmed_by_admin', sender_admin and m.sender_contact_id is distinct from bp.requester_contact_id),
      bp.requester_profile_id);
    return jsonb_build_object('ok', true, 'action', 'join', 'reservation_id', v_old.id, 'summary', n);
  end if;

  if bp.action = 'cancel' then
    select * into v_old from public.reservations where id = (bp.payload->>'reservation_id')::uuid for update;
    if not found or v_old.status::text <> 'active' then
      update public.conv_booking_proposals set status = 'failed', failure_code = 'RESERVATION_NOT_FOUND' where id = bp.id;
      return conv_private.vfail('RESERVATION_NOT_FOUND', 'Não achei essa reserva ativa.');
    end if;
    update public.reservations set status = 'cancelled', updated_at = now() where id = v_old.id;
    update public.conv_booking_proposals set status = 'confirmed', confirmed_at = now(), confirmed_message_id = m.id,
      confirmed_by_contact_id = m.sender_contact_id, reservation_id = v_old.id where id = bp.id;
    perform conv_private.audit('ai_reservation_canceled', 'reservations', v_old.id::text, null,
      jsonb_build_object('status', 'cancelled'),
      jsonb_build_object('actor', 'ai', 'source', 'whatsapp', 'conversation_id', bp.conversation_id, 'group_id', v_conv.group_id,
        'requester_profile_id', bp.requester_profile_id, 'proposal_id', bp.id), bp.requester_profile_id);
    return jsonb_build_object('ok', true, 'action', 'cancel', 'reservation_id', v_old.id, 'summary', bp.payload);
  end if;

  n := bp.payload;
  v_court := (n->>'court_id')::uuid; v_date := (n->>'date')::date;
  -- Trava por quadra e dia: serializa gravações concorrentes.
  perform pg_advisory_xact_lock(hashtextextended('conv_res:' || v_court::text || ':' || v_date::text, 0));

  v_in := n || jsonb_build_object('start', n->>'start', 'requester_profile_id', bp.requester_profile_id,
    'exclude_reservation_id', case when bp.action = 'reschedule' then n->>'reservation_id' else null end);
  v_val := conv_private.validate_reservation(v_in);
  if not (v_val->>'ok')::boolean then
    update public.conv_booking_proposals set status = 'failed', failure_code = v_val->>'code' where id = bp.id;
    return v_val;
  end if;
  n := v_val->'normalized';

  select coalesce(array_agg(x::uuid), '{}') into v_socio from jsonb_array_elements_text(n->'participant_ids') x;
  select coalesce(array_agg(x::uuid), '{}') into v_students from jsonb_array_elements_text(n->'non_socio_student_ids') x;
  v_student_type := case when n->>'type' = 'Aula' then
    case when cardinality(v_socio) > 0 and cardinality(v_students) = 0 then 'socio'
         when cardinality(v_socio) = 0 and cardinality(v_students) > 0 then 'non-socio' else null end else null end;
  v_obs := 'Reserva via WhatsApp (IA)';

  -- Mesmo efeito do app: sócio que vira aluno ganha o perfil de aluno ativo.
  if n->>'type' = 'Aula' and cardinality(v_socio) > 0 then
    insert into public.student_profiles(profile_id, professor_id, student_status)
    select x, nullif(n->>'professor_id', '')::uuid, 'active' from unnest(v_socio) x
    on conflict (profile_id) do nothing;
  end if;

  insert into public.reservations(type, date, start_time, end_time, court_id, creator_id, participant_ids, guest_name,
    guest_responsible_id, professor_id, student_type, non_socio_student_id, non_socio_student_ids, observation, status)
  values (n->>'type', v_date, (n->>'start')::time, (n->>'end')::time, v_court, bp.requester_profile_id, v_socio,
    n->>'guest_name', case when nullif(n->>'guest_name', '') is null then null else bp.requester_profile_id end,
    nullif(n->>'professor_id', '')::uuid, v_student_type,
    case when cardinality(v_students) = 1 then v_students[1] else null end, v_students, v_obs, 'active')
  returning id into v_res;

  if bp.action = 'reschedule' then
    update public.reservations set status = 'cancelled', updated_at = now() where id = (bp.payload->>'reservation_id')::uuid and status::text = 'active';
  end if;

  update public.conv_booking_proposals set status = 'confirmed', confirmed_at = now(), confirmed_message_id = m.id,
    confirmed_by_contact_id = m.sender_contact_id, reservation_id = v_res where id = bp.id;
  perform conv_private.audit('ai_reservation_created', 'reservations', v_res::text, null,
    jsonb_build_object('type', n->>'type', 'date', n->>'date', 'start', n->>'start', 'court', n->>'court_name'),
    jsonb_build_object('actor', 'ai', 'source', 'whatsapp', 'conversation_id', bp.conversation_id, 'group_id', v_conv.group_id,
      'requester_profile_id', bp.requester_profile_id, 'proposal_id', bp.id, 'action', bp.action,
      'confirmed_by_admin', sender_admin and m.sender_contact_id is distinct from bp.requester_contact_id),
    bp.requester_profile_id);
  return jsonb_build_object('ok', true, 'action', bp.action, 'reservation_id', v_res, 'summary', n);
end $function$;
--@@ 45 funcao conv_private.ai_confirm_pendency_step(p_proposal uuid, p_messag
CREATE OR REPLACE FUNCTION conv_private.ai_confirm_pendency_step(p_proposal uuid, p_message uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  bp public.conv_booking_proposals%rowtype; m public.conv_messages%rowtype; v_admin uuid;
  v_prev_claims text; v_prev_sub text; v_res jsonb; v_err text; v_code text; v_conv public.conv_conversations%rowtype;
begin
  select * into bp from public.conv_booking_proposals where id = p_proposal for update;
  if not found or bp.action not like 'fin\_%' then return conv_private.ai_confirm_booking(p_proposal, p_message); end if;
  if bp.status = 'confirmed' then return jsonb_build_object('ok', true, 'replayed', true, 'action', bp.action, 'summary', bp.payload); end if;
  if bp.status <> 'open' then return conv_private.vfail('PROPOSAL_CLOSED', 'Essa proposta não está mais aberta.'); end if;
  if bp.expires_at <= now() then
    update public.conv_booking_proposals set status = 'expired' where id = bp.id;
    return conv_private.vfail('PROPOSAL_EXPIRED', 'A proposta venceu. Posso montar outra.');
  end if;

  select * into m from public.conv_messages where id = p_message and direction = 'inbound' and conversation_id = bp.conversation_id;
  if not found or m.created_at <= bp.created_at then
    return conv_private.vfail('CONFIRMATION_NOT_AFTER_PROPOSAL', 'A confirmação precisa vir depois da proposta.');
  end if;
  if m.kind <> 'text' or not (conv_private.is_confirmation(m.body) or conv_private.is_semantic_acceptance(m.body, false)) then
    return conv_private.vfail('NOT_EXPLICIT', 'Não entendi como confirmação clara.');
  end if;
  -- Só o próprio administrador que pediu confirma (nada de outro admin confirmar por ele).
  if m.sender_contact_id is distinct from bp.requester_contact_id then
    return conv_private.vfail('NOT_AUTHORIZED_TO_CONFIRM', 'Só o administrador que pediu pode confirmar.');
  end if;
  v_admin := conv_private.ai_admin_requester(bp.session_id);
  if v_admin is null or v_admin <> bp.requester_profile_id then
    update public.conv_booking_proposals set status = 'failed', failure_code = 'ADMIN_ONLY_PRIVATE' where id = bp.id;
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;

  -- Executa como o administrador: as funções do app checam o papel por auth.uid().
  v_prev_claims := current_setting('request.jwt.claims', true);
  v_prev_sub := current_setting('request.jwt.claim.sub', true);
  perform set_config('request.jwt.claims', jsonb_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
  perform set_config('request.jwt.claim.sub', v_admin::text, true);
  begin
    if bp.action = 'fin_pendency_create' then
      v_res := public.fin_create_member_pendency(bp.request_key, bp.payload - 'member_name');
    elsif bp.action = 'fin_pendency_collection' then
      v_res := public.fin_set_pendency_collection(bp.request_key, (bp.payload->>'charge_id')::uuid, (bp.payload->>'enabled')::boolean);
    elsif bp.action = 'fin_pendency_send' then
      v_res := public.fin_send_pendency_now(bp.request_key, (bp.payload->>'charge_id')::uuid);
    else
      v_res := public.fin_register_payment(bp.request_key, (bp.payload->>'charge_id')::uuid, (bp.payload->>'amount_cents')::bigint,
        (bp.payload->>'paid_on')::date, bp.payload->>'method', (bp.payload->>'account_id')::uuid, 'Baixa pelo WhatsApp (João)');
    end if;
  exception when others then
    v_err := sqlerrm;
  end;
  perform set_config('request.jwt.claims', coalesce(v_prev_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(v_prev_sub, ''), true);

  if v_err is not null then
    v_code := case when v_err ~ '^[A-Z][A-Z_]+$' then v_err else 'FINANCE_FAILED' end;
    update public.conv_booking_proposals set status = 'failed', failure_code = v_code where id = bp.id;
    return conv_private.vfail(v_code, 'O financeiro recusou: ' || v_code || '.');
  end if;

  update public.conv_booking_proposals set status = 'confirmed', confirmed_at = now(), confirmed_message_id = m.id,
    confirmed_by_contact_id = m.sender_contact_id, payload = bp.payload || jsonb_build_object('result', v_res) where id = bp.id;
  select * into v_conv from public.conv_conversations where id = bp.conversation_id;
  perform conv_private.audit('ai_admin_finance', 'fin_member_charges', coalesce(v_res->>'id', bp.payload->>'charge_id'), null,
    jsonb_build_object('action', bp.action, 'amount_cents', bp.payload->'amount_cents', 'enabled', bp.payload->'enabled'),
    jsonb_build_object('actor', 'ai', 'source', 'whatsapp', 'conversation_id', bp.conversation_id, 'proposal_id', bp.id,
      'requester_profile_id', bp.requester_profile_id),
    bp.requester_profile_id);
  return jsonb_build_object('ok', true, 'action', bp.action, 'summary', bp.payload || jsonb_build_object('result', v_res));
end $function$;
--@@ 45 funcao conv_private.ai_confirm_pre_briefing_step(p_proposal uuid, p_me
CREATE OR REPLACE FUNCTION conv_private.ai_confirm_pre_briefing_step(p_proposal uuid, p_message uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  bp public.conv_booking_proposals%rowtype; m public.conv_messages%rowtype; v_admin uuid; v_err text; v_code text;
  r jsonb; v_contact uuid; v_conv uuid; v_n int := 0; v_at timestamptz;
begin
  select * into bp from public.conv_booking_proposals where id = p_proposal for update;
  if not found or bp.action <> 'adm_broadcast_send' then return conv_private.ai_confirm_pre_broadcast_step(p_proposal, p_message); end if;
  if bp.status = 'confirmed' then return jsonb_build_object('ok', true, 'replayed', true, 'action', bp.action, 'summary', bp.payload - 'recipients'); end if;
  if bp.status <> 'open' then return conv_private.vfail('PROPOSAL_CLOSED', 'Essa proposta não está mais aberta.'); end if;
  if bp.expires_at <= now() then
    update public.conv_booking_proposals set status = 'expired' where id = bp.id;
    return conv_private.vfail('PROPOSAL_EXPIRED', 'A proposta venceu. Posso montar outra.');
  end if;
  select * into m from public.conv_messages where id = p_message and direction = 'inbound' and conversation_id = bp.conversation_id;
  if not found or m.created_at <= bp.created_at then
    return conv_private.vfail('CONFIRMATION_NOT_AFTER_PROPOSAL', 'A confirmação precisa vir depois da proposta.');
  end if;
  if m.kind <> 'text' or not (conv_private.is_confirmation(m.body) or conv_private.is_semantic_acceptance(m.body, false)) then
    return conv_private.vfail('NOT_EXPLICIT', 'Não entendi como confirmação clara.');
  end if;
  if m.sender_contact_id is distinct from bp.requester_contact_id then
    return conv_private.vfail('NOT_AUTHORIZED_TO_CONFIRM', 'Só o administrador que pediu pode confirmar.');
  end if;
  v_admin := conv_private.ai_admin_requester(bp.session_id);
  if v_admin is null or v_admin <> bp.requester_profile_id then
    update public.conv_booking_proposals set status = 'failed', failure_code = 'ADMIN_ONLY_PRIVATE' where id = bp.id;
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;
  v_at := greatest((bp.payload->>'send_at')::timestamptz, now());
  begin
    for r in select * from jsonb_array_elements(bp.payload->'recipients') loop
      if exists (select 1 from public.conv_contacts c where c.phone = r->>'phone' and c.opt_out) then continue; end if;
      v_contact := conv_private.upsert_contact(r->>'phone', null, r->>'name', true);
      v_conv := conv_private.open_direct(v_contact);
      insert into public.conv_followups(conversation_id, due_at, note, send_body, created_by)
      values (v_conv, v_at, 'Comunicado da diretoria (WhatsApp)', bp.payload->>'body', v_admin);
      v_n := v_n + 1;
    end loop;
  exception when others then
    v_err := sqlerrm;
  end;
  if v_err is not null then
    v_code := case when v_err ~ '^[A-Z][A-Z_]+$' then v_err else 'ADMIN_ACTION_FAILED' end;
    update public.conv_booking_proposals set status = 'failed', failure_code = v_code where id = bp.id;
    return conv_private.vfail(v_code, 'Não consegui concluir: ' || v_code || '.');
  end if;
  update public.conv_booking_proposals set status = 'confirmed', confirmed_at = now(), confirmed_message_id = m.id,
    confirmed_by_contact_id = m.sender_contact_id,
    payload = (bp.payload - 'recipients') || jsonb_build_object('queued', v_n) where id = bp.id;
  perform conv_private.audit('ai_admin_action', 'conv_booking_proposals', bp.id::text, null,
    jsonb_build_object('action', bp.action, 'queued', v_n, 'send_at', v_at),
    jsonb_build_object('actor', 'ai', 'source', 'whatsapp', 'conversation_id', bp.conversation_id, 'proposal_id', bp.id,
      'requester_profile_id', bp.requester_profile_id),
    bp.requester_profile_id);
  return jsonb_build_object('ok', true, 'action', bp.action, 'summary', (bp.payload - 'recipients') || jsonb_build_object('queued', v_n));
end $function$;
--@@ 45 funcao conv_private.ai_confirm_pre_broadcast_step(p_proposal uuid, p_m
CREATE OR REPLACE FUNCTION conv_private.ai_confirm_pre_broadcast_step(p_proposal uuid, p_message uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  bp public.conv_booking_proposals%rowtype; m public.conv_messages%rowtype; v_admin uuid; v_res jsonb; v_err text; v_code text;
  v_contact uuid; v_conv uuid; v_fu uuid;
begin
  select * into bp from public.conv_booking_proposals where id = p_proposal for update;
  if not found or bp.action <> 'adm_message_send' then return conv_private.ai_confirm_pre_message_step(p_proposal, p_message); end if;
  if bp.status = 'confirmed' then return jsonb_build_object('ok', true, 'replayed', true, 'action', bp.action, 'summary', bp.payload); end if;
  if bp.status <> 'open' then return conv_private.vfail('PROPOSAL_CLOSED', 'Essa proposta não está mais aberta.'); end if;
  if bp.expires_at <= now() then
    update public.conv_booking_proposals set status = 'expired' where id = bp.id;
    return conv_private.vfail('PROPOSAL_EXPIRED', 'A proposta venceu. Posso montar outra.');
  end if;
  select * into m from public.conv_messages where id = p_message and direction = 'inbound' and conversation_id = bp.conversation_id;
  if not found or m.created_at <= bp.created_at then
    return conv_private.vfail('CONFIRMATION_NOT_AFTER_PROPOSAL', 'A confirmação precisa vir depois da proposta.');
  end if;
  if m.kind <> 'text' or not (conv_private.is_confirmation(m.body) or conv_private.is_semantic_acceptance(m.body, false)) then
    return conv_private.vfail('NOT_EXPLICIT', 'Não entendi como confirmação clara.');
  end if;
  if m.sender_contact_id is distinct from bp.requester_contact_id then
    return conv_private.vfail('NOT_AUTHORIZED_TO_CONFIRM', 'Só o administrador que pediu pode confirmar.');
  end if;
  v_admin := conv_private.ai_admin_requester(bp.session_id);
  if v_admin is null or v_admin <> bp.requester_profile_id then
    update public.conv_booking_proposals set status = 'failed', failure_code = 'ADMIN_ONLY_PRIVATE' where id = bp.id;
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;
  begin
    if exists (select 1 from public.conv_contacts c where c.phone = bp.payload->>'phone' and c.opt_out) then raise exception 'OPT_OUT'; end if;
    v_contact := conv_private.upsert_contact(bp.payload->>'phone', null, bp.payload->>'member_name', true);
    v_conv := conv_private.open_direct(v_contact);
    insert into public.conv_followups(conversation_id, due_at, note, send_body, created_by)
    values (v_conv, now(), 'Mensagem pedida pelo administrador (WhatsApp)', bp.payload->>'body', v_admin) returning id into v_fu;
    v_res := jsonb_build_object('conversation_id', v_conv, 'followup_id', v_fu);
  exception when others then
    v_err := sqlerrm;
  end;
  if v_err is not null then
    v_code := case when v_err ~ '^[A-Z][A-Z_]+$' then v_err else 'ADMIN_ACTION_FAILED' end;
    update public.conv_booking_proposals set status = 'failed', failure_code = v_code where id = bp.id;
    return conv_private.vfail(v_code, 'Não consegui concluir: ' || v_code || '.');
  end if;
  update public.conv_booking_proposals set status = 'confirmed', confirmed_at = now(), confirmed_message_id = m.id,
    confirmed_by_contact_id = m.sender_contact_id, payload = bp.payload || jsonb_build_object('result', v_res) where id = bp.id;
  perform conv_private.audit('ai_admin_action', 'conv_conversations', v_conv::text, null,
    jsonb_build_object('action', bp.action, 'member', bp.payload->>'profile_id'),
    jsonb_build_object('actor', 'ai', 'source', 'whatsapp', 'conversation_id', bp.conversation_id, 'proposal_id', bp.id,
      'requester_profile_id', bp.requester_profile_id),
    bp.requester_profile_id);
  return jsonb_build_object('ok', true, 'action', bp.action, 'summary', bp.payload || jsonb_build_object('result', v_res));
end $function$;
--@@ 45 funcao conv_private.ai_confirm_pre_dependent_step(p_proposal uuid, p_m
CREATE OR REPLACE FUNCTION conv_private.ai_confirm_pre_dependent_step(p_proposal uuid, p_message uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  bp public.conv_booking_proposals%rowtype; m public.conv_messages%rowtype; v_admin uuid;
  v_prev_claims text; v_prev_sub text; v_res jsonb := '{}'::jsonb; v_err text; v_code text; v_id uuid; v_pref text; v_n int;
begin
  select * into bp from public.conv_booking_proposals where id = p_proposal for update;
  if not found or bp.action not in ('adm_followup_create', 'adm_followup_done', 'adm_court_block', 'adm_pref_set') then
    return conv_private.ai_confirm_wave7_step(p_proposal, p_message);
  end if;
  if bp.status = 'confirmed' then return jsonb_build_object('ok', true, 'replayed', true, 'action', bp.action, 'summary', bp.payload); end if;
  if bp.status <> 'open' then return conv_private.vfail('PROPOSAL_CLOSED', 'Essa proposta não está mais aberta.'); end if;
  if bp.expires_at <= now() then
    update public.conv_booking_proposals set status = 'expired' where id = bp.id;
    return conv_private.vfail('PROPOSAL_EXPIRED', 'A proposta venceu. Posso montar outra.');
  end if;
  select * into m from public.conv_messages where id = p_message and direction = 'inbound' and conversation_id = bp.conversation_id;
  if not found or m.created_at <= bp.created_at then
    return conv_private.vfail('CONFIRMATION_NOT_AFTER_PROPOSAL', 'A confirmação precisa vir depois da proposta.');
  end if;
  if m.kind <> 'text' or not (conv_private.is_confirmation(m.body) or conv_private.is_semantic_acceptance(m.body, false)) then
    return conv_private.vfail('NOT_EXPLICIT', 'Não entendi como confirmação clara.');
  end if;
  if m.sender_contact_id is distinct from bp.requester_contact_id then
    return conv_private.vfail('NOT_AUTHORIZED_TO_CONFIRM', 'Só o administrador que pediu pode confirmar.');
  end if;
  v_admin := conv_private.ai_admin_requester(bp.session_id);
  if v_admin is null or v_admin <> bp.requester_profile_id then
    update public.conv_booking_proposals set status = 'failed', failure_code = 'ADMIN_ONLY_PRIVATE' where id = bp.id;
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;

  v_prev_claims := current_setting('request.jwt.claims', true);
  v_prev_sub := current_setting('request.jwt.claim.sub', true);
  perform set_config('request.jwt.claims', jsonb_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
  perform set_config('request.jwt.claim.sub', v_admin::text, true);
  begin
    if bp.action = 'adm_followup_create' then
      v_id := public.conv_add_followup((bp.payload->>'conversation_id')::uuid, (bp.payload->>'due_at')::timestamptz, bp.payload->>'note', bp.payload->>'send_body');
      v_res := jsonb_build_object('id', v_id);
    elsif bp.action = 'adm_followup_done' then
      perform public.conv_update_followup((bp.payload->>'followup_id')::uuid, bp.payload->>'new_status');
      v_res := jsonb_build_object('id', bp.payload->>'followup_id');
    elsif bp.action = 'adm_court_block' then
      if conv_private.court_busy((bp.payload->>'court_id')::uuid, (bp.payload->>'date')::date,
           extract(hour from (bp.payload->>'start')::time)::int * 60 + extract(minute from (bp.payload->>'start')::time)::int,
           extract(hour from (bp.payload->>'start')::time)::int * 60 + extract(minute from (bp.payload->>'start')::time)::int + (bp.payload->>'duration')::int) then
        raise exception 'SLOT_TAKEN';
      end if;
      insert into public.reservations(type, date, start_time, end_time, court_id, creator_id, participant_ids, observation, status)
      values ('Play', (bp.payload->>'date')::date, (bp.payload->>'start')::time, (bp.payload->>'end')::time, (bp.payload->>'court_id')::uuid, v_admin, '{}',
        'Bloqueio' || coalesce(': ' || (bp.payload->>'reason'), ''), 'active')
      returning id into v_id;
      v_res := jsonb_build_object('id', v_id);
    else
      v_pref := bp.payload->>'pref';
      insert into public.conv_admin_prefs(profile_id) values (v_admin) on conflict do nothing;
      if v_pref = 'resumo' then update public.conv_admin_prefs set briefing_enabled = (bp.payload->>'active')::boolean, updated_at = now() where profile_id = v_admin;
      elsif v_pref = 'alertas' then update public.conv_admin_prefs set alerts_enabled = (bp.payload->>'active')::boolean, updated_at = now() where profile_id = v_admin;
      elsif v_pref = 'estilo' then update public.conv_admin_prefs set briefing_style = bp.payload->>'value', updated_at = now() where profile_id = v_admin;
      elsif v_pref = 'saldo_minimo' then update public.conv_admin_prefs set min_balance_cents = nullif(bp.payload->>'cents', '')::bigint, updated_at = now() where profile_id = v_admin;
      elsif v_pref = 'dias_atraso' then update public.conv_admin_prefs set overdue_days = (bp.payload->>'value')::int, updated_at = now() where profile_id = v_admin;
      else update public.conv_admin_prefs set default_account_id = nullif(bp.payload->>'account_id', '')::uuid, updated_at = now() where profile_id = v_admin;
      end if;
    end if;
  exception when others then
    v_err := sqlerrm;
  end;
  perform set_config('request.jwt.claims', coalesce(v_prev_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(v_prev_sub, ''), true);

  if v_err is not null then
    v_code := case when v_err ~ '^[A-Z][A-Z_]+$' then v_err else 'ADMIN_ACTION_FAILED' end;
    update public.conv_booking_proposals set status = 'failed', failure_code = v_code where id = bp.id;
    return conv_private.vfail(v_code, 'Não consegui concluir: ' || v_code || '.');
  end if;

  update public.conv_booking_proposals set status = 'confirmed', confirmed_at = now(), confirmed_message_id = m.id,
    confirmed_by_contact_id = m.sender_contact_id, payload = bp.payload || jsonb_build_object('result', v_res) where id = bp.id;
  perform conv_private.audit('ai_admin_action', 'conv_booking_proposals', bp.id::text, null,
    jsonb_build_object('action', bp.action, 'target', coalesce(v_res->>'id', bp.payload->>'pref')),
    jsonb_build_object('actor', 'ai', 'source', 'whatsapp', 'conversation_id', bp.conversation_id, 'proposal_id', bp.id,
      'requester_profile_id', bp.requester_profile_id),
    bp.requester_profile_id);
  return jsonb_build_object('ok', true, 'action', bp.action, 'summary', bp.payload || jsonb_build_object('result', v_res));
end $function$;
--@@ 45 funcao conv_private.ai_confirm_pre_memory_step(p_proposal uuid, p_mess
CREATE OR REPLACE FUNCTION conv_private.ai_confirm_pre_memory_step(p_proposal uuid, p_message uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  bp public.conv_booking_proposals%rowtype; m public.conv_messages%rowtype; v_admin uuid;
begin
  select * into bp from public.conv_booking_proposals where id = p_proposal for update;
  if not found or bp.action <> 'adm_briefing_recipient' then return conv_private.ai_confirm_pre_briefing_step(p_proposal, p_message); end if;
  if bp.status = 'confirmed' then return jsonb_build_object('ok', true, 'replayed', true, 'action', bp.action, 'summary', bp.payload); end if;
  if bp.status <> 'open' then return conv_private.vfail('PROPOSAL_CLOSED', 'Essa proposta não está mais aberta.'); end if;
  if bp.expires_at <= now() then
    update public.conv_booking_proposals set status = 'expired' where id = bp.id;
    return conv_private.vfail('PROPOSAL_EXPIRED', 'A proposta venceu. Posso montar outra.');
  end if;
  select * into m from public.conv_messages where id = p_message and direction = 'inbound' and conversation_id = bp.conversation_id;
  if not found or m.created_at <= bp.created_at then
    return conv_private.vfail('CONFIRMATION_NOT_AFTER_PROPOSAL', 'A confirmação precisa vir depois da proposta.');
  end if;
  if m.kind <> 'text' or not (conv_private.is_confirmation(m.body) or conv_private.is_semantic_acceptance(m.body, false)) then
    return conv_private.vfail('NOT_EXPLICIT', 'Não entendi como confirmação clara.');
  end if;
  if m.sender_contact_id is distinct from bp.requester_contact_id then
    return conv_private.vfail('NOT_AUTHORIZED_TO_CONFIRM', 'Só o administrador que pediu pode confirmar.');
  end if;
  v_admin := conv_private.ai_admin_requester(bp.session_id);
  if v_admin is null or v_admin <> bp.requester_profile_id then
    update public.conv_booking_proposals set status = 'failed', failure_code = 'ADMIN_ONLY_PRIVATE' where id = bp.id;
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;
  insert into public.conv_admin_briefing_recipients(profile_id, enabled)
  values ((bp.payload->>'profile_id')::uuid, (bp.payload->>'enabled')::boolean)
  on conflict (profile_id) do update set enabled = excluded.enabled;
  update public.conv_booking_proposals set status = 'confirmed', confirmed_at = now(), confirmed_message_id = m.id,
    confirmed_by_contact_id = m.sender_contact_id where id = bp.id;
  perform conv_private.audit('ai_admin_action', 'conv_admin_briefing_recipients', bp.payload->>'profile_id', null,
    jsonb_build_object('action', bp.action, 'enabled', bp.payload->'enabled'),
    jsonb_build_object('actor', 'ai', 'source', 'whatsapp', 'conversation_id', bp.conversation_id, 'proposal_id', bp.id,
      'requester_profile_id', bp.requester_profile_id), bp.requester_profile_id);
  return jsonb_build_object('ok', true, 'action', bp.action, 'summary', bp.payload);
end $function$;
--@@ 45 funcao conv_private.ai_confirm_pre_message_step(p_proposal uuid, p_mes
CREATE OR REPLACE FUNCTION conv_private.ai_confirm_pre_message_step(p_proposal uuid, p_message uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  bp public.conv_booking_proposals%rowtype; m public.conv_messages%rowtype; v_admin uuid; v_id uuid; v_res jsonb; v_err text; v_code text;
begin
  select * into bp from public.conv_booking_proposals where id = p_proposal for update;
  if not found or bp.action <> 'adm_dependent_create' then return conv_private.ai_confirm_pre_dependent_step(p_proposal, p_message); end if;
  if bp.status = 'confirmed' then return jsonb_build_object('ok', true, 'replayed', true, 'action', bp.action, 'summary', bp.payload); end if;
  if bp.status <> 'open' then return conv_private.vfail('PROPOSAL_CLOSED', 'Essa proposta não está mais aberta.'); end if;
  if bp.expires_at <= now() then
    update public.conv_booking_proposals set status = 'expired' where id = bp.id;
    return conv_private.vfail('PROPOSAL_EXPIRED', 'A proposta venceu. Posso montar outra.');
  end if;
  select * into m from public.conv_messages where id = p_message and direction = 'inbound' and conversation_id = bp.conversation_id;
  if not found or m.created_at <= bp.created_at then
    return conv_private.vfail('CONFIRMATION_NOT_AFTER_PROPOSAL', 'A confirmação precisa vir depois da proposta.');
  end if;
  if m.kind <> 'text' or not (conv_private.is_confirmation(m.body) or conv_private.is_semantic_acceptance(m.body, false)) then
    return conv_private.vfail('NOT_EXPLICIT', 'Não entendi como confirmação clara.');
  end if;
  if m.sender_contact_id is distinct from bp.requester_contact_id then
    return conv_private.vfail('NOT_AUTHORIZED_TO_CONFIRM', 'Só o administrador que pediu pode confirmar.');
  end if;
  v_admin := conv_private.ai_admin_requester(bp.session_id);
  if v_admin is null or v_admin <> bp.requester_profile_id then
    update public.conv_booking_proposals set status = 'failed', failure_code = 'ADMIN_ONLY_PRIVATE' where id = bp.id;
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;
  begin
    if not exists (select 1 from public.profiles where id = (bp.payload->>'profile_id')::uuid and role::text in ('socio', 'admin') and coalesce(is_active, true)) then
      raise exception 'MEMBER_NOT_FOUND';
    end if;
    insert into public.non_socio_students(name, phone, student_type, responsible_socio_id, relationship_type, plan_type, plan_status)
    values (bp.payload->>'dependent_name', bp.payload->>'phone', 'dependent', (bp.payload->>'profile_id')::uuid, bp.payload->>'relationship', 'Dependente', 'active')
    returning id into v_id;
    insert into public.student_profiles(non_socio_student_id, student_status) values (v_id, 'active');
    v_res := jsonb_build_object('id', v_id);
  exception when others then
    v_err := sqlerrm;
  end;
  if v_err is not null then
    v_code := case when v_err ~ '^[A-Z][A-Z_]+$' then v_err else 'ADMIN_ACTION_FAILED' end;
    update public.conv_booking_proposals set status = 'failed', failure_code = v_code where id = bp.id;
    return conv_private.vfail(v_code, 'Não consegui concluir: ' || v_code || '.');
  end if;
  update public.conv_booking_proposals set status = 'confirmed', confirmed_at = now(), confirmed_message_id = m.id,
    confirmed_by_contact_id = m.sender_contact_id, payload = bp.payload || jsonb_build_object('result', v_res) where id = bp.id;
  perform conv_private.audit('ai_admin_action', 'non_socio_students', v_id::text, null,
    jsonb_build_object('action', bp.action, 'responsible', bp.payload->>'profile_id', 'relationship', bp.payload->>'relationship'),
    jsonb_build_object('actor', 'ai', 'source', 'whatsapp', 'conversation_id', bp.conversation_id, 'proposal_id', bp.id,
      'requester_profile_id', bp.requester_profile_id),
    bp.requester_profile_id);
  return jsonb_build_object('ok', true, 'action', bp.action, 'summary', bp.payload || jsonb_build_object('result', v_res));
end $function$;
--@@ 45 funcao conv_private.ai_confirm_single_step(p_proposal uuid, p_message 
CREATE OR REPLACE FUNCTION conv_private.ai_confirm_single_step(p_proposal uuid, p_message uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  bp public.conv_booking_proposals%rowtype; m public.conv_messages%rowtype; v_admin uuid; v_n int;
begin
  select * into bp from public.conv_booking_proposals where id = p_proposal for update;
  if not found or bp.action <> 'adm_memory_forget' then return conv_private.ai_confirm_pre_memory_step(p_proposal, p_message); end if;
  if bp.status = 'confirmed' then return jsonb_build_object('ok', true, 'replayed', true, 'action', bp.action, 'summary', bp.payload); end if;
  if bp.status <> 'open' then return conv_private.vfail('PROPOSAL_CLOSED', 'Essa proposta não está mais aberta.'); end if;
  if bp.expires_at <= now() then
    update public.conv_booking_proposals set status = 'expired' where id = bp.id;
    return conv_private.vfail('PROPOSAL_EXPIRED', 'A proposta venceu. Posso montar outra.');
  end if;
  select * into m from public.conv_messages where id = p_message and direction = 'inbound' and conversation_id = bp.conversation_id;
  if not found or m.created_at <= bp.created_at then
    return conv_private.vfail('CONFIRMATION_NOT_AFTER_PROPOSAL', 'A confirmação precisa vir depois da proposta.');
  end if;
  if m.kind <> 'text' or not (conv_private.is_confirmation(m.body) or conv_private.is_semantic_acceptance(m.body, false)) then
    return conv_private.vfail('NOT_EXPLICIT', 'Não entendi como confirmação clara.');
  end if;
  if m.sender_contact_id is distinct from bp.requester_contact_id then
    return conv_private.vfail('NOT_AUTHORIZED_TO_CONFIRM', 'Só o administrador que pediu pode confirmar.');
  end if;
  v_admin := conv_private.ai_admin_requester(bp.session_id);
  if v_admin is null or v_admin <> bp.requester_profile_id then
    update public.conv_booking_proposals set status = 'failed', failure_code = 'ADMIN_ONLY_PRIVATE' where id = bp.id;
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;
  update public.conv_ai_memory_candidates set status = 'superseded', reviewed_at = now()
   where status = 'approved' and id in (select (x->>'id')::uuid from jsonb_array_elements(bp.payload->'items') x);
  get diagnostics v_n = row_count;
  update public.conv_booking_proposals set status = 'confirmed', confirmed_at = now(), confirmed_message_id = m.id,
    confirmed_by_contact_id = m.sender_contact_id, payload = bp.payload || jsonb_build_object('forgotten', v_n) where id = bp.id;
  perform conv_private.audit('ai_admin_action', 'conv_ai_memory_candidates', bp.id::text, null,
    jsonb_build_object('action', bp.action, 'forgotten', v_n),
    jsonb_build_object('actor', 'ai', 'source', 'whatsapp', 'conversation_id', bp.conversation_id, 'proposal_id', bp.id,
      'requester_profile_id', bp.requester_profile_id), bp.requester_profile_id);
  return jsonb_build_object('ok', true, 'action', bp.action, 'summary', bp.payload || jsonb_build_object('forgotten', v_n));
end $function$;
--@@ 45 funcao conv_private.ai_confirm_wave2_step(p_proposal uuid, p_message u
CREATE OR REPLACE FUNCTION conv_private.ai_confirm_wave2_step(p_proposal uuid, p_message uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  bp public.conv_booking_proposals%rowtype; m public.conv_messages%rowtype; v_admin uuid;
  v_prev_claims text; v_prev_sub text; v_res jsonb; v_err text; v_code text;
begin
  select * into bp from public.conv_booking_proposals where id = p_proposal for update;
  if not found or bp.action not in ('fin_charge_cancel', 'fin_charge_adjust', 'fin_payment_reverse', 'fin_receipt_reject', 'fin_entry_create') then
    return conv_private.ai_confirm_pendency_step(p_proposal, p_message);
  end if;
  if bp.status = 'confirmed' then return jsonb_build_object('ok', true, 'replayed', true, 'action', bp.action, 'summary', bp.payload); end if;
  if bp.status <> 'open' then return conv_private.vfail('PROPOSAL_CLOSED', 'Essa proposta não está mais aberta.'); end if;
  if bp.expires_at <= now() then
    update public.conv_booking_proposals set status = 'expired' where id = bp.id;
    return conv_private.vfail('PROPOSAL_EXPIRED', 'A proposta venceu. Posso montar outra.');
  end if;
  select * into m from public.conv_messages where id = p_message and direction = 'inbound' and conversation_id = bp.conversation_id;
  if not found or m.created_at <= bp.created_at then
    return conv_private.vfail('CONFIRMATION_NOT_AFTER_PROPOSAL', 'A confirmação precisa vir depois da proposta.');
  end if;
  if m.kind <> 'text' or not (conv_private.is_confirmation(m.body) or conv_private.is_semantic_acceptance(m.body, false)) then
    return conv_private.vfail('NOT_EXPLICIT', 'Não entendi como confirmação clara.');
  end if;
  if m.sender_contact_id is distinct from bp.requester_contact_id then
    return conv_private.vfail('NOT_AUTHORIZED_TO_CONFIRM', 'Só o administrador que pediu pode confirmar.');
  end if;
  v_admin := conv_private.ai_admin_requester(bp.session_id);
  if v_admin is null or v_admin <> bp.requester_profile_id then
    update public.conv_booking_proposals set status = 'failed', failure_code = 'ADMIN_ONLY_PRIVATE' where id = bp.id;
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;

  v_prev_claims := current_setting('request.jwt.claims', true);
  v_prev_sub := current_setting('request.jwt.claim.sub', true);
  perform set_config('request.jwt.claims', jsonb_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
  perform set_config('request.jwt.claim.sub', v_admin::text, true);
  begin
    if bp.action = 'fin_charge_cancel' then
      v_res := public.fin_cancel_charge(bp.request_key, (bp.payload->>'charge_id')::uuid, bp.payload->>'reason');
    elsif bp.action = 'fin_charge_adjust' then
      v_res := public.fin_adjust_charge(bp.request_key, (bp.payload->>'charge_id')::uuid, bp.payload->>'adjust_kind',
        (bp.payload->>'amount_cents')::bigint, bp.payload->>'reason');
    elsif bp.action = 'fin_payment_reverse' then
      v_res := public.fin_reverse_payment(bp.request_key, (bp.payload->>'payment_id')::uuid, bp.payload->>'reason');
    elsif bp.action = 'fin_receipt_reject' then
      v_res := public.fin_reject_receipt(bp.request_key, (bp.payload->>'submission_id')::uuid, bp.payload->>'reason');
    else
      v_res := public.fin_create_entry(bp.request_key, jsonb_strip_nulls(jsonb_build_object(
        'kind', bp.payload->>'entry_kind', 'description', bp.payload->>'description', 'amount_cents', (bp.payload->>'amount_cents')::bigint,
        'status', bp.payload->>'entry_status', 'due_date', bp.payload->>'due_date', 'paid_on', bp.payload->>'paid_on',
        'account_id', bp.payload->>'account_id', 'category_id', bp.payload->>'category_id', 'supplier', bp.payload->>'supplier')));
    end if;
  exception when others then
    v_err := sqlerrm;
  end;
  perform set_config('request.jwt.claims', coalesce(v_prev_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(v_prev_sub, ''), true);

  if v_err is not null then
    v_code := case when v_err ~ '^[A-Z][A-Z_]+$' then v_err else 'FINANCE_FAILED' end;
    update public.conv_booking_proposals set status = 'failed', failure_code = v_code where id = bp.id;
    return conv_private.vfail(v_code, 'O financeiro recusou: ' || v_code || '.');
  end if;

  update public.conv_booking_proposals set status = 'confirmed', confirmed_at = now(), confirmed_message_id = m.id,
    confirmed_by_contact_id = m.sender_contact_id, payload = bp.payload || jsonb_build_object('result', v_res) where id = bp.id;
  perform conv_private.audit('ai_admin_finance', 'fin_member_charges', coalesce(v_res->>'id', bp.payload->>'charge_id', bp.payload->>'submission_id'), null,
    jsonb_build_object('action', bp.action, 'amount_cents', bp.payload->'amount_cents', 'reason', bp.payload->'reason'),
    jsonb_build_object('actor', 'ai', 'source', 'whatsapp', 'conversation_id', bp.conversation_id, 'proposal_id', bp.id,
      'requester_profile_id', bp.requester_profile_id),
    bp.requester_profile_id);
  return jsonb_build_object('ok', true, 'action', bp.action, 'summary', bp.payload || jsonb_build_object('result', v_res));
end $function$;
--@@ 45 funcao conv_private.ai_confirm_wave3_step(p_proposal uuid, p_message u
CREATE OR REPLACE FUNCTION conv_private.ai_confirm_wave3_step(p_proposal uuid, p_message uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  bp public.conv_booking_proposals%rowtype; m public.conv_messages%rowtype; v_admin uuid;
  v_prev_claims text; v_prev_sub text; v_res jsonb; v_err text; v_code text; v_n int;
begin
  select * into bp from public.conv_booking_proposals where id = p_proposal for update;
  if not found or bp.action not like 'adm\_%' then return conv_private.ai_confirm_wave2_step(p_proposal, p_message); end if;
  if bp.status = 'confirmed' then return jsonb_build_object('ok', true, 'replayed', true, 'action', bp.action, 'summary', bp.payload); end if;
  if bp.status <> 'open' then return conv_private.vfail('PROPOSAL_CLOSED', 'Essa proposta não está mais aberta.'); end if;
  if bp.expires_at <= now() then
    update public.conv_booking_proposals set status = 'expired' where id = bp.id;
    return conv_private.vfail('PROPOSAL_EXPIRED', 'A proposta venceu. Posso montar outra.');
  end if;
  select * into m from public.conv_messages where id = p_message and direction = 'inbound' and conversation_id = bp.conversation_id;
  if not found or m.created_at <= bp.created_at then
    return conv_private.vfail('CONFIRMATION_NOT_AFTER_PROPOSAL', 'A confirmação precisa vir depois da proposta.');
  end if;
  if m.kind <> 'text' or not (conv_private.is_confirmation(m.body) or conv_private.is_semantic_acceptance(m.body, false)) then
    return conv_private.vfail('NOT_EXPLICIT', 'Não entendi como confirmação clara.');
  end if;
  if m.sender_contact_id is distinct from bp.requester_contact_id then
    return conv_private.vfail('NOT_AUTHORIZED_TO_CONFIRM', 'Só o administrador que pediu pode confirmar.');
  end if;
  v_admin := conv_private.ai_admin_requester(bp.session_id);
  if v_admin is null or v_admin <> bp.requester_profile_id then
    update public.conv_booking_proposals set status = 'failed', failure_code = 'ADMIN_ONLY_PRIVATE' where id = bp.id;
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;

  v_prev_claims := current_setting('request.jwt.claims', true);
  v_prev_sub := current_setting('request.jwt.claim.sub', true);
  perform set_config('request.jwt.claims', jsonb_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
  perform set_config('request.jwt.claim.sub', v_admin::text, true);
  begin
    if bp.action = 'adm_announcement_create' then
      insert into public.announcements(title, message, show_once, expires_at, is_active)
      values (bp.payload->>'title', bp.payload->>'message', coalesce((bp.payload->>'show_once')::boolean, false),
        case when bp.payload->>'expires_on' is null then null else ((bp.payload->>'expires_on') || ' 23:59:59-03')::timestamptz end, true)
      returning jsonb_build_object('id', id) into v_res;
    elsif bp.action = 'adm_announcement_deactivate' then
      update public.announcements set is_active = false, updated_at = now() where id = (bp.payload->>'announcement_id')::uuid and coalesce(is_active, true);
      get diagnostics v_n = row_count;
      if v_n = 0 then raise exception 'ANNOUNCEMENT_NOT_FOUND'; end if;
      v_res := jsonb_build_object('id', bp.payload->>'announcement_id');
    elsif bp.action = 'adm_student_status' then
      update public.student_profiles set student_status = bp.payload->>'status' where id = (bp.payload->>'student_profile_id')::uuid;
      get diagnostics v_n = row_count;
      if v_n = 0 then raise exception 'STUDENT_NOT_FOUND'; end if;
      v_res := jsonb_build_object('id', bp.payload->>'student_profile_id');
    elsif bp.action = 'adm_member_status' then
      update public.profiles set is_active = (bp.payload->>'active')::boolean where id = (bp.payload->>'profile_id')::uuid and role::text <> 'admin';
      get diagnostics v_n = row_count;
      if v_n = 0 then raise exception 'MEMBER_NOT_FOUND'; end if;
      v_res := jsonb_build_object('id', bp.payload->>'profile_id');
    elsif bp.action = 'adm_signature_resend' then
      v_res := jsonb_build_object('id', bp.payload->>'document_id', 'resent', public.sig_resend_failed((bp.payload->>'document_id')::uuid));
    else
      update public.reservations set status = 'cancelled', updated_at = now() where id = (bp.payload->>'reservation_id')::uuid and coalesce(status::text, 'active') = 'active';
      get diagnostics v_n = row_count;
      if v_n = 0 then raise exception 'RESERVATION_NOT_FOUND'; end if;
      v_res := jsonb_build_object('id', bp.payload->>'reservation_id');
    end if;
  exception when others then
    v_err := sqlerrm;
  end;
  perform set_config('request.jwt.claims', coalesce(v_prev_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(v_prev_sub, ''), true);

  if v_err is not null then
    v_code := case when v_err ~ '^[A-Z][A-Z_]+$' then v_err else 'ADMIN_ACTION_FAILED' end;
    update public.conv_booking_proposals set status = 'failed', failure_code = v_code where id = bp.id;
    return conv_private.vfail(v_code, 'Não consegui concluir: ' || v_code || '.');
  end if;

  update public.conv_booking_proposals set status = 'confirmed', confirmed_at = now(), confirmed_message_id = m.id,
    confirmed_by_contact_id = m.sender_contact_id, payload = bp.payload || jsonb_build_object('result', v_res) where id = bp.id;
  perform conv_private.audit('ai_admin_action', 'conv_booking_proposals', bp.id::text, null,
    jsonb_build_object('action', bp.action, 'target', coalesce(v_res->>'id', bp.payload->>'profile_id')),
    jsonb_build_object('actor', 'ai', 'source', 'whatsapp', 'conversation_id', bp.conversation_id, 'proposal_id', bp.id,
      'requester_profile_id', bp.requester_profile_id),
    bp.requester_profile_id);
  return jsonb_build_object('ok', true, 'action', bp.action, 'summary', bp.payload || jsonb_build_object('result', v_res));
end $function$;
--@@ 45 funcao conv_private.ai_confirm_wave6_step(p_proposal uuid, p_message u
CREATE OR REPLACE FUNCTION conv_private.ai_confirm_wave6_step(p_proposal uuid, p_message uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  bp public.conv_booking_proposals%rowtype; m public.conv_messages%rowtype; v_admin uuid;
  v_prev_claims text; v_prev_sub text; v_res jsonb; v_err text; v_code text;
begin
  select * into bp from public.conv_booking_proposals where id = p_proposal for update;
  if not found or bp.action not in ('fin_receipt_approve', 'fin_charges_generate') then
    return conv_private.ai_confirm_wave3_step(p_proposal, p_message);
  end if;
  if bp.status = 'confirmed' then return jsonb_build_object('ok', true, 'replayed', true, 'action', bp.action, 'summary', bp.payload); end if;
  if bp.status <> 'open' then return conv_private.vfail('PROPOSAL_CLOSED', 'Essa proposta não está mais aberta.'); end if;
  if bp.expires_at <= now() then
    update public.conv_booking_proposals set status = 'expired' where id = bp.id;
    return conv_private.vfail('PROPOSAL_EXPIRED', 'A proposta venceu. Posso montar outra.');
  end if;
  select * into m from public.conv_messages where id = p_message and direction = 'inbound' and conversation_id = bp.conversation_id;
  if not found or m.created_at <= bp.created_at then
    return conv_private.vfail('CONFIRMATION_NOT_AFTER_PROPOSAL', 'A confirmação precisa vir depois da proposta.');
  end if;
  if m.kind <> 'text' or not (conv_private.is_confirmation(m.body) or conv_private.is_semantic_acceptance(m.body, false)) then
    return conv_private.vfail('NOT_EXPLICIT', 'Não entendi como confirmação clara.');
  end if;
  if m.sender_contact_id is distinct from bp.requester_contact_id then
    return conv_private.vfail('NOT_AUTHORIZED_TO_CONFIRM', 'Só o administrador que pediu pode confirmar.');
  end if;
  v_admin := conv_private.ai_admin_requester(bp.session_id);
  if v_admin is null or v_admin <> bp.requester_profile_id then
    update public.conv_booking_proposals set status = 'failed', failure_code = 'ADMIN_ONLY_PRIVATE' where id = bp.id;
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;

  v_prev_claims := current_setting('request.jwt.claims', true);
  v_prev_sub := current_setting('request.jwt.claim.sub', true);
  perform set_config('request.jwt.claims', jsonb_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
  perform set_config('request.jwt.claim.sub', v_admin::text, true);
  begin
    if bp.action = 'fin_receipt_approve' then
      v_res := public.fin_approve_receipt(bp.request_key, (bp.payload->>'submission_id')::uuid, jsonb_build_object(
        'paid_on', bp.payload->>'paid_on', 'method', bp.payload->>'method', 'account_id', bp.payload->>'account_id',
        'note', 'Aprovado pelo João (WhatsApp)',
        'allocations', (select jsonb_agg(jsonb_build_object('charge_id', a->>'charge_id', 'amount_cents', (a->>'amount_cents')::bigint))
                        from jsonb_array_elements(bp.payload->'allocations') a)));
    else
      v_res := public.fin_generate_member_charges(bp.request_key, null, null);
    end if;
  exception when others then
    v_err := sqlerrm;
  end;
  perform set_config('request.jwt.claims', coalesce(v_prev_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(v_prev_sub, ''), true);

  if v_err is not null then
    v_code := case when v_err ~ '^[A-Z][A-Z_]+$' then v_err else 'FINANCE_FAILED' end;
    update public.conv_booking_proposals set status = 'failed', failure_code = v_code where id = bp.id;
    return conv_private.vfail(v_code, 'O financeiro recusou: ' || v_code || '.');
  end if;

  update public.conv_booking_proposals set status = 'confirmed', confirmed_at = now(), confirmed_message_id = m.id,
    confirmed_by_contact_id = m.sender_contact_id, payload = bp.payload || jsonb_build_object('result', v_res) where id = bp.id;
  perform conv_private.audit('ai_admin_finance', 'fin_receipt_submissions', coalesce(bp.payload->>'submission_id', bp.id::text), null,
    jsonb_build_object('action', bp.action, 'amount_cents', bp.payload->'amount_cents'),
    jsonb_build_object('actor', 'ai', 'source', 'whatsapp', 'conversation_id', bp.conversation_id, 'proposal_id', bp.id,
      'requester_profile_id', bp.requester_profile_id),
    bp.requester_profile_id);
  return jsonb_build_object('ok', true, 'action', bp.action, 'summary', bp.payload || jsonb_build_object('result', v_res));
end $function$;
--@@ 45 funcao conv_private.ai_confirm_wave7_step(p_proposal uuid, p_message u
CREATE OR REPLACE FUNCTION conv_private.ai_confirm_wave7_step(p_proposal uuid, p_message uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  bp public.conv_booking_proposals%rowtype; m public.conv_messages%rowtype; v_admin uuid;
  v_prev_claims text; v_prev_sub text; v_err text; v_code text; v_n int;
begin
  select * into bp from public.conv_booking_proposals where id = p_proposal for update;
  if not found or bp.action not in ('fin_member_create', 'fin_access_approve', 'adm_access_reject') then
    return conv_private.ai_confirm_wave6_step(p_proposal, p_message);
  end if;
  if bp.status = 'confirmed' then return jsonb_build_object('ok', true, 'replayed', true, 'action', bp.action, 'summary', bp.payload); end if;
  if bp.status <> 'open' then return conv_private.vfail('PROPOSAL_CLOSED', 'Essa proposta não está mais aberta.'); end if;
  if bp.expires_at <= now() then
    update public.conv_booking_proposals set status = 'expired' where id = bp.id;
    return conv_private.vfail('PROPOSAL_EXPIRED', 'A proposta venceu. Posso montar outra.');
  end if;
  select * into m from public.conv_messages where id = p_message and direction = 'inbound' and conversation_id = bp.conversation_id;
  if not found or m.created_at <= bp.created_at then
    return conv_private.vfail('CONFIRMATION_NOT_AFTER_PROPOSAL', 'A confirmação precisa vir depois da proposta.');
  end if;
  if m.kind <> 'text' or not (conv_private.is_confirmation(m.body) or conv_private.is_semantic_acceptance(m.body, false)) then
    return conv_private.vfail('NOT_EXPLICIT', 'Não entendi como confirmação clara.');
  end if;
  if m.sender_contact_id is distinct from bp.requester_contact_id then
    return conv_private.vfail('NOT_AUTHORIZED_TO_CONFIRM', 'Só o administrador que pediu pode confirmar.');
  end if;
  v_admin := conv_private.ai_admin_requester(bp.session_id);
  if v_admin is null or v_admin <> bp.requester_profile_id then
    update public.conv_booking_proposals set status = 'failed', failure_code = 'ADMIN_ONLY_PRIVATE' where id = bp.id;
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;

  -- Cadastro: o servidor cria o usuário no Auth e depois chama conv_svc_ai_admin_member_onboard (a proposta segue aberta até lá).
  if bp.action <> 'adm_access_reject' then
    -- Marca que a confirmação (e a segunda, de R$ 400 em diante) já passou: só então o cadastro pode ser concluído.
    update public.conv_booking_proposals set payload = payload || jsonb_build_object('cleared', true, 'cleared_message_id', m.id) where id = bp.id;
    return jsonb_build_object('ok', true, 'needs_provision', true, 'action', bp.action, 'proposal_id', bp.id, 'summary', bp.payload);
  end if;

  v_prev_claims := current_setting('request.jwt.claims', true);
  v_prev_sub := current_setting('request.jwt.claim.sub', true);
  perform set_config('request.jwt.claims', jsonb_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
  perform set_config('request.jwt.claim.sub', v_admin::text, true);
  begin
    update public.access_requests set status = 'rejected', rejection_reason = bp.payload->>'reason', decided_by = v_admin, decided_at = now()
    where id = (bp.payload->>'request_id')::uuid and status = 'pending';
    get diagnostics v_n = row_count;
    if v_n = 0 then raise exception 'ACCESS_NOT_FOUND'; end if;
  exception when others then
    v_err := sqlerrm;
  end;
  perform set_config('request.jwt.claims', coalesce(v_prev_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(v_prev_sub, ''), true);

  if v_err is not null then
    v_code := case when v_err ~ '^[A-Z][A-Z_]+$' then v_err else 'ADMIN_ACTION_FAILED' end;
    update public.conv_booking_proposals set status = 'failed', failure_code = v_code where id = bp.id;
    return conv_private.vfail(v_code, 'Não consegui concluir: ' || v_code || '.');
  end if;
  update public.conv_booking_proposals set status = 'confirmed', confirmed_at = now(), confirmed_message_id = m.id,
    confirmed_by_contact_id = m.sender_contact_id where id = bp.id;
  perform conv_private.audit('ai_admin_action', 'access_requests', bp.payload->>'request_id', null,
    jsonb_build_object('action', bp.action, 'target', bp.payload->>'name'),
    jsonb_build_object('actor', 'ai', 'source', 'whatsapp', 'conversation_id', bp.conversation_id, 'proposal_id', bp.id,
      'requester_profile_id', bp.requester_profile_id),
    bp.requester_profile_id);
  return jsonb_build_object('ok', true, 'action', bp.action, 'summary', bp.payload);
end $function$;
--@@ 45 funcao conv_private.ai_context(p_session uuid)
CREATE OR REPLACE FUNCTION conv_private.ai_context(p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  sess public.conv_ai_sessions%rowtype; cv public.conv_conversations%rowtype; c public.conv_contacts%rowtype;
  pr public.profiles%rowtype; s public.conv_ai_settings%rowtype; ch public.conv_channel%rowtype; v_transcript jsonb;
  v_prof_json jsonb := null; v_prof_id uuid; v_since timestamptz; v_cutoff timestamptz; v_older integer; v_prior text;
begin
  select * into sess from public.conv_ai_sessions where id = p_session;
  if not found then raise exception 'SESSION_NOT_FOUND'; end if;
  select * into cv from public.conv_conversations where id = sess.conversation_id;
  select * into c from public.conv_contacts where id = sess.requester_contact_id;
  select * into s from public.conv_ai_settings where active order by version desc limit 1;
  select * into ch from public.conv_channel where id;
  v_since := coalesce(cv.handoff_at, '-infinity'::timestamptz);

  if c.profile_id is not null and c.link_status in ('linked', 'manual') then
    select * into pr from public.profiles where id = c.profile_id;
    v_prof_json := jsonb_build_object('id', pr.id, 'name', pr.name, 'is_admin', pr.role::text = 'admin',
      'is_member', pr.role::text in ('socio', 'admin') and coalesce(pr.is_active, true),
      'professor_id', (select p2.id from public.professors p2 where p2.user_id = pr.id and coalesce(p2.is_active, true) limit 1));
    v_prof_id := pr.id;
  end if;

  -- Janela de contexto: as últimas 8 trocas desta pessoa (8 mensagens dela e o que veio no meio: IA, equipe, automação).
  -- O que ficou para trás não some: vira o resumo que o agente mantém na memória da sessão (`memory.summary`).
  if cv.kind = 'group' then
    select min(x.created_at) into v_cutoff from (
      select m.created_at from public.conv_messages m
      where m.ai_session_id = p_session and m.direction = 'inbound' and m.deleted_at is null order by m.created_at desc limit 8) x;
    select count(*) into v_older from public.conv_messages m
      where m.ai_session_id = p_session and m.deleted_at is null and m.created_at < coalesce(v_cutoff, '-infinity'::timestamptz);
    select coalesce(jsonb_agg(t order by t.created_at), '[]'::jsonb) into v_transcript from (
      select m.id, m.created_at, m.direction, m.origin, m.kind, left(coalesce(m.body, ''), 1000) as body
      from public.conv_messages m
      where m.ai_session_id = p_session and m.deleted_at is null and m.created_at >= coalesce(v_cutoff, '-infinity'::timestamptz)
      order by m.created_at desc limit 40) t;
  else
    select min(x.created_at) into v_cutoff from (
      select m.created_at from public.conv_messages m
      where m.conversation_id = cv.id and m.direction = 'inbound' and m.deleted_at is null and m.created_at > v_since order by m.created_at desc limit 8) x;
    select count(*) into v_older from public.conv_messages m
      where m.conversation_id = cv.id and m.deleted_at is null and m.created_at > v_since and m.created_at < coalesce(v_cutoff, '-infinity'::timestamptz);
    select coalesce(jsonb_agg(t order by t.created_at), '[]'::jsonb) into v_transcript from (
      select m.id, m.created_at, m.direction, m.origin, m.kind, left(coalesce(m.body, ''), 1000) as body
      from public.conv_messages m
      where m.conversation_id = cv.id and m.deleted_at is null and m.created_at > v_since and m.created_at >= coalesce(v_cutoff, '-infinity'::timestamptz)
      order by m.created_at desc limit 40) t;
  end if;

  -- Atendimento anterior da MESMA pessoa nesta conversa: o resumo dele continua valendo (a sessão nova começa sem memória).
  select left(s2.memory->>'summary', 700) into v_prior from public.conv_ai_sessions s2
    where s2.conversation_id = sess.conversation_id and s2.requester_contact_id = sess.requester_contact_id and s2.id <> sess.id
      and nullif(s2.memory->>'summary', '') is not null and s2.started_at > now() - interval '30 days'
    order by s2.started_at desc limit 1;

  return jsonb_build_object(
    'now_local', to_char(now() at time zone 'America/Fortaleza', 'YYYY-MM-DD"T"HH24:MI'),
    'weekday_today', extract(dow from now() at time zone 'America/Fortaleza')::int,
    'settings', to_jsonb(s) - 'created_by',
    'institutional_name', ch.institutional_name,
    'is_group', cv.kind = 'group',
    'group_name', (select g.name from public.conv_groups g where g.id = cv.group_id),
    'session', jsonb_build_object('id', sess.id, 'turns', sess.turns, 'memory', sess.memory, 'status', sess.status, 'expires_at', sess.expires_at),
    'requester', jsonb_build_object('contact_name', c.name, 'link_status', c.link_status, 'profile', v_prof_json),
    'courts', (select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name, 'type', x.type::text) order by x.name), '[]'::jsonb)
               from public.courts x where coalesce(x.is_active, true)),
    'my_reservations', case when v_prof_id is null then '[]'::jsonb else conv_private.ai_my_reservations(v_prof_id) end,
    'open_proposal', (select jsonb_build_object('id', bp.id, 'action', bp.action, 'payload', bp.payload, 'expires_at', bp.expires_at)
                      from public.conv_booking_proposals bp where bp.session_id = p_session and bp.status = 'open' and bp.expires_at > now()
                      order by bp.created_at desc limit 1),
    'transcript', v_transcript, 'older_messages', v_older, 'prior_summary', v_prior,
    'agenda', conv_private.ai_agenda(v_prof_id));
end $function$;
--@@ 45 funcao conv_private.ai_expire_sessions()
CREATE OR REPLACE FUNCTION conv_private.ai_expire_sessions()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_n integer;
begin
  update public.conv_ai_sessions set status = 'expired', awaiting = false where status = 'open' and expires_at <= now();
  get diagnostics v_n = row_count;
  update public.conv_booking_proposals set status = 'expired' where status = 'open' and expires_at <= now();
  return v_n;
end $function$;
--@@ 45 funcao conv_private.ai_financial_context()
CREATE OR REPLACE FUNCTION conv_private.ai_financial_context()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
with
today as (
  select (now() at time zone 'America/Fortaleza')::date as d
),
students as (
  select
    ns.id, ns.name, ns.plan_type, ns.plan_status, coalesce(ns.is_active,true) record_active,
    ns.student_type, ns.master_expiration_date,
    coalesce(sp.student_status,'active') student_status,
    prof_profile.name professor_name, resp.name responsible_name,
    greatest(ns.master_expiration_date,ap.active_valid_until::date) effective_valid_until,
    ap.last_active_payment_at, ap.last_active_amount,
    lp.payment_date latest_payment_at, lp.amount latest_payment_amount, lp.status::text latest_payment_status,
    lp.cancelled_reason latest_cancelled_reason
  from public.non_socio_students ns
  left join lateral (
    select x.student_status,x.professor_id from public.student_profiles x
    where x.non_socio_student_id=ns.id order by x.updated_at desc,x.created_at desc limit 1
  ) sp on true
  left join public.professors prof on prof.id=coalesce(sp.professor_id,ns.professor_id)
  left join public.profiles prof_profile on prof_profile.id=prof.user_id
  left join public.profiles resp on resp.id=ns.responsible_socio_id
  left join lateral (
    select max(p.valid_until) filter(where p.status::text='active') active_valid_until,
      max(p.payment_date) filter(where p.status::text='active') last_active_payment_at,
      (array_agg(p.amount order by p.payment_date desc) filter(where p.status::text='active'))[1] last_active_amount
    from public.student_payments p where p.student_id=ns.id
  ) ap on true
  left join lateral (
    select p.payment_date,p.amount,p.status,p.cancelled_reason from public.student_payments p
    where p.student_id=ns.id order by p.payment_date desc,p.created_at desc limit 1
  ) lp on true
),
student_json as (
  select coalesce(jsonb_agg(jsonb_build_object(
    'name',s.name,'plan_type',s.plan_type,'plan_status',s.plan_status,'record_active',s.record_active,
    'student_type',s.student_type,'student_status',s.student_status,
    'card_status',case
      when not s.record_active then 'inactive'
      when s.student_status='paused' then 'paused'
      when s.student_status='ended' then 'ended'
      when coalesce(s.plan_status,'active')<>'active' then coalesce(s.plan_status,'inactive')
      when s.plan_type='Dependente' then 'active'
      when s.effective_valid_until is null then 'no_validity'
      when s.effective_valid_until>=t.d then 'active' else 'expired' end,
    'valid_until',s.effective_valid_until,
    'days_to_expiration',case when s.effective_valid_until is null then null else s.effective_valid_until-t.d end,
    'professor',s.professor_name,'responsible',s.responsible_name,
    'last_active_payment_on',s.last_active_payment_at,'last_active_payment_amount',s.last_active_amount,
    'latest_payment_on',s.latest_payment_at,'latest_payment_amount',s.latest_payment_amount,
    'latest_payment_status',s.latest_payment_status,'latest_cancelled_reason',s.latest_cancelled_reason
  ) order by s.name),'[]'::jsonb) value
  from students s cross join today t
),
day_cards as (
  select r.date occurred_on,trim(r.guest_name) guest_name,p.name booked_by,r.payment_status::text payment_status,
    case when r.payment_status::text='exempt' then 0::bigint else fs.day_card_price_cents end amount_cents
  from public.reservations r
  left join public.profiles p on p.id=r.creator_id
  cross join public.fin_settings fs cross join today t
  where r.type='Play' and nullif(trim(coalesce(r.guest_name,'')),'') is not null
    and coalesce(r.status::text,'active')<>'cancelled'
    and r.date between (t.d-90) and (t.d+60)
),
day_card_json as (
  select coalesce(jsonb_agg(jsonb_build_object(
    'date',d.occurred_on,'guest_name',d.guest_name,'booked_by',d.booked_by,
    'payment_status',d.payment_status,'amount_cents',d.amount_cents
  ) order by d.occurred_on desc,d.guest_name),'[]'::jsonb) value from day_cards d
),
pendencies as (
  select c.id,c.profile_id,p.name member_name,c.description,c.pendency_kind,c.guest_name,c.guest_date,
    c.competence_month,c.due_date,c.status,c.collection_enabled,cat.name category_name,
    st.principal_paid,st.principal_remaining,st.fees_due,st.total_due,st.days_late,st.overdue,
    exists(
      select 1 from public.fin_receipt_charges rc join public.fin_receipt_submissions rs on rs.id=rc.submission_id
      where rc.charge_id=c.id and rs.status in ('submitted','in_review')
    ) in_review
  from public.fin_member_charges c
  join public.profiles p on p.id=c.profile_id
  left join public.fin_categories cat on cat.id=c.category_id
  cross join today t
  cross join lateral fin_private.charge_statement(c.id,t.d) st
  where c.charge_type='member_pendency'
    and (c.status in ('open','partial') or c.updated_at>=now()-interval '90 days')
),
pendency_json as (
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',x.id,'member_id',x.profile_id,'member_name',x.member_name,'description',x.description,
    'kind',x.pendency_kind,'category',x.category_name,'guest_name',x.guest_name,'guest_date',x.guest_date,
    'competence',x.competence_month,'due_date',x.due_date,'status',x.status,'collection_enabled',x.collection_enabled,
    'principal_paid_cents',x.principal_paid,'principal_remaining_cents',x.principal_remaining,
    'fees_cents',x.fees_due,'total_due_cents',x.total_due,'days_late',x.days_late,'overdue',x.overdue,'in_review',x.in_review
  ) order by (x.status in ('open','partial')) desc,x.due_date,x.member_name),'[]'::jsonb) value
  from pendencies x
)
select jsonb_build_object(
  'as_of',to_char(now() at time zone 'America/Fortaleza','YYYY-MM-DD"T"HH24:MI'),
  'students',(select value from student_json),
  'day_cards',(select value from day_card_json),
  'member_pendencies',(select value from pendency_json),
  'day_card_price_cents',(select day_card_price_cents from public.fin_settings where id),
  'pix_key',(select pix_key from public.fin_settings where id)
)
$function$;
--@@ 45 funcao conv_private.ai_find_courts(p_label text)
CREATE OR REPLACE FUNCTION conv_private.ai_find_courts(p_label text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'type', c.type::text) order by c.name), '[]'::jsonb)
  from public.courts c
  where coalesce(c.is_active, true)
    and (nullif(trim(coalesce(p_label, '')), '') is null
         or conv_private.fold(c.type::text) like '%' || conv_private.fold(replace(trim(p_label), 'á', 'a')) || '%'
         or conv_private.fold(c.name) like '%' || conv_private.fold(trim(p_label)) || '%') $function$;
--@@ 45 funcao conv_private.ai_group_context(p_session uuid)
CREATE OR REPLACE FUNCTION conv_private.ai_group_context(p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_conv uuid; v_kind text; v_persona text;
begin
  select s.conversation_id, c.kind into v_conv, v_kind
  from public.conv_ai_sessions s
  join public.conv_conversations c on c.id = s.conversation_id
  where s.id = p_session;
  if v_conv is null then raise exception 'SESSION_NOT_FOUND'; end if;
  if v_kind <> 'group' then return '[]'::jsonb; end if;

  select coalesce(a.persona_name, 'João Fonseca') into v_persona
  from public.conv_ai_settings a where a.active order by a.version desc limit 1;

  return (
    select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at), '[]'::jsonb)
    from (
      select m.created_at,
             case
               when m.direction = 'inbound' then coalesce(p.name, cc.name, 'Participante')
               when m.origin = 'ai' then v_persona
               when m.origin = 'automation' then 'Clube'
               else 'Equipe'
             end as sender,
             left(coalesce(m.body, case when m.kind <> 'text' then '[' || m.kind || ']' else '' end), 320) as body
      from public.conv_messages m
      left join public.conv_contacts cc on cc.id = m.sender_contact_id
      left join public.profiles p on p.id = cc.profile_id
      where m.conversation_id = v_conv
        and m.deleted_at is null
        and m.created_at > now() - interval '60 minutes'
      order by m.created_at desc
      limit 12
    ) x
  );
end $function$;
--@@ 45 funcao conv_private.ai_handoff(p_session uuid, p_kind text, p_note tex
CREATE OR REPLACE FUNCTION conv_private.ai_handoff(p_session uuid, p_kind text, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sess public.conv_ai_sessions%rowtype; cv public.conv_conversations%rowtype; v_member boolean;
begin
  if p_kind not in ('soft', 'hard') then raise exception 'INVALID_HANDOFF'; end if;
  select * into sess from public.conv_ai_sessions where id = p_session for update;
  if not found then raise exception 'SESSION_NOT_FOUND'; end if;
  select * into cv from public.conv_conversations where id = sess.conversation_id for update;

  select exists (
    select 1 from public.conv_contacts c join public.profiles pr on pr.id = c.profile_id
    where c.id = sess.requester_contact_id and c.link_status in ('linked', 'manual')
      and pr.role::text in ('socio', 'admin') and coalesce(pr.is_active, true)
  ) into v_member;
  if cv.kind = 'direct' and v_member then
    perform conv_private.audit('ai_handoff_blocked', 'conv_conversations', cv.id::text, null,
      jsonb_build_object('kind', p_kind, 'note', left(coalesce(p_note, ''), 300)),
      jsonb_build_object('actor', 'ai', 'session_id', p_session, 'reason', 'MEMBER_PRIVATE_NO_HANDOFF'));
    return;
  end if;

  update public.conv_conversations set
    ai_status = case when p_kind = 'hard' and kind = 'direct' then 'human' else ai_status end,
    handoff_kind = p_kind, handoff_note = left(p_note, 1000), handoff_at = now(),
    staff_read_at = case when p_kind = 'hard' then least(coalesce(staff_read_at, now()), now() - interval '1 second') else staff_read_at end
  where id = cv.id;
  if p_kind = 'hard' then
    update public.conv_ai_sessions set status = 'handoff', awaiting = false where id = p_session;
    update public.conv_booking_proposals set status = 'canceled' where session_id = p_session and status = 'open';
  end if;
  perform conv_private.audit('ai_handoff', 'conv_conversations', cv.id::text, null,
    jsonb_build_object('kind', p_kind, 'note', left(coalesce(p_note, ''), 300)), jsonb_build_object('actor', 'ai', 'session_id', p_session));
end $function$;
--@@ 45 funcao conv_private.ai_is_latest(p_message uuid)
CREATE OR REPLACE FUNCTION conv_private.ai_is_latest(p_message uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select not exists (
    select 1 from public.conv_messages m join public.conv_messages n on n.conversation_id = m.conversation_id
    where m.id = p_message and n.direction = 'inbound' and n.created_at > m.created_at
      and n.sender_contact_id is not distinct from m.sender_contact_id)
  and exists (select 1 from public.conv_messages m join public.conv_conversations cv on cv.id = m.conversation_id
              where m.id = p_message and cv.status = 'open' and cv.ai_status = 'ai') $function$;
--@@ 45 funcao conv_private.ai_joao_pack(p_session uuid)
CREATE OR REPLACE FUNCTION conv_private.ai_joao_pack(p_session uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'memories', conv_private.ai_approved_memories(),
    'results', conv_private.ai_recent_results(21),
    'own_lines', conv_private.ai_own_lines(p_session)) $function$;
--@@ 45 funcao conv_private.ai_member_onboard(p_proposal uuid, p_profile uuid,
CREATE OR REPLACE FUNCTION conv_private.ai_member_onboard(p_proposal uuid, p_profile uuid, p_message uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  bp public.conv_booking_proposals%rowtype; m public.conv_messages%rowtype; v_admin uuid; pr public.profiles%rowtype;
  v_prev_claims text; v_prev_sub text; v_err text; v_code text; v_today date := conv_private.today();
  v_month date; v_amount bigint; v_plan uuid; v_charge uuid; v_remaining bigint; v_fees bigint; v_status text; v_sub_status text;
  v_sub uuid; v_paid_on date; v_alloc jsonb; v_waivers jsonb := '[]'::jsonb; v_res jsonb := '{}'::jsonb;
begin
  select * into bp from public.conv_booking_proposals where id = p_proposal for update;
  if not found or bp.action not in ('fin_member_create', 'fin_access_approve') then
    return conv_private.vfail('INVALID_ACTION', 'Proposta inválida.');
  end if;
  if bp.status = 'confirmed' then return jsonb_build_object('ok', true, 'replayed', true, 'action', bp.action, 'summary', bp.payload); end if;
  if bp.status <> 'open' or bp.expires_at <= now() then return conv_private.vfail('PROPOSAL_CLOSED', 'Essa proposta não está mais aberta.'); end if;
  select * into m from public.conv_messages where id = p_message and direction = 'inbound' and conversation_id = bp.conversation_id
    and sender_contact_id = bp.requester_contact_id;
  if not found or m.created_at <= bp.created_at or coalesce((bp.payload->>'cleared')::boolean, false) is not true
     or (bp.payload->>'cleared_message_id')::uuid is distinct from m.id then
    return conv_private.vfail('CONFIRMATION_NOT_AFTER_PROPOSAL', 'A confirmação precisa vir depois da proposta.');
  end if;
  v_admin := conv_private.ai_admin_requester(bp.session_id);
  if v_admin is null or v_admin <> bp.requester_profile_id then
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;
  select * into pr from public.profiles where id = p_profile;
  if not found or pr.role::text <> 'socio' or not coalesce(pr.is_active, false) or conv_private.br_local_phone(pr.phone) <> bp.payload->>'phone' then
    return conv_private.vfail('PROFILE_MISMATCH', 'O cadastro criado não confere com o pedido. Confira no painel.');
  end if;

  v_amount := (bp.payload->>'amount_cents')::bigint;
  v_month := (bp.payload->>'month')::date;
  v_sub := (bp.payload->>'submission_id')::uuid;
  v_paid_on := (bp.payload->>'paid_on')::date;

  v_prev_claims := current_setting('request.jwt.claims', true);
  v_prev_sub := current_setting('request.jwt.claim.sub', true);
  perform set_config('request.jwt.claims', jsonb_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
  perform set_config('request.jwt.claim.sub', v_admin::text, true);
  begin
    -- 1) plano de sócio com a mensalidade informada, desde o início do mês de entrada
    select id into v_plan from public.fin_member_plans where profile_id = p_profile and status <> 'ended' limit 1;
    if v_plan is null then
      v_res := public.fin_create_member_plan(md5(bp.id::text || 'plan')::uuid,
        jsonb_build_object('profile_id', p_profile, 'start_on', v_month, 'amount_cents', v_amount));
      v_plan := (v_res->>'id')::uuid;
    end if;
    -- 2) cobranças (idempotente)
    perform public.fin_generate_member_charges(md5(bp.id::text || 'gen')::uuid, v_plan, v_today);
    select c.id, c.status into v_charge, v_status from public.fin_member_charges c
    where c.plan_id = v_plan and c.competence_month = v_month and c.status <> 'canceled';
    if v_charge is null then raise exception 'CHARGE_NOT_GENERATED'; end if;
    -- 3) comprovante para o novo sócio e aprovação com baixa total do mês (juros do mês de entrada dispensados)
    select status into v_sub_status from public.fin_receipt_submissions where id = v_sub;
    if v_sub_status is null then raise exception 'RECEIPT_NOT_FOUND'; end if;
    if v_sub_status in ('submitted', 'in_review') then
      select st.principal_remaining, st.fees_due into v_remaining, v_fees from fin_private.charge_statement(v_charge, v_paid_on) st;
      if v_remaining <> v_amount then raise exception 'AMOUNT_MISMATCH'; end if;
      update public.fin_receipt_submissions set profile_id = p_profile, updated_at = now() where id = v_sub;
      if coalesce(v_fees, 0) > 0 then
        v_waivers := jsonb_build_array(jsonb_build_object('charge_id', v_charge, 'amount_cents', v_fees,
          'reason', 'Sócio novo: mensalidade do mês de entrada'));
      end if;
      v_alloc := jsonb_build_array(jsonb_build_object('charge_id', v_charge, 'amount_cents', v_amount));
      v_res := public.fin_approve_receipt(md5(bp.id::text || 'approve')::uuid, v_sub, jsonb_build_object(
        'paid_on', v_paid_on, 'method', 'pix', 'account_id', bp.payload->>'account_id', 'allocations', v_alloc, 'waivers', v_waivers,
        'note', 'Sócio novo cadastrado pelo João (WhatsApp)'));
    elsif v_sub_status <> 'approved' then
      raise exception 'RECEIPT_NOT_PENDING';
    end if;
    -- 4) pedido(s) de acesso deste telefone
    update public.access_requests set status = 'approved', rejection_reason = null, decided_by = v_admin, decided_at = now()
    where status = 'pending' and (id = nullif(bp.payload->>'request_id', '')::uuid or phone_normalized = bp.payload->>'phone');
  exception when others then
    v_err := sqlerrm;
  end;
  perform set_config('request.jwt.claims', coalesce(v_prev_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(v_prev_sub, ''), true);

  if v_err is not null then
    v_code := case when v_err ~ '^[A-Z][A-Z_]+$' then v_err else 'ONBOARD_FAILED' end;
    return conv_private.vfail(v_code, 'O cadastro de ' || (bp.payload->>'name') || ' foi criado, mas não consegui concluir a mensalidade (' || v_code
      || '). Confira no painel (Financeiro) ou me peça de novo com "sim".');
  end if;

  update public.conv_booking_proposals set status = 'confirmed', confirmed_at = now(), confirmed_message_id = m.id,
    confirmed_by_contact_id = m.sender_contact_id, payload = bp.payload || jsonb_build_object('profile_id', p_profile) where id = bp.id;
  perform conv_private.audit('ai_admin_finance', 'profiles', p_profile::text, null,
    jsonb_build_object('action', bp.action, 'amount_cents', v_amount, 'name', bp.payload->>'name'),
    jsonb_build_object('actor', 'ai', 'source', 'whatsapp', 'conversation_id', bp.conversation_id, 'proposal_id', bp.id,
      'requester_profile_id', bp.requester_profile_id),
    bp.requester_profile_id);
  return jsonb_build_object('ok', true, 'action', bp.action, 'summary', bp.payload || jsonb_build_object('profile_id', p_profile));
end $function$;
--@@ 45 funcao conv_private.ai_my_reservations(p_profile uuid)
CREATE OR REPLACE FUNCTION conv_private.ai_my_reservations(p_profile uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'type', r.type, 'date', r.date,
    'start', to_char(r.start_time, 'HH24:MI'), 'end', to_char(r.end_time, 'HH24:MI'), 'court', c.name,
    'is_creator', r.creator_id = p_profile) order by r.date, r.start_time), '[]'::jsonb)
  from (select * from public.reservations x
        where x.status::text = 'active' and x.type in ('Play', 'Aula')
          and (x.creator_id = p_profile or p_profile = any (coalesce(x.participant_ids, '{}')))
          and (x.date > conv_private.today() or (x.date = conv_private.today() and x.end_time > (now() at time zone 'America/Fortaleza')::time))
        order by x.date, x.start_time limit 6) r
  left join public.courts c on c.id = r.court_id $function$;
--@@ 45 funcao conv_private.ai_own_lines(p_session uuid)
CREATE OR REPLACE FUNCTION conv_private.ai_own_lines(p_session uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(jsonb_agg(x.body order by x.created_at), '[]'::jsonb)
  from (
    select left(m.body, 200) as body, m.created_at
    from public.conv_messages m
    where m.conversation_id = (select s.conversation_id from public.conv_ai_sessions s where s.id = p_session)
      and m.direction = 'outbound' and m.origin in ('ai', 'system')
      and m.deleted_at is null and m.kind = 'text' and nullif(trim(m.body), '') is not null
      and m.created_at > now() - interval '3 days'
    order by m.created_at desc
    limit 14
  ) x $function$;
--@@ 45 funcao conv_private.ai_propose(p_session uuid, p jsonb)
CREATE OR REPLACE FUNCTION conv_private.ai_propose(p_session uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  sess public.conv_ai_sessions%rowtype; c public.conv_contacts%rowtype; s public.conv_ai_settings%rowtype;
  v_action text := coalesce(p->>'action', 'create'); v_in jsonb; v_val jsonb; v_old public.reservations%rowtype;
  v_payload jsonb; v_id uuid; v_req uuid; v_is_admin boolean; v_party uuid[];
begin
  select * into sess from public.conv_ai_sessions where id = p_session and status = 'open' for update;
  if not found then return conv_private.vfail('SESSION_CLOSED', 'Atendimento encerrado.'); end if;
  select * into c from public.conv_contacts where id = sess.requester_contact_id;
  if c.profile_id is null or c.link_status not in ('linked', 'manual') then
    return conv_private.vfail('REQUESTER_NOT_IDENTIFIED', 'Não consegui identificar seu cadastro de sócio por este telefone.');
  end if;
  v_req := c.profile_id;
  select * into s from public.conv_ai_settings where active order by version desc limit 1;
  select p2.role::text = 'admin' into v_is_admin from public.profiles p2 where p2.id = v_req;
  if v_action not in ('create', 'cancel', 'reschedule', 'join', 'participants') then return conv_private.vfail('INVALID_ACTION', 'Ação inválida.'); end if;

  -- Entrar num jogo que já ocupa o horário (mesma regra do botão "Entrar no Jogo" do app). Só o solicitante entra.
  -- Mexer nos atletas de uma reserva de Play (sair, retirar, adicionar, convidado): mesmas regras da Agenda.
  if v_action = 'participants' then
    v_val := conv_private.participants_check(nullif(p->>'reservation_id', '')::uuid, v_req,
      array(select x::uuid from jsonb_array_elements_text(coalesce(p->'add_ids', '[]'::jsonb)) x),
      array(select x::uuid from jsonb_array_elements_text(coalesce(p->'remove_ids', '[]'::jsonb)) x),
      nullif(trim(coalesce(p->>'add_guest', '')), ''), coalesce((p->>'remove_guest')::boolean, false));
    if not (v_val->>'ok')::boolean then return v_val; end if;
    update public.conv_booking_proposals set status = 'canceled' where session_id = p_session and status = 'open';
    insert into public.conv_booking_proposals(conversation_id, session_id, requester_contact_id, requester_profile_id, action, payload, expires_at)
    values (sess.conversation_id, p_session, c.id, v_req, 'participants', v_val->'change', now() + make_interval(mins => coalesce(s.proposal_ttl_minutes, 20)))
    returning id into v_id;
    return jsonb_build_object('ok', true, 'proposal_id', v_id, 'action', 'participants', 'summary', v_val->'change');
  end if;

  if v_action = 'join' then
    -- Entra o solicitante e as pessoas que ele disse que jogam com ele (`participant_ids`, já resolvidas no cadastro) e/ou um convidado.
    select coalesce(array_agg(distinct x::uuid), '{}') into v_party from jsonb_array_elements_text(coalesce(p->'participant_ids', '[]'::jsonb)) x;
    v_val := conv_private.join_party_check(nullif(p->>'reservation_id', '')::uuid, v_req, v_party, nullif(trim(coalesce(p->>'guest_name', '')), ''));
    if not (v_val->>'ok')::boolean then return v_val; end if;
    update public.conv_booking_proposals set status = 'canceled' where session_id = p_session and status = 'open';
    insert into public.conv_booking_proposals(conversation_id, session_id, requester_contact_id, requester_profile_id, action, payload, expires_at)
    values (sess.conversation_id, p_session, c.id, v_req, 'join', v_val->'game', now() + make_interval(mins => coalesce(s.proposal_ttl_minutes, 20)))
    returning id into v_id;
    return jsonb_build_object('ok', true, 'proposal_id', v_id, 'action', 'join', 'summary', v_val->'game');
  end if;

  if v_action in ('cancel', 'reschedule') then
    select * into v_old from public.reservations where id = nullif(p->>'reservation_id', '')::uuid;
    if not found or v_old.status::text <> 'active' then return conv_private.vfail('RESERVATION_NOT_FOUND', 'Não achei essa reserva ativa.'); end if;
    if v_old.creator_id is distinct from v_req and not coalesce(v_is_admin, false) then
      return conv_private.vfail('NOT_YOUR_RESERVATION', 'Só quem criou a reserva (ou um administrador) pode cancelar ou remarcar.');
    end if;
    if v_old.type not in ('Play', 'Aula') then return conv_private.vfail('NEEDS_HUMAN', 'Esse tipo de reserva só a equipe altera.'); end if;
    if v_old.date < conv_private.today() or (v_old.date = conv_private.today() and v_old.start_time <= (now() at time zone 'America/Fortaleza')::time) then
      return conv_private.vfail('IN_PAST', 'Essa reserva já começou ou passou.');
    end if;
    if v_action = 'cancel' then
      v_payload := jsonb_build_object('reservation_id', v_old.id, 'type', v_old.type, 'date', v_old.date,
        'start', to_char(v_old.start_time, 'HH24:MI'), 'end', to_char(v_old.end_time, 'HH24:MI'),
        'court_name', (select name from public.courts where id = v_old.court_id));
    end if;
  end if;

  if v_action in ('create', 'reschedule') then
    v_in := p - 'action' - 'reservation_id' || jsonb_build_object('requester_profile_id', v_req);
    if v_action = 'reschedule' then
      -- Remarcar mantém o tipo, os participantes e a quadra, salvo o que a pessoa mudou.
      v_in := jsonb_build_object('type', v_old.type, 'participant_ids', to_jsonb(coalesce(v_old.participant_ids, '{}')),
        'guest_name', v_old.guest_name, 'professor_id', v_old.professor_id,
        'non_socio_student_ids', to_jsonb(coalesce(v_old.non_socio_student_ids, '{}')), 'court_id', v_old.court_id,
        'duration', (extract(epoch from (case when v_old.end_time = time '00:00' then time '23:59:59' else v_old.end_time end - v_old.start_time)) / 60)::int)
        || (v_in - 'type') || jsonb_build_object('exclude_reservation_id', v_old.id);
    end if;
    v_val := conv_private.validate_reservation(v_in);
    if not (v_val->>'ok')::boolean then return v_val; end if;
    v_payload := coalesce(v_payload, '{}'::jsonb) || (v_val->'normalized');
    if v_action = 'reschedule' then v_payload := v_payload || jsonb_build_object('reservation_id', v_old.id); end if;
  end if;

  -- Uma proposta aberta por sessão: a nova substitui a anterior.
  update public.conv_booking_proposals set status = 'canceled' where session_id = p_session and status = 'open';
  insert into public.conv_booking_proposals(conversation_id, session_id, requester_contact_id, requester_profile_id, action, payload, expires_at)
  values (sess.conversation_id, p_session, c.id, v_req, v_action, v_payload, now() + make_interval(mins => coalesce(s.proposal_ttl_minutes, 20)))
  returning id into v_id;
  return jsonb_build_object('ok', true, 'proposal_id', v_id, 'action', v_action, 'summary', v_payload);
end $function$;
--@@ 45 funcao conv_private.ai_recent_results(p_days integer)
CREATE OR REPLACE FUNCTION conv_private.ai_recent_results(p_days integer DEFAULT 21)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(jsonb_agg(to_jsonb(r) order by r.played_on desc, r.sort_at desc), '[]'::jsonb)
  from (
    select x.played_on, x.sort_at, x.championship, x.phase, x.walkover,
           case when x.a_wins then x.name_a else x.name_b end as winner,
           case when x.a_wins then x.name_b else x.name_a end as loser,
           case when x.walkover then null else (
             select string_agg(case when x.a_wins then s.a::text || 'x' || s.b::text else s.b::text || 'x' || s.a::text end, ' ' order by s.i)
             from unnest(x.score_a, x.score_b) with ordinality as s(a, b, i)) end as score
    from (
      select coalesce(m.date, (m.result_set_at at time zone 'America/Fortaleza')::date) as played_on,
             coalesce(m.result_set_at, m.updated_at, m.created_at) as sort_at,
             ch.name as championship, m.phase::text as phase, coalesce(m.is_walkover, false) as walkover,
             m.score_a, m.score_b,
             coalesce(pa.name, ra.name, rega.guest_name) as name_a,
             coalesce(pb.name, rb.name, regb.guest_name) as name_b,
             coalesce(m.winner_id = m.player_a_id or m.winner_registration_id = m.registration_a_id, false) as a_wins,
             coalesce(m.winner_id = m.player_b_id or m.winner_registration_id = m.registration_b_id, false) as b_wins
      from public.matches m
      left join public.championships ch on ch.id = m.championship_id
      left join public.profiles pa on pa.id = m.player_a_id
      left join public.profiles pb on pb.id = m.player_b_id
      left join public.championship_registrations rega on rega.id = m.registration_a_id
      left join public.championship_registrations regb on regb.id = m.registration_b_id
      left join public.profiles ra on ra.id = rega.user_id
      left join public.profiles rb on rb.id = regb.user_id
      where m.status::text = 'finished'
    ) x
    where (x.a_wins or x.b_wins)
      and x.name_a is not null and x.name_b is not null and x.name_a <> x.name_b
      and x.played_on >= (now() at time zone 'America/Fortaleza')::date - greatest(p_days, 1)
    order by x.played_on desc, x.sort_at desc
    limit 10
  ) r $function$;
--@@ 45 funcao conv_private.ai_requester_title(p_session uuid)
CREATE OR REPLACE FUNCTION conv_private.ai_requester_title(p_session uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select m.content
  from public.conv_ai_sessions s
  join public.conv_contacts c on c.id = s.requester_contact_id
  join public.profiles p on p.id = c.profile_id
  join public.conv_ai_memory_candidates m on m.kind = 'role_title' and m.status = 'approved'
    and (lower(m.subject_name) = lower(p.name) or lower(split_part(p.name, ' ', 1)) = lower(split_part(m.subject_name, ' ', 1)) and length(m.subject_name) <= length(split_part(p.name, ' ', 1)))
  where s.id = p_session
  order by m.reviewed_at desc nulls last, m.created_at desc
  limit 1 $function$;
--@@ 45 funcao conv_private.ai_resolve_mentions(p_items jsonb)
CREATE OR REPLACE FUNCTION conv_private.ai_resolve_mentions(p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_item jsonb; v_id text; v_phone text; v_out jsonb := '[]'::jsonb; v_bot boolean; v_ch public.conv_channel%rowtype;
  v_profiles uuid[]; v_name text; v_via text; v_contact public.conv_contacts%rowtype; v_key text;
begin
  select * into v_ch from public.conv_channel where id;
  for v_item in select * from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) loop
    v_id := conv_private.norm_lid(v_item->>'id');
    continue when v_id is null;
    v_phone := nullif(v_item->>'phone', '');
    v_bot := v_id = any (coalesce(v_ch.bot_lids, '{}'))
             or (v_ch.bot_phone is not null and length(v_id) <= 13 and conv_private.phone_key(v_id) is not null
                 and conv_private.phone_key(v_id) = conv_private.phone_key(v_ch.bot_phone))
             or (v_ch.bot_phone is not null and v_phone is not null and conv_private.phone_key(v_phone) = conv_private.phone_key(v_ch.bot_phone));
    v_profiles := '{}'; v_name := null; v_via := null;
    if not v_bot then
      -- (1) contato do WhatsApp com esse LID, já ligado a um sócio
      select * into v_contact from public.conv_contacts where lid = v_id limit 1;
      if found and v_contact.profile_id is not null then
        select array[p.id] into v_profiles from public.profiles p
          where p.id = v_contact.profile_id and coalesce(p.is_active, true) and p.role::text in ('socio', 'admin');
        if v_profiles is not null then v_via := 'lid'; end if;
      end if;
      -- (2) telefone: o informado, o do contato com esse LID, ou o próprio identificador (se for telefone)
      if v_profiles is null or cardinality(v_profiles) = 0 then
        v_key := coalesce(conv_private.phone_key(v_phone), conv_private.phone_key(v_contact.phone),
                          case when length(v_id) <= 13 then conv_private.phone_key(v_id) end);
        if v_key is not null then
          select coalesce(array_agg(p.id), '{}') into v_profiles from public.profiles p
            where p.phone is not null and conv_private.phone_key(p.phone) = v_key and coalesce(p.is_active, true) and p.role::text in ('socio', 'admin');
          if cardinality(v_profiles) > 0 then v_via := 'phone'; end if;
        end if;
      end if;
      if v_profiles is not null and cardinality(v_profiles) = 1 then
        select p.name::text into v_name from public.profiles p where p.id = v_profiles[1];
      end if;
    end if;
    v_out := v_out || jsonb_build_array(jsonb_build_object('id', v_id, 'is_bot', v_bot,
      'name', v_name, 'profile_id', case when v_name is not null then v_profiles[1] end, 'via', case when v_name is not null then v_via end));
  end loop;
  return v_out;
end $function$;
--@@ 45 funcao conv_private.ai_resolve_people(p_names text[], p_scope text)
CREATE OR REPLACE FUNCTION conv_private.ai_resolve_people(p_names text[], p_scope text DEFAULT 'member'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_out jsonb := '[]'::jsonb; v_name text; v_q text; v_match jsonb; v_n integer;
begin
  if p_scope not in ('member', 'student', 'professor') then raise exception 'INVALID_SCOPE'; end if;
  foreach v_name in array coalesce(p_names, '{}') loop
    v_q := conv_private.fold(trim(v_name));
    continue when length(v_q) < 2;
    with pool as (
      select p.id, p.name::text as name, 'member'::text as kind, p.category::text as hint, 'member'::text as sc,
             coalesce(mc.aliases, '{}'::text[]) as aliases
        from public.profiles p
        left join public.conv_ai_member_context mc on mc.profile_id = p.id
        where coalesce(p.is_active, true) and p.role::text in ('socio', 'admin')
      union all
      select p.id, p.name::text, 'socio', p.category::text, 'student',
             coalesce(mc.aliases, '{}'::text[])
        from public.profiles p
        join public.student_profiles sp on sp.profile_id = p.id
        left join public.conv_ai_member_context mc on mc.profile_id = p.id
        where sp.student_status = 'active' and coalesce(p.is_active, true) and p.role::text in ('socio', 'admin')
      union all
      select s.id, s.name::text, 'non_socio', s.plan_type::text, 'student', '{}'::text[]
        from public.non_socio_students s where coalesce(s.is_active, true)
      union all
      select pf.id, pf.name::text, 'professor', null, 'professor', '{}'::text[]
        from public.professors pf where coalesce(pf.is_active, true)
    ), exact as (
      select * from pool
      where sc = p_scope
        and (
          conv_private.fold(name) = v_q
          or exists (select 1 from unnest(aliases) a where conv_private.fold(a) = v_q)
        )
      order by name limit 6
    ), partial as (
      select * from pool
      where sc = p_scope
        and not exists (
          select 1 from regexp_split_to_table(v_q, '\s+') w
          where w <> ''
            and not (
              conv_private.fold(name) like '%' || w || '%'
              or exists (select 1 from unnest(aliases) a where conv_private.fold(a) like '%' || w || '%')
            )
        )
      order by name limit 6
    ), chosen as (
      select * from exact
      union all
      select * from partial where not exists (select 1 from exact)
    )
    select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'kind', c.kind, 'hint', c.hint) order by c.name), '[]'::jsonb), count(*)
      into v_match, v_n from chosen c;
    v_out := v_out || jsonb_build_array(jsonb_build_object('query', v_name,
      'status', case when v_n = 1 then 'unique' when v_n = 0 then 'none' else 'ambiguous' end, 'matches', v_match));
  end loop;
  return v_out;
end $function$;
--@@ 45 funcao conv_private.ai_save_turn(p_session uuid, p_memory jsonb, p_dec
CREATE OR REPLACE FUNCTION conv_private.ai_save_turn(p_session uuid, p_memory jsonb, p_decision text, p_payload jsonb, p_awaiting boolean, p_close boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_version integer; v_conv uuid;
begin
  select version into v_version from public.conv_ai_settings where active order by version desc limit 1;
  update public.conv_ai_sessions set memory = coalesce(p_memory, memory), turns = turns + 1, last_turn_at = now(),
    awaiting = coalesce(p_awaiting, false) and not coalesce(p_close, false),
    status = case when coalesce(p_close, false) then 'done' else status end
  where id = p_session returning conversation_id into v_conv;
  if v_conv is null then raise exception 'SESSION_NOT_FOUND'; end if;
  update public.conv_conversations set ai_turns = ai_turns + 1, ai_last_turn_at = now() where id = v_conv;
  if v_version is not null then
    insert into public.conv_ai_decisions(conversation_id, session_id, settings_version, decision, tool_name, tool_result)
    values (v_conv, p_session, v_version, left(coalesce(p_decision, 'reply'), 60), left(p_payload->>'action', 60), p_payload);
  end if;
end $function$;
--@@ 45 funcao conv_private.ai_slot_games(p_court uuid, p_date date, p_start_m
CREATE OR REPLACE FUNCTION conv_private.ai_slot_games(p_court uuid, p_date date, p_start_min integer, p_end_min integer, p_requester uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(jsonb_agg(g order by g->>'start'), '[]'::jsonb) from (
    select conv_private.game_summary(r.id) || jsonb_build_object(
             'joinable', coalesce((conv_private.join_check(r.id, p_requester)->>'ok')::boolean, false),
             'reason', conv_private.join_check(r.id, p_requester)->>'code') as g
    from public.reservations r
    where r.court_id = p_court and r.date = p_date and r.status::text <> 'cancelled'
      and (extract(hour from r.start_time)::int * 60 + extract(minute from r.start_time)::int) < p_end_min
      and (case when r.end_time = time '00:00' then 1440
                else extract(hour from r.end_time)::int * 60 + extract(minute from r.end_time)::int end) > p_start_min) x $function$;
--@@ 45 funcao conv_private.ai_student_card_propose(p_session uuid, p jsonb)
CREATE OR REPLACE FUNCTION conv_private.ai_student_card_propose(p_session uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  sess public.conv_ai_sessions%rowtype; s public.conv_ai_settings%rowtype; st public.non_socio_students%rowtype;
  rc public.fin_receipt_submissions%rowtype; fs public.fin_settings%rowtype;
  v_admin uuid; v_id uuid; v_today date := conv_private.today(); v_default constant bigint := 20000;
  v_amount bigint; v_paid_on date; v_new_exp date; v_prev_exp date; v_payload jsonb; v_receipt jsonb := null;
  v_warn text[] := '{}'; v_use boolean := coalesce((p->>'use_receipt')::boolean, true);
  v_payee text; v_ident text; v_has_receipt boolean := false;
begin
  select * into sess from public.conv_ai_sessions where id = p_session and status = 'open' for update;
  if not found then return conv_private.vfail('SESSION_CLOSED', 'Atendimento encerrado.'); end if;
  v_admin := conv_private.ai_admin_requester(p_session);
  if v_admin is null then
    return conv_private.vfail('ADMIN_ONLY_PRIVATE', 'Isso só um administrador faz, e só na conversa privada comigo.');
  end if;

  select * into st from public.non_socio_students where id = nullif(p->>'student_id', '')::uuid and coalesce(is_active, true);
  if not found then return conv_private.vfail('STUDENT_NOT_FOUND', 'Não achei esse aluno no cadastro.'); end if;
  if st.plan_type <> 'Card Mensal' then
    return conv_private.vfail('NOT_CARD_MENSAL', st.name || ' está no plano ' || st.plan_type || ', não no Card Mensal. Essa renovação eu só faço para Card Mensal.');
  end if;

  -- Último comprovante que o administrador mandou nesta conversa (ainda não usado).
  if v_use then
    select r.* into rc
    from public.fin_receipt_submissions r
    join public.conv_messages m on m.id = r.source_message_id
    where m.conversation_id = sess.conversation_id and m.direction = 'inbound'
      and r.source = 'whatsapp' and r.status in ('submitted', 'in_review')
      and r.created_at > now() - interval '3 hours'
    order by r.created_at desc limit 1;
    v_has_receipt := found;
  end if;

  v_amount := nullif(p->>'amount_cents', '')::bigint;
  v_paid_on := nullif(p->>'paid_on', '')::date;
  if v_has_receipt then
    v_payee := nullif(trim(coalesce(rc.ocr->>'payee', '')), '');
    v_ident := nullif(trim(coalesce(rc.ocr->>'identifier', '')), '');
    select * into fs from public.fin_settings where id;
    if rc.ocr_status <> 'ok' then
      v_warn := v_warn || 'Não consegui ler o comprovante; confira valor e data com ele.';
    else
      if v_payee is not null and not fin_private.payee_matches(v_payee, fs.payee_names) then
        return conv_private.vfail('PAYEE_MISMATCH', 'O comprovante é para "' || v_payee || '", que não é o clube. Não registro assim.');
      elsif v_payee is null then
        v_warn := v_warn || 'Não li o favorecido no comprovante.';
      end if;
      if v_amount is null then v_amount := rc.declared_amount_cents; end if;
      if v_paid_on is null then v_paid_on := rc.declared_paid_on; end if;
      if rc.declared_amount_cents is not null and v_amount is not null and rc.declared_amount_cents <> v_amount then
        v_warn := v_warn || 'O comprovante mostra R$ ' || replace(to_char(rc.declared_amount_cents / 100.0, 'FM999990.00'), '.', ',') || ', diferente do valor informado.';
      end if;
    end if;
    if rc.possible_duplicate or (v_ident is not null and exists (
      select 1 from public.fin_receipt_submissions o
      where o.id <> rc.id and o.status = 'approved' and nullif(trim(o.ocr->>'identifier'), '') = v_ident)) then
      return conv_private.vfail('RECEIPT_DUPLICATE', 'Esse comprovante parece já ter sido usado antes. Não registro de novo.');
    end if;
    v_receipt := jsonb_strip_nulls(jsonb_build_object('id', rc.id, 'file_name', rc.file_name, 'payee', v_payee,
      'identifier', v_ident, 'amount_cents', rc.declared_amount_cents, 'paid_on', rc.declared_paid_on, 'ocr_status', rc.ocr_status));
  end if;

  v_amount := coalesce(v_amount, v_default);
  if v_amount <= 0 or v_amount > 1000000000 then
    return conv_private.vfail('INVALID_AMOUNT', 'Qual é o valor pago?');
  end if;
  v_paid_on := coalesce(v_paid_on, v_today);
  if v_paid_on > v_today then return conv_private.vfail('INVALID_DATE', 'A data do pagamento não pode ser no futuro.'); end if;
  if v_paid_on < v_today - 60 then
    v_warn := v_warn || 'A data do pagamento é de mais de 60 dias atrás.';
  end if;

  select max(valid_until::date) into v_prev_exp from public.student_payments where student_id = st.id and status = 'active';
  if exists (select 1 from public.student_payments x where x.student_id = st.id and x.status = 'active'
             and (x.payment_date at time zone 'America/Fortaleza')::date = v_paid_on and round(x.amount * 100) = v_amount) then
    return conv_private.vfail('ALREADY_RECORDED', 'O Card de ' || st.name || ' já tem um pagamento de R$ ' || replace(to_char(v_amount / 100.0, 'FM999990.00'), '.', ',')
      || ' em ' || to_char(v_paid_on, 'DD/MM/YYYY') || ' (válido até ' || to_char(coalesce(v_prev_exp, v_paid_on), 'DD/MM/YYYY') || '). Não registro em duplicidade.');
  end if;
  v_new_exp := (v_paid_on + interval '1 month')::date;

  v_payload := jsonb_strip_nulls(jsonb_build_object('student_id', st.id, 'student_name', st.name, 'plan_type', st.plan_type,
    'amount_cents', v_amount, 'default_price_cents', v_default, 'paid_on', v_paid_on, 'method', 'pix',
    'previous_valid_until', coalesce(v_prev_exp, st.master_expiration_date), 'new_valid_until', v_new_exp,
    'receipt', v_receipt, 'warnings', to_jsonb(v_warn)));

  select * into s from public.conv_ai_settings where active order by version desc limit 1;
  update public.conv_booking_proposals set status = 'canceled' where session_id = p_session and status = 'open';
  insert into public.conv_booking_proposals(conversation_id, session_id, requester_contact_id, requester_profile_id, action, payload, expires_at)
  values (sess.conversation_id, p_session, sess.requester_contact_id, v_admin, 'student_card_renew', v_payload,
    now() + make_interval(mins => coalesce(s.proposal_ttl_minutes, 20)))
  returning id into v_id;
  return jsonb_build_object('ok', true, 'proposal_id', v_id, 'action', 'student_card_renew', 'summary', v_payload);
exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow or numeric_value_out_of_range then
  return conv_private.vfail('INVALID_DATA', 'Algum dado veio num formato que não entendi (data ou valor).');
end $function$;
--@@ 45 funcao conv_private.ai_trigger(p_message uuid)
CREATE OR REPLACE FUNCTION conv_private.ai_trigger(p_message uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  m public.conv_messages%rowtype; cv public.conv_conversations%rowtype; ch public.conv_channel%rowtype;
  s public.conv_ai_settings%rowtype; g public.conv_groups%rowtype; v_sess public.conv_ai_sessions%rowtype;
  v_reason text; v_admin boolean := false; v_ai_msg public.conv_messages%rowtype; v_requester uuid; v_budget integer;
begin
  select * into m from public.conv_messages where id = p_message and direction = 'inbound';
  if not found then return jsonb_build_object('run', false, 'reason', 'not_inbound'); end if;
  select * into cv from public.conv_conversations where id = m.conversation_id;
  if cv.status <> 'open' then return jsonb_build_object('run', false, 'reason', 'conversation_closed'); end if;
  select * into s from public.conv_ai_settings where active order by version desc limit 1;
  if not found then return jsonb_build_object('run', false, 'reason', 'ai_inactive'); end if;
  select * into ch from public.conv_channel where id;
  if cv.ai_status <> 'ai' then return jsonb_build_object('run', false, 'reason', 'not_ai_conversation'); end if;
  -- Pedido de descadastro não é conversa com a IA.
  if cv.kind = 'direct' and m.kind = 'text' and conv_private.is_opt_out(m.body) then return jsonb_build_object('run', false, 'reason', 'opt_out'); end if;
  select count(*) into v_budget from public.conv_ai_decisions where created_at >= date_trunc('day', now() at time zone 'America/Fortaleza') at time zone 'America/Fortaleza';
  if v_budget >= s.daily_turn_budget then return jsonb_build_object('run', false, 'reason', 'budget_exhausted'); end if;

  if cv.kind = 'direct' then
    if not ch.ai_direct_enabled then return jsonb_build_object('run', false, 'reason', 'direct_ai_off'); end if;
    v_requester := cv.contact_id; v_reason := 'direct_message';
    select * into v_sess from public.conv_ai_sessions where conversation_id = cv.id and requester_contact_id = v_requester and status = 'open' for update;
    if found and v_sess.expires_at <= now() then
      update public.conv_ai_sessions set status = 'expired' where id = v_sess.id;
      v_sess := null;
    end if;
    if v_sess.id is null then
      insert into public.conv_ai_sessions(conversation_id, requester_contact_id, trigger_message_id, expires_at)
      values (cv.id, v_requester, m.id, now() + interval '24 hours') returning * into v_sess;
    else
      update public.conv_ai_sessions set expires_at = now() + interval '24 hours' where id = v_sess.id;
    end if;
  else
    select * into g from public.conv_groups where id = cv.group_id;
    if not (ch.ai_group_enabled and ch.mention_verified_at is not null and g.ai_enabled and g.status = 'allowed') then
      return jsonb_build_object('run', false, 'reason', 'group_ai_off');
    end if;
    if m.sender_contact_id is null then return jsonb_build_object('run', false, 'reason', 'no_sender'); end if;
    v_requester := m.sender_contact_id;
    if m.mention_direct then
      v_reason := 'direct_mention';
      select * into v_sess from public.conv_ai_sessions where conversation_id = cv.id and requester_contact_id = v_requester and status = 'open' for update;
      if found and v_sess.expires_at <= now() then
        update public.conv_ai_sessions set status = 'expired' where id = v_sess.id; v_sess := null;
      end if;
      if v_sess.id is null then
        insert into public.conv_ai_sessions(conversation_id, requester_contact_id, trigger_message_id, expires_at)
        values (cv.id, v_requester, m.id, now() + make_interval(mins => ch.group_session_minutes)) returning * into v_sess;
      else
        update public.conv_ai_sessions set expires_at = now() + make_interval(mins => ch.group_session_minutes) where id = v_sess.id;
      end if;
    else
      -- (b) continuação: mesmo solicitante, sessão aberta, a IA estava esperando resposta.
      select * into v_sess from public.conv_ai_sessions where conversation_id = cv.id and requester_contact_id = v_requester
        and status = 'open' and awaiting and expires_at > now() for update;
      if found then
        v_reason := 'session_followup';
        update public.conv_ai_sessions set expires_at = now() + make_interval(mins => ch.group_session_minutes) where id = v_sess.id;
      else
        -- (b') rajada: o solicitante manda o pedido em duas mensagens seguidas (a 2ª sem menção) antes de a IA falar.
        select * into v_sess from public.conv_ai_sessions where conversation_id = cv.id and requester_contact_id = v_requester
          and status = 'open' and turns = 0 and started_at > now() - interval '90 seconds' and expires_at > now() for update;
        if found then v_reason := 'burst'; end if;
      end if;
      if v_reason is not null then
        null;   -- continuação já decidida acima
      elsif m.reply_to_provider_id is not null then
        -- (c) Reply no grupo é uma forma explícita de falar com o João.
        -- A mensagem citada pode ser de uma sessão conversacional OU uma fala
        -- proativa do João (ex.: bom dia diário), que não possui ai_session_id.
        select * into v_ai_msg
        from public.conv_messages
        where provider_message_id = m.reply_to_provider_id
          and origin = 'ai'
          and conversation_id = cv.id;

        if not found then
          return jsonb_build_object('run', false, 'reason', 'no_trigger');
        end if;

        -- Se a fala citada já pertence à sessão deste mesmo membro, continua nela.
        if v_ai_msg.ai_session_id is not null then
          select * into v_sess
          from public.conv_ai_sessions
          where id = v_ai_msg.ai_session_id
            and status = 'open'
            and expires_at > now()
          for update;

          if found and v_sess.requester_contact_id = v_requester then
            update public.conv_ai_sessions
            set expires_at = now() + make_interval(mins => ch.group_session_minutes)
            where id = v_sess.id;
            v_reason := 'reply_to_ai';
          end if;
        end if;

        -- Reply de outro membro, ou reply a uma fala proativa sem sessão:
        -- abre/continua uma sessão PRÓPRIA para quem respondeu. Assim qualquer
        -- participante pode responder ao João sem @ e sem herdar a sessão alheia.
        if v_reason is null then
          select * into v_sess
          from public.conv_ai_sessions
          where conversation_id = cv.id
            and requester_contact_id = v_requester
            and status = 'open'
            and expires_at > now()
          order by started_at desc
          limit 1
          for update;

          if not found then
            insert into public.conv_ai_sessions(conversation_id, requester_contact_id, trigger_message_id, expires_at)
            values (cv.id, v_requester, m.id, now() + make_interval(mins => ch.group_session_minutes))
            returning * into v_sess;
          else
            update public.conv_ai_sessions
            set expires_at = now() + make_interval(mins => ch.group_session_minutes)
            where id = v_sess.id;
          end if;

          v_reason := 'reply_to_ai';
        end if;
      else
        return jsonb_build_object('run', false, 'reason', 'no_trigger');
      end if;
    end if;
  end if;

  update public.conv_messages set ai_session_id = v_sess.id where id = m.id;
  return jsonb_build_object('run', true, 'reason', v_reason, 'session_id', v_sess.id, 'conversation_id', cv.id,
    'sender_contact_id', m.sender_contact_id, 'is_group', cv.kind = 'group', 'acting_admin', v_admin);
end $function$;
--@@ 45 funcao conv_private.apply_delete(p_provider_id text)
CREATE OR REPLACE FUNCTION conv_private.apply_delete(p_provider_id text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  update public.conv_messages set deleted_at = coalesce(deleted_at, now()) where provider_message_id = p_provider_id;
$function$;
--@@ 45 funcao conv_private.apply_edit(p_provider_id text, p_body text)
CREATE OR REPLACE FUNCTION conv_private.apply_edit(p_provider_id text, p_body text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  update public.conv_messages set body = left(p_body, 8192), edited_at = now()
  where provider_message_id = p_provider_id and deleted_at is null and coalesce(p_body, '') <> '';
$function$;
--@@ 45 funcao conv_private.apply_edit_with_mention(p_provider_id text, p_body
CREATE OR REPLACE FUNCTION conv_private.apply_edit_with_mention(p_provider_id text, p_body text, p_mention_direct boolean, p_mention_evidence text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_msg public.conv_messages%rowtype;
  v_previous boolean;
begin
  select *
    into v_msg
    from public.conv_messages
   where provider_message_id = p_provider_id
     and deleted_at is null
   for update;

  if not found then
    return jsonb_build_object('found', false);
  end if;

  v_previous := coalesce(v_msg.mention_direct, false);

  update public.conv_messages
     set body = left(p_body, 8192),
         edited_at = now(),
         mention_direct = case
           when direction = 'inbound' then coalesce(p_mention_direct, mention_direct)
           else mention_direct
         end,
         mention_evidence = case
           when direction = 'inbound' and p_mention_evidence is not null
             then left(p_mention_evidence, 80)
           else mention_evidence
         end
   where id = v_msg.id;

  return jsonb_build_object(
    'found', true,
    'message_id', v_msg.id,
    'conversation_id', v_msg.conversation_id,
    'direction', v_msg.direction,
    'became_direct_mention',
      v_msg.direction = 'inbound'
      and not v_previous
      and coalesce(p_mention_direct, false)
  );
end;
$function$;
--@@ 45 funcao conv_private.apply_reaction(p_target text, p_emoji text, p_from
CREATE OR REPLACE FUNCTION conv_private.apply_reaction(p_target text, p_emoji text, p_from_me boolean)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  update public.conv_messages set reactions = case
    when coalesce(trim(p_emoji), '') = '' then reactions - (case when p_from_me then 'staff' else 'customer' end)
    else reactions || jsonb_build_object(case when p_from_me then 'staff' else 'customer' end, left(trim(p_emoji), 16)) end
  where provider_message_id = p_target;
$function$;
--@@ 45 funcao conv_private.aud_advance(a conv_automations, p_as_of date)
CREATE OR REPLACE FUNCTION conv_private.aud_advance(a conv_automations, p_as_of date)
 RETURNS SETOF conv_private.audience_row
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d jsonb := a.definition; v_champ uuid := nullif(d->>'championship_id', '')::uuid;
  v_settle integer := coalesce(nullif(d->>'settle_minutes', '')::int, 10);
begin
  return query
  with nxt as (
    select src.id as src_id, nx.id as next_id, nx.phase as next_phase, c.name as cname,
      case when nx.player_a_source_match_id = src.id then nx.registration_a_id else nx.registration_b_id end as adv_reg,
      case when nx.player_a_source_match_id = src.id then nx.registration_b_id else nx.registration_a_id end as other_reg,
      coalesce(src.walkover_winner_registration_id, src.winner_registration_id) as win_reg, nx.status::text as next_status
    from public.matches src join public.championships c on c.id = src.championship_id
    join public.matches nx on (nx.player_a_source_match_id = src.id or nx.player_b_source_match_id = src.id)
    where src.status::text = 'finished' and c.status::text in ('ongoing', 'active')
      and (v_champ is null or src.championship_id = v_champ)
      and src.result_set_at is not null and src.result_set_at >= coalesce(a.activated_at, now())
      and src.result_set_at <= now() - make_interval(mins => v_settle)
  )
  select 'adv:' || n.next_id || ':' || coalesce(n.adv_reg::text, '-'), r.user_id, null::uuid, pr.phone::text, pr.name,
    jsonb_build_object('match_id', n.src_id, 'next_match_id', n.next_id, 'championship', n.cname, 'phase', n.next_phase,
      'opponent', (select coalesce(p2.name, r2.guest_name) from public.championship_registrations r2 left join public.profiles p2 on p2.id = r2.user_id
                   where r2.id = n.other_reg), 'registration_id', n.adv_reg),
    (r.user_id is not null and coalesce(pr.is_active, true) and n.next_status = 'pending' and n.adv_reg is not null and n.adv_reg = n.win_reg),
    case when n.adv_reg is null or n.adv_reg is distinct from n.win_reg then 'AVANCO_NAO_CONFIRMADO_PELO_MOTOR'
         when r.user_id is null then 'CONVIDADO_SEM_CADASTRO' when n.next_status <> 'pending' then 'PARTIDA_SEGUINTE_JA_INICIADA'
         when not coalesce(pr.is_active, true) then 'SOCIO_INATIVO' end
  from nxt n left join public.championship_registrations r on r.id = n.adv_reg left join public.profiles pr on pr.id = r.user_id;
end $function$;
--@@ 45 funcao conv_private.aud_audience(a conv_automations, p_as_of date, p_b
CREATE OR REPLACE FUNCTION conv_private.aud_audience(a conv_automations, p_as_of date, p_bucket text)
 RETURNS SETOF conv_private.audience_row
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d jsonb := a.definition; v_kind text := d->>'audience'; v_champ uuid := nullif(d->>'championship_id', '')::uuid;
  v_status text; v_cname text;
begin
  if a.source = 'championship_notice' then
    select c.status::text, c.name into v_status, v_cname from public.championships c where c.id = v_champ;
    if v_status is null then return; end if;
    return query
    select 'cn:' || p_bucket || ':' || v_champ || ':' || coalesce(r.user_id::text, r.id::text), r.user_id, null::uuid, pr.phone::text,
      coalesce(pr.name, r.guest_name), jsonb_build_object('championship', v_cname, 'class', r.class, 'registration_id', r.id),
      (r.user_id is not null and v_status in ('ongoing', 'active') and coalesce(pr.is_active, true)),
      case when v_status not in ('ongoing', 'active') then 'CAMPEONATO_NAO_ATIVO'
           when r.user_id is null then 'CONVIDADO_SEM_CADASTRO' when not coalesce(pr.is_active, true) then 'SOCIO_INATIVO' end
    from public.championship_registrations r left join public.profiles pr on pr.id = r.user_id
    where r.championship_id = v_champ and (d->'classes' is null or jsonb_array_length(d->'classes') = 0 or d->'classes' ? r.class);
    return;
  end if;
  if v_kind = 'members' then
    return query select 'aud:' || p_bucket || ':' || pr.id, pr.id, null::uuid, pr.phone::text, pr.name, '{}'::jsonb,
      (coalesce(pr.is_active, true)), case when not coalesce(pr.is_active, true) then 'SOCIO_INATIVO' end
      from public.profiles pr where pr.role::text in ('socio', 'admin');
  elsif v_kind = 'students' then
    return query
      select 'aud:' || p_bucket || ':' || pr.id, pr.id, null::uuid, pr.phone::text, pr.name, '{}'::jsonb,
        (sp.student_status = 'active' and coalesce(pr.is_active, true)),
        case when sp.student_status <> 'active' then 'ALUNO_PAUSADO_OU_ENCERRADO' when not coalesce(pr.is_active, true) then 'SOCIO_INATIVO' end
      from public.student_profiles sp join public.profiles pr on pr.id = sp.profile_id
      union all
      select 'aud:' || p_bucket || ':' || s.id, null::uuid, s.id, s.phone::text, s.name::text, '{}'::jsonb,
        (coalesce(sp.student_status, 'active') = 'active' and coalesce(s.is_active, true) and coalesce(s.student_type, 'regular') = 'regular'),
        case when coalesce(s.student_type, 'regular') <> 'regular' then 'DEPENDENTE'
             when coalesce(sp.student_status, 'active') <> 'active' or not coalesce(s.is_active, true) then 'ALUNO_PAUSADO_OU_ENCERRADO' end
      from public.non_socio_students s left join public.student_profiles sp on sp.non_socio_student_id = s.id;
  elsif v_kind = 'dependents' then
    -- Dependente: o aviso vai ao SÓCIO responsável (uma mensagem por responsável).
    return query
      select 'aud:' || p_bucket || ':' || pr.id, pr.id, null::uuid, pr.phone::text, pr.name, '{}'::jsonb,
        (coalesce(pr.is_active, true)), case when not coalesce(pr.is_active, true) then 'SOCIO_INATIVO' end
      from public.profiles pr where pr.id in (select s.responsible_socio_id from public.non_socio_students s
        where s.student_type = 'dependent' and coalesce(s.is_active, true) and s.responsible_socio_id is not null);
  elsif v_kind = 'professors' then
    return query select 'aud:' || p_bucket || ':' || pr.id, pr.id, null::uuid, pr.phone::text, pr.name, '{}'::jsonb,
      (coalesce(pf.is_active, true) and coalesce(pr.is_active, true)), case when not coalesce(pf.is_active, true) then 'PROFESSOR_INATIVO' end
      from public.professors pf join public.profiles pr on pr.id = pf.user_id;
  elsif v_kind = 'card_holders' then
    return query select 'aud:' || p_bucket || ':' || s.id, null::uuid, s.id, s.phone::text, s.name::text, '{}'::jsonb,
      (coalesce(s.plan_status, 'inactive') = 'active' and coalesce(s.is_active, true)),
      case when coalesce(s.plan_status, 'inactive') <> 'active' then 'CARD_INATIVO_OU_CANCELADO' when not coalesce(s.is_active, true) then 'ALUNO_PAUSADO_OU_ENCERRADO' end
      from public.non_socio_students s where s.plan_type = 'Card Mensal' and coalesce(s.student_type, 'regular') = 'regular';
  elsif v_kind = 'championship_participants' then
    select c.status::text, c.name into v_status, v_cname from public.championships c where c.id = v_champ;
    if v_status is null then return; end if;
    return query select 'aud:' || p_bucket || ':' || r.user_id, r.user_id, null::uuid, pr.phone::text, pr.name,
      jsonb_build_object('championship', v_cname, 'class', r.class),
      (v_status in ('ongoing', 'active') and coalesce(pr.is_active, true)), case when v_status not in ('ongoing', 'active') then 'CAMPEONATO_NAO_ATIVO' end
      from public.championship_registrations r join public.profiles pr on pr.id = r.user_id where r.championship_id = v_champ;
  end if;
end $function$;
--@@ 45 funcao conv_private.aud_card(a conv_automations, p_as_of date)
CREATE OR REPLACE FUNCTION conv_private.aud_card(a conv_automations, p_as_of date)
 RETURNS SETOF conv_private.audience_row
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d jsonb := a.definition; v_before integer := coalesce(nullif(d->>'days_before', '')::int, 7);
  v_after integer := coalesce(nullif(d->>'days_after', '')::int, 0);
begin
  return query
  select 'card:' || s.id || ':' || s.master_expiration_date::text, null::uuid, s.id, s.phone::text, s.name::text,
    jsonb_build_object('student_id', s.id, 'expiration', s.master_expiration_date),
    (coalesce(s.plan_status, 'inactive') = 'active' and coalesce(s.is_active, true)
      and coalesce(sp.student_status, 'active') = 'active' and coalesce(s.student_type, 'regular') = 'regular'
      and s.master_expiration_date between p_as_of - v_after and p_as_of + v_before),
    case when coalesce(s.student_type, 'regular') <> 'regular' then 'DEPENDENTE'
         when coalesce(s.plan_status, 'inactive') <> 'active' then 'CARD_INATIVO_OU_CANCELADO'
         when not coalesce(s.is_active, true) or coalesce(sp.student_status, 'active') <> 'active' then 'ALUNO_PAUSADO_OU_ENCERRADO'
         when s.master_expiration_date < p_as_of - v_after then 'VENCIDO_HA_MUITO_TEMPO'
         when s.master_expiration_date > p_as_of + v_before then 'AINDA_LONGE_DO_VENCIMENTO' end
  from public.non_socio_students s left join public.student_profiles sp on sp.non_socio_student_id = s.id
  where s.plan_type = 'Card Mensal' and s.master_expiration_date is not null;
end $function$;
--@@ 45 funcao conv_private.aud_finance(a conv_automations, p_as_of date)
CREATE OR REPLACE FUNCTION conv_private.aud_finance(a conv_automations, p_as_of date)
 RETURNS SETOF conv_private.audience_row
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  d jsonb := a.definition; v_stage text := d->>'stage';
  v_days integer := coalesce(nullif(d->>'days','')::int, case v_stage when 'period_start' then 3 when 'before_due' then 3 else 1 end);
  v_repeat integer := greatest(coalesce(nullif(d->>'repeat_days','')::int,7),1);
  v_excl boolean := coalesce((d->>'exclude_in_review')::boolean,true);
  v_filters jsonb; v_enabled boolean; v_reminders integer[];
begin
  if v_stage='member_pendency' then
    select pendency_automation_enabled, pendency_reminder_days into v_enabled,v_reminders from public.fin_settings where id;
    if not coalesce(v_enabled,true) then return; end if;
    return query
    with trigger_profiles as (
      select distinct c.profile_id
      from public.fin_member_charges c
      cross join lateral fin_private.charge_statement(c.id,p_as_of) st
      where c.charge_type='member_pendency'
        and c.collection_enabled
        and c.status in ('open','partial')
        and st.total_due > 0
        and p_as_of >= c.due_date
        and (p_as_of-c.due_date)=any(coalesce(v_reminders,array[0,3,7,14,21]))
        and not exists (
          select 1 from public.fin_receipt_charges rc
          join public.fin_receipt_submissions rs on rs.id=rc.submission_id
          where rc.charge_id=c.id and rs.status in ('submitted','in_review')
        )
    )
    select
      'fin:member_pendency:'||tp.profile_id||':'||p_as_of::text,
      tp.profile_id,null::uuid,pr.phone::text,pr.name,
      s.subject || jsonb_build_object('scope','due'),
      coalesce(pr.is_active,true) and s.subject is not null,
      case when not coalesce(pr.is_active,true) then 'SOCIO_INATIVO'
           when s.subject is null then 'SEM_PENDENCIA_COBRAVEL' end
    from trigger_profiles tp
    join public.profiles pr on pr.id=tp.profile_id
    cross join lateral (select conv_private.member_pendency_subject(tp.profile_id,p_as_of,false) subject) s;
    return;
  end if;

  v_filters := case v_stage
    when 'period_start' then jsonb_build_object('competence_from',p_as_of-v_days,'competence_to',p_as_of)
    when 'before_due' then jsonb_build_object('due_from',p_as_of,'due_to',p_as_of+v_days)
    when 'overdue' then jsonb_build_object('due_from',p_as_of-730,'due_to',p_as_of-1)
    else jsonb_build_object('competence_from',p_as_of-730) end;

  return query
  with rows as (
    select r.* from fin_private.charge_rows(null,null,v_filters,p_as_of,5000,0) r
    join public.fin_member_charges c on c.id=r.charge_id
    where c.charge_type='membership'
      and r.stored_status in ('open','partial')
      and case v_stage
        when 'period_start' then r.competence_month<=p_as_of and p_as_of-r.competence_month<v_days
        when 'before_due' then r.due_date>=p_as_of and r.due_date-p_as_of<=v_days
        when 'overdue' then p_as_of>r.due_date and r.days_late>=v_days
        when 'in_review' then r.in_review else false end
      and (v_stage='in_review' or not r.in_review or not v_excl)
  ), agg as (
    select r.profile_id,max(r.profile_name) pname,array_agg(r.charge_id order by r.due_date,r.charge_id) ids,
      sum(r.total_due_cents) total,sum(r.principal_remaining_cents) principal,sum(r.fees_due_cents) fees,
      min(r.due_date) due,max(r.days_late) late,bool_and(r.fees_configured) fees_ok,
      array_agg(distinct r.competence_month order by r.competence_month) comps,max(r.competence_month) last_comp
    from rows r group by r.profile_id
  )
  select
    'fin:'||v_stage||':'||g.profile_id||':'||
      case v_stage when 'period_start' then to_char(g.last_comp,'YYYY-MM')
                   when 'before_due' then g.due::text
                   when 'overdue' then (g.late/v_repeat)::text
                   else md5(array_to_string(g.ids,',')) end,
    g.profile_id,null::uuid,pr.phone::text,g.pname,
    jsonb_build_object('charge_ids',to_jsonb(g.ids),'total_cents',g.total,'principal_cents',g.principal,'fees_cents',g.fees,
      'fees_configured',g.fees_ok,'due_date',g.due,'days_late',g.late,
      'competence_label',(select string_agg(conv_private.month_pt(x),' e ' order by x) from unnest(g.comps) x)),
    coalesce(pr.is_active,true),
    case when not coalesce(pr.is_active,true) then 'SOCIO_INATIVO' end
  from agg g join public.profiles pr on pr.id=g.profile_id;
end $function$;
--@@ 45 funcao conv_private.aud_result(a conv_automations, p_as_of date)
CREATE OR REPLACE FUNCTION conv_private.aud_result(a conv_automations, p_as_of date)
 RETURNS SETOF conv_private.audience_row
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d jsonb := a.definition; v_champ uuid := nullif(d->>'championship_id', '')::uuid;
  v_settle integer := coalesce(nullif(d->>'settle_minutes', '')::int, 10);
begin
  return query
  with m as (
    select mt.*, c.name as cname, ra.user_id as ra_user, rb.user_id as rb_user,
      coalesce(mt.walkover_winner_registration_id, mt.winner_registration_id) as win_reg,
      coalesce(mt.player_a_id, ra.user_id) as a_user, coalesce(mt.player_b_id, rb.user_id) as b_user,
      coalesce(pa.name, ra.guest_name) as a_name, coalesce(pb.name, rb.guest_name) as b_name
    from public.matches mt join public.championships c on c.id = mt.championship_id
    left join public.championship_registrations ra on ra.id = mt.registration_a_id
    left join public.championship_registrations rb on rb.id = mt.registration_b_id
    left join public.profiles pa on pa.id = coalesce(mt.player_a_id, ra.user_id)
    left join public.profiles pb on pb.id = coalesce(mt.player_b_id, rb.user_id)
    where mt.status::text = 'finished' and c.status::text in ('ongoing', 'active')
      and (v_champ is null or mt.championship_id = v_champ)
      and mt.result_set_at is not null and mt.result_set_at >= coalesce(a.activated_at, now())
      and mt.result_set_at <= now() - make_interval(mins => v_settle)
  ), side as (
    select m.*, 'a' as side, m.a_user as uid, m.a_name as who, m.b_name as opp, m.registration_a_id as reg from m
    union all
    select m.*, 'b', m.b_user, m.b_name, m.a_name, m.registration_b_id from m
  )
  select 'res:' || s.id || ':' || coalesce(s.uid::text, '-'), s.uid, null::uuid, pr.phone::text, s.who,
    jsonb_build_object('match_id', s.id, 'championship', s.cname, 'phase', s.phase, 'opponent', s.opp,
      'score', (select string_agg(case when s.side = 'a' then (s.score_a)[i]::text || '-' || (s.score_b)[i]::text
                                       else (s.score_b)[i]::text || '-' || (s.score_a)[i]::text end, ' ' order by i)
                from generate_subscripts(s.score_a, 1) i where (s.score_b)[i] is not null),
      'outcome', case
        when s.result_type = 'technical_draw' then 'empate técnico'
        when (s.win_reg is not null and s.win_reg = s.reg) or (s.win_reg is null and coalesce(s.walkover_winner_id, s.winner_id) = s.uid)
          then case when coalesce(s.is_walkover, false) or s.result_type = 'walkover' then 'vitória por W.O.' else 'vitória' end
        else case when coalesce(s.is_walkover, false) or s.result_type = 'walkover' then 'derrota por W.O.' else 'derrota' end end,
      'winner_ref', coalesce(s.win_reg::text, coalesce(s.walkover_winner_id, s.winner_id)::text)),
    (s.uid is not null and coalesce(pr.is_active, true)
      and (s.result_type = 'technical_draw' or s.win_reg is not null or coalesce(s.walkover_winner_id, s.winner_id) is not null)
      and (s.result_type in ('walkover', 'technical_draw') or coalesce(s.is_walkover, false) or cardinality(coalesce(s.score_a, '{}')) > 0)),
    case when s.uid is null then 'CONVIDADO_SEM_CADASTRO'
         when not (s.result_type = 'technical_draw' or s.win_reg is not null or coalesce(s.walkover_winner_id, s.winner_id) is not null) then 'RESULTADO_INCOMPLETO'
         when not (s.result_type in ('walkover', 'technical_draw') or coalesce(s.is_walkover, false) or cardinality(coalesce(s.score_a, '{}')) > 0) then 'PLACAR_INCOMPLETO'
         when not coalesce(pr.is_active, true) then 'SOCIO_INATIVO' end
  from side s left join public.profiles pr on pr.id = s.uid;
end $function$;
--@@ 45 funcao conv_private.audience(a conv_automations, p_as_of date, p_bucke
CREATE OR REPLACE FUNCTION conv_private.audience(a conv_automations, p_as_of date, p_bucket text DEFAULT NULL::text)
 RETURNS SETOF conv_private.audience_row
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_bucket text := coalesce(p_bucket, p_as_of::text); v_rows conv_private.audience_row[];
begin
  if a.source = 'finance_charge' then
    select array_agg(t) into v_rows from conv_private.aud_finance(a, p_as_of) t;
  elsif a.source = 'card_mensal' then
    select array_agg(t) into v_rows from conv_private.aud_card(a, p_as_of) t;
  elsif a.source in ('championship_notice', 'audience') then
    select array_agg(t) into v_rows from conv_private.aud_audience(a, p_as_of, v_bucket) t;
  elsif a.source = 'championship_result' then
    select array_agg(t) into v_rows from conv_private.aud_result(a, p_as_of) t;
  elsif a.source = 'championship_advance' then
    select array_agg(t) into v_rows from conv_private.aud_advance(a, p_as_of) t;
  end if;
  return query
  select x.dedupe_key, x.profile_id, x.student_id, conv_private.phone_e164(x.phone), x.display_name, x.subject,
    (x.included and conv_private.phone_e164(x.phone) is not null and not coalesce(ct.opt_out, false)),
    coalesce(x.reason, case when conv_private.phone_e164(x.phone) is null then 'SEM_TELEFONE_VALIDO'
                            when coalesce(ct.opt_out, false) then 'OPT_OUT' end)
  from unnest(coalesce(v_rows, '{}'::conv_private.audience_row[])) x
  left join public.conv_contacts ct on ct.phone = conv_private.phone_e164(x.phone);
end $function$;
--@@ 45 funcao conv_private.audit(p_action text, p_table text, p_record text, 
CREATE OR REPLACE FUNCTION conv_private.audit(p_action text, p_table text, p_record text, p_old jsonb, p_new jsonb, p_meta jsonb DEFAULT '{}'::jsonb, p_target uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old jsonb := p_old; v_new jsonb := p_new; v_key text;
begin
  foreach v_key in array array['inbound_token_hash', 'token', 'secret', 'api_key', 'payload'] loop
    v_old := v_old - v_key; v_new := v_new - v_key;
  end loop;
  perform public.admin_audit_insert_log(
    'conv.' || p_action, p_table, p_record, p_target,
    case when p_target is null then '{}'::uuid[] else array[p_target] end,
    case when v_old is not null and v_new is not null then public.admin_audit_changed_fields(v_old, v_new) else null end,
    v_old, v_new, coalesce(p_meta, '{}'::jsonb), 'conversations', now());
end $function$;
--@@ 45 funcao conv_private.automation_cap_until(p_contact uuid)
CREATE OR REPLACE FUNCTION conv_private.automation_cap_until(p_contact uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare s public.conv_automation_settings%rowtype; v_last timestamptz; v_today integer; v_week integer; v_until timestamptz := '-infinity';
  v_midnight timestamptz; v_edge timestamptz;
begin
  select * into s from public.conv_automation_settings where id;
  select max(e) into v_last from conv_private.automation_events(p_contact) e;
  if v_last is null then return null; end if;
  if s.min_hours_between > 0 then v_until := v_last + make_interval(hours => s.min_hours_between); end if;
  v_midnight := date_trunc('day', now() at time zone 'America/Fortaleza') at time zone 'America/Fortaleza';
  select count(*) filter (where e >= v_midnight), count(*) into v_today, v_week
    from conv_private.automation_events(p_contact) e where e > now() - interval '7 days';
  if v_today >= s.daily_cap then v_until := greatest(v_until, v_midnight + interval '1 day'); end if;
  if v_week >= s.weekly_cap then
    select e + interval '7 days' into v_edge from conv_private.automation_events(p_contact) e
      where e > now() - interval '7 days' order by e desc offset s.weekly_cap - 1 limit 1;
    v_until := greatest(v_until, coalesce(v_edge, now()));
  end if;
  return case when v_until > now() then v_until end;
end $function$;
--@@ 45 funcao conv_private.automation_claim(p_limit integer)
CREATE OR REPLACE FUNCTION conv_private.automation_claim(p_limit integer DEFAULT 10)
 RETURNS TABLE(recipient_id uuid, conversation_id uuid, body text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r public.conv_automation_recipients%rowtype; a public.conv_automations%rowtype; s public.conv_automation_settings%rowtype;
  v_chk jsonb; v_ctx jsonb; v_body text; v_contact uuid; v_next timestamptz; v_cap timestamptz; v_taken integer := 0;
  v_max integer := greatest(least(coalesce(p_limit, 10), 50), 1); v_opt boolean; v_name text;
begin
  select * into s from public.conv_automation_settings where id;
  if not coalesce(s.enabled, true) then return; end if;
  for r in select x.* from public.conv_automation_recipients x
           where (x.status = 'pending' and x.due_at <= now()) or (x.status = 'processing' and x.claimed_at < now() - interval '10 minutes')
           order by x.due_at limit v_max * 4 for update skip locked loop
    exit when v_taken >= v_max;
    select * into a from public.conv_automations where id = r.automation_id;
    -- Pausa/encerramento interrompem o que ainda não saiu.
    if not (a.status = 'active' or (a.trigger_type = 'manual' and a.status = 'draft')) and r.status = 'pending' then
      update public.conv_automation_recipients set status = 'canceled', skip_reason = 'AUTOMACAO_' || upper(a.status) where id = r.id;
      continue;
    end if;

    v_contact := conv_private.upsert_contact(r.phone, null, r.display_name, true);
    select ct.opt_out into v_opt from public.conv_contacts ct where ct.id = v_contact;
    if coalesce(v_opt, false) then
      update public.conv_automation_recipients set status = 'skipped', skip_reason = 'OPT_OUT', contact_id = v_contact where id = r.id;
      continue;
    end if;

    v_chk := conv_private.automation_revalidate(a, r);
    if not (v_chk->>'ok')::boolean then
      update public.conv_automation_recipients set status = 'skipped', skip_reason = left(v_chk->>'reason', 120), contact_id = v_contact where id = r.id;
      continue;
    end if;
    v_name := r.display_name;
    v_ctx := conv_private.automation_ctx(a.source, v_chk->'subject', v_name);
    v_body := conv_private.render_template(a.message_body, v_ctx);
    if v_body is null then
      update public.conv_automation_recipients set status = 'skipped', contact_id = v_contact,
        skip_reason = 'VARIAVEL_SEM_VALOR' where id = r.id;
      continue;
    end if;

    -- Janela e anti-spam: reagenda, não pula.
    v_next := conv_private.automation_next_allowed(now());
    v_cap := conv_private.automation_cap_until(v_contact);
    if v_cap is not null then v_next := conv_private.automation_next_allowed(greatest(v_next, v_cap)); end if;
    if v_next > now() + interval '1 minute' then
      update public.conv_automation_recipients set due_at = v_next, status = 'pending', claimed_at = null, contact_id = v_contact where id = r.id;
      continue;
    end if;

    update public.conv_automation_recipients set status = 'processing', claimed_at = now(), attempts = attempts + 1,
      contact_id = v_contact, body = v_body, subject = coalesce(subject, '{}'::jsonb) || coalesce(v_chk->'subject', '{}'::jsonb) where id = r.id;
    v_taken := v_taken + 1;
    recipient_id := r.id; conversation_id := conv_private.open_direct(v_contact); body := v_body;
    return next;
  end loop;
end $function$;
--@@ 45 funcao conv_private.automation_ctx(p_source text, p_subject jsonb, p_n
CREATE OR REPLACE FUNCTION conv_private.automation_ctx(p_source text, p_subject jsonb, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v jsonb:=jsonb_build_object('nome',conv_private.first_name(p_name),'clube','Sobral Tênis Clube'); v_days integer;
begin
  if p_source='finance_charge' then
    v:=v||jsonb_build_object(
      'competencia',p_subject->>'competence_label',
      'vencimento',case when p_subject->>'due_date' is null then null else conv_private.date_br((p_subject->>'due_date')::date) end,
      'valor',case when p_subject->>'principal_cents' is null then null else conv_private.brl((p_subject->>'principal_cents')::bigint) end,
      'total',case when p_subject->>'total_cents' is null then null else conv_private.brl((p_subject->>'total_cents')::bigint) end,
      'dias_atraso',nullif(p_subject->>'days_late','0'),
      'encargos',case when coalesce((p_subject->>'fees_configured')::boolean,false) then conv_private.brl(coalesce((p_subject->>'fees_cents')::bigint,0)) end,
      'itens',p_subject->>'items_text',
      'qtd',p_subject->>'item_count',
      'pix',p_subject->>'pix_key',
      'pago',case when p_subject->>'paid_cents' is null then null else conv_private.brl((p_subject->>'paid_cents')::bigint) end,
      'saldo',case when p_subject->>'balance_cents' is null then null else conv_private.brl((p_subject->>'balance_cents')::bigint) end
    );
  elsif p_source='card_mensal' then
    v_days:=((p_subject->>'expiration')::date-conv_private.today());
    v:=v||jsonb_build_object('vencimento',conv_private.date_br((p_subject->>'expiration')::date),
      'dias_para_vencer',case when v_days>=0 then v_days::text end,
      'dias_vencido',case when v_days<0 then (-v_days)::text end);
  elsif p_source='championship_notice' then
    v:=v||jsonb_build_object('campeonato',p_subject->>'championship','classe',p_subject->>'class');
  elsif p_source='championship_result' then
    v:=v||jsonb_build_object('campeonato',p_subject->>'championship','fase',p_subject->>'phase',
      'adversario',p_subject->>'opponent','placar',p_subject->>'score','resultado',p_subject->>'outcome');
  elsif p_source='championship_advance' then
    v:=v||jsonb_build_object('campeonato',p_subject->>'championship','fase',p_subject->>'phase',
      'adversario',coalesce(p_subject->>'opponent','a definir'));
  end if;
  return v;
end $function$;
--@@ 45 funcao conv_private.automation_events(p_contact uuid)
CREATE OR REPLACE FUNCTION conv_private.automation_events(p_contact uuid)
 RETURNS SETOF timestamp with time zone
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select m.sent_at from public.conv_messages m join public.conv_conversations cv on cv.id = m.conversation_id
   where cv.contact_id = p_contact and m.origin = 'automation' and m.status in ('sent', 'delivered', 'read') and m.sent_at is not null
  union all
  -- Reserva antiga (> 10 min) é de um envio que caiu no meio: o `claim` a reaproveita, então não bloqueia ninguém.
  select r.claimed_at from public.conv_automation_recipients r
   where r.contact_id = p_contact and r.status = 'processing' and r.claimed_at > now() - interval '10 minutes' $function$;
--@@ 45 funcao conv_private.automation_finish(p_recipient uuid, p_message uuid
CREATE OR REPLACE FUNCTION conv_private.automation_finish(p_recipient uuid, p_message uuid, p_ok boolean, p_error text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.conv_automation_recipients%rowtype;
begin
  select * into r from public.conv_automation_recipients where id = p_recipient for update;
  if not found or r.status <> 'processing' then return; end if;   -- já tratado: idempotente
  if p_ok then
    update public.conv_automation_recipients set status = 'sent', sent_at = now(), message_id = coalesce(p_message, message_id), last_error = null where id = p_recipient;
  elsif r.attempts < 3 then
    update public.conv_automation_recipients set status = 'pending', due_at = now() + make_interval(mins => 10 * r.attempts), claimed_at = null,
      last_error = left(coalesce(p_error, 'SEND_FAILED'), 300) where id = p_recipient;
  else
    update public.conv_automation_recipients set status = 'failed', last_error = left(coalesce(p_error, 'SEND_FAILED'), 300) where id = p_recipient;
    perform conv_private.audit('automation_send_failed', 'conv_automation_recipients', p_recipient::text, null,
      jsonb_build_object('automation_id', r.automation_id, 'error', left(coalesce(p_error, 'SEND_FAILED'), 80), 'attempts', r.attempts),
      jsonb_build_object('actor', 'system'));
  end if;
  update public.conv_automation_runs run set status = 'done', finished_at = now()
    where run.id = r.run_id and run.status = 'running'
      and not exists (select 1 from public.conv_automation_recipients x where x.run_id = run.id and x.status in ('pending', 'processing'));
end $function$;
--@@ 45 funcao conv_private.automation_materialize(a conv_automations, p_run u
CREATE OR REPLACE FUNCTION conv_private.automation_materialize(a conv_automations, p_run uuid, p_as_of date, p_bucket text, p_status text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_n integer; v_purpose text := conv_private.automation_purpose(a);
begin
  insert into public.conv_automation_recipients(run_id, automation_id, purpose_key, dedupe_key, profile_id, student_id, phone,
    display_name, subject, status, due_at)
  select p_run, a.id, v_purpose, x.dedupe_key, x.profile_id, x.student_id, x.phone, x.display_name, coalesce(x.subject, '{}'::jsonb), p_status, now()
  from conv_private.audience(a, p_as_of, p_bucket) x where x.included
  on conflict (purpose_key, dedupe_key) where status <> 'canceled' do nothing;
  get diagnostics v_n = row_count;
  return v_n;
end $function$;
--@@ 45 funcao conv_private.automation_next_allowed(p_at timestamp with time z
CREATE OR REPLACE FUNCTION conv_private.automation_next_allowed(p_at timestamp with time zone)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare s public.conv_automation_settings%rowtype; v_local timestamp; v_day date; i integer;
begin
  select * into s from public.conv_automation_settings where id;
  if not found then return p_at; end if;
  v_local := p_at at time zone 'America/Fortaleza';
  v_day := v_local::date;
  for i in 0..14 loop
    if extract(dow from v_day)::integer = any (s.days) then
      if i = 0 and v_local::time >= s.window_start and v_local::time < s.window_end then return p_at; end if;
      if i > 0 or v_local::time < s.window_start then return (v_day + s.window_start) at time zone 'America/Fortaleza'; end if;
    end if;
    v_day := v_day + 1;
  end loop;
  return p_at;
end $function$;
--@@ 45 funcao conv_private.automation_problems(a conv_automations)
CREATE OR REPLACE FUNCTION conv_private.automation_problems(a conv_automations)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_p text[] := '{}'; d jsonb := a.definition; s jsonb := a.schedule; k text; v_allowed text[] := conv_private.automation_vars(a.source);
  v_fee_ok boolean; v_date text; v_time text := s->>'time';
begin
  if length(trim(a.message_body)) = 0 then v_p := array_append(v_p, 'MENSAGEM_VAZIA'::text); end if;
  foreach k in array conv_private.template_vars(a.message_body) loop
    if not (k = any (v_allowed)) then v_p := array_append(v_p, 'VARIAVEL_INDISPONIVEL:' || k); end if;
  end loop;
  if 'encargos' = any (conv_private.template_vars(a.message_body)) then
    select (late_fee_confirmed_at is not null) into v_fee_ok from public.fin_settings where id;
    if not coalesce(v_fee_ok, false) then v_p := array_append(v_p, 'ENCARGOS_NAO_CONFIGURADOS'::text); end if;
  end if;

  if a.source = 'finance_charge' and coalesce(d->>'stage', '') not in ('period_start', 'before_due', 'overdue', 'in_review') then v_p := array_append(v_p, 'ESTAGIO_INVALIDO'::text); end if;
  if a.source in ('championship_notice') or (a.source = 'audience' and d->>'audience' = 'championship_participants') then
    if not exists (select 1 from public.championships c where c.id = nullif(d->>'championship_id', '')::uuid) then v_p := array_append(v_p, 'CAMPEONATO_OBRIGATORIO'::text); end if;
  end if;
  if a.source = 'audience' and coalesce(d->>'audience', '') not in ('members', 'students', 'dependents', 'professors', 'card_holders', 'championship_participants') then
    v_p := array_append(v_p, 'PUBLICO_INVALIDO'::text);
  end if;
  if a.source in ('championship_result', 'championship_advance') and nullif(d->>'championship_id', '') is not null
     and not exists (select 1 from public.championships c where c.id = (d->>'championship_id')::uuid) then v_p := array_append(v_p, 'CAMPEONATO_INEXISTENTE'::text); end if;

  if a.trigger_type = 'scheduled' then
    if v_time is null or conv_private.hhmm_to_min(v_time) is null then v_p := array_append(v_p, 'HORARIO_INVALIDO'::text); end if;
    if coalesce(jsonb_typeof(s->'dates') = 'array' and jsonb_array_length(s->'dates') > 0, false) then
      for v_date in select jsonb_array_elements_text(s->'dates') loop
        begin perform v_date::date; exception when others then v_p := array_append(v_p, 'DATA_INVALIDA'::text); end;
      end loop;
    elsif not coalesce(jsonb_typeof(s->'weekdays') = 'array' and jsonb_array_length(s->'weekdays') between 1 and 7, false) then
      v_p := array_append(v_p, 'RECORRENCIA_OBRIGATORIA'::text);
    end if;
  end if;
  return v_p;
end $function$;
--@@ 45 funcao conv_private.automation_purpose(a conv_automations)
CREATE OR REPLACE FUNCTION conv_private.automation_purpose(a conv_automations)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select a.source || ':' || coalesce(nullif(a.definition->>'stage', ''), nullif(a.definition->>'audience', ''), 'x') ||
    case when a.source in ('championship_notice', 'audience') then ':' || a.id::text else '' end $function$;
--@@ 45 funcao conv_private.automation_queue(p_recipient uuid, p_conversation 
CREATE OR REPLACE FUNCTION conv_private.automation_queue(p_recipient uuid, p_conversation uuid, p_body text)
 RETURNS TABLE(message_id uuid, destination text, already_sent boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.conv_automation_recipients%rowtype; q record;
begin
  select * into r from public.conv_automation_recipients where id = p_recipient for update;
  if not found then raise exception 'RECIPIENT_NOT_FOUND'; end if;
  if r.status <> 'processing' then raise exception 'RECIPIENT_NOT_PROCESSING'; end if;
  if length(trim(coalesce(p_body, ''))) not between 1 and 1000 then raise exception 'BODY_REQUIRED'; end if;
  select * into q from conv_private.queue_message(p_conversation, jsonb_build_object('kind', 'text', 'body', trim(p_body)), null, p_recipient, 'automation', null, p_recipient);
  update public.conv_automation_recipients set message_id = q.message_id, body = trim(p_body) where id = p_recipient;
  return query select q.message_id, q.destination, q.already_sent;
end $function$;
--@@ 45 funcao conv_private.automation_revalidate(a conv_automations, r conv_a
CREATE OR REPLACE FUNCTION conv_private.automation_revalidate(a conv_automations, r conv_automation_recipients)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  d jsonb:=a.definition; v_stage text:=d->>'stage'; v_ids uuid[]; v_subject jsonb; v_row record; v_as_of date:=conv_private.today();
  v_total bigint:=0; v_principal bigint:=0; v_fees bigint:=0; v_due date; v_late integer:=0; v_fees_ok boolean:=true; v_comps date[];
  v_repeat integer; v_c record; v_ok boolean; s record; v_include_future boolean; v_rs text;
begin
  if a.source='finance_charge' and v_stage='member_pendency_receipt_review' then
    select status into v_rs from public.fin_receipt_submissions where id=(r.subject->>'submission_id')::uuid;
    if v_rs not in ('submitted','in_review') then
      return jsonb_build_object('ok',false,'reason','COMPROVANTE_JA_RESOLVIDO');
    end if;
    return jsonb_build_object('ok',true,'subject',r.subject);
  elsif a.source='finance_charge' and v_stage='member_pendency_paid' then
    v_subject:=conv_private.pendency_paid_subject((r.subject->>'submission_id')::uuid);
    if v_subject is null then return jsonb_build_object('ok',false,'reason','PAGAMENTO_NAO_CONFIRMADO'); end if;
    return jsonb_build_object('ok',true,'subject',v_subject);
  elsif a.source='finance_charge' and v_stage='member_pendency' then
    if not coalesce((select pendency_automation_enabled from public.fin_settings where id),true)
       and coalesce(r.subject->>'scope','')<>'manual' then
      return jsonb_build_object('ok',false,'reason','COBRANCA_AUTOMATICA_DESATIVADA');
    end if;
    v_include_future:=coalesce(r.subject->>'scope','')='manual';
    v_subject:=conv_private.member_pendency_subject(r.profile_id,v_as_of,v_include_future);
    if v_subject is null then return jsonb_build_object('ok',false,'reason','PENDENCIA_QUITADA_OU_EM_ANALISE'); end if;
    return jsonb_build_object('ok',true,'subject',v_subject||jsonb_build_object('scope',coalesce(r.subject->>'scope','due')));
  elsif a.source='finance_charge' then
    select coalesce(array_agg(x::uuid),'{}') into v_ids from jsonb_array_elements_text(r.subject->'charge_ids') x;
    v_repeat:=greatest(coalesce(nullif(d->>'repeat_days','')::int,7),1);
    for v_c in select * from fin_private.charge_rows(r.profile_id,v_ids,'{}'::jsonb,v_as_of,100,0) loop
      v_ok:=v_c.stored_status in ('open','partial') and case v_stage
        when 'period_start' then v_c.competence_month<=v_as_of
        when 'before_due' then v_c.due_date>=v_as_of
        when 'overdue' then v_as_of>v_c.due_date
        when 'in_review' then v_c.in_review else false end
        and (v_stage='in_review' or not v_c.in_review or not coalesce((d->>'exclude_in_review')::boolean,true));
      continue when not v_ok;
      v_total:=v_total+v_c.total_due_cents; v_principal:=v_principal+v_c.principal_remaining_cents; v_fees:=v_fees+v_c.fees_due_cents;
      v_due:=least(coalesce(v_due,v_c.due_date),v_c.due_date); v_late:=greatest(v_late,v_c.days_late);
      v_fees_ok:=v_fees_ok and v_c.fees_configured; v_comps:=array_append(coalesce(v_comps,'{}'),v_c.competence_month);
    end loop;
    if v_comps is null then return jsonb_build_object('ok',false,'reason','COBRANCA_NAO_PENDENTE'); end if;
    v_subject:=jsonb_build_object('total_cents',v_total,'principal_cents',v_principal,'fees_cents',v_fees,'fees_configured',v_fees_ok,
      'due_date',v_due,'days_late',v_late,
      'competence_label',(select string_agg(conv_private.month_pt(x),' e ' order by x) from (select distinct unnest(v_comps) x) q));
  elsif a.source='card_mensal' then
    select s2.* into s from public.non_socio_students s2 where s2.id=r.student_id;
    if not found or s.plan_type<>'Card Mensal' or coalesce(s.plan_status,'inactive')<>'active' or not coalesce(s.is_active,true) then
      return jsonb_build_object('ok',false,'reason','CARD_INATIVO_OU_CANCELADO');
    end if;
    if s.master_expiration_date is distinct from (r.subject->>'expiration')::date then return jsonb_build_object('ok',false,'reason','CARD_RENOVADO_OU_ALTERADO'); end if;
    if exists(select 1 from public.student_profiles sp where sp.non_socio_student_id=s.id and sp.student_status<>'active') then
      return jsonb_build_object('ok',false,'reason','ALUNO_PAUSADO_OU_ENCERRADO');
    end if;
    v_subject:=r.subject;
  elsif a.source in ('championship_result','championship_advance') then
    select x.* into v_row from conv_private.audience(a,v_as_of,null) x where x.dedupe_key=r.dedupe_key;
    if not found or not v_row.included then return jsonb_build_object('ok',false,'reason',coalesce(v_row.reason,'EVENTO_NAO_CONFIRMADO_AGORA')); end if;
    if a.source='championship_result' and (v_row.subject->>'winner_ref') is distinct from (r.subject->>'winner_ref') then
      return jsonb_build_object('ok',false,'reason','RESULTADO_ALTERADO');
    end if;
    v_subject:=v_row.subject;
  else
    select x.* into v_row from conv_private.audience(a,v_as_of,split_part(r.dedupe_key,':',2)) x where x.dedupe_key=r.dedupe_key;
    if not found or not v_row.included then return jsonb_build_object('ok',false,'reason',coalesce(v_row.reason,'FORA_DO_PUBLICO')); end if;
    v_subject:=coalesce(v_row.subject,r.subject);
  end if;
  return jsonb_build_object('ok',true,'subject',v_subject);
end $function$;
--@@ 45 funcao conv_private.automation_test_payload(p_actor uuid, p_id uuid)
CREATE OR REPLACE FUNCTION conv_private.automation_test_payload(p_actor uuid, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.conv_automations%rowtype; v_phone text; v_first record; v_body text;
begin
  select conv_private.phone_e164(p.phone) into v_phone from public.profiles p where p.id = p_actor and p.role::text = 'admin';
  if v_phone is null then raise exception 'ADMIN_WITHOUT_PHONE'; end if;
  select * into a from public.conv_automations where id = p_id;
  if not found then raise exception 'AUTOMATION_NOT_FOUND'; end if;
  select * into v_first from conv_private.audience(a, conv_private.today(), conv_private.today()::text) x where x.included limit 1;
  if v_first.dedupe_key is null then raise exception 'NO_SAMPLE_RECIPIENT'; end if;
  v_body := conv_private.render_template(a.message_body, conv_private.automation_ctx(a.source, v_first.subject, v_first.display_name));
  if v_body is null then raise exception 'VARIABLE_UNAVAILABLE'; end if;
  return jsonb_build_object('phone', v_phone, 'body', '[TESTE — exemplo com dados reais de um destinatário] ' || v_body);
end $function$;
--@@ 45 funcao conv_private.automation_tick(p_now timestamp with time zone)
CREATE OR REPLACE FUNCTION conv_private.automation_tick(p_now timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  a public.conv_automations%rowtype; s public.conv_automation_settings%rowtype; v_local timestamp := p_now at time zone 'America/Fortaleza';
  v_today date := v_local::date; v_planned timestamptz; v_run uuid; v_n integer; v_runs integer := 0; v_recipients integer := 0;
  v_due_today boolean; v_end date; v_bucket text;
begin
  select * into s from public.conv_automation_settings where id;
  if not coalesce(s.enabled, true) then return jsonb_build_object('enabled', false); end if;
  for a in select * from public.conv_automations where status = 'active' and trigger_type in ('scheduled', 'conditional', 'event') order by created_at loop
    v_end := nullif(a.schedule->>'end_date', '')::date;
    if v_end is not null and v_today > v_end then
      update public.conv_automations set status = 'ended', ended_at = now(), updated_at = now() where id = a.id;
      update public.conv_automation_recipients set status = 'canceled', skip_reason = 'AUTOMACAO_ENCERRADA' where automation_id = a.id and status in ('pending', 'review');
      perform conv_private.audit('automation_ended', 'conv_automations', a.id::text, null, jsonb_build_object('status', 'ended', 'reason', 'end_date'),
        jsonb_build_object('actor', 'system'));
      continue;
    end if;

    if a.trigger_type = 'scheduled' then
      v_due_today := case
        when jsonb_typeof(a.schedule->'dates') = 'array' and jsonb_array_length(a.schedule->'dates') > 0 then a.schedule->'dates' ? v_today::text
        else coalesce(a.schedule->'weekdays', '[]'::jsonb) @> to_jsonb(extract(dow from v_today)::int) end;
      continue when not v_due_today;
      v_planned := (v_today + (a.schedule->>'time')::time) at time zone 'America/Fortaleza';
      continue when p_now < v_planned;
      v_bucket := v_today::text;
    else
      -- condicional e evento: uma execução por dia, que recebe quem passou a atender a condição.
      v_planned := v_today::timestamp at time zone 'America/Fortaleza';
      v_bucket := v_today::text;
    end if;

    insert into public.conv_automation_runs(automation_id, version, kind, planned_for)
    values (a.id, a.version, a.trigger_type, v_planned)
    on conflict (automation_id, planned_for) do nothing returning id into v_run;
    if v_run is null then
      if a.trigger_type = 'scheduled' then continue; end if;   -- agendada: já rodou hoje
      select id into v_run from public.conv_automation_runs where automation_id = a.id and planned_for = v_planned and status = 'running';
      continue when v_run is null;
    else v_runs := v_runs + 1; end if;

    v_n := conv_private.automation_materialize(a, v_run, v_today, v_bucket, 'pending');
    v_recipients := v_recipients + v_n;
    -- Execução sem ninguém: não deixa lixo (condicional/evento volta amanhã; agendada fica registrada como feita).
    if v_n = 0 and a.trigger_type <> 'scheduled' and not exists (select 1 from public.conv_automation_recipients where run_id = v_run) then
      delete from public.conv_automation_runs where id = v_run;
      v_runs := v_runs - 1;
    elsif v_n = 0 and not exists (select 1 from public.conv_automation_recipients where run_id = v_run and status in ('pending', 'processing')) then
      update public.conv_automation_runs set status = 'done', finished_at = now() where id = v_run;
    end if;
    v_run := null;
  end loop;
  return jsonb_build_object('enabled', true, 'runs', v_runs, 'recipients', v_recipients);
end $function$;
--@@ 45 funcao conv_private.automation_vars(p_source text)
CREATE OR REPLACE FUNCTION conv_private.automation_vars(p_source text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case p_source
    when 'finance_charge' then array['nome','clube','competencia','vencimento','valor','total','dias_atraso','encargos','itens','qtd','pix','pago','saldo']
    when 'card_mensal' then array['nome','clube','vencimento','dias_para_vencer','dias_vencido']
    when 'championship_notice' then array['nome','clube','campeonato','classe']
    when 'championship_result' then array['nome','clube','campeonato','fase','adversario','placar','resultado']
    when 'championship_advance' then array['nome','clube','campeonato','fase','adversario']
    when 'audience' then array['nome','clube']
    else array[]::text[] end
$function$;
--@@ 45 funcao conv_private.available_slots(p_date date, p_court uuid, p_durat
CREATE OR REPLACE FUNCTION conv_private.available_slots(p_date date, p_court uuid, p_duration integer)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_now timestamp := now() at time zone 'America/Fortaleza'; m integer; v_out text[] := '{}';
begin
  if p_date is null or p_date < v_now::date or p_duration not in (30, 60, 90, 120) then return v_out; end if;
  for m in select g from generate_series(300, 1350, 30) g loop
    continue when m + p_duration > 1380;
    continue when p_date = v_now::date and m <= extract(hour from v_now)::int * 60 + extract(minute from v_now)::int;
    continue when conv_private.court_busy(p_court, p_date, m, m + p_duration);
    v_out := v_out || conv_private.min_to_hhmm(m);
  end loop;
  return v_out;
end $function$;
--@@ 45 funcao conv_private.begin_op(p_key uuid, p_action text)
CREATE OR REPLACE FUNCTION conv_private.begin_op(p_key uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := auth.uid(); v_row public.conv_requests%rowtype;
begin
  if v_actor is null then raise exception 'CONV_FORBIDDEN' using errcode = '42501'; end if;
  if p_key is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED'; end if;
  insert into public.conv_requests(request_id, action, actor_id) values (p_key, p_action, v_actor)
  on conflict (request_id) do nothing;
  if not found then
    select * into v_row from public.conv_requests where request_id = p_key;
    if v_row.action <> p_action or v_row.actor_id is distinct from v_actor then
      raise exception 'IDEMPOTENCY_KEY_REUSED';
    end if;
    return coalesce(v_row.result, '{}'::jsonb) || jsonb_build_object('replayed', true);
  end if;
  return null;
end $function$;
--@@ 45 funcao conv_private.br_local_phone(p text)
CREATE OR REPLACE FUNCTION conv_private.br_local_phone(p text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare d text := regexp_replace(coalesce(p, ''), '\D', '', 'g');
begin
  if d like '55%' and length(d) >= 12 then d := substr(d, 3); end if;
  if length(d) > 11 then d := right(d, 11); end if;
  return d;
end $function$;
--@@ 45 funcao conv_private.briefing_list_names(p_extra uuid, p_enabled boolea
CREATE OR REPLACE FUNCTION conv_private.briefing_list_names(p_extra uuid, p_enabled boolean)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(string_agg(p.name, ', ' order by p.name), 'ninguém')
  from public.profiles p
  where p.role::text = 'admin' and coalesce(p.is_active, true)
    and ((exists (select 1 from public.conv_admin_briefing_recipients r where r.profile_id = p.id and r.enabled) and p.id is distinct from case when not p_enabled then p_extra end)
         or (p_enabled and p.id = p_extra)) $function$;
--@@ 45 funcao conv_private.brl(p_cents bigint)
CREATE OR REPLACE FUNCTION conv_private.brl(p_cents bigint)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select 'R$ ' || regexp_replace(trunc(abs(p_cents) / 100)::text, '(\d)(?=(\d{3})+$)', '\1.', 'g') || ',' || lpad((abs(p_cents) % 100)::text, 2, '0') $function$;
--@@ 45 funcao conv_private.can_merge(a uuid, b uuid)
CREATE OR REPLACE FUNCTION conv_private.can_merge(a uuid, b uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ca public.conv_contacts%rowtype; cb public.conv_contacts%rowtype; ia text; ib text;
begin
  select * into ca from public.conv_contacts where id = a;
  select * into cb from public.conv_contacts where id = b;
  if ca.id is null or cb.id is null or ca.merged_into is not null or cb.merged_into is not null then return false; end if;
  ia := coalesce(ca.profile_id::text, ca.non_socio_student_id::text);
  ib := coalesce(cb.profile_id::text, cb.non_socio_student_id::text);
  if ia is not null and ib is not null and ia <> ib then return false; end if;
  if ca.lid is not null and cb.lid is not null and ca.lid <> cb.lid then return false; end if;
  if ca.phone is not null and cb.phone is not null
     and conv_private.phone_key(ca.phone) is distinct from conv_private.phone_key(cb.phone) then return false; end if;
  return true;
end $function$;
--@@ 45 funcao conv_private.channel_delivery()
CREATE OR REPLACE FUNCTION conv_private.channel_delivery()
 RETURNS TABLE(inbound_token_hash text, bot_phone text, bot_lids text[], ai_direct_enabled boolean, ai_group_enabled boolean, mention_verified_at timestamp with time zone, group_session_minutes smallint, institutional_name text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select c.inbound_token_hash, c.bot_phone, c.bot_lids, c.ai_direct_enabled, c.ai_group_enabled, c.mention_verified_at,
    c.group_session_minutes, c.institutional_name
  from public.conv_channel c where c.id $function$;
--@@ 45 funcao conv_private.claim_due_followups(p_limit integer)
CREATE OR REPLACE FUNCTION conv_private.claim_due_followups(p_limit integer)
 RETURNS TABLE(followup_id uuid, conversation_id uuid, send_body text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  update public.conv_followups f set status = 'sending'
  where f.id in (
    select id from public.conv_followups where status = 'pending' and send_body is not null and due_at <= now()
    order by due_at limit greatest(least(coalesce(p_limit, 20), 50), 1) for update skip locked)
  returning f.id, f.conversation_id, f.send_body;
$function$;
--@@ 45 funcao conv_private.conversation_contact(p_conversation uuid)
CREATE OR REPLACE FUNCTION conv_private.conversation_contact(p_conversation uuid)
 RETURNS TABLE(contact_id uuid, destination text, name text, avatar_url text, avatar_checked_at timestamp with time zone, is_group boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select c.id, coalesce(c.phone, g.group_jid), coalesce(c.name, g.name), c.avatar_url, c.avatar_checked_at, cv.kind = 'group'
  from public.conv_conversations cv left join public.conv_contacts c on c.id = cv.contact_id
  left join public.conv_groups g on g.id = cv.group_id where cv.id = p_conversation;
$function$;
--@@ 45 funcao conv_private.court_busy(p_court uuid, p_date date, p_start_min 
CREATE OR REPLACE FUNCTION conv_private.court_busy(p_court uuid, p_date date, p_start_min integer, p_end_min integer, p_exclude uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1 from public.reservations r
    where r.court_id = p_court and r.date = p_date and r.status::text <> 'cancelled'
      and (p_exclude is null or r.id <> p_exclude)
      and (extract(hour from r.start_time)::int * 60 + extract(minute from r.start_time)::int) < p_end_min
      and (case when r.end_time = time '00:00' then 1440
                else extract(hour from r.end_time)::int * 60 + extract(minute from r.end_time)::int end) > p_start_min);
$function$;
--@@ 45 funcao conv_private.date_br(p_date date)
CREATE OR REPLACE FUNCTION conv_private.date_br(p_date date)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$ select to_char(p_date, 'DD/MM/YYYY') $function$;
--@@ 45 funcao conv_private.dedupe_contact(p_id uuid)
CREATE OR REPLACE FUNCTION conv_private.dedupe_contact(p_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.conv_contacts%rowtype; o record; v_cur uuid := p_id; v_keep uuid; v_key text;
begin
  select * into c from public.conv_contacts where id = p_id;
  if c.id is null then return p_id; end if;
  if c.merged_into is not null then return c.merged_into; end if;
  v_key := conv_private.phone_key(c.phone);
  for o in
    select x.id from public.conv_contacts x
    where x.merged_into is null and x.id <> p_id
      and ((c.profile_id is not null and x.profile_id = c.profile_id)
        or (c.non_socio_student_id is not null and x.non_socio_student_id = c.non_socio_student_id)
        or (v_key is not null and x.phone is not null and conv_private.phone_key(x.phone) = v_key))
    order by x.created_at, x.id
  loop
    if not conv_private.can_merge(v_cur, o.id) then continue; end if;
    v_keep := conv_private.older_of(v_cur, o.id);
    perform conv_private.merge_contacts(v_keep, case when v_keep = v_cur then o.id else v_cur end);
    v_cur := v_keep;
  end loop;
  return v_cur;
end $function$;
--@@ 45 funcao conv_private.digits(p text)
CREATE OR REPLACE FUNCTION conv_private.digits(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select regexp_replace(coalesce(p, ''), '[^0-9]', '', 'g') $function$;
--@@ 45 funcao conv_private.finish_followup(p_followup uuid, p_message uuid, p
CREATE OR REPLACE FUNCTION conv_private.finish_followup(p_followup uuid, p_message uuid, p_error text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  update public.conv_followups set status = case when p_error is null then 'sent' else 'failed' end,
    message_id = p_message, last_error = left(p_error, 300), done_at = now()
  where id = p_followup and status = 'sending';
$function$;
--@@ 45 funcao conv_private.finish_message(p_message uuid, p_sent boolean, p_p
CREATE OR REPLACE FUNCTION conv_private.finish_message(p_message uuid, p_sent boolean, p_provider_id text, p_error text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_conv uuid; v_origin text;
begin
  update public.conv_messages set
    status = case when p_sent then 'sent' else 'failed' end,
    provider_message_id = case when p_sent then coalesce(nullif(p_provider_id, ''), provider_message_id) else provider_message_id end,
    sent_at = case when p_sent then now() else sent_at end,
    attempts = attempts + 1,
    last_error = case when p_sent then null else left(coalesce(p_error, 'SEND_FAILED'), 300) end
  where id = p_message and status in ('queued', 'failed')
  returning conversation_id, origin into v_conv, v_origin;
  if p_sent and v_conv is not null then
    update public.conv_conversations set
      last_staff_at = now(), last_message_at = now(),
      staff_read_at = case when v_origin = 'staff' then now() else staff_read_at end
    where id = v_conv;
  end if;
end $function$;
--@@ 45 funcao conv_private.finish_op(p_key uuid, p_result jsonb)
CREATE OR REPLACE FUNCTION conv_private.finish_op(p_key uuid, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  update public.conv_requests set result = p_result where request_id = p_key;
  return p_result;
end $function$;
--@@ 45 funcao conv_private.first_name(p text)
CREATE OR REPLACE FUNCTION conv_private.first_name(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select nullif(initcap(split_part(btrim(coalesce(p, '')), ' ', 1)), '') $function$;
--@@ 45 funcao conv_private.fold(p text)
CREATE OR REPLACE FUNCTION conv_private.fold(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select lower(translate(coalesce(p, ''),
    'ÁÀÂÃÄáàâãäÉÈÊËéèêëÍÌÎÏíìîïÓÒÔÕÖóòôõöÚÙÛÜúùûüÇçÑñ',
    'AAAAAaaaaaEEEEeeeeIIIIiiiiOOOOOoooooUUUUuuuuCcNn')) $function$;
--@@ 45 funcao conv_private.fold_conversation(p_keep uuid, p_drop uuid)
CREATE OR REPLACE FUNCTION conv_private.fold_conversation(p_keep uuid, p_drop uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_keep = p_drop then return; end if;
  -- Sessões abertas da conversa absorvida terminam (a IA recomeça no contexto da conversa mantida).
  update public.conv_ai_sessions set status = 'expired' where conversation_id = p_drop and status = 'open';
  update public.conv_messages set conversation_id = p_keep where conversation_id = p_drop;
  update public.conv_notes set conversation_id = p_keep where conversation_id = p_drop;
  update public.conv_followups set conversation_id = p_keep where conversation_id = p_drop;
  update public.conv_ai_sessions set conversation_id = p_keep where conversation_id = p_drop;
  update public.conv_booking_proposals set conversation_id = p_keep where conversation_id = p_drop;
  update public.conv_ai_decisions set conversation_id = p_keep where conversation_id = p_drop;

  update public.conv_conversations kv set
    last_message_at = greatest(kv.last_message_at, dv.last_message_at),
    last_inbound_at = greatest(kv.last_inbound_at, dv.last_inbound_at),
    last_staff_at = greatest(kv.last_staff_at, dv.last_staff_at),
    staff_read_at = least(coalesce(kv.staff_read_at, dv.staff_read_at), coalesce(dv.staff_read_at, kv.staff_read_at)),
    tags = (select coalesce(array_agg(t), '{}') from (select distinct t from unnest(kv.tags || dv.tags) t limit 12) s),
    assigned_to = coalesce(kv.assigned_to, dv.assigned_to),
    handled_by_human = kv.handled_by_human or dv.handled_by_human,
    -- O estado mais restritivo vence: se a equipe assumiu ou pausou a IA em qualquer uma, segue assim.
    ai_status = case when 'human' in (kv.ai_status, dv.ai_status) then 'human'
                     when 'paused' in (kv.ai_status, dv.ai_status) then 'paused' else 'ai' end,
    handoff_kind = case when kv.handoff_at is not null and (dv.handoff_at is null or kv.handoff_at >= dv.handoff_at)
                        then kv.handoff_kind else coalesce(dv.handoff_kind, kv.handoff_kind) end,
    handoff_note = case when kv.handoff_at is not null and (dv.handoff_at is null or kv.handoff_at >= dv.handoff_at)
                        then kv.handoff_note else coalesce(dv.handoff_note, kv.handoff_note) end,
    handoff_at = greatest(kv.handoff_at, dv.handoff_at)
  from public.conv_conversations dv
  where kv.id = p_keep and dv.id = p_drop;

  update public.conv_conversations set status = 'closed', merged_into = p_keep, last_message_at = null where id = p_drop;
end $function$;
--@@ 45 funcao conv_private.game_people(p_reservation uuid)
CREATE OR REPLACE FUNCTION conv_private.game_people(p_reservation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.reservations%rowtype; v_ids uuid[];
begin
  select * into r from public.reservations where id = p_reservation;
  if not found or r.type <> 'Play' then return '[]'::jsonb; end if;
  select coalesce(array_agg(x order by o), '{}') into v_ids from (
    select x, min(o) o from (
      select r.creator_id x, 0 o where r.creator_id is not null
      union all select p, ord from unnest(coalesce(r.participant_ids, '{}')) with ordinality as t(p, ord)) a group by x) b;
  return coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name::text) order by array_position(v_ids, p.id))
                   from public.profiles p where p.id = any (v_ids)), '[]'::jsonb);
end $function$;
--@@ 45 funcao conv_private.game_summary(p_reservation uuid)
CREATE OR REPLACE FUNCTION conv_private.game_summary(p_reservation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.reservations%rowtype; v_ids uuid[]; v_names jsonb := '[]'::jsonb; v_guest text; v_n integer;
begin
  select * into r from public.reservations where id = p_reservation;
  if not found then return null; end if;
  v_guest := nullif(trim(coalesce(r.guest_name, '')), '');
  -- Quem criou vem primeiro; depois os demais participantes, sem repetir.
  select coalesce(array_agg(x order by o), '{}') into v_ids from (
    select x, min(o) o from (
      select r.creator_id x, 0 o where r.creator_id is not null
      union all select p, ord from unnest(coalesce(r.participant_ids, '{}')) with ordinality as t(p, ord)
    ) a group by x) b;
  v_n := cardinality(v_ids) + case when v_guest is null then 0 else 1 end;
  if r.type = 'Play' then
    select coalesce(jsonb_agg(p.name::text order by array_position(v_ids, p.id)), '[]'::jsonb) into v_names
      from public.profiles p where p.id = any (v_ids);
    if v_guest is not null then v_names := v_names || to_jsonb(v_guest || ' (convidado)'); end if;
  end if;
  return jsonb_build_object('reservation_id', r.id, 'type', r.type, 'date', r.date,
    'start', to_char(r.start_time, 'HH24:MI'), 'end', to_char(r.end_time, 'HH24:MI'),
    'court_id', r.court_id, 'court_name', (select c.name from public.courts c where c.id = r.court_id),
    'names', v_names, 'participants', v_n, 'spots_left', greatest(8 - v_n, 0));
end $function$;
--@@ 45 funcao conv_private.hhmm_to_min(p text)
CREATE OR REPLACE FUNCTION conv_private.hhmm_to_min(p text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
  if p !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then return null; end if;
  return substr(p, 1, 2)::int * 60 + substr(p, 4, 2)::int;
end $function$;
--@@ 45 funcao conv_private.immutable_row()
CREATE OR REPLACE FUNCTION conv_private.immutable_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin raise exception 'CONV_IMMUTABLE: % é histórico e não se altera.', tg_table_name using errcode = '42501'; end $function$;
--@@ 45 funcao conv_private.ingest_message(p jsonb)
CREATE OR REPLACE FUNCTION conv_private.ingest_message(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_pid text := nullif(trim(p->>'provider_id'), '');
  v_group_kind boolean := coalesce(p->>'chat_kind', 'direct') = 'group';
  v_from_me boolean := coalesce((p->>'from_me')::boolean, false);
  v_at timestamptz := coalesce(nullif(p->>'sent_at', '')::timestamptz, now());
  v_kind text := coalesce(nullif(p->>'kind', ''), 'text');
  v_body text := nullif(p->>'body', '');
  v_reply text := nullif(p->>'reply_to', '');
  v_preview text; v_msg uuid; v_conv uuid; v_contact uuid; v_sender uuid; v_group public.conv_groups%rowtype;
  v_jid text := nullif(p->>'group_jid', '');
  v_dup record;
begin
  if v_pid is null then raise exception 'PROVIDER_ID_REQUIRED'; end if;
  if v_kind not in ('text','image','video','audio','ptt','document','sticker','location','contact','other') then v_kind := 'other'; end if;

  select id, conversation_id into v_dup from public.conv_messages where provider_message_id = v_pid;
  if found then
    return jsonb_build_object('message_id', v_dup.id, 'conversation_id', v_dup.conversation_id, 'duplicate', true);
  end if;

  if v_group_kind then
    if v_jid is null or v_jid !~ '^[0-9A-Za-z._-]{5,64}@g\.us$' then raise exception 'INVALID_GROUP'; end if;
    insert into public.conv_groups(group_jid, name, last_payload_shape)
    values (v_jid, left(nullif(p->>'group_name', ''), 200), p->'payload_shape')
    on conflict (group_jid) do update set
      last_seen_at = now(), events_seen = public.conv_groups.events_seen + 1,
      name = coalesce(nullif(excluded.name, ''), public.conv_groups.name),
      last_payload_shape = coalesce(excluded.last_payload_shape, public.conv_groups.last_payload_shape)
    returning * into v_group;
    -- Grupo não permitido: não se grava nada do conteúdo.
    if v_group.status <> 'allowed' then
      return jsonb_build_object('ignored', 'group_not_allowed', 'group_id', v_group.id, 'group_status', v_group.status);
    end if;
    if not v_from_me then
      v_sender := conv_private.upsert_contact(p->>'phone', p->>'lid', p->>'name', false);
    end if;
    v_conv := conv_private.open_group(v_group.id);
  else
    v_contact := conv_private.upsert_contact(p->>'phone', null, p->>'name', v_from_me);
    v_sender := case when v_from_me then null else v_contact end;
    v_conv := conv_private.open_direct(v_contact);
  end if;

  if v_reply is not null then
    select coalesce(nullif(body, ''), case kind when 'image' then '📷 Foto' when 'video' then '🎥 Vídeo'
      when 'audio' then '🎤 Áudio' when 'ptt' then '🎤 Áudio' when 'document' then '📄 Documento' else '' end)
      into v_preview from public.conv_messages where provider_message_id = v_reply;
  end if;

  insert into public.conv_messages(conversation_id, direction, origin, sender_contact_id, kind, body, status,
    provider_message_id, sent_at, media_mime, media_name, meta, reply_to_provider_id, reply_preview, mention_direct, mention_evidence)
  values (v_conv, case when v_from_me then 'outbound' else 'inbound' end, case when v_from_me then 'staff' else 'customer' end,
    v_sender, v_kind, v_body, case when v_from_me then 'sent' else 'received' end, v_pid, v_at,
    nullif(p->>'mime', ''), left(nullif(p->>'file_name', ''), 120), coalesce(p->'meta', '{}'::jsonb), v_reply, left(v_preview, 200),
    coalesce((p#>>'{mention,direct}')::boolean, false) and v_group_kind and not v_from_me,
    left(nullif(p#>>'{mention,evidence}', ''), 80))
  on conflict (provider_message_id) where provider_message_id is not null do nothing
  returning id into v_msg;
  if v_msg is null then
    select id into v_msg from public.conv_messages where provider_message_id = v_pid;
    return jsonb_build_object('message_id', v_msg, 'conversation_id', v_conv, 'duplicate', true);
  end if;

  update public.conv_conversations set
    last_message_at = greatest(coalesce(last_message_at, v_at), v_at),
    last_inbound_at = case when v_from_me then last_inbound_at else v_at end,
    last_staff_at = case when v_from_me then v_at else last_staff_at end,
    -- Resposta dada pelo celular do clube também conta como lida pela equipe.
    staff_read_at = case when v_from_me then greatest(coalesce(staff_read_at, v_at), v_at) else staff_read_at end
  where id = v_conv;

  return jsonb_build_object('message_id', v_msg, 'conversation_id', v_conv, 'contact_id', v_sender, 'duplicate', false,
    'kind', case when v_group_kind then 'group' else 'direct' end, 'from_me', v_from_me);
end $function$;
--@@ 45 funcao conv_private.is_confirmation(p text)
CREATE OR REPLACE FUNCTION conv_private.is_confirmation(p text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare t text; w text; n integer := 0; v_ok boolean := false;
  allowed text[] := array['sim','pode','ser','confirmar','confirmo','confirmado','confirma','marcar','reservar','marca','reserva','fechado',
    'isso','mesmo','ok','okay','perfeito','certo','combinado','beleza','claro','positivo','por','favor','pf','pfv','obrigado','obrigada',
    'valeu','vamos','bora','la','esse','essa','horario','quadra','e','a','o','s','uhum','aham','exato','exatamente',
    'quero','entrar','entro','topo','topa','coloca','coloque','adiciona','adicione','me','no','nesse','jogo','tambem'];
  yes_first text[] := array['sim','pode','confirmo','confirmado','confirma','fechado','isso','ok','okay','perfeito','certo','combinado',
    'beleza','claro','positivo','s','uhum','aham','exato','exatamente','marca','reserva','vamos','bora','entro','topo','topa'];
begin
  if p is null or length(p) > 80 or position('?' in p) > 0 then return false; end if;
  t := conv_private.fold(p);
  t := replace(t, '👍', ' sim ');
  t := regexp_replace(t, '[^a-z ]', ' ', 'g');
  for w in select x from regexp_split_to_table(btrim(t), '\s+') x where x <> '' loop
    n := n + 1;
    if n > 8 or not (w = any (allowed)) then return false; end if;
    if n = 1 then v_ok := w = any (yes_first); end if;
  end loop;
  return n > 0 and v_ok;
end $function$;
--@@ 45 funcao conv_private.is_opt_out(p_body text)
CREATE OR REPLACE FUNCTION conv_private.is_opt_out(p_body text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with t as (select btrim(regexp_replace(conv_private.fold(coalesce(p_body, '')), '[^a-z0-9 ]', ' ', 'g')) x)
  select exists (
    select 1 from t, public.conv_automation_settings s, unnest(s.opt_out_keywords) k
    where s.id and t.x <> '' and array_length(regexp_split_to_array(t.x, '\s+'), 1) <= 6
      and (t.x = conv_private.fold(k) or t.x like conv_private.fold(k) || ' %')) $function$;
--@@ 45 funcao conv_private.is_semantic_acceptance(p text, p_allow_cancel bool
CREATE OR REPLACE FUNCTION conv_private.is_semantic_acceptance(p text, p_allow_cancel boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare t text; w text; n integer := 0;
  blockers text[] := array['nao','nunca','jamais','cancela','cancelar','cancelei','desisto','desisti','outro','outra','outros','outras','troca','trocar',
    'muda','mudar','depois','talvez','ver','pensar','acho','mas','porem','ou','espera','aguarda','antes','so','apenas','tambem','alem','menos'];
begin
  if p is null or length(p) > 160 or position('?' in p) > 0 then return false; end if;
  t := conv_private.fold(p);
  t := regexp_replace(t, '[^a-z ]', ' ', 'g');
  for w in select x from regexp_split_to_table(btrim(t), '\s+') x where x <> '' loop
    n := n + 1;
    -- "cancela/cancelar" só barra quando a proposta NÃO é de cancelamento ("sim, pode cancelar" aceita um cancelamento).
    if w = any (blockers) and not (p_allow_cancel and w in ('cancela', 'cancelar')) then return false; end if;
  end loop;
  return n > 0;
end $function$;
--@@ 45 funcao conv_private.join_check(p_reservation uuid, p_profile uuid)
CREATE OR REPLACE FUNCTION conv_private.join_check(p_reservation uuid, p_profile uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.reservations%rowtype; v_p public.profiles%rowtype; v_game jsonb;
begin
  select * into r from public.reservations where id = p_reservation;
  if not found or r.status::text <> 'active' then return conv_private.vfail('RESERVATION_NOT_FOUND', 'Essa reserva não está mais ativa.'); end if;
  if r.type <> 'Play' then return conv_private.vfail('NOT_JOINABLE', 'Só dá para entrar em jogos de Play.'); end if;
  if r.date < conv_private.today() or (r.date = conv_private.today()
      and (case when r.end_time = time '00:00' then time '23:59:59' else r.end_time end) <= (now() at time zone 'America/Fortaleza')::time) then
    return conv_private.vfail('IN_PAST', 'Esse jogo já terminou.');
  end if;
  select * into v_p from public.profiles where id = p_profile;
  if not found or coalesce(v_p.is_active, true) = false or v_p.role::text not in ('socio', 'admin') then
    return conv_private.vfail('REQUESTER_NOT_MEMBER', 'Só sócios ativos entram em jogos por aqui.');
  end if;
  if p_profile = r.creator_id or p_profile = any (coalesce(r.participant_ids, '{}')) then
    return conv_private.vfail('ALREADY_IN', 'Você já está nesse jogo.');
  end if;
  v_game := conv_private.game_summary(r.id);
  if (v_game->>'participants')::int >= 8 then return conv_private.vfail('GAME_FULL', 'Esse jogo já tem 8 participantes.'); end if;
  return jsonb_build_object('ok', true, 'game', v_game);
end $function$;
--@@ 45 funcao conv_private.join_party_check(p_reservation uuid, p_profile uui
CREATE OR REPLACE FUNCTION conv_private.join_party_check(p_reservation uuid, p_profile uuid, p_extra uuid[], p_guest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.reservations%rowtype; v_base jsonb; v_game jsonb; v_in uuid[]; v_new uuid[]; v_names jsonb; v_adding integer;
  v_guest text := nullif(trim(coalesce(p_guest, '')), '');
begin
  -- Regras do solicitante: Play ativo, ainda não terminou, sócio ativo, ainda não está, jogo não lotado.
  v_base := conv_private.join_check(p_reservation, p_profile);
  if not (v_base->>'ok')::boolean then return v_base; end if;
  v_game := v_base->'game';
  select * into r from public.reservations where id = p_reservation;
  v_in := array_cat(array[r.creator_id], coalesce(r.participant_ids, '{}'));
  select coalesce(array_agg(distinct x), '{}') into v_new from unnest(coalesce(p_extra, '{}')) x where x <> p_profile and not (x = any (v_in));
  if (select count(*) from public.profiles p where p.id = any (v_new) and coalesce(p.is_active, true) and p.role::text in ('socio', 'admin')) <> cardinality(v_new) then
    return conv_private.vfail('PARTICIPANT_NOT_MEMBER', 'Algum participante não está ativo como sócio.');
  end if;
  if v_guest is not null then
    if length(v_guest) not between 2 and 80 then return conv_private.vfail('INVALID_GUEST', 'Informe o nome do convidado.'); end if;
    if nullif(trim(coalesce(r.guest_name, '')), '') is not null then return conv_private.vfail('GUEST_ALREADY', 'Esse jogo já tem um convidado.'); end if;
  end if;
  v_adding := 1 + cardinality(v_new) + case when v_guest is null then 0 else 1 end;
  if (v_game->>'participants')::int + v_adding > 8 then
    return jsonb_build_object('ok', false, 'code', 'NOT_ENOUGH_SPOTS', 'message', 'Não há vagas suficientes neste jogo.',
      'spots_left', (v_game->>'spots_left')::int, 'wanted', v_adding, 'game', v_game);
  end if;
  select coalesce(jsonb_agg(p.name::text order by array_position(v_new, p.id)), '[]'::jsonb) into v_names from public.profiles p where p.id = any (v_new);
  if v_guest is not null then v_names := v_names || to_jsonb(v_guest || ' (convidado)'); end if;
  return jsonb_build_object('ok', true, 'game', v_game || jsonb_build_object(
    'add_ids', to_jsonb(array[p_profile] || v_new), 'add_names', v_names, 'guest_name', v_guest, 'adding', v_adding));
end $function$;
--@@ 45 funcao conv_private.link_contact(p_contact uuid)
CREATE OR REPLACE FUNCTION conv_private.link_contact(p_contact uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.conv_contacts%rowtype; v_key text; v_profiles uuid[]; v_students uuid[];
begin
  select * into c from public.conv_contacts where id = p_contact for update;
  if not found or c.link_status in ('manual', 'linked') or c.phone is null then return; end if;
  v_key := conv_private.phone_key(c.phone);
  if v_key is null then return; end if;
  select coalesce(array_agg(p.id), '{}') into v_profiles from public.profiles p
    where p.phone is not null and conv_private.phone_key(p.phone) = v_key;
  if cardinality(v_profiles) = 1 then
    update public.conv_contacts set profile_id = v_profiles[1], non_socio_student_id = null, link_status = 'linked', updated_at = now() where id = p_contact;
  elsif cardinality(v_profiles) > 1 then
    update public.conv_contacts set link_status = 'ambiguous', updated_at = now() where id = p_contact;
  else
    select coalesce(array_agg(s.id), '{}') into v_students from public.non_socio_students s
      where s.phone is not null and conv_private.phone_key(s.phone) = v_key;
    if cardinality(v_students) = 1 then
      update public.conv_contacts set non_socio_student_id = v_students[1], link_status = 'linked', updated_at = now() where id = p_contact;
    elsif cardinality(v_students) > 1 then
      update public.conv_contacts set link_status = 'ambiguous', updated_at = now() where id = p_contact;
    end if;
  end if;
end $function$;
--@@ 45 funcao conv_private.log_webhook(p_event text, p_outcome text, p_detail
CREATE OR REPLACE FUNCTION conv_private.log_webhook(p_event text, p_outcome text, p_detail text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id bigint;
begin
  insert into public.conv_webhook_log(event, outcome, detail) values (left(p_event, 60), left(p_outcome, 60), left(p_detail, 200))
  returning id into v_id;
  if v_id % 50 = 0 then delete from public.conv_webhook_log where at < now() - interval '7 days'; end if;
end $function$;
--@@ 45 funcao conv_private.mark_read_collect(p_conversation uuid)
CREATE OR REPLACE FUNCTION conv_private.mark_read_collect(p_conversation uuid)
 RETURNS TABLE(destination text, provider_ids text[], is_group boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_since timestamptz;
begin
  select staff_read_at into v_since from public.conv_conversations where id = p_conversation for update;
  if not found then raise exception 'CONVERSATION_NOT_FOUND'; end if;
  update public.conv_conversations set staff_read_at = now() where id = p_conversation;
  return query
    select coalesce(c.phone, g.group_jid),
      coalesce(array(select m.provider_message_id from public.conv_messages m
        where m.conversation_id = p_conversation and m.direction = 'inbound' and m.provider_message_id is not null
          and m.created_at > coalesce(v_since, '-infinity'::timestamptz) order by m.created_at desc limit 100), '{}'),
      cv.kind = 'group'
    from public.conv_conversations cv left join public.conv_contacts c on c.id = cv.contact_id
    left join public.conv_groups g on g.id = cv.group_id where cv.id = p_conversation;
end $function$;
--@@ 45 funcao conv_private.mark_unread(p_conversation uuid)
CREATE OR REPLACE FUNCTION conv_private.mark_unread(p_conversation uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_last timestamptz;
begin
  select max(created_at) into v_last from public.conv_messages where conversation_id = p_conversation and direction = 'inbound';
  if v_last is null then raise exception 'NOTHING_TO_UNREAD'; end if;
  update public.conv_conversations set staff_read_at = v_last - interval '1 millisecond' where id = p_conversation;
end $function$;
--@@ 45 funcao conv_private.member_pendency_subject(p_profile uuid, p_as_of da
CREATE OR REPLACE FUNCTION conv_private.member_pendency_subject(p_profile uuid, p_as_of date, p_include_future boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
with rows as (
  select r.*, c.description, c.pendency_kind, c.guest_name, c.guest_date
  from fin_private.charge_rows(p_profile, null, '{}'::jsonb, p_as_of, 1000, 0) r
  join public.fin_member_charges c on c.id=r.charge_id
  where c.charge_type='member_pendency'
    and c.collection_enabled
    and r.stored_status in ('open','partial')
    and not r.in_review
    and (p_include_future or r.due_date <= p_as_of)
    and r.total_due_cents > 0
), agg as (
  select
    array_agg(charge_id order by (due_date >= p_as_of), due_date, charge_id) ids,
    sum(total_due_cents)::bigint total,
    sum(principal_remaining_cents)::bigint principal,
    sum(fees_due_cents)::bigint fees,
    min(due_date) due,
    max(days_late) late,
    bool_and(fees_configured) fees_ok,
    string_agg(
      '• ' || description
      || case when guest_name is not null then ' — ' || guest_name else '' end
      || case when guest_date is not null then ' (' || conv_private.date_br(guest_date) || ')' else '' end
      || ' — ' || conv_private.brl(total_due_cents)
      || ' — vence ' || conv_private.date_br(due_date),
      E'\n' order by (due_date >= p_as_of), due_date, charge_id
    ) items,
    count(*)::integer qty,
    array_agg(distinct competence_month order by competence_month) comps
  from rows
)
select case when coalesce(a.qty,0)=0 then null else
  jsonb_build_object(
    'charge_ids',to_jsonb(a.ids),
    'total_cents',a.total,
    'principal_cents',a.principal,
    'fees_cents',a.fees,
    'fees_configured',a.fees_ok,
    'due_date',a.due,
    'days_late',a.late,
    'competence_label',(select string_agg(conv_private.month_pt(x),' e ' order by x) from unnest(a.comps) x),
    'items_text',a.items,
    'item_count',a.qty,
    'pix_key',(select pix_key from public.fin_settings where id),
    'include_future',p_include_future
  ) end
from agg a
$function$;
--@@ 45 funcao conv_private.merge_contacts(p_keep uuid, p_drop uuid)
CREATE OR REPLACE FUNCTION conv_private.merge_contacts(p_keep uuid, p_drop uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  k public.conv_contacts%rowtype; d public.conv_contacts%rowtype; dc record; v_open uuid;
  v_profile uuid; v_student uuid; v_num constant text := '^[0-9+ ()-]+$';
begin
  if p_keep is null or p_drop is null or p_keep = p_drop then return p_keep; end if;
  perform 1 from public.conv_contacts where id in (p_keep, p_drop) order by id for update;
  select * into k from public.conv_contacts where id = p_keep;
  select * into d from public.conv_contacts where id = p_drop;
  if k.id is null or d.id is null or k.merged_into is not null or d.merged_into is not null then return p_keep; end if;

  -- 1. O absorvido solta telefone/LID/cadastro (índices únicos) e passa a apontar para o mantido.
  update public.conv_contacts set merged_into = p_keep, phone = null, lid = null,
    profile_id = null, non_socio_student_id = null, link_status = 'none', updated_at = now()
  where id = p_drop;
  update public.conv_contacts set merged_into = p_keep where merged_into = p_drop;

  -- 2. O mantido herda o que faltava.
  v_profile := coalesce(k.profile_id, d.profile_id);
  v_student := case when v_profile is null then coalesce(k.non_socio_student_id, d.non_socio_student_id) end;
  update public.conv_contacts set
    phone = coalesce(phone, d.phone), lid = coalesce(lid, d.lid),
    name = case when (name is null or name ~ v_num) and d.name is not null and d.name !~ v_num then d.name else name end,
    avatar_url = coalesce(avatar_url, d.avatar_url), avatar_checked_at = coalesce(avatar_checked_at, d.avatar_checked_at),
    profile_id = v_profile, non_socio_student_id = v_student,
    link_status = case when 'manual' in (k.link_status, d.link_status) then 'manual'
                       when v_profile is not null or v_student is not null then 'linked'
                       when 'ambiguous' in (k.link_status, d.link_status) then 'ambiguous' else 'none' end,
    opt_out = k.opt_out or d.opt_out, opt_out_at = coalesce(k.opt_out_at, d.opt_out_at), updated_at = now()
  where id = p_keep;

  -- 3. Histórico: quem falou, conversas, sessões, propostas, automações.
  update public.conv_messages set sender_contact_id = p_keep where sender_contact_id = p_drop;
  select id into v_open from public.conv_conversations
    where contact_id = p_keep and kind = 'direct' and status = 'open' and merged_into is null;
  for dc in select id, status from public.conv_conversations where contact_id = p_drop and kind = 'direct' order by created_at loop
    if dc.status = 'open' and v_open is not null then
      perform conv_private.fold_conversation(v_open, dc.id);
      update public.conv_conversations set contact_id = p_keep where id = dc.id;
    else
      update public.conv_conversations set contact_id = p_keep where id = dc.id;
      if dc.status = 'open' then v_open := dc.id; end if;
    end if;
  end loop;
  update public.conv_ai_sessions s set status = 'expired'
    where s.requester_contact_id = p_drop and s.status = 'open'
      and exists (select 1 from public.conv_ai_sessions x
                  where x.conversation_id = s.conversation_id and x.requester_contact_id = p_keep and x.status = 'open');
  update public.conv_ai_sessions set requester_contact_id = p_keep where requester_contact_id = p_drop;
  update public.conv_booking_proposals set requester_contact_id = p_keep where requester_contact_id = p_drop;
  update public.conv_booking_proposals set confirmed_by_contact_id = p_keep where confirmed_by_contact_id = p_drop;
  update public.conv_automation_recipients set contact_id = p_keep where contact_id = p_drop;

  -- Só ids: nunca telefone, nome ou conteúdo.
  perform conv_private.audit('contact_merge', 'conv_contacts', p_keep::text, jsonb_build_object('merged', p_drop),
    jsonb_build_object('kept', p_keep), jsonb_build_object('actor', 'system'));
  return p_keep;
end $function$;
--@@ 45 funcao conv_private.message_target(p_message uuid)
CREATE OR REPLACE FUNCTION conv_private.message_target(p_message uuid)
 RETURNS TABLE(provider_message_id text, destination text, direction text, created_at timestamp with time zone, conversation_id uuid, is_group boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select m.provider_message_id, coalesce(c.phone, g.group_jid), m.direction, m.created_at, m.conversation_id, cv.kind = 'group'
  from public.conv_messages m join public.conv_conversations cv on cv.id = m.conversation_id
  left join public.conv_contacts c on c.id = cv.contact_id left join public.conv_groups g on g.id = cv.group_id
  where m.id = p_message;
$function$;
--@@ 45 funcao conv_private.min_to_hhmm(p integer)
CREATE OR REPLACE FUNCTION conv_private.min_to_hhmm(p integer)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select lpad((p / 60)::text, 2, '0') || ':' || lpad((p % 60)::text, 2, '0') $function$;
--@@ 45 funcao conv_private.month_pt(p_date date)
CREATE OR REPLACE FUNCTION conv_private.month_pt(p_date date)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select (array['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'])[extract(month from p_date)::int]
    || '/' || extract(year from p_date)::int $function$;
--@@ 45 funcao conv_private.no_delete()
CREATE OR REPLACE FUNCTION conv_private.no_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  raise exception 'CONV_NO_DELETE: % não é apagado; arquive ou encerre.', tg_table_name using errcode = '42501';
end $function$;
--@@ 45 funcao conv_private.norm_lid(p text)
CREATE OR REPLACE FUNCTION conv_private.norm_lid(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select nullif(lower(regexp_replace(split_part(split_part(coalesce(p, ''), '@', 1), ':', 1), '[^0-9a-zA-Z._-]', '', 'g')), '') $function$;
--@@ 45 funcao conv_private.older_of(a uuid, b uuid)
CREATE OR REPLACE FUNCTION conv_private.older_of(a uuid, b uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select id from public.conv_contacts where id in (a, b) order by created_at, id limit 1 $function$;
--@@ 45 funcao conv_private.on_inbound_opt_out()
CREATE OR REPLACE FUNCTION conv_private.on_inbound_opt_out()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_contact uuid;
begin
  if new.direction <> 'inbound' or new.kind <> 'text' or new.sender_contact_id is null then return new; end if;
  if not exists (select 1 from public.conv_conversations c where c.id = new.conversation_id and c.kind = 'direct') then return new; end if;
  if not conv_private.is_opt_out(new.body) then return new; end if;
  v_contact := new.sender_contact_id;
  update public.conv_contacts set opt_out = true, opt_out_at = now(), updated_at = now() where id = v_contact and not opt_out;
  if found then
    update public.conv_automation_recipients set status = 'canceled', skip_reason = 'OPT_OUT'
      where contact_id = v_contact and status in ('pending', 'review');
    perform conv_private.audit('opt_out', 'conv_contacts', v_contact::text, null, jsonb_build_object('opt_out', true),
      jsonb_build_object('actor', 'system', 'via', 'inbound_message'));
  end if;
  return new;
end $function$;
--@@ 45 funcao conv_private.open_direct(p_contact uuid)
CREATE OR REPLACE FUNCTION conv_private.open_direct(p_contact uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
  select id into v_id from public.conv_conversations where contact_id = p_contact and kind = 'direct' and status = 'open' for update;
  if found then return v_id; end if;
  insert into public.conv_conversations(kind, contact_id, last_message_at) values ('direct', p_contact, now())
  on conflict (contact_id) where status = 'open' and kind = 'direct' do nothing returning id into v_id;
  if v_id is null then
    select id into v_id from public.conv_conversations where contact_id = p_contact and kind = 'direct' and status = 'open';
  end if;
  return v_id;
end $function$;
--@@ 45 funcao conv_private.open_group(p_group uuid)
CREATE OR REPLACE FUNCTION conv_private.open_group(p_group uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
  select id into v_id from public.conv_conversations where group_id = p_group and kind = 'group' and status = 'open' for update;
  if found then return v_id; end if;
  insert into public.conv_conversations(kind, group_id, last_message_at, ai_status) values ('group', p_group, now(), 'ai')
  on conflict (group_id) where status = 'open' and kind = 'group' do nothing returning id into v_id;
  if v_id is null then
    select id into v_id from public.conv_conversations where group_id = p_group and kind = 'group' and status = 'open';
  end if;
  return v_id;
end $function$;
--@@ 45 funcao conv_private.participants_check(p_reservation uuid, p_profile u
CREATE OR REPLACE FUNCTION conv_private.participants_check(p_reservation uuid, p_profile uuid, p_add uuid[], p_remove uuid[], p_add_guest text, p_remove_guest boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.reservations%rowtype; v_p public.profiles%rowtype; v_admin boolean; v_in uuid[]; v_add uuid[]; v_rem uuid[]; v_all uuid[]; v_after uuid[];
  v_now timestamp := now() at time zone 'America/Fortaleza'; v_guest_old text; v_guest_new text; v_n integer; v_self_only boolean; v_cancel boolean;
  v_game jsonb; v_names jsonb; v_add_names jsonb; v_rem_names jsonb;
begin
  select * into r from public.reservations where id = p_reservation;
  if not found or r.status::text <> 'active' then return conv_private.vfail('RESERVATION_NOT_FOUND', 'Essa reserva não está mais ativa.'); end if;
  if r.type <> 'Play' then return conv_private.vfail('NOT_PLAY', 'Só dá para mexer nos atletas de reservas de Play.'); end if;
  select * into v_p from public.profiles where id = p_profile;
  if not found or coalesce(v_p.is_active, true) = false or v_p.role::text not in ('socio', 'admin') then
    return conv_private.vfail('REQUESTER_NOT_MEMBER', 'Só sócios ativos mexem nos atletas por aqui.');
  end if;
  v_admin := v_p.role::text = 'admin';
  v_in := array_cat(array[r.creator_id], coalesce(r.participant_ids, '{}'));
  select coalesce(array_agg(distinct x), '{}') into v_add from unnest(coalesce(p_add, '{}')) x where not (x = any (v_in));
  select coalesce(array_agg(distinct x), '{}') into v_rem from unnest(coalesce(p_remove, '{}')) x;
  v_guest_old := nullif(trim(coalesce(r.guest_name, '')), '');
  if cardinality(v_add) + cardinality(v_rem) = 0 and nullif(trim(coalesce(p_add_guest, '')), '') is null and not coalesce(p_remove_guest, false) then
    return conv_private.vfail('NOTHING_TO_DO', 'Não há nada para alterar nessa reserva.');
  end if;
  if exists (select 1 from unnest(v_rem) x where not (x = any (v_in))) then
    return conv_private.vfail('NOT_IN_RESERVATION', 'Essa pessoa não está nessa reserva.');
  end if;
  if (select count(*) from public.profiles q where q.id = any (v_add) and coalesce(q.is_active, true) and q.role::text in ('socio', 'admin')) <> cardinality(v_add) then
    return conv_private.vfail('PARTICIPANT_NOT_MEMBER', 'Algum participante não está ativo como sócio.');
  end if;
  if (r.date + (case when r.end_time = time '00:00' then time '23:59:59' else r.end_time end)) <= v_now then
    return conv_private.vfail('IN_PAST', 'Esse jogo já terminou.');
  end if;
  v_self_only := cardinality(v_add) = 0 and nullif(trim(coalesce(p_add_guest, '')), '') is null and not coalesce(p_remove_guest, false) and v_rem = array[p_profile];
  if (r.date + r.start_time) <= v_now and not v_self_only then
    return conv_private.vfail('RESERVATION_STARTED', 'Esse jogo já começou: agora só dá para sair dele.');
  end if;
  if r.creator_id = any (v_rem) and r.creator_id <> p_profile and not v_admin then
    return conv_private.vfail('CREATOR_PROTECTED', 'Só o criador da reserva ou um administrador pode retirar o criador.');
  end if;
  -- convidado: a reserva guarda um só
  v_guest_new := v_guest_old;
  if coalesce(p_remove_guest, false) then v_guest_new := null; end if;
  if nullif(trim(coalesce(p_add_guest, '')), '') is not null then
    if length(trim(p_add_guest)) not between 2 and 80 then return conv_private.vfail('INVALID_GUEST', 'Informe o nome do convidado.'); end if;
    if v_guest_new is not null then return conv_private.vfail('GUEST_ALREADY', 'Esse jogo já tem um convidado.'); end if;
    v_guest_new := trim(p_add_guest);
  end if;
  -- quem fica
  select coalesce(array_agg(x order by o), '{}') into v_all from (
    select x, min(o) o from unnest(v_in || v_add) with ordinality t(x, o) where x is not null group by x) a;
  select coalesce(array_agg(x order by o), '{}') into v_after from unnest(v_all) with ordinality t(x, o) where not (x = any (v_rem));
  v_n := cardinality(v_after) + case when v_guest_new is null then 0 else 1 end;
  if v_n > 8 then
    return jsonb_build_object('ok', false, 'code', 'NOT_ENOUGH_SPOTS', 'message', 'Não há vagas suficientes neste jogo.',
      'spots_left', greatest(8 - (cardinality(array(select distinct x from unnest(v_in) x where x is not null)) + case when v_guest_old is null then 0 else 1 end), 0),
      'wanted', cardinality(v_add) + case when nullif(trim(coalesce(p_add_guest, '')), '') is null then 0 else 1 end);
  end if;
  v_cancel := cardinality(v_after) = 0 and v_guest_new is null;
  v_game := conv_private.game_summary(r.id);
  select coalesce(jsonb_agg(q.name::text order by array_position(v_after, q.id)), '[]'::jsonb) into v_names from public.profiles q where q.id = any (v_after);
  if v_guest_new is not null then v_names := v_names || to_jsonb(v_guest_new || ' (convidado)'); end if;
  select coalesce(jsonb_agg(q.name::text order by array_position(v_add, q.id)), '[]'::jsonb) into v_add_names from public.profiles q where q.id = any (v_add);
  select coalesce(jsonb_agg(q.name::text order by array_position(v_rem, q.id)), '[]'::jsonb) into v_rem_names from public.profiles q where q.id = any (v_rem);
  return jsonb_build_object('ok', true, 'change', v_game || jsonb_build_object(
    'reservation_id', r.id, 'add_ids', to_jsonb(v_add), 'add_names', v_add_names, 'remove_ids', to_jsonb(v_rem), 'remove_names', v_rem_names,
    'add_guest', nullif(trim(coalesce(p_add_guest, '')), ''), 'remove_guest', coalesce(p_remove_guest, false), 'guest_after', v_guest_new,
    'after_names', v_names, 'cancel_all', v_cancel, 'self_leaving', p_profile = any (v_rem)));
end $function$;
--@@ 45 funcao conv_private.pendency_paid_subject(p_submission uuid)
CREATE OR REPLACE FUNCTION conv_private.pendency_paid_subject(p_submission uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
with s as (
  select r.id,r.profile_id,r.status,
    coalesce((select sum(p.amount_cents) from public.fin_charge_payments p where p.submission_id=r.id and p.kind='payment'),0)::bigint paid
  from public.fin_receipt_submissions r where r.id=p_submission
), bal as (
  select coalesce(sum(st.total_due),0)::bigint balance
  from s
  join public.fin_member_charges c on c.profile_id=s.profile_id and c.status in ('open','partial')
  cross join lateral fin_private.charge_statement(c.id,fin_private.today()) st
  where (c.charge_type='member_pendency' and c.collection_enabled)
     or (c.charge_type='membership' and (
          c.competence_month<=fin_private.today()
          or exists(select 1 from public.fin_receipt_charges rc where rc.submission_id=s.id and rc.charge_id=c.id)))
)
select case when s.status<>'approved' then null else jsonb_build_object(
  'submission_id',s.id,'paid_cents',s.paid,'balance_cents',bal.balance
) end
from s cross join bal
$function$;
--@@ 45 funcao conv_private.pendency_send_existing(p_profile uuid)
CREATE OR REPLACE FUNCTION conv_private.pendency_send_existing(p_profile uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object('id', r.id, 'status', r.status, 'sent_at', r.sent_at,
    'hhmm', to_char(coalesce(r.sent_at, r.due_at) at time zone 'America/Fortaleza', 'HH24:MI'))
  from public.conv_automation_recipients r
  join public.conv_automations a on a.id = r.automation_id and a.source = 'finance_charge' and a.definition->>'stage' = 'member_pendency'
  where r.profile_id = p_profile
    and (r.status in ('pending', 'review', 'processing') or (r.status = 'sent' and r.sent_at > now() - interval '30 minutes'))
  order by coalesce(r.sent_at, r.due_at) desc
  limit 1
$function$;
--@@ 45 funcao conv_private.phone_e164(p text)
CREATE OR REPLACE FUNCTION conv_private.phone_e164(p text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare d text := conv_private.digits(p);
begin
  if length(d) in (10, 11) then d := '55' || d; end if;
  if d ~ '^[1-9][0-9]{9,14}$' then return d; end if;
  return null;
end $function$;
--@@ 45 funcao conv_private.phone_key(p text)
CREATE OR REPLACE FUNCTION conv_private.phone_key(p text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare l text := conv_private.phone_local(p);
begin
  if l is null or length(l) < 10 then return null; end if;
  return substr(l, 1, 2) || right(l, 8);
end $function$;
--@@ 45 funcao conv_private.phone_local(p text)
CREATE OR REPLACE FUNCTION conv_private.phone_local(p text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare d text := conv_private.digits(p);
begin
  if d like '55%' and length(d) >= 12 then d := substr(d, 3); end if;
  if length(d) > 11 then d := right(d, 11); end if;
  return nullif(d, '');
end $function$;
--@@ 45 funcao conv_private.queue_member_pendency_now(p_profile uuid, p_charge
CREATE OR REPLACE FUNCTION conv_private.queue_member_pendency_now(p_profile uuid, p_charge uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  a public.conv_automations%rowtype;
  v_run uuid;
  v_rec uuid;
  v_subject jsonb;
  v_name text;
  v_phone text;
  v_existing jsonb;
  v_at timestamptz:=clock_timestamp();
begin
  select * into a from public.conv_automations
  where source='finance_charge' and definition->>'stage'='member_pendency' and status='active'
  order by created_at limit 1;
  if not found then return null; end if;

  -- Duas chamadas simultâneas para o mesmo sócio esperam uma pela outra e a segunda enxerga a primeira.
  perform pg_advisory_xact_lock(hashtextextended('pendency_send:'||p_profile::text,7));
  v_existing:=conv_private.pendency_send_existing(p_profile);
  if v_existing is not null then return (v_existing->>'id')::uuid; end if;

  v_subject:=conv_private.member_pendency_subject(p_profile,conv_private.today(),true);
  if v_subject is null then return null; end if;
  select name,phone::text into v_name,v_phone from public.profiles where id=p_profile;
  if v_name is null then return null; end if;

  insert into public.conv_automation_runs(automation_id,version,kind,planned_for,status,created_at)
  values(a.id,a.version,'manual',v_at,'running',v_at)
  returning id into v_run;

  insert into public.conv_automation_recipients(
    run_id,automation_id,purpose_key,dedupe_key,profile_id,phone,display_name,subject,status,due_at
  ) values(
    v_run,a.id,conv_private.automation_purpose(a),
    'fin:member_pendency:manual:'||v_run::text,
    p_profile,conv_private.phone_e164(v_phone),v_name,
    v_subject||jsonb_build_object('scope','manual'),'pending',v_at
  )
  returning id into v_rec;

  return v_rec;
end $function$;
--@@ 45 funcao conv_private.queue_message(p_conversation uuid, p jsonb, p_auth
CREATE OR REPLACE FUNCTION conv_private.queue_message(p_conversation uuid, p jsonb, p_author uuid, p_key uuid, p_origin text DEFAULT 'staff'::text, p_session uuid DEFAULT NULL::uuid, p_recipient uuid DEFAULT NULL::uuid)
 RETURNS TABLE(message_id uuid, destination text, already_sent boolean, reply_provider_id text, is_group boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_kind text := coalesce(nullif(p->>'kind', ''), 'text'); v_body text := nullif(p->>'body', '');
  v_existing public.conv_messages%rowtype; v_conv public.conv_conversations%rowtype;
  v_reply uuid := nullif(p->>'reply_to_message_id', '')::uuid; v_reply_provider text; v_preview text;
  v_dest text; v_group boolean; v_id uuid;
begin
  if p_key is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED'; end if;
  if p_origin not in ('staff', 'ai', 'automation', 'system') then raise exception 'INVALID_ORIGIN'; end if;
  if v_kind not in ('text','image','video','audio','ptt','document') then raise exception 'INVALID_KIND'; end if;
  if v_kind = 'text' and (v_body is null or length(trim(v_body)) = 0) then raise exception 'BODY_REQUIRED'; end if;
  if v_body is not null and length(v_body) > 4096 then raise exception 'BODY_TOO_LONG'; end if;
  if v_kind <> 'text' and nullif(p->>'media_path', '') is null then raise exception 'MEDIA_REQUIRED'; end if;
  if v_kind <> 'text' and (p->>'media_path') !~ '^(in|out)/[0-9a-f-]{36}/[A-Za-z0-9._-]{1,120}$' then raise exception 'INVALID_MEDIA_PATH'; end if;

  select * into v_existing from public.conv_messages where request_id = p_key;
  if found then
    if v_existing.conversation_id <> p_conversation then raise exception 'IDEMPOTENCY_KEY_REUSED'; end if;
    select coalesce(c.phone, g.group_jid), cv.kind = 'group' into v_dest, v_group
      from public.conv_conversations cv left join public.conv_contacts c on c.id = cv.contact_id
      left join public.conv_groups g on g.id = cv.group_id where cv.id = p_conversation;
    return query select v_existing.id, v_dest, v_existing.status in ('sent','delivered','read'), v_existing.reply_to_provider_id, v_group;
    return;
  end if;

  select * into v_conv from public.conv_conversations where id = p_conversation for update;
  if not found then raise exception 'CONVERSATION_NOT_FOUND'; end if;
  if v_conv.kind = 'direct' then
    select c.phone into v_dest from public.conv_contacts c where c.id = v_conv.contact_id;
    if v_dest is null then raise exception 'CONTACT_WITHOUT_PHONE'; end if;
    v_group := false;
  else
    select g.group_jid into v_dest from public.conv_groups g where g.id = v_conv.group_id;
    v_group := true;
  end if;

  -- Responder reabre: a conversa encerrada volta para a caixa.
  if v_conv.status = 'closed' then
    if exists (select 1 from public.conv_conversations o where o.status = 'open' and o.id <> v_conv.id and o.kind = v_conv.kind
               and ((v_conv.kind = 'direct' and o.contact_id = v_conv.contact_id) or (v_conv.kind = 'group' and o.group_id = v_conv.group_id))) then
      raise exception 'CONVERSATION_SUPERSEDED';
    end if;
    update public.conv_conversations set status = 'open' where id = v_conv.id;
  end if;

  if v_reply is not null then
    select provider_message_id, left(coalesce(body, ''), 200) into v_reply_provider, v_preview
      from public.conv_messages where id = v_reply and conversation_id = p_conversation;
  end if;

  insert into public.conv_messages(conversation_id, direction, origin, author_id, kind, body, status, request_id,
    media_path, media_mime, media_name, reply_to_provider_id, reply_preview, ai_session_id, automation_recipient_id)
  values (p_conversation, 'outbound', p_origin, p_author, v_kind, v_body, 'queued', p_key,
    nullif(p->>'media_path', ''), nullif(p->>'mime', ''), left(nullif(p->>'file_name', ''), 120), v_reply_provider, v_preview, p_session, p_recipient)
  returning id into v_id;
  return query select v_id, v_dest, false, v_reply_provider, v_group;
end $function$;
--@@ 45 funcao conv_private.queue_pendency_paid_notice(p_profile uuid, p_submi
CREATE OR REPLACE FUNCTION conv_private.queue_pendency_paid_notice(p_profile uuid, p_submission uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  a public.conv_automations%rowtype;
  v_run uuid;
  v_rec uuid;
  v_subject jsonb;
  v_name text;
  v_phone text;
  v_at timestamptz:=clock_timestamp();
begin
  select * into a from public.conv_automations
  where source='finance_charge' and definition->>'stage'='member_pendency_paid' and status='active'
  order by created_at limit 1;
  if not found then return null; end if;
  v_subject:=conv_private.pendency_paid_subject(p_submission);
  if v_subject is null then return null; end if;
  select name,phone::text into v_name,v_phone from public.profiles where id=p_profile;
  if v_name is null then return null; end if;

  insert into public.conv_automation_runs(automation_id,version,kind,planned_for,status,created_at)
  values(a.id,a.version,'manual',v_at,'running',v_at) returning id into v_run;

  insert into public.conv_automation_recipients(
    run_id,automation_id,purpose_key,dedupe_key,profile_id,phone,display_name,subject,status,due_at
  ) values(
    v_run,a.id,conv_private.automation_purpose(a),
    'fin:member_pendency:paid:'||p_submission::text,
    p_profile,conv_private.phone_e164(v_phone),v_name,v_subject,'pending',v_at
  )
  on conflict (purpose_key,dedupe_key) where status<>'canceled' do nothing
  returning id into v_rec;

  if v_rec is null then update public.conv_automation_runs set status='done',finished_at=clock_timestamp() where id=v_run; end if;
  return v_rec;
end $function$;
--@@ 45 funcao conv_private.queue_pendency_receipt_review_notice(p_profile uui
CREATE OR REPLACE FUNCTION conv_private.queue_pendency_receipt_review_notice(p_profile uuid, p_submission uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  a public.conv_automations%rowtype;
  v_run uuid;
  v_rec uuid;
  v_name text;
  v_phone text;
  v_at timestamptz:=clock_timestamp();
begin
  select * into a from public.conv_automations
  where source='finance_charge' and definition->>'stage'='member_pendency_receipt_review' and status='active'
  order by created_at limit 1;
  if not found then return null; end if;
  select name,phone::text into v_name,v_phone from public.profiles where id=p_profile;
  if v_name is null then return null; end if;

  insert into public.conv_automation_runs(automation_id,version,kind,planned_for,status,created_at)
  values(a.id,a.version,'manual',v_at,'running',v_at) returning id into v_run;

  insert into public.conv_automation_recipients(
    run_id,automation_id,purpose_key,dedupe_key,profile_id,phone,display_name,subject,status,due_at
  ) values(
    v_run,a.id,conv_private.automation_purpose(a),
    'fin:member_pendency:receipt_review:'||p_submission::text,
    p_profile,conv_private.phone_e164(v_phone),v_name,
    jsonb_build_object('submission_id',p_submission),'pending',v_at
  )
  on conflict (purpose_key,dedupe_key) where status<>'canceled' do nothing
  returning id into v_rec;

  if v_rec is null then update public.conv_automation_runs set status='done',finished_at=clock_timestamp() where id=v_run; end if;
  return v_rec;
end $function$;
--@@ 45 funcao conv_private.render_template(p_body text, p_ctx jsonb)
CREATE OR REPLACE FUNCTION conv_private.render_template(p_body text, p_ctx jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v text := coalesce(p_body, ''); k text;
begin
  foreach k in array conv_private.template_vars(p_body) loop
    if nullif(p_ctx->>k, '') is null then return null; end if;
    v := regexp_replace(v, '\{\{\s*' || k || '\s*\}\}', replace(replace(p_ctx->>k, '\', '\\'), '&', '\&'), 'g');
  end loop;
  return btrim(v, E' \t\r\n');
end $function$;
--@@ 45 funcao conv_private.require_admin()
CREATE OR REPLACE FUNCTION conv_private.require_admin()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not public.is_admin() then
    raise exception 'CONV_FORBIDDEN' using errcode = '42501';
  end if;
  return auth.uid();
end $function$;
--@@ 45 funcao conv_private.resolve_contact(p_phone text, p_lid text)
CREATE OR REPLACE FUNCTION conv_private.resolve_contact(p_phone text, p_lid text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_phone text := conv_private.phone_e164(p_phone); v_lid text := conv_private.norm_lid(p_lid);
  v_by_phone uuid; v_by_lid uuid; v_key text; v_ids uuid[]; v_cands uuid[]; v_id uuid;
begin
  if v_phone is not null then
    select id into v_by_phone from public.conv_contacts where phone = v_phone and merged_into is null;
  end if;
  if v_lid is not null then
    select id into v_by_lid from public.conv_contacts where lid = v_lid and merged_into is null;
  end if;
  -- Telefone e LID do MESMO evento apontando para dois contatos: é a mesma pessoa.
  if v_by_phone is not null and v_by_lid is not null and v_by_phone <> v_by_lid
     and conv_private.can_merge(v_by_phone, v_by_lid) then
    return conv_private.merge_contacts(conv_private.older_of(v_by_phone, v_by_lid),
      case when conv_private.older_of(v_by_phone, v_by_lid) = v_by_phone then v_by_lid else v_by_phone end);
  end if;
  if v_by_phone is not null then return v_by_phone; end if;
  if v_by_lid is not null then return v_by_lid; end if;

  v_key := conv_private.phone_key(v_phone);
  if v_key is null then return null; end if;

  -- Mesmo número (tolerando o nono dígito): só se houver um único candidato.
  select coalesce(array_agg(id), '{}') into v_ids from public.conv_contacts
    where merged_into is null and phone is not null and conv_private.phone_key(phone) = v_key
      and (v_lid is null or lid is null or lid = v_lid);
  if cardinality(v_ids) = 1 then return v_ids[1]; end if;
  if cardinality(v_ids) > 1 then
    select id into v_id from public.conv_contacts where id = any (v_ids) order by created_at, id limit 1;
    return v_id;
  end if;

  -- Contato já ligado ao cadastro que tem este telefone (cadastro único).
  select coalesce(array_agg(p.id), '{}') into v_cands from public.profiles p
    where p.phone is not null and conv_private.phone_key(p.phone) = v_key;
  if cardinality(v_cands) = 1 then
    select id into v_id from public.conv_contacts where profile_id = v_cands[1] and merged_into is null
      and (v_lid is null or lid is null or lid = v_lid) order by created_at, id limit 1;
    return v_id;
  elsif cardinality(v_cands) = 0 then
    select coalesce(array_agg(s.id), '{}') into v_cands from public.non_socio_students s
      where s.phone is not null and conv_private.phone_key(s.phone) = v_key;
    if cardinality(v_cands) = 1 then
      select id into v_id from public.conv_contacts where non_socio_student_id = v_cands[1] and merged_into is null
        and (v_lid is null or lid is null or lid = v_lid) order by created_at, id limit 1;
      return v_id;
    end if;
  end if;
  return null;
end $function$;
--@@ 45 funcao conv_private.resolve_undecryptable(p_provider_id text, p_body t
CREATE OR REPLACE FUNCTION conv_private.resolve_undecryptable(p_provider_id text, p_body text, p_kind text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  update public.conv_messages set body = left(p_body, 8192), kind = coalesce(nullif(p_kind, ''), kind)
  where provider_message_id = p_provider_id and body like '%[Undecryptable]%' and coalesce(p_body, '') <> '';
$function$;
--@@ 45 funcao conv_private.set_avatar(p_contact uuid, p_url text)
CREATE OR REPLACE FUNCTION conv_private.set_avatar(p_contact uuid, p_url text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  update public.conv_contacts set avatar_url = nullif(p_url, ''), avatar_checked_at = now() where id = p_contact;
$function$;
--@@ 45 funcao conv_private.set_message_media(p_provider_id text, p_path text,
CREATE OR REPLACE FUNCTION conv_private.set_message_media(p_provider_id text, p_path text, p_mime text)
 RETURNS uuid
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  update public.conv_messages set media_path = p_path, media_mime = coalesce(nullif(p_mime, ''), media_mime)
  where provider_message_id = p_provider_id returning id;
$function$;
--@@ 45 funcao conv_private.set_message_transcription(p_message uuid, p jsonb)
CREATE OR REPLACE FUNCTION conv_private.set_message_transcription(p_message uuid, p jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_status text := p->>'status';
  v jsonb;
begin
  if v_status is null or v_status not in ('ok', 'unclear', 'failed') then raise exception 'INVALID_TRANSCRIPTION'; end if;
  -- Só as chaves conhecidas, com tipos conferidos: o resto do payload é descartado.
  v := jsonb_strip_nulls(jsonb_build_object(
    'status', v_status,
    'text', case when v_status = 'ok' then left(nullif(btrim(p->>'text'), ''), 4000) end,
    'low_confidence', case when v_status = 'ok' and jsonb_typeof(p->'low_confidence') = 'boolean' then p->'low_confidence' end,
    'confidence', case when jsonb_typeof(p->'confidence') = 'number' then p->'confidence' end,
    'model', left(p->>'model', 60),
    'language', left(p->>'language', 20),
    'seconds', case when jsonb_typeof(p->'seconds') = 'number' then p->'seconds' end,
    'reason', left(p->>'reason', 60),
    'at', now()));
  if v_status = 'ok' and v->>'text' is null then
    v := v || '{"status":"unclear","reason":"sem_texto"}'::jsonb;
  end if;
  update public.conv_messages
     set meta = coalesce(meta, '{}'::jsonb) || jsonb_build_object('transcription', v)
   where id = p_message and kind in ('audio', 'ptt') and direction = 'inbound';
  return found;
end $function$;
--@@ 45 funcao conv_private.staff_delete_message(p_message uuid)
CREATE OR REPLACE FUNCTION conv_private.staff_delete_message(p_message uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  update public.conv_messages set deleted_at = now()
  where id = p_message and direction = 'outbound' and deleted_at is null and status in ('sent','delivered','read');
  if not found then raise exception 'MESSAGE_NOT_DELETABLE'; end if;
end $function$;
--@@ 45 funcao conv_private.staff_edit_message(p_message uuid, p_body text)
CREATE OR REPLACE FUNCTION conv_private.staff_edit_message(p_message uuid, p_body text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_body is null or length(trim(p_body)) = 0 then raise exception 'BODY_REQUIRED'; end if;
  update public.conv_messages set body = p_body, edited_at = now()
  where id = p_message and direction = 'outbound' and deleted_at is null and kind = 'text'
    and status in ('sent','delivered','read') and created_at > now() - interval '15 minutes';
  if not found then raise exception 'MESSAGE_NOT_EDITABLE'; end if;
end $function$;
--@@ 45 funcao conv_private.staff_react(p_message uuid, p_emoji text)
CREATE OR REPLACE FUNCTION conv_private.staff_react(p_message uuid, p_emoji text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  update public.conv_messages set reactions = case when coalesce(trim(p_emoji), '') = ''
    then reactions - 'staff' else reactions || jsonb_build_object('staff', left(trim(p_emoji), 16)) end
  where id = p_message;
$function$;
--@@ 45 funcao conv_private.template_vars(p_body text)
CREATE OR REPLACE FUNCTION conv_private.template_vars(p_body text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select coalesce(array_agg(distinct m[1]), '{}') from regexp_matches(coalesce(p_body, ''), '\{\{\s*([a-z_]+)\s*\}\}', 'g') m $function$;
--@@ 45 funcao conv_private.today()
CREATE OR REPLACE FUNCTION conv_private.today()
 RETURNS date
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select (now() at time zone 'America/Fortaleza')::date $function$;
--@@ 45 funcao conv_private.update_message_status(p_provider_id text, p_status
CREATE OR REPLACE FUNCTION conv_private.update_message_status(p_provider_id text, p_status text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  update public.conv_messages set status = p_status
  where provider_message_id = p_provider_id and direction = 'outbound' and p_status in ('delivered', 'read')
    and array_position(array['queued','sent','delivered','read'], status)
        < array_position(array['queued','sent','delivered','read'], p_status);
$function$;
--@@ 45 funcao conv_private.upsert_contact(p_phone text, p_lid text, p_name te
CREATE OR REPLACE FUNCTION conv_private.upsert_contact(p_phone text, p_lid text, p_name text, p_staff_sent boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_phone text := conv_private.phone_e164(p_phone); v_lid text := conv_private.norm_lid(p_lid);
  v_id uuid; v_name text := nullif(trim(coalesce(p_name, '')), '');
begin
  if v_phone is null and v_lid is null then raise exception 'INVALID_CONTACT'; end if;
  v_id := conv_private.resolve_contact(p_phone, p_lid);
  if v_id is null then
    insert into public.conv_contacts(phone, lid, name) values (v_phone, v_lid, case when p_staff_sent then null else v_name end)
    on conflict do nothing returning id into v_id;
    if v_id is null then
      select id into v_id from public.conv_contacts
        where merged_into is null and ((v_phone is not null and phone = v_phone) or (v_lid is not null and lid = v_lid)) limit 1;
    end if;
  else
    -- Completa o que faltava (telefone ou LID), sem tirar nada.
    begin
      update public.conv_contacts set
        phone = coalesce(phone, v_phone), lid = coalesce(lid, v_lid),
        name = case when p_staff_sent or v_name is null then name
                    when name is null or name ~ '^[0-9+ ()-]+$' then v_name else name end,
        updated_at = now()
      where id = v_id;
    exception when unique_violation then
      null; -- corrida: outro contato tomou este telefone/LID; a próxima mensagem se reconcilia
    end;
  end if;
  perform conv_private.link_contact(v_id);
  v_id := conv_private.dedupe_contact(v_id);
  -- O número que o provedor entrega numa mensagem recebida é o real (com ou sem nono dígito).
  if not p_staff_sent and v_phone is not null then
    begin
      update public.conv_contacts set phone = v_phone, updated_at = now() where id = v_id and phone is distinct from v_phone;
    exception when unique_violation then
      null;
    end;
  end if;
  return v_id;
end $function$;
--@@ 45 funcao conv_private.validate_reservation(p jsonb)
CREATE OR REPLACE FUNCTION conv_private.validate_reservation(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_type text := p->>'type'; v_date date; v_smin integer; v_dur integer; v_emin integer;
  v_court public.courts%rowtype; v_req public.profiles%rowtype;
  v_parts uuid[]; v_students uuid[]; v_guest text := nullif(trim(coalesce(p->>'guest_name', '')), '');
  v_prof uuid := nullif(p->>'professor_id', '')::uuid; v_ex uuid := nullif(p->>'exclude_reservation_id', '')::uuid;
  v_now timestamp := now() at time zone 'America/Fortaleza'; v_n integer; v_bad text; v_s record; v_socio_count integer;
  v_restrict boolean := false; v_student_status text;
begin
  select * into v_req from public.profiles where id = nullif(p->>'requester_profile_id', '')::uuid;
  if not found or coalesce(v_req.is_active, true) = false or v_req.role::text not in ('socio', 'admin') then
    return conv_private.vfail('REQUESTER_NOT_MEMBER', 'Só sócios ativos podem fazer reservas por aqui.');
  end if;
  if v_type not in ('Play', 'Aula') then return conv_private.vfail('INVALID_TYPE', 'Tipo de reserva inválido.'); end if;

  begin v_date := (p->>'date')::date; exception when others then return conv_private.vfail('INVALID_DATE', 'Data inválida.'); end;
  v_smin := conv_private.hhmm_to_min(p->>'start');
  begin v_dur := nullif(p->>'duration', '')::integer; exception when others then v_dur := null; end;
  if v_date is null then return conv_private.vfail('INVALID_DATE', 'Data inválida.'); end if;
  if v_smin is null or v_smin < 300 or v_smin > 1350 or v_smin % 30 <> 0 then
    return conv_private.vfail('INVALID_START', 'O horário de início precisa ser entre 05:00 e 22:30, de 30 em 30 minutos.');
  end if;
  if v_type = 'Play' and (v_dur is null or v_dur not in (60, 90, 120)) then return conv_private.vfail('INVALID_DURATION', 'Reserva de Play tem 60, 90 ou 120 minutos.'); end if;
  if v_type = 'Aula' and v_dur is distinct from 30 then return conv_private.vfail('INVALID_DURATION', 'Aula tem 30 minutos.'); end if;
  v_emin := v_smin + v_dur;
  if v_emin > 1380 then return conv_private.vfail('AFTER_CLOSING', 'A reserva terminaria depois das 23:00, quando o clube fecha.'); end if;
  if v_date < v_now::date or (v_date = v_now::date and v_smin <= extract(hour from v_now)::int * 60 + extract(minute from v_now)::int) then
    return conv_private.vfail('IN_PAST', 'Esse horário já passou.');
  end if;

  select * into v_court from public.courts where id = nullif(p->>'court_id', '')::uuid and coalesce(is_active, true);
  if not found then return conv_private.vfail('COURT_NOT_FOUND', 'Quadra não encontrada ou inativa.'); end if;
  if v_type = 'Aula' and conv_private.fold(v_court.type::text) not like 'r%pida' then
    return conv_private.vfail('AULA_ONLY_FAST_COURT', 'Aulas são permitidas apenas na Quadra Rápida.');
  end if;

  select coalesce(array_agg(distinct x::uuid), '{}') into v_parts from jsonb_array_elements_text(coalesce(p->'participant_ids', '[]'::jsonb)) x;
  select coalesce(array_agg(distinct x::uuid), '{}') into v_students from jsonb_array_elements_text(coalesce(p->'non_socio_student_ids', '[]'::jsonb)) x;

  if v_type = 'Play' then
    -- Quem pede participa (o app já começa com o usuário na lista).
    if not (v_req.id = any (v_parts)) then v_parts := v_parts || v_req.id; end if;
    if v_guest is not null and length(v_guest) not between 2 and 80 then return conv_private.vfail('INVALID_GUEST', 'Informe o nome do convidado.'); end if;
    v_n := cardinality(v_parts);
    if v_guest is not null then v_n := v_n + 1; end if;
    if v_n > 8 then
      return conv_private.vfail('TOO_MANY_PARTICIPANTS', 'Uma reserva tem no máximo 8 participantes.');
    end if;
    v_students := '{}';
  else
    v_guest := null;
    if v_req.role::text <> 'admin' and not exists (select 1 from public.professors pr where pr.user_id = v_req.id and coalesce(pr.is_active, true)) then
      return conv_private.vfail('NOT_ALLOWED_AULA', 'Só administrador ou professor marca aula.');
    end if;
    if v_req.role::text <> 'admin' then
      select pr.id into v_prof from public.professors pr where pr.user_id = v_req.id and coalesce(pr.is_active, true) limit 1;
    elsif v_prof is null or not exists (select 1 from public.professors pr where pr.id = v_prof and coalesce(pr.is_active, true)) then
      return conv_private.vfail('PROFESSOR_REQUIRED', 'Informe o professor da aula.');
    end if;
    if cardinality(v_parts) + cardinality(v_students) = 0 then return conv_private.vfail('STUDENT_REQUIRED', 'Informe ao menos um aluno.'); end if;
    if cardinality(v_parts) + cardinality(v_students) > 8 then return conv_private.vfail('TOO_MANY_PARTICIPANTS', 'Uma reserva tem no máximo 8 participantes.'); end if;
  end if;

  -- Sócios: cadastro ativo.
  select count(*) into v_n from public.profiles where id = any (v_parts) and coalesce(is_active, true) and role::text in ('socio', 'admin');
  if v_n <> cardinality(v_parts) then return conv_private.vfail('PARTICIPANT_NOT_MEMBER', 'Algum participante não é sócio ativo.'); end if;

  if v_type = 'Aula' then
    -- Aluno sócio pausado/encerrado bloqueia.
    select p2.name into v_bad from public.student_profiles sp join public.profiles p2 on p2.id = sp.profile_id
      where sp.profile_id = any (v_parts) and sp.student_status <> 'active' limit 1;
    if v_bad is not null then return conv_private.vfail('STUDENT_PAUSED', v_bad || ' está pausado. Reative o aluno antes de marcar a aula.'); end if;
    -- Não-sócios e dependentes.
    select count(*) into v_n from public.non_socio_students where id = any (v_students);
    if v_n <> cardinality(v_students) then return conv_private.vfail('STUDENT_NOT_FOUND', 'Aluno não encontrado.'); end if;
    for v_s in select s.* from public.non_socio_students s where s.id = any (v_students) loop
      select sp.student_status into v_student_status from public.student_profiles sp where sp.non_socio_student_id = v_s.id;
      v_student_status := coalesce(v_student_status, case when coalesce(v_s.is_active, true) then 'active' else 'paused' end);
      if v_student_status <> 'active' or coalesce(v_s.is_active, true) = false then
        return conv_private.vfail('STUDENT_PAUSED', v_s.name || ' está pausado. Reative o aluno antes de marcar a aula.');
      end if;
      if coalesce(v_s.student_type, 'regular') = 'dependent' then continue; end if;
      -- A conversão do Day Card Experimental na 2ª aula é regra do app: não replicamos aqui.
      if v_s.plan_type = 'Day Card Experimental' then
        return conv_private.vfail('NEEDS_HUMAN', v_s.name || ' tem Day Card Experimental; a equipe precisa conferir antes.');
      end if;
      if coalesce(v_s.plan_status, 'inactive') <> 'active' then
        return conv_private.vfail('CARD_INVALID', v_s.name || ' está sem pagamento válido do clube para esta aula.');
      end if;
      if v_s.plan_type = 'Card Mensal' and (v_s.master_expiration_date is null or v_s.master_expiration_date < v_date) then
        return conv_private.vfail('CARD_INVALID', 'O Card Mensal de ' || v_s.name || ' está vencido.');
      end if;
    end loop;
    -- Só não-sócios/dependentes: manhã (5h–12h) ou noite (20h+), exceto domingo.
    v_socio_count := cardinality(v_parts);
    v_restrict := v_socio_count = 0 and cardinality(v_students) > 0 and extract(dow from v_date) <> 0;
    if v_restrict and not (v_smin < 720 or v_smin >= 1200) then
      return conv_private.vfail('NON_MEMBER_HOURS', 'Aula só com não-sócios ou dependentes: de manhã (5h–12h) ou à noite (20h+).');
    end if;
  end if;

  if conv_private.court_busy(v_court.id, v_date, v_smin, v_emin, v_ex) then
    return conv_private.vfail('SLOT_TAKEN', 'Esse horário já está reservado nessa quadra.');
  end if;

  return jsonb_build_object('ok', true, 'normalized', jsonb_build_object(
    'type', v_type, 'date', v_date, 'start', conv_private.min_to_hhmm(v_smin), 'end', conv_private.min_to_hhmm(v_emin),
    'duration', v_dur, 'court_id', v_court.id, 'court_name', v_court.name, 'court_type', v_court.type::text,
    'requester_profile_id', v_req.id, 'participant_ids', to_jsonb(v_parts), 'guest_name', v_guest,
    'professor_id', v_prof, 'non_socio_student_ids', to_jsonb(v_students), 'exclude_reservation_id', v_ex));
end $function$;
--@@ 45 funcao conv_private.vfail(p_code text, p_message text)
CREATE OR REPLACE FUNCTION conv_private.vfail(p_code text, p_message text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object('ok', false, 'code', p_code, 'message', p_message) $function$;
--@@ 45 funcao fin_private.account_balances(p_at date)
CREATE OR REPLACE FUNCTION fin_private.account_balances(p_at date)
 RETURNS TABLE(id uuid, name text, kind text, active boolean, is_default_receipts boolean, balance_cents bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with s as (select account_id, sum(amount_cents)::bigint amt from fin_private.cash_rows('1900-01-01'::date, p_at) group by 1)
  select a.id, a.name, a.kind, a.active, a.is_default_receipts, coalesce(s.amt, 0)::bigint
  from public.fin_accounts a left join s on s.account_id = a.id
  where a.active or coalesce(s.amt, 0) <> 0
  union all
  select null::uuid, 'Sem conta definida', 'other', true, false, s.amt from s where s.account_id is null and s.amt <> 0
  order by 2
$function$;
--@@ 45 funcao fin_private.add_entry_payment(p_entry uuid, p_amount bigint, p_
CREATE OR REPLACE FUNCTION fin_private.add_entry_payment(p_entry uuid, p_amount bigint, p_paid_on date, p_account uuid, p_note text, p_settle boolean, p_request uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e public.fin_entries%rowtype; v_paid bigint; v_actor uuid := auth.uid();
begin
  select * into e from public.fin_entries where id = p_entry for update;
  perform fin_private.check_account(p_account);
  if p_paid_on is null or p_paid_on > fin_private.today() then raise exception 'INVALID_DATE'; end if;
  if p_amount is null or p_amount <= 0 or p_amount > 100000000000 then raise exception 'INVALID_AMOUNT'; end if;
  insert into public.fin_entry_payments(entry_id, kind, amount_cents, paid_on, account_id, note, actor_id, request_id)
  values (p_entry, 'payment', p_amount, p_paid_on, p_account, nullif(trim(p_note), ''), v_actor, p_request);
  v_paid := fin_private.entry_paid_cents(p_entry);
  if e.kind in ('expense', 'revenue') then
    if v_paid >= e.amount_cents or p_settle then
      if v_paid > e.amount_cents and not p_settle then raise exception 'PAYMENT_EXCEEDS_ENTRY'; end if;
      update public.fin_entries set status = 'paid', settled_on = p_paid_on, adjustment_cents = v_paid - e.amount_cents,
        account_id = coalesce(account_id, p_account), version = version + 1, updated_at = now(), updated_by = v_actor where id = p_entry;
    else
      update public.fin_entries set status = 'partial', version = version + 1, updated_at = now(), updated_by = v_actor where id = p_entry;
    end if;
  else
    update public.fin_entries set status = 'paid', settled_on = p_paid_on, version = version + 1, updated_at = now(), updated_by = v_actor where id = p_entry;
  end if;
end $function$;
--@@ 45 funcao fin_private.adjust_business_day(p_date date, p_rule text)
CREATE OR REPLACE FUNCTION fin_private.adjust_business_day(p_date date, p_rule text)
 RETURNS date
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare d date := p_date; v_step integer; i integer := 0;
begin
  if p_rule = 'keep' or fin_private.is_business_day(d) then return d; end if;
  v_step := case when p_rule = 'previous_business_day' then -1 else 1 end;
  while i < 366 loop
    d := d + v_step; i := i + 1;
    if fin_private.is_business_day(d) then return d; end if;
  end loop;
  raise exception 'NO_BUSINESS_DAY';
end $function$;
--@@ 45 funcao fin_private.apply_payment(p_charge uuid, p_amount bigint, p_pai
CREATE OR REPLACE FUNCTION fin_private.apply_payment(p_charge uuid, p_amount bigint, p_paid_on date, p_method text, p_account uuid, p_submission uuid, p_credit uuid, p_note text, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.fin_member_charges%rowtype; s record; v_fine bigint; v_int bigint; v_prin bigint; v_exc bigint; v_pid uuid;
  v_last date; v_credit uuid; v_status text; v_dup boolean;
begin
  select * into c from public.fin_member_charges where id = p_charge for update;
  if not found then raise exception 'CHARGE_NOT_FOUND'; end if;
  if c.status = 'canceled' then raise exception 'CHARGE_CANCELED'; end if;
  if p_amount is null or p_amount <= 0 or p_amount > 100000000000 then raise exception 'INVALID_AMOUNT'; end if;
  if p_paid_on is null or p_paid_on > fin_private.today() then raise exception 'INVALID_DATE'; end if;
  if p_method not in ('pix', 'transfer', 'cash', 'card', 'other', 'credit') then raise exception 'INVALID_METHOD'; end if;
  if p_method <> 'credit' then perform fin_private.check_account(p_account); end if;
  select max(paid_on) into v_last from fin_private.charge_payments_effective where charge_id = p_charge;
  if v_last is not null and p_paid_on < v_last then raise exception 'PAYMENT_DATE_BEFORE_LAST'; end if;

  select * into s from fin_private.charge_statement(p_charge, p_paid_on);
  v_fine := least(p_amount, s.fine_due);
  v_int := least(p_amount - v_fine, s.interest_due);
  v_prin := least(p_amount - v_fine - v_int, s.principal_remaining);
  v_exc := p_amount - v_fine - v_int - v_prin;
  v_dup := s.settled and v_exc = p_amount;
  if p_method = 'credit' and v_exc > 0 then raise exception 'CREDIT_EXCEEDS_DUE'; end if;

  insert into public.fin_charge_payments(charge_id, kind, amount_cents, paid_on, fine_cents, interest_cents, principal_cents,
    excess_cents, method, account_id, submission_id, credit_id, note, actor_id, request_id)
  values (p_charge, 'payment', p_amount, p_paid_on, v_fine, v_int, v_prin, v_exc, p_method,
    case when p_method = 'credit' then null else p_account end, p_submission, p_credit, nullif(trim(p_note), ''), auth.uid(), p_request)
  returning id into v_pid;
  if v_exc > 0 then
    insert into public.fin_member_credits(profile_id, source_payment_id, reason, amount_cents, remaining_cents)
    values (c.profile_id, v_pid, case when v_dup then 'duplicate' else 'excess' end, v_exc, v_exc) returning id into v_credit;
  end if;
  v_status := fin_private.refresh_charge_status(p_charge);
  return jsonb_build_object('payment_id', v_pid, 'fine_cents', v_fine, 'interest_cents', v_int, 'principal_cents', v_prin,
    'excess_cents', v_exc, 'duplicate', v_dup, 'credit_id', v_credit, 'charge_status', v_status);
end $function$;
--@@ 45 funcao fin_private.audit_row()
CREATE OR REPLACE FUNCTION fin_private.audit_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_old jsonb; v_new jsonb; v_row jsonb; v_changed text[]; v_target uuid; v_reason text;
  v_strip text[] := array['ocr', 'storage_path', 'content_sha256'];
  v_key text;
begin
  if tg_op = 'DELETE' then v_old := to_jsonb(old); v_row := v_old;
  elsif tg_op = 'UPDATE' then
    v_old := to_jsonb(old); v_new := to_jsonb(new); v_row := v_new;
    if v_old = v_new then return new; end if;
  else v_new := to_jsonb(new); v_row := v_new; end if;

  foreach v_key in array v_strip loop
    v_old := v_old - v_key; v_new := v_new - v_key;
  end loop;
  if tg_op = 'UPDATE' then v_changed := public.admin_audit_changed_fields(v_old, v_new); end if;
  v_target := public.admin_audit_try_uuid(v_row->>'profile_id');
  v_reason := nullif(current_setting('fin.reason', true), '');

  perform public.admin_audit_insert_log(
    'fin.' || coalesce(nullif(current_setting('fin.action', true), ''), lower(tg_op)),
    tg_table_name,
    coalesce(v_row->>'id', v_row->>'request_id', v_row->>'holiday_date'),
    v_target,
    case when v_target is null then '{}'::uuid[] else array[v_target] end,
    v_changed, v_old, v_new,
    jsonb_strip_nulls(jsonb_build_object('reason', v_reason, 'request_id', nullif(current_setting('fin.request_id', true), ''), 'op', lower(tg_op))),
    'finance', now());
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $function$;
--@@ 45 funcao fin_private.audit_row_dispatch(p_op text, p_old jsonb, p_new js
CREATE OR REPLACE FUNCTION fin_private.audit_row_dispatch(p_op text, p_old jsonb, p_new jsonb, p_table text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_row jsonb := coalesce(p_new, p_old); v_changed text[];
begin
  if p_op = 'UPDATE' then
    if p_old = p_new then return; end if;
    v_changed := public.admin_audit_changed_fields(p_old, p_new);
  end if;
  perform public.admin_audit_insert_log(
    'fin.' || coalesce(nullif(current_setting('fin.action', true), ''), lower(p_op)),
    p_table, v_row->>'id', null, '{}'::uuid[], v_changed,
    case when p_op = 'INSERT' then null else p_old end,
    case when p_op = 'DELETE' then null else p_new end,
    jsonb_build_object('op', lower(p_op), 'legacy_table', true), 'finance', now());
end $function$;
--@@ 45 funcao fin_private.audit_row_soft()
CREATE OR REPLACE FUNCTION fin_private.audit_row_soft()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old jsonb; v_new jsonb;
begin
  begin
    if tg_op = 'INSERT' then v_new := to_jsonb(new);
    elsif tg_op = 'UPDATE' then v_old := to_jsonb(old); v_new := to_jsonb(new);
    else v_old := to_jsonb(old); end if;
    perform fin_private.audit_row_dispatch(tg_op, v_old, v_new, tg_table_name);
  exception when others then
    raise warning 'fin audit (legado) falhou em %: %', tg_table_name, sqlerrm;
  end;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $function$;
--@@ 45 funcao fin_private.auto_approve_pendency_receipt(p_submission uuid)
CREATE OR REPLACE FUNCTION fin_private.auto_approve_pendency_receipt(p_submission uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  s public.fin_receipt_submissions%rowtype; fs public.fin_settings%rowtype; v_ids uuid[]; v_count integer; v_open_count integer;
  v_amount bigint; v_paid_on date; v_ocr_amount bigint; v_ocr_date date; v_payee text;
  v_conf_amount text; v_conf_date text; v_conf_payee text; v_identifier text; v_account uuid;
  v_remaining bigint; v_alloc bigint; r record; v_res jsonb; v_pay_ids uuid[]:='{}';
  v_duplicate boolean; v_doc_ok boolean; v_total_paid bigint:=0;
begin
  select * into s from public.fin_receipt_submissions where id=p_submission for update;
  if not found then return jsonb_build_object('approved',false,'reason','RECEIPT_NOT_FOUND'); end if;
  if s.status not in ('submitted','in_review') then return jsonb_build_object('approved',false,'reason','RECEIPT_NOT_PENDING'); end if;
  if s.ocr_status<>'ok' or s.ocr is null then return jsonb_build_object('approved',false,'reason','OCR_NOT_OK'); end if;
  if s.possible_duplicate then return jsonb_build_object('approved',false,'reason','POSSIBLE_DUPLICATE'); end if;

  v_amount:=s.declared_amount_cents; v_paid_on:=s.declared_paid_on;
  v_ocr_amount:=nullif(s.ocr->>'amount_cents','')::bigint;
  v_ocr_date:=nullif(s.ocr->>'paid_on','')::date;
  v_conf_amount:=s.ocr->'confidence'->>'amount';
  v_conf_date:=s.ocr->'confidence'->>'date';
  v_conf_payee:=s.ocr->'confidence'->>'payee';
  v_payee:=nullif(trim(s.ocr->>'payee'),'');
  v_identifier:=nullif(trim(s.ocr->>'identifier'),'');

  if v_amount is null or v_paid_on is null or v_ocr_amount is null or v_ocr_date is null then
    return jsonb_build_object('approved',false,'reason','FIELDS_MISSING');
  end if;
  if v_paid_on>fin_private.today() then return jsonb_build_object('approved',false,'reason','DATE_FUTURE'); end if;
  if v_conf_amount is distinct from 'high' or v_conf_date is distinct from 'high' then return jsonb_build_object('approved',false,'reason','LOW_CONFIDENCE'); end if;
  if v_amount<>v_ocr_amount then return jsonb_build_object('approved',false,'reason','AMOUNT_MISMATCH'); end if;
  if v_paid_on<>v_ocr_date then return jsonb_build_object('approved',false,'reason','DATE_MISMATCH'); end if;

  select * into fs from public.fin_settings where id;
  -- O CNPJ do favorecido igual à chave Pix do clube basta; sem ele, vale o nome (palavras inteiras).
  v_doc_ok:=fin_private.cnpj_matches(nullif(trim(s.ocr->>'payee_document'),''),fs.pix_key);
  if not v_doc_ok then
    if cardinality(coalesce(fs.payee_names,'{}'))=0 then return jsonb_build_object('approved',false,'reason','PAYEE_NOT_CONFIGURED'); end if;
    if v_payee is null or v_conf_payee is distinct from 'high' then return jsonb_build_object('approved',false,'reason','PAYEE_NOT_CONFIRMED'); end if;
    if not fin_private.payee_matches(v_payee,fs.payee_names) then return jsonb_build_object('approved',false,'reason','PAYEE_MISMATCH'); end if;
  end if;

  select coalesce(array_agg(rc.charge_id),'{}'),count(*)
    into v_ids,v_count from public.fin_receipt_charges rc where rc.submission_id=p_submission;
  if v_count=0 then return jsonb_build_object('approved',false,'reason','NO_CHARGES_SELECTED'); end if;

  -- Mensalidade e pendência do próprio sócio, ainda em aberto.
  select count(*) into v_open_count
  from public.fin_member_charges c
  where c.id=any(v_ids) and c.profile_id=s.profile_id
    and c.charge_type in ('membership','member_pendency')
    and c.status in ('open','partial');
  if v_open_count<>v_count then return jsonb_build_object('approved',false,'reason','NOT_ONLY_OPEN_CHARGES'); end if;

  select exists(
    select 1 from public.fin_receipt_submissions o
    where o.id<>s.id and o.profile_id=s.profile_id and o.status in ('submitted','in_review','approved')
      and (
        (v_identifier is not null and nullif(trim(o.ocr->>'identifier'),'')=v_identifier)
        or (o.declared_amount_cents=v_amount and o.declared_paid_on=v_paid_on)
      )
  ) into v_duplicate;
  if v_duplicate then return jsonb_build_object('approved',false,'reason','DUPLICATE_FIELDS'); end if;

  -- Mesmo valor e data já pagos por outro caminho (ex.: baixa manual do administrador).
  if exists(
    select 1 from fin_private.charge_payments_effective p
    join public.fin_member_charges c on c.id=p.charge_id
    where c.profile_id=s.profile_id and p.method<>'credit'
      and p.amount_cents=v_amount and p.paid_on=v_paid_on
      and p.submission_id is distinct from s.id
  ) then return jsonb_build_object('approved',false,'reason','DUPLICATE_PAYMENT'); end if;

  select id into v_account from public.fin_accounts where is_default_receipts and active order by position,id limit 1;
  if v_account is null then return jsonb_build_object('approved',false,'reason','DEFAULT_ACCOUNT_MISSING'); end if;

  begin
    v_remaining:=v_amount;
    for r in
      select z.*
      from (
        select cr.*,
          row_number() over(order by (cr.due_date>=v_paid_on),cr.due_date,cr.charge_id) rn,
          count(*) over() n
        from fin_private.charge_rows(s.profile_id,v_ids,'{}'::jsonb,v_paid_on,1000,0) cr
        join public.fin_member_charges c on c.id=cr.charge_id
        where cr.stored_status in ('open','partial') and cr.total_due_cents>0
      ) z
      order by z.rn
    loop
      exit when v_remaining<=0;
      -- A última cobrança recebe o resto: o motor transforma o excedente em crédito do sócio.
      v_alloc:=case when r.rn=r.n then v_remaining else least(v_remaining,r.total_due_cents) end;
      v_res:=fin_private.apply_payment(r.charge_id,v_alloc,v_paid_on,'pix',v_account,p_submission,null,
        'Baixa automática por comprovante OCR',gen_random_uuid());
      v_pay_ids:=v_pay_ids||(v_res->>'payment_id')::uuid;
      v_total_paid:=v_total_paid+v_alloc;
      v_remaining:=v_remaining-v_alloc;
    end loop;
  exception when others then
    -- Desfaz só os pagamentos deste bloco; o comprovante fica para análise.
    return jsonb_build_object('approved',false,'reason','PAYMENT_REJECTED');
  end;

  if cardinality(v_pay_ids)=0 then return jsonb_build_object('approved',false,'reason','NO_OPEN_BALANCE'); end if;

  update public.fin_receipt_submissions
  set status='approved',reviewed_by=null,reviewed_at=now(),
      decision_reason='Baixa automática: OCR com alta confiança e dados conferidos',
      approved_payment_ids=v_pay_ids,version=version+1,updated_at=now()
  where id=p_submission;

  return jsonb_build_object('approved',true,'status','approved','payment_ids',to_jsonb(v_pay_ids),'total_cents',v_total_paid);
end $function$;
--@@ 45 funcao fin_private.begin_op(p_key uuid, p_action text, p_reason text)
CREATE OR REPLACE FUNCTION fin_private.begin_op(p_key uuid, p_action text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := auth.uid(); v_row public.fin_requests%rowtype;
begin
  if v_actor is null then raise exception 'FINANCE_FORBIDDEN' using errcode = '42501'; end if;
  if p_key is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED'; end if;
  insert into public.fin_requests(request_id, action, actor_id) values (p_key, p_action, v_actor)
  on conflict (request_id) do nothing;
  if not found then
    select * into v_row from public.fin_requests where request_id = p_key;
    if v_row.action <> p_action or v_row.actor_id is distinct from v_actor then
      raise exception 'IDEMPOTENCY_KEY_REUSED';
    end if;
    return coalesce(v_row.result, '{}'::jsonb) || jsonb_build_object('replayed', true);
  end if;
  perform set_config('fin.action', p_action, true);
  perform set_config('fin.reason', coalesce(trim(p_reason), ''), true);
  perform set_config('fin.request_id', p_key::text, true);
  return null;
end $function$;
--@@ 45 funcao fin_private.cash_rows(p_from date, p_to date)
CREATE OR REPLACE FUNCTION fin_private.cash_rows(p_from date, p_to date)
 RETURNS TABLE(source_type text, source_id text, leg text, occurred_on date, flow text, description text, category_id uuid, account_id uuid, amount_cents bigint, is_transfer boolean, origin text, profile_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.fin_settings%rowtype; v_default uuid;
begin
  select * into s from public.fin_settings;
  select id into v_default from public.fin_accounts where is_default_receipts and active limit 1;
  return query
  with u as (
    -- Mensalidade: principal / encargos / excedente, no dia do pagamento, na conta escolhida.
    -- Pagamento por crédito do sócio NÃO é entrada de dinheiro (o dinheiro entrou antes).
    select 'member_payment'::text st, p.id::text sid, 'principal'::text leg, p.paid_on d, 'receipt'::text flow,
      case when c.charge_type='member_pendency' then c.description else 'Mensalidade' end::text descr,
      coalesce(c.category_id, fin_private.category_id('member_fees')) cat,
      p.account_id acct, p.principal_cents amt, false tr, 'auto'::text org, c.profile_id prof
    from public.fin_charge_payments p join public.fin_member_charges c on c.id = p.charge_id
    where p.kind = 'payment' and p.method <> 'credit' and p.principal_cents > 0 and p.paid_on between p_from and p_to
    union all
    select 'member_payment', p.id::text, 'fees', p.paid_on, 'fee', 'Multa e juros de mora', fin_private.category_id('late_fees'), p.account_id,
      (p.fine_cents + p.interest_cents), false, 'auto', c.profile_id
    from public.fin_charge_payments p join public.fin_member_charges c on c.id = p.charge_id
    where p.kind = 'payment' and p.method <> 'credit' and p.fine_cents + p.interest_cents > 0 and p.paid_on between p_from and p_to
    union all
    select 'member_payment', p.id::text, 'excess', p.paid_on, 'credit', 'Crédito do sócio (excedente/duplicado)', null::uuid, p.account_id,
      p.excess_cents, false, 'auto', c.profile_id
    from public.fin_charge_payments p join public.fin_member_charges c on c.id = p.charge_id
    where p.kind = 'payment' and p.method <> 'credit' and p.excess_cents > 0 and p.paid_on between p_from and p_to
    union all
    -- Estorno de pagamento: sai o mesmo dinheiro, no dia do estorno.
    select 'member_reversal', p.id::text, 'reversal', p.paid_on, 'refund',
      case when c.charge_type='member_pendency' then 'Estorno — '||c.description else 'Estorno de pagamento de mensalidade' end,
      fin_private.category_id('refunds'),
      p.account_id, -(p.principal_cents + p.fine_cents + p.interest_cents + p.excess_cents), false, 'auto', c.profile_id
    from public.fin_charge_payments p join public.fin_member_charges c on c.id = p.charge_id
    where p.kind = 'reversal' and p.method <> 'credit' and p.paid_on between p_from and p_to
    union all
    -- Card Mensal / Aula avulsa dos alunos (student_payments ativos) — conta padrão de recebimentos.
    select 'student_payment', sp.id::text, 'main', (sp.payment_date at time zone 'America/Fortaleza')::date, 'receipt',
      case when (sp.valid_until at time zone 'America/Fortaleza')::date > (sp.payment_date at time zone 'America/Fortaleza')::date then 'Card Mensal' else 'Aula avulsa' end
        || ' — ' || coalesce(st.name, 'aluno'),
      fin_private.category_id(case when (sp.valid_until at time zone 'America/Fortaleza')::date > (sp.payment_date at time zone 'America/Fortaleza')::date then 'card_mensal' else 'aula_avulsa' end),
      v_default, round(sp.amount * 100)::bigint, false, 'auto', null::uuid
    from public.student_payments sp left join public.non_socio_students st on st.id = sp.student_id
    where sp.status = 'active' and (sp.payment_date at time zone 'America/Fortaleza')::date between p_from and p_to
    union all
    -- Day Card do convidado (derivado da reserva): só entra no caixa se o clube disser que recebe na hora (padrão: não).
    select 'day_card', d.reservation_id::text, 'main', d.occurred_on, 'day_card',
      'Day Card — ' || d.guest_name, fin_private.category_id('day_card'), v_default, d.charged_cents, false, 'derived', null::uuid
    from fin_private.day_card_rows(p_from, p_to) d where s.day_card_in_cash and d.charged_cents > 0
    union all
    -- Lançamentos (pagamentos/recebimentos de contas, aportes, retiradas, devoluções).
    select 'entry_payment', x.id::text, case when e.kind = 'transfer' then 'out' else 'main' end, x.paid_on,
      case e.kind when 'expense' then 'expense' when 'revenue' then 'revenue' when 'contribution' then 'contribution'
        when 'withdrawal' then 'withdrawal' when 'transfer' then 'transfer' else 'member_refund' end,
      e.description, e.category_id, x.account_id,
      (case when e.kind in ('expense', 'withdrawal', 'transfer', 'member_refund') then -1 else 1 end * case when x.kind = 'payment' then 1 else -1 end * x.amount_cents)::bigint,
      e.kind = 'transfer', 'manual', null::uuid
    from public.fin_entry_payments x join public.fin_entries e on e.id = x.entry_id where x.paid_on between p_from and p_to
    union all
    select 'entry_payment', x.id::text, 'in', x.paid_on, 'transfer', e.description, null::uuid, e.counter_account_id,
      (case when x.kind = 'payment' then 1 else -1 end * x.amount_cents)::bigint, true, 'manual', null::uuid
    from public.fin_entry_payments x join public.fin_entries e on e.id = x.entry_id
    where e.kind = 'transfer' and x.paid_on between p_from and p_to
    union all
    select 'opening', a.id::text, 'main', a.opening_date, 'opening', 'Saldo inicial — ' || a.name, null::uuid, a.id, a.opening_balance_cents,
      false, 'manual', null::uuid
    from public.fin_accounts a where a.opening_balance_cents <> 0 and a.opening_date between p_from and p_to
  )
  -- Antes da data de saldo inicial de uma conta o movimento já está dentro do saldo informado.
  select u.st, u.sid, u.leg, u.d, u.flow, u.descr, u.cat, u.acct, u.amt, u.tr, u.org, u.prof
  from u left join public.fin_accounts a on a.id = u.acct
  where a.id is null or u.d >= a.opening_date;
end $function$;
--@@ 45 funcao fin_private.category_id(p_key text)
CREATE OR REPLACE FUNCTION fin_private.category_id(p_key text)
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select id from public.fin_categories where system_key = p_key $function$;
--@@ 45 funcao fin_private.charge_rows(p_profile uuid, p_ids uuid[], p_filters
CREATE OR REPLACE FUNCTION fin_private.charge_rows(p_profile uuid, p_ids uuid[], p_filters jsonb, p_as_of date, p_limit integer, p_offset integer)
 RETURNS TABLE(charge_id uuid, plan_id uuid, profile_id uuid, profile_name text, competence_month date, period_months smallint, due_date date, original_amount_cents bigint, stored_status text, display_status text, in_review boolean, principal_base_cents bigint, principal_paid_cents bigint, principal_remaining_cents bigint, days_late integer, fine_due_cents bigint, interest_due_cents bigint, fees_due_cents bigint, fees_paid_cents bigint, fees_waived_cents bigint, total_due_cents bigint, fees_configured boolean, overdue boolean, last_payment_on date, cancel_reason text, total_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_search text := nullif(trim(coalesce(p_filters->>'search', '')), '');
begin
  return query
  with x as (
    select c.id, c.plan_id, c.profile_id, pr.name pname, c.competence_month, c.period_months, c.due_date, c.original_amount_cents,
      c.status, c.cancel_reason,
      exists (select 1 from public.fin_receipt_charges rc join public.fin_receipt_submissions rs on rs.id = rc.submission_id
              where rc.charge_id = c.id and rs.status in ('submitted', 'in_review')) as rev,
      st.*,
      (select max(e.paid_on) from fin_private.charge_payments_effective e where e.charge_id = c.id) as last_pay
    from public.fin_member_charges c
    join public.profiles pr on pr.id = c.profile_id
    cross join lateral fin_private.charge_statement(c.id, p_as_of) st
    where (p_profile is null or c.profile_id = p_profile)
      and (p_ids is null or c.id = any(p_ids))
      and (v_search is null or pr.name ilike '%' || v_search || '%')
      and (nullif(p_filters->>'profile_id', '') is null or c.profile_id = (p_filters->>'profile_id')::uuid)
      and (nullif(p_filters->>'plan_id', '') is null or c.plan_id = (p_filters->>'plan_id')::uuid)
      and (nullif(p_filters->>'charge_type', '') is null or c.charge_type = p_filters->>'charge_type')
      and (nullif(p_filters->>'competence_from', '') is null or c.competence_month >= (p_filters->>'competence_from')::date)
      and (nullif(p_filters->>'competence_to', '') is null or c.competence_month <= (p_filters->>'competence_to')::date)
      and (nullif(p_filters->>'due_from', '') is null or c.due_date >= (p_filters->>'due_from')::date)
      and (nullif(p_filters->>'due_to', '') is null or c.due_date <= (p_filters->>'due_to')::date)
  ), y as (
    select x.*, case
      when x.status = 'canceled' then 'canceled'
      when x.status = 'paid' then 'paid'
      when x.rev then 'in_review'
      when x.status = 'partial' then 'partial'
      when p_as_of > x.due_date then 'overdue'
      when p_as_of <= ((x.competence_month + make_interval(months => x.period_months::integer))::date - 1) then 'forecast'
      else 'open' end as dstatus
    from x
  )
  select y.id, y.plan_id, y.profile_id, y.pname, y.competence_month, y.period_months, y.due_date, y.original_amount_cents,
    y.status, y.dstatus, y.rev, y.principal_base, y.principal_paid, y.principal_remaining, y.days_late, y.fine_due, y.interest_due,
    y.fees_due, y.fees_paid, y.fees_waived, y.total_due, y.fees_configured, y.overdue, y.last_pay, y.cancel_reason,
    count(*) over() as total_count
  from y
  where (nullif(p_filters->>'status', '') is null or y.dstatus = (p_filters->>'status'))
  order by y.due_date desc, y.pname, y.id
  limit greatest(p_limit, 0) offset greatest(p_offset, 0);
end $function$;
--@@ 45 funcao fin_private.charge_statement(p_charge uuid, p_as_of date)
CREATE OR REPLACE FUNCTION fin_private.charge_statement(p_charge uuid, p_as_of date)
 RETURNS TABLE(principal_base bigint, principal_paid bigint, principal_remaining bigint, grace_until date, days_late integer, fine_accrued bigint, interest_accrued bigint, fees_paid bigint, fees_waived bigint, fine_due bigint, interest_due bigint, fees_due bigint, total_due bigint, fees_configured boolean, overdue boolean, settled boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  c public.fin_member_charges%rowtype; s public.fin_settings%rowtype;
  v_disc bigint; v_inc bigint; v_waived bigint; v_base bigint; v_paid bigint; v_feespaid bigint;
  v_grace date; v_days integer; v_fine bigint := 0; v_int bigint := 0; v_first date; v_cursor date; v_b bigint; v_seg integer;
  pd date[]; pp bigint[]; i integer; n integer; v_red bigint; v_fine_due bigint; v_int_due bigint; v_principal_rem bigint;
  v_fee_configured boolean; v_grace_days integer; v_fine_fixed bigint; v_fine_bps integer; v_int_fixed bigint; v_int_bps integer;
begin
  select * into c from public.fin_member_charges where id = p_charge;
  if not found then raise exception 'CHARGE_NOT_FOUND'; end if;
  select * into s from public.fin_settings;

  if c.charge_type = 'member_pendency' then
    v_fee_configured := true;
    v_grace_days := greatest(s.pendency_grace_days, 0);
    v_fine_fixed := coalesce(s.pendency_fine_fixed_cents, 0);
    v_fine_bps := coalesce(s.pendency_fine_percent_bps, 0);
    v_int_fixed := coalesce(s.pendency_interest_daily_fixed_cents, 0);
    v_int_bps := coalesce(s.pendency_interest_daily_percent_bps, 0);
  else
    v_fee_configured := s.late_fee_confirmed_at is not null;
    v_grace_days := greatest(s.grace_days, 0);
    v_fine_fixed := coalesce(s.fine_fixed_cents, 0);
    v_fine_bps := coalesce(s.fine_percent_bps, 0);
    v_int_fixed := coalesce(s.interest_daily_fixed_cents, 0);
    v_int_bps := coalesce(s.interest_daily_percent_bps, 0);
  end if;

  select coalesce(sum(amount_cents) filter (where kind = 'discount'), 0),
         coalesce(sum(amount_cents) filter (where kind = 'increase'), 0),
         coalesce(sum(amount_cents) filter (where kind = 'fee_waiver'), 0)
    into v_disc, v_inc, v_waived
  from public.fin_charge_adjustments where charge_id = p_charge;

  select coalesce(array_agg(paid_on order by paid_on, created_at, id), '{}'),
         coalesce(array_agg(principal_cents order by paid_on, created_at, id), '{}'),
         coalesce(sum(principal_cents), 0),
         coalesce(sum(fine_cents + interest_cents), 0)
    into pd, pp, v_paid, v_feespaid
  from fin_private.charge_payments_effective
  where charge_id = p_charge and paid_on <= p_as_of;

  v_base := greatest(c.original_amount_cents - v_disc + v_inc, 0);
  v_principal_rem := case when c.status = 'canceled' then 0 else greatest(v_base - v_paid, 0) end;
  v_grace := c.due_date + v_grace_days;
  v_days := greatest(p_as_of - v_grace, 0);
  n := coalesce(array_length(pd, 1), 0);

  if v_fee_configured and c.status <> 'canceled' and v_days > 0 then
    v_first := v_grace + 1;
    v_b := v_base;
    for i in 1..n loop if pd[i] < v_first then v_b := v_b - pp[i]; end if; end loop;
    v_b := greatest(v_b, 0);
    if v_b > 0 then
      v_fine := v_fine_fixed + round(v_b::numeric * v_fine_bps / 10000)::bigint;
    end if;
    v_cursor := v_first;
    for i in 1..n loop
      if pd[i] >= v_first and pd[i] < p_as_of then
        v_seg := pd[i] - v_cursor + 1;
        if v_seg > 0 and v_b > 0 then
          v_int := v_int + v_int_fixed * v_seg
            + round(v_b::numeric * v_seg * v_int_bps / 10000)::bigint;
        end if;
        v_b := greatest(v_b - pp[i], 0);
        v_cursor := pd[i] + 1;
      end if;
    end loop;
    v_seg := p_as_of - v_cursor + 1;
    if v_seg > 0 and v_b > 0 then
      v_int := v_int + v_int_fixed * v_seg
        + round(v_b::numeric * v_seg * v_int_bps / 10000)::bigint;
    end if;
  end if;

  v_red := v_feespaid + v_waived;
  v_fine_due := greatest(v_fine - v_red, 0);
  v_int_due := greatest(v_fine + v_int - v_red - v_fine_due, 0);

  return query select v_base, v_paid, v_principal_rem, v_grace, v_days, v_fine, v_int, v_feespaid, v_waived,
    v_fine_due, v_int_due, v_fine_due + v_int_due, v_principal_rem + v_fine_due + v_int_due,
    v_fee_configured,
    (c.status <> 'canceled' and v_principal_rem + v_fine_due + v_int_due > 0 and p_as_of > c.due_date),
    (c.status = 'canceled' or v_principal_rem + v_fine_due + v_int_due = 0);
end $function$;
--@@ 45 funcao fin_private.check_account(p_account uuid)
CREATE OR REPLACE FUNCTION fin_private.check_account(p_account uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_account is null then raise exception 'ACCOUNT_REQUIRED'; end if;
  if not exists (select 1 from public.fin_accounts where id = p_account and active) then raise exception 'INVALID_ACCOUNT'; end if;
end $function$;
--@@ 45 funcao fin_private.check_category(p_category uuid, p_kind text)
CREATE OR REPLACE FUNCTION fin_private.check_category(p_category uuid, p_kind text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.fin_categories%rowtype;
begin
  if p_category is null then raise exception 'CATEGORY_REQUIRED'; end if;
  select * into c from public.fin_categories where id = p_category;
  if not found or not c.active or c.kind <> p_kind then raise exception 'INVALID_CATEGORY'; end if;
  if c.system_key in ('member_fees', 'card_mensal', 'aula_avulsa', 'day_card', 'late_fees', 'discounts', 'refunds', 'interest') then
    raise exception 'CATEGORY_RESERVED';
  end if;
end $function$;
--@@ 45 funcao fin_private.check_period(p_from date, p_to date)
CREATE OR REPLACE FUNCTION fin_private.check_period(p_from date, p_to date)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 731 then raise exception 'INVALID_PERIOD'; end if;
end $function$;
--@@ 45 funcao fin_private.cnpj_matches(p_read text, p_key text)
CREATE OR REPLACE FUNCTION fin_private.cnpj_matches(p_read text, p_key text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select coalesce(
    length(t.r)=14 and length(t.k)=14 and length(replace(t.r,'*',''))>=8
    and not exists (select 1 from generate_series(1,14) i where substr(t.r,i,1)<>'*' and substr(t.r,i,1)<>substr(t.k,i,1)),
    false)
  from (select regexp_replace(coalesce(p_read,''),'[^0-9*]','','g') r, regexp_replace(coalesce(p_key,''),'\D','','g') k) t
$function$;
--@@ 45 funcao fin_private.day_card_rows(p_from date, p_to date)
CREATE OR REPLACE FUNCTION fin_private.day_card_rows(p_from date, p_to date)
 RETURNS TABLE(reservation_id uuid, occurred_on date, guest_name text, booked_by text, exempt boolean, charged_cents bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_price bigint;
begin
  select day_card_price_cents into v_price from public.fin_settings;
  return query
  select r.id, r.date, trim(r.guest_name),
    (select p.name from public.profiles p where p.id = r.creator_id),
    (r.payment_status::text = 'exempt'),
    case when r.payment_status::text = 'exempt' then 0::bigint else v_price end
  from public.reservations r
  where r.type = 'Play' and nullif(trim(coalesce(r.guest_name, '')), '') is not null
    and r.date between p_from and p_to and coalesce(r.status, 'active') <> 'cancelled'
  order by r.date, r.id;
end $function$;
--@@ 45 funcao fin_private.dre_lines(p_from date, p_to date)
CREATE OR REPLACE FUNCTION fin_private.dre_lines(p_from date, p_to date)
 RETURNS TABLE(line text, category_id uuid, name text, parent_name text, amount_cents bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select c.dre_line, c.id, c.name, g.name,
    (case when c.dre_line = 'revenue' then 1 else -1 end * sum(x.amount_cents))::bigint
  from fin_private.dre_rows(p_from, p_to) x
  join public.fin_categories c on c.id = x.category_id
  left join public.fin_categories g on g.id = c.parent_id
  where c.dre_line <> 'none'
  group by c.dre_line, c.id, c.name, g.name
  having sum(x.amount_cents) <> 0
$function$;
--@@ 45 funcao fin_private.dre_rows(p_from date, p_to date)
CREATE OR REPLACE FUNCTION fin_private.dre_rows(p_from date, p_to date)
 RETURNS TABLE(category_id uuid, amount_cents bigint, source_type text, source_id text, occurred_on date, description text, profile_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.fin_settings%rowtype;
begin
  select * into s from public.fin_settings;
  return query
  -- 1. Mensalidades de sócios: o valor do período é rateado nos meses de competência
  --    (resto dos centavos no primeiro mês); entra o mês cujo dia 1 está no período.
  with m as (
    select c.id, c.profile_id, c.period_months n, c.original_amount_cents o, gs.i,
      (c.competence_month + make_interval(months => gs.i))::date as month_start
    from public.fin_member_charges c cross join lateral generate_series(0, c.period_months - 1) as gs(i)
    where c.status <> 'canceled' and c.charge_type = 'membership'
  ), adj as (
    select a.charge_id,
      coalesce(sum(a.amount_cents) filter (where a.kind = 'discount'), 0)::bigint disc,
      coalesce(sum(a.amount_cents) filter (where a.kind = 'increase'), 0)::bigint inc
    from public.fin_charge_adjustments a group by a.charge_id
  )
  select fin_private.category_id('member_fees'),
    (((m.o + coalesce(adj.inc, 0)) / m.n) + case when m.i = 0 then (m.o + coalesce(adj.inc, 0)) - ((m.o + coalesce(adj.inc, 0)) / m.n) * m.n else 0 end)::bigint,
    'member_charge', m.id::text, m.month_start, 'Mensalidade ' || to_char(m.month_start, 'MM/YYYY'), m.profile_id
  from m left join adj on adj.charge_id = m.id where m.month_start between p_from and p_to
  union all
  select fin_private.category_id('discounts'),
    -(((coalesce(adj.disc, 0)) / m.n) + case when m.i = 0 then coalesce(adj.disc, 0) - (coalesce(adj.disc, 0) / m.n) * m.n else 0 end)::bigint,
    'member_discount', m.id::text, m.month_start, 'Desconto na mensalidade ' || to_char(m.month_start, 'MM/YYYY'), m.profile_id
  from m join adj on adj.charge_id = m.id where adj.disc > 0 and m.month_start between p_from and p_to
  union all
  -- Pendências manuais do sócio entram na competência escolhida e na categoria de receita escolhida.
  select c.category_id, (c.original_amount_cents + coalesce(adj.inc,0))::bigint,
    'member_pendency', c.id::text, c.competence_month, c.description, c.profile_id
  from public.fin_member_charges c
  left join adj on adj.charge_id=c.id
  where c.charge_type='member_pendency' and c.status<>'canceled'
    and c.competence_month between p_from and p_to
  union all
  select fin_private.category_id('discounts'), -coalesce(adj.disc,0)::bigint,
    'member_pendency_discount', c.id::text, c.competence_month, 'Desconto — '||c.description, c.profile_id
  from public.fin_member_charges c
  join adj on adj.charge_id=c.id
  where c.charge_type='member_pendency' and c.status<>'canceled' and adj.disc>0
    and c.competence_month between p_from and p_to
  union all
  -- 2. Multas e juros recebidos: reconhecidos no dia do pagamento; o estorno devolve na data do estorno.
  select fin_private.category_id('late_fees'), (p.fine_cents + p.interest_cents)::bigint, 'member_fee_payment', p.id::text, p.paid_on,
    'Multa e juros de mora', c.profile_id
  from public.fin_charge_payments p join public.fin_member_charges c on c.id = p.charge_id
  where p.kind = 'payment' and p.fine_cents + p.interest_cents > 0 and p.paid_on between p_from and p_to
  union all
  select fin_private.category_id('refunds'), -(p.fine_cents + p.interest_cents)::bigint, 'member_fee_reversal', p.id::text, p.paid_on,
    'Estorno de multa e juros', c.profile_id
  from public.fin_charge_payments p join public.fin_member_charges c on c.id = p.charge_id
  where p.kind = 'reversal' and p.fine_cents + p.interest_cents > 0 and p.paid_on between p_from and p_to
  union all
  -- 3. Card Mensal e Aula avulsa dos alunos não-sócios: o que foi PAGO e registrado em `student_payments`
  --    (ATIVOS, pela data do pagamento). Validade além do dia = Card Mensal; no próprio dia = Aula avulsa
  --    (no app, o plano "Day Card" do aluno). Cancelados/estornados não são receita. A aula em si não gera
  --    receita derivada: o dinheiro já está no pagamento (ou coberto pelo Card Mensal).
  select fin_private.category_id(case when (sp.valid_until at time zone 'America/Fortaleza')::date > (sp.payment_date at time zone 'America/Fortaleza')::date
      then 'card_mensal' else 'aula_avulsa' end),
    round(sp.amount * 100)::bigint, 'student_payment', sp.id::text, (sp.payment_date at time zone 'America/Fortaleza')::date,
    case when (sp.valid_until at time zone 'America/Fortaleza')::date > (sp.payment_date at time zone 'America/Fortaleza')::date then 'Card Mensal' else 'Aula avulsa' end
      || ' — ' || coalesce(st.name, 'aluno'), null::uuid
  from public.student_payments sp left join public.non_socio_students st on st.id = sp.student_id
  where sp.status = 'active' and (sp.payment_date at time zone 'America/Fortaleza')::date between p_from and p_to
  union all
  -- 4. Day Card do convidado, derivado da reserva com convidado (isentas valem R$ 0 e ficam de fora).
  select fin_private.category_id('day_card'), d.charged_cents, 'day_card', d.reservation_id::text,
    d.occurred_on, 'Day Card — ' || d.guest_name, null::uuid
  from fin_private.day_card_rows(p_from, p_to) d where d.charged_cents > 0
  union all
  -- 5. Contas e receitas manuais pela competência (pagas ou não — regime de competência).
  select e.category_id, case when e.kind = 'expense' then -e.amount_cents else e.amount_cents end, 'entry', e.id::text, e.competence_date,
    e.description, null::uuid
  from public.fin_entries e where e.status <> 'canceled' and e.kind in ('expense', 'revenue') and e.competence_date between p_from and p_to
  union all
  -- 6. Pagou diferente do documento: a diferença é juros/multa (ou desconto obtido) na data da quitação.
  select fin_private.category_id('interest'), case when e.kind = 'expense' then -e.adjustment_cents else e.adjustment_cents end, 'entry_adjustment',
    e.id::text, e.settled_on, 'Diferença no pagamento — ' || e.description, null::uuid
  from public.fin_entries e where e.status = 'paid' and e.kind in ('expense', 'revenue') and e.adjustment_cents <> 0 and e.settled_on between p_from and p_to;
end $function$;
--@@ 45 funcao fin_private.due_date(p_competence date, p_period_months integer
CREATE OR REPLACE FUNCTION fin_private.due_date(p_competence date, p_period_months integer, p_due_day integer, p_offset integer, p_rule text)
 RETURNS date
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v_target date; v_last integer; v_nominal date;
begin
  v_target := (date_trunc('month', p_competence::timestamp) + make_interval(months => p_period_months - 1 + p_offset))::date;
  v_last := extract(day from (date_trunc('month', v_target::timestamp) + interval '1 month - 1 day'))::integer;
  v_nominal := v_target + (least(greatest(p_due_day, 1), v_last) - 1);
  return fin_private.adjust_business_day(v_nominal, p_rule);
end $function$;
--@@ 45 funcao fin_private.easter(p_year integer)
CREATE OR REPLACE FUNCTION fin_private.easter(p_year integer)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare a int; b int; c int; d int; e int; f int; g int; h int; i int; k int; l int; m int; mo int; dy int;
begin
  a := p_year % 19; b := p_year / 100; c := p_year % 100; d := b / 4; e := b % 4;
  f := (b + 8) / 25; g := (b - f + 1) / 3; h := (19 * a + b - d - g + 15) % 30;
  i := c / 4; k := c % 4; l := (32 + 2 * e + 2 * i - h - k) % 7; m := (a + 11 * h + 22 * l) / 451;
  mo := (h + l - 7 * m + 114) / 31; dy := ((h + l - 7 * m + 114) % 31) + 1;
  return make_date(p_year, mo, dy);
end $function$;
--@@ 45 funcao fin_private.end_plan(p_plan uuid, p_ended_on date, p_reason tex
CREATE OR REPLACE FUNCTION fin_private.end_plan(p_plan uuid, p_ended_on date, p_reason text, p_auto boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare pl public.fin_member_plans%rowtype; v_end date; v_n integer;
begin
  select * into pl from public.fin_member_plans where id = p_plan for update;
  if not found then raise exception 'PLAN_NOT_FOUND'; end if;
  if pl.status = 'ended' then return jsonb_build_object('id', p_plan, 'canceled_charges', 0, 'already_ended', true); end if;
  v_end := greatest(p_ended_on, pl.start_on);
  perform set_config('fin.action', case when p_auto then 'plan_end_auto' else 'plan_end' end, true);
  perform set_config('fin.reason', coalesce(p_reason, ''), true);
  update public.fin_member_plans set status = 'ended', ended_on = v_end, end_reason = p_reason,
    version = version + 1, updated_at = now(), updated_by = auth.uid() where id = p_plan;
  update public.fin_member_charges c set status = 'canceled', canceled_at = now(), canceled_by = auth.uid(),
    cancel_reason = 'Vínculo encerrado em ' || to_char(v_end, 'DD/MM/YYYY') || ' — cobrança futura cancelada',
    version = version + 1, updated_at = now(), updated_by = auth.uid()
  where c.plan_id = p_plan and c.status = 'open' and c.competence_month > v_end
    and not exists (select 1 from fin_private.charge_payments_effective p where p.charge_id = c.id);
  get diagnostics v_n = row_count;
  return jsonb_build_object('id', p_plan, 'ended_on', v_end, 'canceled_charges', v_n);
end $function$;
--@@ 45 funcao fin_private.ensure_holidays(p_from_year integer, p_to_year inte
CREATE OR REPLACE FUNCTION fin_private.ensure_holidays(p_from_year integer, p_to_year integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare y integer;
begin
  for y in p_from_year..p_to_year loop perform fin_private.seed_holidays(y); end loop;
end $function$;
--@@ 45 funcao fin_private.ensure_member_charges(p_profile uuid, p_extend bool
CREATE OR REPLACE FUNCTION fin_private.ensure_member_charges(p_profile uuid, p_extend boolean)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare pl public.fin_member_plans%rowtype; fs public.fin_settings%rowtype; v_next date; v_before integer; v_after integer;
begin
  select count(*) into v_before from public.fin_member_charges where profile_id=p_profile;
  for pl in select * from public.fin_member_plans where profile_id=p_profile and status='active' order by created_at loop
    perform fin_private.generate_charges(pl.id,fin_private.today());
  end loop;

  if p_extend and not exists(
    select 1 from public.fin_member_charges c
    cross join lateral fin_private.charge_statement(c.id,fin_private.today()) st
    where c.profile_id=p_profile and c.status in ('open','partial') and st.total_due>0
  ) then
    select * into fs from public.fin_settings where id;
    for pl in select * from public.fin_member_plans where profile_id=p_profile and status='active' order by created_at loop
      select coalesce((max(c.competence_month)+make_interval(months=>pl.period_months))::date,
                      date_trunc('month',pl.start_on::timestamp)::date)
        into v_next from public.fin_member_charges c where c.plan_id=pl.id;
      if pl.ended_on is null or v_next<=pl.ended_on then
        -- generate_charges vai até mês(p_today)+horizonte: este p_today faz o limite cair na próxima competência.
        perform fin_private.generate_charges(pl.id,(v_next-make_interval(months=>fs.horizon_months))::date);
      end if;
    end loop;
  end if;

  select count(*) into v_after from public.fin_member_charges where profile_id=p_profile;
  return v_after-v_before;
end $function$;
--@@ 45 funcao fin_private.entry_paid_cents(p_entry uuid)
CREATE OR REPLACE FUNCTION fin_private.entry_paid_cents(p_entry uuid)
 RETURNS bigint
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select coalesce(sum(case when kind = 'payment' then amount_cents else -amount_cents end), 0)::bigint
  from public.fin_entry_payments where entry_id = p_entry $function$;
--@@ 45 funcao fin_private.finish_op(p_key uuid, p_result jsonb)
CREATE OR REPLACE FUNCTION fin_private.finish_op(p_key uuid, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  update public.fin_requests set result = p_result where request_id = p_key;
  return p_result;
end $function$;
--@@ 45 funcao fin_private.fold_text(p_text text)
CREATE OR REPLACE FUNCTION fin_private.fold_text(p_text text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select translate(
    lower(coalesce(p_text,'')),
    'áàâãäéèêëíìîïóòôõöúùûüç',
    'aaaaaeeeeiiiiooooouuuuc'
  )
$function$;
--@@ 45 funcao fin_private.generate_charges(p_plan uuid, p_today date)
CREATE OR REPLACE FUNCTION fin_private.generate_charges(p_plan uuid, p_today date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.fin_settings%rowtype; pl public.fin_member_plans%rowtype; v_until date; v_cursor date; v_amount bigint;
  v_due date; v_n integer; v_created integer := 0; v_existing integer := 0; v_missing integer := 0;
begin
  select * into s from public.fin_settings;
  v_until := (date_trunc('month', p_today::timestamp) + make_interval(months => s.horizon_months))::date;
  for pl in select * from public.fin_member_plans where status = 'active' and (p_plan is null or id = p_plan) order by created_at loop
    perform fin_private.ensure_holidays(extract(year from pl.start_on)::integer, extract(year from v_until)::integer + 1);
    v_cursor := date_trunc('month', pl.start_on::timestamp)::date;
    while v_cursor <= v_until and (pl.ended_on is null or v_cursor <= pl.ended_on) loop
      select amount_cents into v_amount from public.fin_member_plan_prices
      where plan_id = pl.id and effective_from <= v_cursor order by effective_from desc limit 1;
      if not found then
        v_missing := v_missing + 1;
      else
        v_due := fin_private.due_date(v_cursor, pl.period_months, coalesce(pl.due_day, s.due_day),
          coalesce(pl.due_month_offset, s.due_month_offset), s.non_business_rule);
        insert into public.fin_member_charges(plan_id, profile_id, competence_month, period_months, due_date, original_amount_cents, created_by, updated_by)
        values (pl.id, pl.profile_id, v_cursor, pl.period_months, v_due, v_amount, auth.uid(), auth.uid())
        on conflict (plan_id, competence_month) do nothing;
        get diagnostics v_n = row_count;
        if v_n > 0 then v_created := v_created + 1; else v_existing := v_existing + 1; end if;
      end if;
      v_cursor := (v_cursor + make_interval(months => pl.period_months))::date;
    end loop;
  end loop;
  return jsonb_build_object('created', v_created, 'existing', v_existing, 'missing_price', v_missing);
end $function$;
--@@ 45 funcao fin_private.generate_recurrences(p_recurrence uuid, p_until dat
CREATE OR REPLACE FUNCTION fin_private.generate_recurrences(p_recurrence uuid, p_until date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.fin_recurrences%rowtype; v_month date; v_step integer; v_until date; v_count integer := 0; v_n integer;
begin
  v_until := date_trunc('month', coalesce(p_until, (fin_private.today() + interval '1 month')::date)::timestamp)::date;
  for r in select * from public.fin_recurrences where active and (p_recurrence is null or id = p_recurrence) loop
    v_step := case r.frequency when 'monthly' then 1 when 'quarterly' then 3 else 12 end;
    v_month := r.start_month;
    while v_month <= least(v_until, coalesce(r.end_month, v_until)) loop
      insert into public.fin_entries(kind, status, description, supplier, category_id, amount_cents, competence_date, due_date,
        account_id, recurrence_id, notes, request_id, created_by, updated_by)
      values ('expense', 'pending', r.description, r.supplier, r.category_id, r.amount_cents, v_month,
        fin_private.recurrence_due_date(v_month, r.due_day, r.due_month_offset), r.account_id, r.id, r.notes,
        gen_random_uuid(), auth.uid(), auth.uid())
      on conflict (recurrence_id, competence_date) where recurrence_id is not null do nothing;
      get diagnostics v_n = row_count;
      v_count := v_count + v_n;
      v_month := (v_month + make_interval(months => v_step))::date;
    end loop;
  end loop;
  return v_count;
end $function$;
--@@ 45 funcao fin_private.is_active_member(p_profile uuid)
CREATE OR REPLACE FUNCTION fin_private.is_active_member(p_profile uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (select 1 from public.profiles p where p.id = p_profile and p.role::text in ('socio', 'admin') and coalesce(p.is_active, true)) $function$;
--@@ 45 funcao fin_private.is_business_day(p_date date)
CREATE OR REPLACE FUNCTION fin_private.is_business_day(p_date date)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select case extract(dow from p_date)::int
           when 0 then false
           when 6 then coalesce((select saturday_is_business from public.fin_settings), false)
           else true end
     and not exists (select 1 from public.fin_holidays h where h.holiday_date = p_date and h.active)
$function$;
--@@ 45 funcao fin_private.no_delete()
CREATE OR REPLACE FUNCTION fin_private.no_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin raise exception 'FINANCE_NO_DELETE'; end $function$;
--@@ 45 funcao fin_private.no_delete_recurrence()
CREATE OR REPLACE FUNCTION fin_private.no_delete_recurrence()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if coalesce(current_setting('fin.delete_recurrence', true), '') is distinct from old.id::text then
    raise exception 'FINANCE_NO_DELETE';
  end if;
  return old;
end $function$;
--@@ 45 funcao fin_private.on_profile_membership_change()
CREATE OR REPLACE FUNCTION fin_private.on_profile_membership_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_plan uuid;
begin
  begin
    if (old.role::text in ('socio', 'admin') and coalesce(old.is_active, true))
       and (new.role::text not in ('socio', 'admin') or not coalesce(new.is_active, true)) then
      for v_plan in select id from public.fin_member_plans where profile_id = new.id and status <> 'ended' loop
        perform fin_private.end_plan(v_plan, fin_private.today(), 'Vínculo encerrado automaticamente (perfil inativado ou deixou de ser sócio)', true);
      end loop;
    end if;
  exception when others then
    raise warning 'fin: não foi possível encerrar o plano do sócio %: %', new.id, sqlerrm;
  end;
  return new;
end $function$;
--@@ 45 funcao fin_private.payee_matches(p_read text, p_expected text[])
CREATE OR REPLACE FUNCTION fin_private.payee_matches(p_read text, p_expected text[])
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select exists(
    select 1 from unnest(coalesce(p_expected,'{}')) e
    where length(trim(regexp_replace(fin_private.fold_text(e),'[^a-z0-9]+',' ','g')))>=3
      and ' '||trim(regexp_replace(fin_private.fold_text(p_read),'[^a-z0-9]+',' ','g'))||' '
          like '% '||trim(regexp_replace(fin_private.fold_text(e),'[^a-z0-9]+',' ','g'))||' %'
  )
$function$;
--@@ 45 funcao fin_private.receipt_auto_paid_notice()
CREATE OR REPLACE FUNCTION fin_private.receipt_auto_paid_notice()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.status='approved'
     and old.status is distinct from 'approved'
     and (new.source='whatsapp' or coalesce(new.decision_reason,'') like 'Baixa automática:%') then
    perform conv_private.queue_pendency_paid_notice(new.profile_id,new.id);
  end if;
  return new;
end $function$;
--@@ 45 funcao fin_private.recurrence_due_date(p_competence date, p_day intege
CREATE OR REPLACE FUNCTION fin_private.recurrence_due_date(p_competence date, p_day integer, p_offset integer)
 RETURNS date
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select (date_trunc('month', p_competence::timestamp) + make_interval(months => p_offset)
    + make_interval(days => least(p_day, extract(day from (date_trunc('month', p_competence::timestamp)
      + make_interval(months => p_offset + 1) - interval '1 day'))::integer) - 1))::date
$function$;
--@@ 45 funcao fin_private.refresh_charge_status(p_charge uuid)
CREATE OR REPLACE FUNCTION fin_private.refresh_charge_status(p_charge uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.fin_member_charges%rowtype; st record; v_has boolean; v_status text; v_asof date; v_last date;
begin
  select * into c from public.fin_member_charges where id = p_charge for update;
  if c.status = 'canceled' then return 'canceled'; end if;
  select max(paid_on) into v_last from fin_private.charge_payments_effective where charge_id = p_charge;
  v_asof := greatest(fin_private.today(), coalesce(v_last, fin_private.today()));
  select * into st from fin_private.charge_statement(p_charge, v_asof);
  v_has := v_last is not null;
  v_status := case when st.settled then 'paid' when v_has then 'partial' else 'open' end;
  if v_status <> c.status then
    update public.fin_member_charges set status = v_status, version = version + 1, updated_at = now(), updated_by = auth.uid() where id = p_charge;
  end if;
  return v_status;
end $function$;
--@@ 45 funcao fin_private.require_admin()
CREATE OR REPLACE FUNCTION fin_private.require_admin()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not public.is_admin() then
    raise exception 'FINANCE_FORBIDDEN' using errcode = '42501';
  end if;
  return auth.uid();
end $function$;
--@@ 45 funcao fin_private.seed_holidays(p_year integer)
CREATE OR REPLACE FUNCTION fin_private.seed_holidays(p_year integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_easter date := fin_private.easter(p_year); v_n integer;
begin
  insert into public.fin_holidays(holiday_date, name, scope, kind, active)
  select * from (values
    (make_date(p_year, 1, 1), 'Confraternização Universal', 'national', 'holiday', false),
    (v_easter - 2, 'Sexta-feira Santa', 'national', 'holiday', false),
    (make_date(p_year, 4, 21), 'Tiradentes', 'national', 'holiday', false),
    (make_date(p_year, 5, 1), 'Dia do Trabalho', 'national', 'holiday', false),
    (make_date(p_year, 9, 7), 'Independência do Brasil', 'national', 'holiday', false),
    (make_date(p_year, 10, 12), 'Nossa Senhora Aparecida', 'national', 'holiday', false),
    (make_date(p_year, 11, 2), 'Finados', 'national', 'holiday', false),
    (make_date(p_year, 11, 15), 'Proclamação da República', 'national', 'holiday', false),
    (make_date(p_year, 12, 25), 'Natal', 'national', 'holiday', false),
    (v_easter - 48, 'Carnaval (segunda-feira)', 'national', 'optional', false),
    (v_easter - 47, 'Carnaval (terça-feira)', 'national', 'optional', false),
    (v_easter + 60, 'Corpus Christi', 'national', 'optional', false)
  ) v(d, n, s, k, a)
  on conflict (holiday_date, scope) do nothing;
  get diagnostics v_n = row_count;
  if p_year >= 2024 then
    insert into public.fin_holidays(holiday_date, name, scope, kind, active)
    values (make_date(p_year, 11, 20), 'Dia da Consciência Negra', 'national', 'holiday', false)
    on conflict (holiday_date, scope) do nothing;
  end if;
  return v_n;
end $function$;
--@@ 45 funcao fin_private.statement_json(p_charge uuid, p_as_of date)
CREATE OR REPLACE FUNCTION fin_private.statement_json(p_charge uuid, p_as_of date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select to_jsonb(s) from fin_private.charge_statement(p_charge, p_as_of) s $function$;
--@@ 45 funcao fin_private.today()
CREATE OR REPLACE FUNCTION fin_private.today()
 RETURNS date
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select (now() at time zone 'America/Fortaleza')::date $function$;
--@@ 45 funcao fin_private.waive_fees(p_charge uuid, p_amount bigint, p_reason
CREATE OR REPLACE FUNCTION fin_private.waive_fees(p_charge uuid, p_amount bigint, p_reason text, p_as_of date, p_request uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare st record; v_id uuid; v_before jsonb;
begin
  if p_reason is null or length(trim(p_reason)) < 5 then raise exception 'REASON_REQUIRED'; end if;
  if p_amount is null or p_amount <= 0 then raise exception 'INVALID_AMOUNT'; end if;
  perform 1 from public.fin_member_charges where id = p_charge for update;
  select * into st from fin_private.charge_statement(p_charge, p_as_of);
  if p_amount > st.fees_due then raise exception 'WAIVER_EXCEEDS_FEES'; end if;
  v_before := fin_private.statement_json(p_charge, p_as_of);
  insert into public.fin_charge_adjustments(charge_id, kind, amount_cents, reason, before_data, actor_id, request_id)
  values (p_charge, 'fee_waiver', p_amount, trim(p_reason), v_before, auth.uid(), p_request) returning id into v_id;
  update public.fin_charge_adjustments set after_data = fin_private.statement_json(p_charge, p_as_of) where id = v_id;
end $function$;
--@@ 45 funcao public.access_requests_set_updated_at()
CREATE OR REPLACE FUNCTION public.access_requests_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$;
--@@ 45 funcao public.admin_audit_changed_fields(p_old jsonb, p_new jsonb)
CREATE OR REPLACE FUNCTION public.admin_audit_changed_fields(p_old jsonb, p_new jsonb)
 RETURNS text[]
 LANGUAGE sql
 STABLE
AS $function$
    SELECT COALESCE(array_agg(key ORDER BY key), '{}')
    FROM (
        SELECT n.key
        FROM jsonb_each(COALESCE(p_new, '{}'::jsonb)) n
        FULL OUTER JOIN jsonb_each(COALESCE(p_old, '{}'::jsonb)) o USING (key)
        WHERE n.value IS DISTINCT FROM o.value
    ) changed;
$function$;
--@@ 45 funcao public.admin_audit_insert_log(p_action text, p_table_name text,
CREATE OR REPLACE FUNCTION public.admin_audit_insert_log(p_action text, p_table_name text DEFAULT NULL::text, p_record_id text DEFAULT NULL::text, p_target_user_id uuid DEFAULT NULL::uuid, p_related_user_ids uuid[] DEFAULT '{}'::uuid[], p_changed_fields text[] DEFAULT NULL::text[], p_old_data jsonb DEFAULT NULL::jsonb, p_new_data jsonb DEFAULT NULL::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb, p_source text DEFAULT 'trigger'::text, p_occurred_at timestamp with time zone DEFAULT now())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_actor UUID := auth.uid();
    v_actor_name TEXT;
    v_actor_role TEXT;
    v_target_name TEXT;
    v_log_id UUID;
BEGIN
    IF v_actor IS NOT NULL THEN
        SELECT p.name, p.role::text
        INTO v_actor_name, v_actor_role
        FROM public.profiles p
        WHERE p.id = v_actor;
    END IF;

    IF p_target_user_id IS NOT NULL THEN
        SELECT p.name
        INTO v_target_name
        FROM public.profiles p
        WHERE p.id = p_target_user_id;
    END IF;

    INSERT INTO public.admin_audit_logs (
        occurred_at,
        actor_user_id,
        actor_name_snapshot,
        actor_role,
        action,
        table_name,
        record_id,
        target_user_id,
        target_name_snapshot,
        related_user_ids,
        changed_fields,
        old_data,
        new_data,
        metadata,
        source
    ) VALUES (
        p_occurred_at,
        v_actor,
        v_actor_name,
        v_actor_role,
        p_action,
        p_table_name,
        p_record_id,
        p_target_user_id,
        v_target_name,
        COALESCE(p_related_user_ids, '{}'),
        p_changed_fields,
        p_old_data,
        p_new_data,
        COALESCE(p_metadata, '{}'::jsonb),
        p_source
    )
    RETURNING id INTO v_log_id;

    RETURN v_log_id;
END;
$function$;
--@@ 45 funcao public.admin_audit_related_users(p_table_name text, p_row jsonb
CREATE OR REPLACE FUNCTION public.admin_audit_related_users(p_table_name text, p_row jsonb)
 RETURNS uuid[]
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_ids UUID[] := '{}';
    v_key TEXT;
    v_candidate UUID;
    v_value JSONB;
BEGIN
    IF p_row IS NULL THEN
        RETURN v_ids;
    END IF;

    FOREACH v_key IN ARRAY ARRAY[
        'user_id',
        'creator_id',
        'player_a_id',
        'player_b_id',
        'winner_id',
        'winner_id',
        'challenger_id',
        'challenged_id',
        'decided_by',
        'executed_by'
    ] LOOP
        v_candidate := public.admin_audit_try_uuid(p_row ->> v_key);
        IF v_candidate IS NOT NULL THEN
            v_ids := array_append(v_ids, v_candidate);
        END IF;
    END LOOP;

    IF p_table_name = 'profiles' THEN
        v_candidate := public.admin_audit_try_uuid(p_row ->> 'id');
        IF v_candidate IS NOT NULL THEN
            v_ids := array_append(v_ids, v_candidate);
        END IF;
    END IF;

    IF jsonb_typeof(p_row -> 'participant_ids') = 'array' THEN
        FOR v_value IN SELECT value FROM jsonb_array_elements(p_row -> 'participant_ids') LOOP
            v_candidate := public.admin_audit_try_uuid(trim(both '"' from v_value::text));
            IF v_candidate IS NOT NULL THEN
                v_ids := array_append(v_ids, v_candidate);
            END IF;
        END LOOP;
    END IF;

    RETURN COALESCE(ARRAY(SELECT DISTINCT unnest(v_ids)), '{}');
END;
$function$;
--@@ 45 funcao public.admin_audit_table_changes()
CREATE OR REPLACE FUNCTION public.admin_audit_table_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_old JSONB := NULL;
    v_new JSONB := NULL;
    v_action TEXT := lower(TG_OP);
    v_row JSONB;
    v_record_id TEXT;
    v_related UUID[];
    v_target UUID;
    v_changed TEXT[];
BEGIN
    IF TG_TABLE_NAME = 'admin_audit_logs' THEN
        IF TG_OP = 'DELETE' THEN
            RETURN OLD;
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP IN ('UPDATE', 'DELETE') THEN
        v_old := to_jsonb(OLD);
    END IF;

    IF TG_OP IN ('INSERT', 'UPDATE') THEN
        v_new := to_jsonb(NEW);
        v_row := v_new;
    ELSE
        v_row := v_old;
    END IF;

    v_record_id := COALESCE(v_row ->> 'id', v_row ->> 'uuid');
    v_related := public.admin_audit_related_users(TG_TABLE_NAME, v_row);
    v_target := NULLIF(v_related[1]::text, '')::uuid;

    IF TG_OP = 'UPDATE' THEN
        v_changed := public.admin_audit_changed_fields(v_old, v_new);
        IF COALESCE(array_length(v_changed, 1), 0) = 0 THEN
            RETURN NEW;
        END IF;
    ELSE
        v_changed := NULL;
    END IF;

    PERFORM public.admin_audit_insert_log(
        v_action,
        TG_TABLE_NAME,
        v_record_id,
        v_target,
        v_related,
        v_changed,
        v_old,
        v_new,
        '{}'::jsonb,
        'trigger',
        NOW()
    );

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;

    RETURN NEW;
END;
$function$;
--@@ 45 funcao public.admin_audit_try_uuid(p_value text)
CREATE OR REPLACE FUNCTION public.admin_audit_try_uuid(p_value text)
 RETURNS uuid
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
    IF p_value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RETURN p_value::uuid;
    END IF;

    RETURN NULL;
END;
$function$;
--@@ 45 funcao public.admin_record_user_access(p_event text, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.admin_record_user_access(p_event text DEFAULT 'app_open'::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_actor UUID := auth.uid();
    v_event TEXT := COALESCE(NULLIF(BTRIM(p_event), ''), 'app_open');
BEGIN
    IF v_actor IS NULL THEN
        RAISE EXCEPTION 'Usuário não autenticado.' USING ERRCODE = '42501';
    END IF;

    IF v_event NOT IN ('login', 'app_open') THEN
        RAISE EXCEPTION 'Evento de acesso inválido.' USING ERRCODE = '22023';
    END IF;

    RETURN public.admin_audit_insert_log(
        v_event,
        NULL,
        NULL,
        v_actor,
        ARRAY[v_actor],
        NULL,
        NULL,
        NULL,
        COALESCE(p_metadata, '{}'::jsonb),
        CASE WHEN v_event = 'login' THEN 'auth' ELSE 'app' END,
        NOW()
    );
END;
$function$;
--@@ 45 funcao public.admin_record_user_login(p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.admin_record_user_login(p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    RETURN public.admin_record_user_access('login', COALESCE(p_metadata, '{}'::jsonb));
END;
$function$;
--@@ 45 funcao public.admin_reset_ranking_full(p_confirmation text, p_reason t
CREATE OR REPLACE FUNCTION public.admin_reset_ranking_full(p_confirmation text DEFAULT NULL::text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_actor UUID := auth.uid();
    v_event_id UUID;
    v_now TIMESTAMPTZ := NOW();
    v_affected_profiles INTEGER := 0;
BEGIN
    IF v_actor IS NULL THEN
        RAISE EXCEPTION 'Usuário não autenticado.' USING ERRCODE = '42501';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.profiles p
        WHERE p.id = v_actor
          AND p.role::text = 'admin'
    ) THEN
        RAISE EXCEPTION 'Apenas administradores podem zerar o ranking.' USING ERRCODE = '42501';
    END IF;

    IF COALESCE(BTRIM(p_confirmation), '') <> 'ZERAR' THEN
        RAISE EXCEPTION 'Confirmação inválida. Digite ZERAR para continuar.' USING ERRCODE = '22023';
    END IF;

    -- Prevent concurrent resets and keep cycle event ordering consistent
    LOCK TABLE public.ranking_reset_events IN EXCLUSIVE MODE;

    UPDATE public.profiles
    SET
        legacy_wins = 0,
        legacy_losses = 0,
        legacy_sets_won = 0,
        legacy_sets_lost = 0,
        legacy_games_won = 0,
        legacy_games_lost = 0,
        legacy_tiebreaks_won = 0,
        legacy_tiebreaks_lost = 0,
        legacy_matches_played = 0,
        legacy_matches_with_tiebreak = 0,
        legacy_points = 0
    WHERE role::text IN ('socio', 'admin')
      AND COALESCE(is_active, TRUE) = TRUE;

    GET DIAGNOSTICS v_affected_profiles = ROW_COUNT;

    INSERT INTO public.ranking_reset_events (
        executed_by,
        reason,
        reset_scope,
        executed_at
    ) VALUES (
        v_actor,
        NULLIF(BTRIM(p_reason), ''),
        'full',
        v_now
    )
    RETURNING id INTO v_event_id;

    RETURN jsonb_build_object(
        'event_id', v_event_id,
        'executed_at', v_now,
        'affected_profiles', v_affected_profiles,
        'reset_scope', 'full'
    );
END;
$function$;
--@@ 45 funcao public.apagar_mensagem_antiga()
CREATE OR REPLACE FUNCTION public.apagar_mensagem_antiga()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
BEGIN
    UPDATE public.Memory_Long
    SET message_text = NULL
    WHERE
        message_text IS NOT NULL -- Apenas se ainda houver conteúdo para apagar
        AND update_at IS NOT NULL
        AND update_at < NOW() - INTERVAL '24 hours'; -- Se o update_at for anterior a 24h atrás
END;
$function$;
--@@ 45 funcao public.apply_championship_edition_points(p_championship_id uuid
CREATE OR REPLACE FUNCTION public.apply_championship_edition_points(p_championship_id uuid)
 RETURNS TABLE(user_id uuid, phase text, earned_points integer, defended_points integer, net_change integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_series_id     UUID;
    v_edition_year  INTEGER;
    v_prev_champ_id UUID;
    v_reg           RECORD;
    v_profile_class TEXT;
    v_raw_pts       INTEGER;
    v_final_pts     INTEGER;
    v_defended_pts  INTEGER;
    v_is_lower      BOOLEAN;
    v_reason        TEXT;
BEGIN
    SELECT c.series_id, c.edition_year
    INTO   v_series_id, v_edition_year
    FROM   public.championships c
    WHERE  c.id = p_championship_id;

    IF v_series_id IS NULL THEN
        RAISE EXCEPTION 'Championship % has no series_id. Assign it to a series first.', p_championship_id;
    END IF;

    SELECT c.id INTO v_prev_champ_id
    FROM   public.championships c
    WHERE  c.series_id   = v_series_id
      AND  c.edition_year < v_edition_year
    ORDER  BY c.edition_year DESC
    LIMIT  1;

    FOR v_reg IN
        SELECT cr.id AS reg_id,
               cr.user_id,
               cr.class AS reg_class,
               cr.final_phase
        FROM   public.championship_registrations cr
        WHERE  cr.championship_id  = p_championship_id
          AND  cr.participant_type = 'socio'
          AND  cr.final_phase      IS NOT NULL
          AND  cr.user_id          IS NOT NULL
          AND  (
              cr.class = '5ª Classe'
              OR NOT EXISTS (
                  SELECT 1
                  FROM public.championship_registrations cr_5
                  WHERE cr_5.championship_id = cr.championship_id
                    AND cr_5.user_id = cr.user_id
                    AND cr_5.class = '5ª Classe'
              )
          )
        ORDER BY cr.user_id, cr.created_at
    LOOP
        IF EXISTS (
            SELECT 1
            FROM public.point_history ph
            WHERE ph.user_id = v_reg.user_id
              AND ph.event_id = p_championship_id
              AND ph.reason IN ('championship_earn', 'championship_earn_lower_class')
        ) THEN
            CONTINUE;
        END IF;

        SELECT p.category INTO v_profile_class
        FROM   public.profiles p
        WHERE  p.id = v_reg.user_id;

        v_raw_pts := public.get_championship_phase_points(v_reg.final_phase);
        IF v_raw_pts IS NULL THEN
            v_raw_pts := 5;
        END IF;

        v_is_lower := public.is_lower_class(v_reg.reg_class, v_profile_class);

        IF v_is_lower THEN
            v_final_pts := FLOOR(v_raw_pts::NUMERIC / 2)::INTEGER;
            v_reason    := 'championship_earn_lower_class';
        ELSE
            v_final_pts := v_raw_pts;
            v_reason    := 'championship_earn';
        END IF;

        v_defended_pts := 0;
        IF v_prev_champ_id IS NOT NULL THEN
            SELECT COALESCE(SUM(ph.amount), 0) INTO v_defended_pts
            FROM   public.point_history ph
            WHERE  ph.user_id  = v_reg.user_id
              AND  ph.event_id = v_prev_champ_id
              AND  ph.reason IN ('championship_earn', 'championship_earn_lower_class')
              AND  ph.status   = 'active';

            IF v_defended_pts > 0 THEN
                INSERT INTO public.point_history (
                    user_id, amount, event_type, event_id,
                    description, earned_date, expires_at,
                    series_id, edition_year, phase, registration_class, reason, status
                ) VALUES (
                    v_reg.user_id,
                    -v_defended_pts,
                    'Campeonato',
                    v_prev_champ_id,
                    'Defesa: remoção de pontos da edição anterior',
                    NOW()::DATE,
                    NOW()::DATE,
                    v_series_id,
                    v_edition_year,
                    v_reg.final_phase,
                    v_reg.reg_class,
                    'defense_removal',
                    'active'
                );

                UPDATE public.point_history ph
                SET    status = 'revoked'
                WHERE  ph.user_id  = v_reg.user_id
                  AND  ph.event_id = v_prev_champ_id
                  AND  ph.reason IN ('championship_earn', 'championship_earn_lower_class');
            END IF;
        END IF;

        INSERT INTO public.point_history (
            user_id, amount, event_type, event_id,
            description, earned_date, expires_at,
            series_id, edition_year, phase, registration_class, reason, status
        ) VALUES (
            v_reg.user_id,
            v_final_pts,
            'Campeonato',
            p_championship_id,
            'Campeonato ' || v_edition_year || ' - ' || v_reg.final_phase ||
                CASE WHEN v_is_lower THEN ' (classe inferior, /2)' ELSE '' END,
            NOW()::DATE,
            (NOW() + INTERVAL '2 years')::DATE,
            v_series_id,
            v_edition_year,
            v_reg.final_phase,
            v_reg.reg_class,
            v_reason,
            'active'
        );

        UPDATE public.profiles p
        SET    legacy_points = COALESCE(p.legacy_points, 0) + v_final_pts - v_defended_pts
        WHERE  p.id = v_reg.user_id;

        RETURN QUERY SELECT
            v_reg.user_id,
            v_reg.final_phase,
            v_final_pts,
            v_defended_pts,
            v_final_pts - v_defended_pts;
    END LOOP;
END;
$function$;
--@@ 45 funcao public.bootstrap_ranking_from_3_circuito(p_dry_run boolean)
CREATE OR REPLACE FUNCTION public.bootstrap_ranking_from_3_circuito(p_dry_run boolean DEFAULT true)
 RETURNS TABLE(user_id uuid, name text, registration_class text, current_class text, phase text, raw_points integer, applied_points integer, class_adjusted boolean, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_champ_id      UUID;
    v_series_id     UUID;
    v_edition_year  INTEGER;
    v_reg           RECORD;
    v_profile_class TEXT;
    v_raw_pts       INTEGER;
    v_final_pts     INTEGER;
    v_is_lower      BOOLEAN;
    v_reason        TEXT;
BEGIN
    -- Only admins
    IF NOT EXISTS (
        SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin'
    ) THEN
        RAISE EXCEPTION 'Permission denied.' USING ERRCODE = '42501';
    END IF;

    -- Locate the 3rd Circuito de Inverno championship
    SELECT c.id, c.series_id, c.edition_year
    INTO   v_champ_id, v_series_id, v_edition_year
    FROM   public.championships c
    JOIN   public.championship_series cs ON cs.id = c.series_id
    WHERE  cs.slug = 'circuito-de-inverno'
      AND  c.edition_year = 2026
    LIMIT  1;

    IF v_champ_id IS NULL THEN
        RAISE EXCEPTION '3rd Circuito de Inverno (edition_year=2026) not found. Run migration 20260422100000 backfill first.';
    END IF;

    -- Ensure final_phase is set on registrations for this championship
    -- (admins must have set them via the admin panel before running this)
    IF NOT EXISTS (
        SELECT 1 FROM public.championship_registrations
        WHERE  championship_id = v_champ_id AND final_phase IS NOT NULL
    ) THEN
        RAISE EXCEPTION 'No final_phase set for 3rd Circuito de Inverno registrations. Set them via the admin panel first.';
    END IF;

    -- ── Dry-run: return diff without committing ──────────────────────────────
    FOR v_reg IN
        SELECT cr.user_id,
               p.name,
               cr.class        AS reg_class,
               p.category      AS profile_class,
               cr.final_phase
        FROM   public.championship_registrations cr
        JOIN   public.profiles p ON p.id = cr.user_id
        WHERE  cr.championship_id  = v_champ_id
          AND  cr.participant_type = 'socio'
          AND  cr.final_phase      IS NOT NULL
          AND  cr.user_id          IS NOT NULL
    LOOP
        v_raw_pts    := COALESCE(public.get_championship_phase_points(v_reg.final_phase), 5);
        v_is_lower   := public.is_lower_class(v_reg.reg_class, v_reg.profile_class);
        v_final_pts  := CASE WHEN v_is_lower
                             THEN FLOOR(v_raw_pts::NUMERIC / 2)::INTEGER
                             ELSE v_raw_pts END;
        v_reason     := CASE WHEN v_is_lower
                             THEN 'championship_earn_lower_class'
                             ELSE 'championship_earn' END;

        RETURN QUERY SELECT
            v_reg.user_id,
            v_reg.name,
            v_reg.reg_class,
            v_reg.profile_class,
            v_reg.final_phase,
            v_raw_pts,
            v_final_pts,
            v_is_lower,
            v_reason;
    END LOOP;

    -- ── If not dry-run, commit the reset + reapplication ────────────────────
    IF NOT p_dry_run THEN
        -- a) Snapshot current class state into class_change_events (state baseline)
        INSERT INTO public.class_change_events (
            user_id, from_class, to_class, points_before, points_after, changed_by
        )
        SELECT
            p.id,
            p.category,
            p.category,
            COALESCE(p.legacy_points, 0),
            COALESCE(p.legacy_points, 0),
            auth.uid()
        FROM   public.profiles p
        WHERE  p.role IN ('socio', 'admin')
          AND  p.is_active = TRUE
        ON CONFLICT DO NOTHING;

        -- b) Full ranking reset (zeros legacy_points on all profiles)
        PERFORM public.admin_reset_ranking_full(
            'Corte inicial — reinício do ranking a partir do 3º Circuito de Inverno',
            'bootstrap_ranking_from_3_circuito'
        );

        -- c) Apply 3rd Circuito points (via existing idempotent function)
        --    Note: apply_championship_edition_points handles class comparison internally.
        PERFORM public.apply_championship_edition_points(v_champ_id);

        -- d) Log in ranking_reset_events
        INSERT INTO public.ranking_reset_events (reason, notes)
        VALUES (
            'refactor_points_from_3_circuito_inverno',
            'Aplicação inicial: 3º Circuito de Inverno (edition_year=2026, dry_run=false)'
        )
        ON CONFLICT DO NOTHING;
    END IF;
END;
$function$;
--@@ 45 funcao public.check_and_auto_finish_championship()
CREATE OR REPLACE FUNCTION public.check_and_auto_finish_championship()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_champ_status       TEXT;
    v_is_resenha_open    BOOLEAN;
    v_final_finished     BOOLEAN;
    v_unfinished_matches INTEGER;
BEGIN
    -- Only act when a match status is updated to 'finished'
    IF NEW.status <> 'finished' OR NEW.championship_id IS NULL THEN
        RETURN NEW;
    END IF;
    IF OLD.status = 'finished' THEN
        RETURN NEW; -- already processed
    END IF;

    -- Fetch championship status
    SELECT status INTO v_champ_status
    FROM public.championships
    WHERE id = NEW.championship_id;

    -- Only auto-finish active/ongoing championships
    IF v_champ_status NOT IN ('active', 'ongoing') THEN
        RETURN NEW;
    END IF;

    -- Check remaining unfinished matches for this championship
    SELECT COUNT(*) INTO v_unfinished_matches
    FROM public.matches
    WHERE championship_id = NEW.championship_id
      AND status <> 'finished';

    -- If all existing matches for this championship are completed
    IF v_unfinished_matches = 0 THEN
        -- Verify that a final match has actually been completed
        SELECT EXISTS (
            SELECT 1
            FROM public.matches m
            JOIN public.championship_rounds r ON r.id = m.round_id
            WHERE m.championship_id = NEW.championship_id
              AND (r.phase ILIKE '%final%' OR r.phase IN ('final', 'Final') OR r.name ILIKE '%final%')
              AND COALESCE(r.phase, '') NOT ILIKE '%semi%'
              AND m.status = 'finished'
        ) INTO v_final_finished;

        IF v_final_finished THEN
            -- Check if it's a Resenha Open championship to resolve its official phases first
            SELECT (name ILIKE '%resenha open%' OR COALESCE(slug, '') ILIKE '%resenha-open%') INTO v_is_resenha_open
            FROM public.championships
            WHERE id = NEW.championship_id;

            IF v_is_resenha_open THEN
                PERFORM public.resolve_resenha_open_final_phases(NEW.championship_id);
            END IF;

            -- Update championship status to 'finished'.
            -- This automatically activates trg_apply_championship_points_on_finish
            -- which resolves final phases and credits ranking points to all socios!
            UPDATE public.championships
            SET status = 'finished'
            WHERE id = NEW.championship_id;
        END IF;
    END IF;

    RETURN NEW;
END;
$function$;
--@@ 45 funcao public.class_rank(p_class text)
CREATE OR REPLACE FUNCTION public.class_rank(p_class text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
    SELECT COALESCE(
        (regexp_match(COALESCE(p_class, ''), '(\d+)'))[1]::INTEGER,
        999
    );
$function$;
--@@ 45 funcao public.clean_model_text(input_text text)
CREATE OR REPLACE FUNCTION public.clean_model_text(input_text text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
  t text := COALESCE(input_text,'');
  rec record;
  key_escaped text;
BEGIN
  IF t = '' THEN RETURN NULL; END IF;
  -- Normalize spacing
  t := regexp_replace(t, '\s+', ' ', 'g');
  -- Remove common compatibility phrases (case-insensitive) using 'i' flag
  t := regexp_replace(t, 'compativel com|compat[ií]vel com|compativel|compat[ií]vel', '', 'gi');
  -- Trim
  t := trim(both ' -,;:' from t);
  -- Apply mappings from brand corrections
  FOR rec IN SELECT * FROM public.marca_correcoes LOOP
    key_escaped := public.escape_for_regexp(rec.chave);
    IF rec.correicao = '' THEN
      -- remove the key occurrences using safer boundary matching with POSIX classes
      t := regexp_replace(t, '(^|[[:space:],;:\/\-])' || key_escaped || '([[:space:],;:\/\-]|$)', ' ', 'gi');
    ELSE
      t := regexp_replace(t, '(^|[[:space:],;:\/\-])' || key_escaped || '([[:space:],;:\/\-]|$)', '\1' || rec.correicao || '\2', 'gi');
    END IF;
  END LOOP;
  -- Clean extra spaces and commas
  t := regexp_replace(t, '\s*,\s*', ', ', 'g');
  t := regexp_replace(t, '\s+', ' ', 'g');
  t := trim(both ' ,-' from t);
  RETURN t;
END; $function$;
--@@ 45 funcao public.conv_add_followup(p_conversation uuid, p_due_at timestam
CREATE OR REPLACE FUNCTION public.conv_add_followup(p_conversation uuid, p_due_at timestamp with time zone, p_note text, p_send_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
  perform conv_private.require_admin();
  if p_due_at is null or p_due_at < now() - interval '1 minute' then raise exception 'INVALID_DUE_DATE'; end if;
  if nullif(trim(coalesce(p_note, '')), '') is null and nullif(trim(coalesce(p_send_body, '')), '') is null then raise exception 'FOLLOWUP_EMPTY'; end if;
  insert into public.conv_followups(conversation_id, due_at, note, send_body, created_by)
  values (p_conversation, p_due_at, nullif(trim(p_note), ''), nullif(trim(p_send_body), ''), auth.uid()) returning id into v_id;
  return v_id;
end $function$;
--@@ 45 funcao public.conv_add_note(p_conversation uuid, p_body text)
CREATE OR REPLACE FUNCTION public.conv_add_note(p_conversation uuid, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
  perform conv_private.require_admin();
  if length(trim(coalesce(p_body, ''))) not between 1 and 4000 then raise exception 'BODY_REQUIRED'; end if;
  insert into public.conv_notes(conversation_id, body, author_id) values (p_conversation, trim(p_body), auth.uid()) returning id into v_id;
  return v_id;
end $function$;
