end $function$;
--@@ 45 funcao public.conv_inbox(p_filter text, p_search text, p_limit integer
CREATE OR REPLACE FUNCTION public.conv_inbox(p_filter text DEFAULT 'open'::text, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 100)
 RETURNS TABLE(id uuid, kind text, status text, title text, destination text, contact_id uuid, group_id uuid, avatar_url text, profile_id uuid, profile_name text, student_id uuid, link_status text, opt_out boolean, last_message_at timestamp with time zone, last_body text, last_message_kind text, last_direction text, last_status text, last_origin text, last_deleted boolean, unread_count integer, tags text[], assigned_to uuid, assigned_name text, next_followup_at timestamp with time zone, waiting_since timestamp with time zone, ai_status text, handoff_kind text, handoff_note text, handoff_at timestamp with time zone, ai_session_open boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_search text := nullif(trim(coalesce(p_search, '')), ''); v_digits text;
begin
  perform conv_private.require_admin();
  v_digits := conv_private.digits(v_search);
  return query
  select cv.id, cv.kind, cv.status,
    coalesce(case when c.name is not null and c.name !~ '^[0-9+ ()-]+$' then c.name end, pr.name, c.name, g.name,
             case when c.phone is not null then '+' || c.phone end, 'Contato'),
    coalesce(c.phone, g.group_jid), c.id, g.id, c.avatar_url,
    c.profile_id, pr.name, c.non_socio_student_id, c.link_status, coalesce(c.opt_out, false),
    coalesce(cv.last_message_at, cv.created_at), m.body, m.kind, m.direction, m.status, m.origin, m.deleted_at is not null,
    (select count(*)::integer from public.conv_messages i where i.conversation_id = cv.id and i.direction = 'inbound'
       and i.created_at > coalesce(cv.staff_read_at, '-infinity'::timestamptz)),
    cv.tags, cv.assigned_to, s.name,
    (select min(f.due_at) from public.conv_followups f where f.conversation_id = cv.id and f.status = 'pending'),
    case when m.direction = 'inbound' then coalesce(cv.last_message_at, cv.created_at) end,
    cv.ai_status, cv.handoff_kind, cv.handoff_note, cv.handoff_at,
    exists (select 1 from public.conv_ai_sessions x where x.conversation_id = cv.id and x.status = 'open' and x.expires_at > now())
  from public.conv_conversations cv
  left join public.conv_contacts c on c.id = cv.contact_id
  left join public.conv_groups g on g.id = cv.group_id
  left join public.profiles pr on pr.id = c.profile_id
  left join public.profiles s on s.id = cv.assigned_to
  left join lateral (
    select x.body, x.kind, x.direction, x.status, x.origin, x.deleted_at from public.conv_messages x
    where x.conversation_id = cv.id order by x.created_at desc limit 1) m on true
  where cv.merged_into is null
    and case coalesce(p_filter, 'open')
      when 'closed' then cv.status = 'closed'
      when 'all' then true
      when 'groups' then cv.status = 'open' and cv.kind = 'group'
      when 'unread' then cv.status = 'open' and exists (select 1 from public.conv_messages i where i.conversation_id = cv.id
        and i.direction = 'inbound' and i.created_at > coalesce(cv.staff_read_at, '-infinity'::timestamptz))
      when 'waiting' then cv.status = 'open' and m.direction = 'inbound'
      when 'mine' then cv.status = 'open' and cv.assigned_to = auth.uid()
      when 'followup' then exists (select 1 from public.conv_followups f where f.conversation_id = cv.id and f.status = 'pending'
        and f.due_at < (date_trunc('day', now() at time zone 'America/Fortaleza') + interval '1 day') at time zone 'America/Fortaleza')
      when 'ai' then cv.status = 'open' and cv.ai_status = 'ai'
        and exists (select 1 from public.conv_ai_sessions x where x.conversation_id = cv.id and x.status = 'open' and x.expires_at > now())
      when 'handoff' then cv.status = 'open' and (cv.ai_status = 'human' or cv.kind = 'group') and cv.handoff_at is not null
        and cv.handoff_at >= coalesce(cv.last_staff_at, '-infinity'::timestamptz)
      else cv.status = 'open' end
    and (v_search is null
         or c.name ilike '%' || v_search || '%' or g.name ilike '%' || v_search || '%' or pr.name ilike '%' || v_search || '%'
         or v_search = any (cv.tags)
         or (length(v_digits) >= 3 and c.phone like '%' || v_digits || '%'))
  order by coalesce(cv.last_message_at, cv.created_at) desc
  limit greatest(least(coalesce(p_limit, 100), 200), 1);
end $function$;
--@@ 45 funcao public.conv_link_contact(p_contact uuid, p_profile uuid, p_stud
CREATE OR REPLACE FUNCTION public.conv_link_contact(p_contact uuid, p_profile uuid, p_student uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old public.conv_contacts%rowtype;
begin
  perform conv_private.require_admin();
  if p_profile is not null and p_student is not null then raise exception 'LINK_ONE_ONLY'; end if;
  select * into v_old from public.conv_contacts where id = p_contact for update;
  if not found then raise exception 'CONTACT_NOT_FOUND'; end if;
  if p_profile is not null and not exists (select 1 from public.profiles where id = p_profile) then raise exception 'PROFILE_NOT_FOUND'; end if;
  if p_student is not null and not exists (select 1 from public.non_socio_students where id = p_student) then raise exception 'STUDENT_NOT_FOUND'; end if;
  update public.conv_contacts set profile_id = p_profile, non_socio_student_id = p_student,
    link_status = case when p_profile is null and p_student is null then 'none' else 'manual' end, updated_at = now()
  where id = p_contact;
  perform conv_private.audit('contact_link', 'conv_contacts', p_contact::text,
    jsonb_build_object('profile_id', v_old.profile_id, 'student_id', v_old.non_socio_student_id, 'link_status', v_old.link_status),
    jsonb_build_object('profile_id', p_profile, 'student_id', p_student), jsonb_build_object('actor', 'admin'), p_profile);
  if p_profile is not null or p_student is not null then
    perform conv_private.dedupe_contact(p_contact);
  end if;
end $function$;
--@@ 45 funcao public.conv_list_ai_memory_candidates(p_status text)
CREATE OR REPLACE FUNCTION public.conv_list_ai_memory_candidates(p_status text DEFAULT 'pending'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform conv_private.require_admin();
  if p_status not in ('pending', 'approved', 'rejected', 'superseded') then raise exception 'INVALID_STATUS'; end if;
  return (
    select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc), '[]'::jsonb)
    from (
      select c.id, c.subject_name, c.kind, c.content, c.confidence, c.status, c.created_at, c.reviewed_at,
             (select left(m.body, 240) from public.conv_messages m where m.id = c.source_message_id) as source_body
      from public.conv_ai_memory_candidates c
      where c.status = p_status
      order by c.created_at desc
      limit 100
    ) x
  );
end $function$;
--@@ 45 funcao public.conv_open_conversation(p_phone text, p_name text)
CREATE OR REPLACE FUNCTION public.conv_open_conversation(p_phone text, p_name text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_contact uuid;
begin
  perform conv_private.require_admin();
  if conv_private.phone_e164(p_phone) is null or length(conv_private.phone_e164(p_phone)) < 12 then raise exception 'INVALID_PHONE'; end if;
  v_contact := conv_private.upsert_contact(p_phone, null, p_name, true);
  return conv_private.open_direct(v_contact);
end $function$;
--@@ 45 funcao public.conv_review_ai_memory_candidate(p_id uuid, p_decision te
CREATE OR REPLACE FUNCTION public.conv_review_ai_memory_candidate(p_id uuid, p_decision text, p_content text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old public.conv_ai_memory_candidates%rowtype; v_content text;
begin
  perform conv_private.require_admin();
  if p_decision not in ('approved', 'rejected') then raise exception 'INVALID_DECISION'; end if;
  select * into v_old from public.conv_ai_memory_candidates where id = p_id for update;
  if not found then raise exception 'CANDIDATE_NOT_FOUND'; end if;
  v_content := left(coalesce(nullif(trim(p_content), ''), v_old.content), 500);
  if char_length(v_content) < 3 then raise exception 'CONTENT_TOO_SHORT'; end if;
  update public.conv_ai_memory_candidates
     set status = p_decision, content = v_content, reviewed_at = now(), reviewed_by = auth.uid()
   where id = p_id;
  perform conv_private.audit('ai_memory_review', 'conv_ai_memory_candidates', p_id::text,
    jsonb_build_object('status', v_old.status, 'content', v_old.content),
    jsonb_build_object('status', p_decision, 'content', v_content),
    jsonb_build_object('actor', 'admin', 'subject', v_old.subject_name, 'kind', v_old.kind));
  return jsonb_build_object('id', p_id, 'status', p_decision);
end $function$;
--@@ 45 funcao public.conv_rotate_inbound_token(p_request uuid, p_token text)
CREATE OR REPLACE FUNCTION public.conv_rotate_inbound_token(p_request uuid, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_replay jsonb;
begin
  perform conv_private.require_admin();
  v_replay := conv_private.begin_op(p_request, 'token_rotate');
  if v_replay is not null then return v_replay - 'token'; end if;
  if p_token is null or p_token !~ '^[0-9A-Za-z_-]{32,128}$' then raise exception 'INVALID_TOKEN'; end if;
  update public.conv_channel set inbound_token_hash = encode(sha256(convert_to(p_token, 'UTF8')), 'hex'),
    inbound_token_rotated_at = now(), version = version + 1, updated_at = now(), updated_by = auth.uid() where id;
  perform conv_private.audit('token_rotate', 'conv_channel', 'channel', null, jsonb_build_object('rotated', true), jsonb_build_object('actor', 'admin'));
  -- O resultado gravado em `conv_requests` NÃO guarda o token.
  return conv_private.finish_op(p_request, jsonb_build_object('rotated', true));
end $function$;
--@@ 45 funcao public.conv_save_ai_settings(p_request uuid, p jsonb)
CREATE OR REPLACE FUNCTION public.conv_save_ai_settings(p_request uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_replay jsonb; v_old public.conv_ai_settings%rowtype; v_version integer; v_model text; v_active boolean;
begin
  perform conv_private.require_admin();
  v_replay := conv_private.begin_op(p_request, 'ai_settings_save');
  if v_replay is not null then return v_replay; end if;
  select * into v_old from public.conv_ai_settings order by version desc limit 1 for update;
  v_version := v_old.version + 1;
  v_model := left(coalesce(nullif(trim(p->>'model'), ''), v_old.model), 120);
  v_active := coalesce((p->>'active')::boolean, v_old.active);
  if v_active and length(trim(v_model)) = 0 then raise exception 'AI_MODEL_REQUIRED'; end if;
  update public.conv_ai_settings set active = false where active;
  insert into public.conv_ai_settings(version, active, persona_name, model, instructions, business_context, buffer_seconds, max_turns,
    handoff_keywords, daily_turn_budget, proposal_ttl_minutes, created_by)
  values (v_version, v_active,
    left(coalesce(nullif(trim(p->>'persona_name'), ''), v_old.persona_name), 40), v_model,
    left(coalesce(p->>'instructions', v_old.instructions), 6000), left(coalesce(p->>'business_context', v_old.business_context), 6000),
    least(greatest(coalesce((p->>'buffer_seconds')::int, v_old.buffer_seconds), 0), 60),
    least(greatest(coalesce((p->>'max_turns')::int, v_old.max_turns), 1), 100),
    case when jsonb_typeof(p->'handoff_keywords') = 'array'
      then array(select left(lower(trim(k)), 40) from jsonb_array_elements_text(p->'handoff_keywords') k where length(trim(k)) > 0)
      else v_old.handoff_keywords end,
    least(greatest(coalesce((p->>'daily_turn_budget')::int, v_old.daily_turn_budget), 1), 5000),
    least(greatest(coalesce((p->>'proposal_ttl_minutes')::int, v_old.proposal_ttl_minutes), 2), 120), auth.uid());
  perform conv_private.audit('ai_settings_save', 'conv_ai_settings', v_version::text,
    jsonb_build_object('active', v_old.active, 'model', v_old.model), jsonb_build_object('active', v_active, 'model', v_model),
    jsonb_build_object('actor', 'admin', 'version', v_version));
  return conv_private.finish_op(p_request, jsonb_build_object('version', v_version));
end $function$;
--@@ 45 funcao public.conv_save_automation(p_request uuid, p_id uuid, p jsonb)
CREATE OR REPLACE FUNCTION public.conv_save_automation(p_request uuid, p_id uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; v_old public.conv_automations%rowtype; a public.conv_automations%rowtype; v_changed boolean;
begin
  v_actor := conv_private.require_admin();
  v_replay := conv_private.begin_op(p_request, case when p_id is null then 'automation_create' else 'automation_update' end);
  if v_replay is not null then return v_replay; end if;
  if p_id is null then
    insert into public.conv_automations(name, description, objective, source, trigger_type, definition, schedule, message_body, created_by, updated_by)
    values (trim(coalesce(p->>'name', '')), left(coalesce(p->>'description', ''), 500), left(coalesce(p->>'objective', ''), 300),
      p->>'source', p->>'trigger_type', coalesce(p->'definition', '{}'::jsonb), coalesce(p->'schedule', '{}'::jsonb),
      left(coalesce(p->>'message_body', ''), 1000), v_actor, v_actor) returning * into a;
    insert into public.conv_automation_versions(automation_id, version, definition, schedule, message_body, trigger_type, created_by)
    values (a.id, 1, a.definition, a.schedule, a.message_body, a.trigger_type, v_actor);
    perform conv_private.audit('automation_create', 'conv_automations', a.id::text, null,
      jsonb_build_object('name', a.name, 'source', a.source, 'trigger_type', a.trigger_type), jsonb_build_object('actor', 'admin'));
  else
    select * into v_old from public.conv_automations where id = p_id for update;
    if not found then raise exception 'AUTOMATION_NOT_FOUND'; end if;
    if v_old.status = 'ended' then raise exception 'AUTOMATION_ENDED'; end if;
    -- Origem e tipo não mudam depois de criada: seria outra automação.
    if (p ? 'source' and p->>'source' <> v_old.source) or (p ? 'trigger_type' and p->>'trigger_type' <> v_old.trigger_type) then raise exception 'AUTOMATION_KIND_FIXED'; end if;
    v_changed := (p ? 'definition' and p->'definition' <> v_old.definition) or (p ? 'schedule' and p->'schedule' <> v_old.schedule)
      or (p ? 'message_body' and p->>'message_body' <> v_old.message_body);
    update public.conv_automations set
      name = coalesce(nullif(trim(p->>'name'), ''), name), description = coalesce(left(p->>'description', 500), description),
      objective = coalesce(left(p->>'objective', 300), objective), definition = coalesce(p->'definition', definition),
      schedule = coalesce(p->'schedule', schedule), message_body = coalesce(left(p->>'message_body', 1000), message_body),
      version = version + case when v_changed then 1 else 0 end, updated_by = v_actor, updated_at = now()
    where id = p_id returning * into a;
    if v_changed then
      insert into public.conv_automation_versions(automation_id, version, definition, schedule, message_body, trigger_type, created_by)
      values (a.id, a.version, a.definition, a.schedule, a.message_body, a.trigger_type, v_actor);
    end if;
    perform conv_private.audit('automation_update', 'conv_automations', a.id::text,
      jsonb_build_object('name', v_old.name, 'definition', v_old.definition, 'schedule', v_old.schedule, 'version', v_old.version),
      jsonb_build_object('name', a.name, 'definition', a.definition, 'schedule', a.schedule, 'version', a.version), jsonb_build_object('actor', 'admin'));
  end if;
  return conv_private.finish_op(p_request, jsonb_build_object('id', a.id, 'version', a.version, 'problems', to_jsonb(conv_private.automation_problems(a))));
end $function$;
--@@ 45 funcao public.conv_save_automation_settings(p_request uuid, p jsonb)
CREATE OR REPLACE FUNCTION public.conv_save_automation_settings(p_request uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_replay jsonb; v_old public.conv_automation_settings%rowtype; v_new public.conv_automation_settings%rowtype;
begin
  perform conv_private.require_admin();
  v_replay := conv_private.begin_op(p_request, 'automation_settings_save');
  if v_replay is not null then return v_replay; end if;
  select * into v_old from public.conv_automation_settings where id for update;
  update public.conv_automation_settings set
    enabled = coalesce((p->>'enabled')::boolean, enabled),
    window_start = coalesce((p->>'window_start')::time, window_start), window_end = coalesce((p->>'window_end')::time, window_end),
    days = case when jsonb_typeof(p->'days') = 'array' then array(select jsonb_array_elements_text(p->'days')::int) else days end,
    min_hours_between = coalesce((p->>'min_hours_between')::int, min_hours_between),
    daily_cap = coalesce((p->>'daily_cap')::int, daily_cap), weekly_cap = coalesce((p->>'weekly_cap')::int, weekly_cap),
    updated_by = auth.uid(), updated_at = now()
  where id returning * into v_new;
  perform conv_private.audit('automation_settings_save', 'conv_automation_settings', 'settings', to_jsonb(v_old) - 'opt_out_keywords',
    to_jsonb(v_new) - 'opt_out_keywords', jsonb_build_object('actor', 'admin'));
  return conv_private.finish_op(p_request, jsonb_build_object('ok', true));
end $function$;
--@@ 45 funcao public.conv_save_channel(p_request uuid, p jsonb)
CREATE OR REPLACE FUNCTION public.conv_save_channel(p_request uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_replay jsonb; v_old public.conv_channel%rowtype; v_new public.conv_channel%rowtype; v_lids text[]; v_phone text;
begin
  perform conv_private.require_admin();
  v_replay := conv_private.begin_op(p_request, 'channel_save');
  if v_replay is not null then return v_replay; end if;
  select * into v_old from public.conv_channel where id for update;
  if p ? 'bot_lids' then
    select coalesce(array_agg(distinct conv_private.norm_lid(x)) filter (where conv_private.norm_lid(x) is not null), '{}') into v_lids
      from jsonb_array_elements_text(p->'bot_lids') x;
  end if;
  v_phone := case when p ? 'bot_phone' then conv_private.phone_e164(p->>'bot_phone') else v_old.bot_phone end;
  if p ? 'bot_phone' and nullif(p->>'bot_phone', '') is not null and v_phone is null then raise exception 'INVALID_PHONE'; end if;
  update public.conv_channel set
    institutional_name = left(coalesce(nullif(trim(p->>'institutional_name'), ''), institutional_name), 80),
    bot_phone = v_phone, bot_lids = coalesce(v_lids, bot_lids),
    ai_direct_enabled = coalesce((p->>'ai_direct_enabled')::boolean, ai_direct_enabled),
    group_session_minutes = coalesce(least(greatest((p->>'group_session_minutes')::int, 2), 120), group_session_minutes),
    version = version + 1, updated_at = now(), updated_by = auth.uid()
  where id returning * into v_new;
  perform conv_private.audit('channel_save', 'conv_channel', 'channel', to_jsonb(v_old), to_jsonb(v_new), jsonb_build_object('actor', 'admin'));
  return conv_private.finish_op(p_request, jsonb_build_object('version', v_new.version));
end $function$;
--@@ 45 funcao public.conv_save_quick_reply(p_id uuid, p_shortcut text, p_titl
CREATE OR REPLACE FUNCTION public.conv_save_quick_reply(p_id uuid, p_shortcut text, p_title text, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid := p_id;
begin
  perform conv_private.require_admin();
  if p_id is null then
    insert into public.conv_quick_replies(shortcut, title, body, created_by) values (lower(trim(p_shortcut)), trim(p_title), trim(p_body), auth.uid())
    returning id into v_id;
  else
    update public.conv_quick_replies set shortcut = lower(trim(p_shortcut)), title = trim(p_title), body = trim(p_body) where id = p_id;
    if not found then raise exception 'QUICK_REPLY_NOT_FOUND'; end if;
  end if;
  return v_id;
exception when unique_violation then
  raise exception 'SHORTCUT_TAKEN';
end $function$;
--@@ 45 funcao public.conv_search_people(p_query text)
CREATE OR REPLACE FUNCTION public.conv_search_people(p_query text)
 RETURNS TABLE(kind text, id uuid, name text, hint text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v text := '%' || conv_private.fold(trim(coalesce(p_query, ''))) || '%';
begin
  perform conv_private.require_admin();
  if length(trim(coalesce(p_query, ''))) < 2 then return; end if;
  return query
    (select 'profile'::text, p.id, p.name, coalesce(p.category, p.role::text)
       from public.profiles p where conv_private.fold(p.name) like v order by p.name limit 10)
    union all
    (select 'student'::text, s.id, s.name::text, coalesce(s.plan_type, 'Aluno')::text
       from public.non_socio_students s where conv_private.fold(s.name) like v order by s.name limit 10);
end $function$;
--@@ 45 funcao public.conv_set_ai_channel(p_direct boolean, p_group boolean)
CREATE OR REPLACE FUNCTION public.conv_set_ai_channel(p_direct boolean, p_group boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform conv_private.require_admin();
  if coalesce(p_group, false) and not exists (select 1 from public.conv_channel where id and mention_verified_at is not null) then
    raise exception 'MENTION_NOT_VERIFIED';
  end if;
  update public.conv_channel set ai_direct_enabled = coalesce(p_direct, false), ai_group_enabled = coalesce(p_group, false),
    version = version + 1, updated_at = now(), updated_by = auth.uid() where id;
  if not coalesce(p_group, false) then update public.conv_groups set ai_enabled = false where ai_enabled; end if;
  perform conv_private.audit('ai_channel', 'conv_channel', 'channel', null,
    jsonb_build_object('ai_direct_enabled', coalesce(p_direct, false), 'ai_group_enabled', coalesce(p_group, false)), jsonb_build_object('actor', 'admin'));
end $function$;
--@@ 45 funcao public.conv_set_ai_status(p_conversation uuid, p_status text)
CREATE OR REPLACE FUNCTION public.conv_set_ai_status(p_conversation uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_old text;
begin
  v_actor := conv_private.require_admin();
  if p_status not in ('ai', 'human', 'paused') then raise exception 'INVALID_STATUS'; end if;
  select ai_status into v_old from public.conv_conversations where id = p_conversation for update;
  if not found then raise exception 'CONVERSATION_NOT_FOUND'; end if;
  update public.conv_conversations set
    ai_status = p_status, handled_by_human = p_status <> 'ai',
    handoff_kind = case when p_status = 'ai' then null else handoff_kind end,
    handoff_note = case when p_status = 'ai' then null else handoff_note end,
    ai_turns = case when p_status = 'ai' then 0 else ai_turns end
  where id = p_conversation;
  if p_status <> 'ai' and to_regclass('public.conv_ai_sessions') is not null then
    update public.conv_ai_sessions set status = 'handoff' where conversation_id = p_conversation and status = 'open';
  end if;
  perform conv_private.audit('ai_status', 'conv_conversations', p_conversation::text,
    jsonb_build_object('ai_status', v_old), jsonb_build_object('ai_status', p_status), jsonb_build_object('actor', 'admin'));
end $function$;
--@@ 45 funcao public.conv_set_group(p_group uuid, p_status text, p_ai boolean
CREATE OR REPLACE FUNCTION public.conv_set_group(p_group uuid, p_status text, p_ai boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_old public.conv_groups%rowtype;
begin
  v_actor := conv_private.require_admin();
  if p_status not in ('detected', 'allowed', 'blocked') then raise exception 'INVALID_STATUS'; end if;
  select * into v_old from public.conv_groups where id = p_group for update;
  if not found then raise exception 'GROUP_NOT_FOUND'; end if;
  if coalesce(p_ai, false) and (p_status <> 'allowed'
     or not exists (select 1 from public.conv_channel where id and ai_group_enabled and mention_verified_at is not null)) then
    raise exception 'GROUP_AI_NOT_ALLOWED';
  end if;
  update public.conv_groups set status = p_status, ai_enabled = coalesce(p_ai, false) and p_status = 'allowed',
    allowed_by = case when p_status = 'allowed' then v_actor else allowed_by end,
    allowed_at = case when p_status = 'allowed' then now() else allowed_at end
  where id = p_group;
  perform conv_private.audit('group_set', 'conv_groups', p_group::text,
    jsonb_build_object('status', v_old.status, 'ai_enabled', v_old.ai_enabled),
    jsonb_build_object('status', p_status, 'ai_enabled', coalesce(p_ai, false) and p_status = 'allowed'),
    jsonb_build_object('actor', 'admin', 'group_name', left(v_old.name, 80)));
end $function$;
--@@ 45 funcao public.conv_set_mention_verified(p_verified boolean)
CREATE OR REPLACE FUNCTION public.conv_set_mention_verified(p_verified boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid;
begin
  v_actor := conv_private.require_admin();
  if coalesce(p_verified, false) then
    if not exists (select 1 from public.conv_channel where id and (bot_phone is not null or cardinality(bot_lids) > 0)) then
      raise exception 'BOT_IDENTITY_REQUIRED';
    end if;
    update public.conv_channel set mention_verified_at = now(), mention_verified_by = v_actor, version = version + 1, updated_at = now(), updated_by = v_actor where id;
  else
    update public.conv_channel set mention_verified_at = null, mention_verified_by = null, ai_group_enabled = false, version = version + 1, updated_at = now(), updated_by = v_actor where id;
    update public.conv_groups set ai_enabled = false where ai_enabled;
  end if;
  perform conv_private.audit('mention_verified', 'conv_channel', 'channel', null, jsonb_build_object('verified', coalesce(p_verified, false)),
    jsonb_build_object('actor', 'admin'));
end $function$;
--@@ 45 funcao public.conv_set_meta(p_conversation uuid, p jsonb)
CREATE OR REPLACE FUNCTION public.conv_set_meta(p_conversation uuid, p jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_tags text[]; v_assignee uuid;
begin
  perform conv_private.require_admin();
  if p ? 'tags' then
    select coalesce(array_agg(distinct left(lower(trim(t)), 30)) filter (where length(trim(t)) > 0), '{}') into v_tags
      from jsonb_array_elements_text(p->'tags') t;
    if cardinality(v_tags) > 12 then raise exception 'TOO_MANY_TAGS'; end if;
  end if;
  if p ? 'assigned_to' and nullif(p->>'assigned_to', '') is not null then
    v_assignee := (p->>'assigned_to')::uuid;
    if not exists (select 1 from public.profiles where id = v_assignee and role::text = 'admin') then raise exception 'ASSIGNEE_NOT_ADMIN'; end if;
  end if;
  update public.conv_conversations set
    tags = coalesce(v_tags, tags),
    assigned_to = case when p ? 'assigned_to' then v_assignee else assigned_to end
  where id = p_conversation;
  if not found then raise exception 'CONVERSATION_NOT_FOUND'; end if;
end $function$;
--@@ 45 funcao public.conv_set_opt_out(p_contact uuid, p_opt_out boolean)
CREATE OR REPLACE FUNCTION public.conv_set_opt_out(p_contact uuid, p_opt_out boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform conv_private.require_admin();
  update public.conv_contacts set opt_out = coalesce(p_opt_out, false),
    opt_out_at = case when coalesce(p_opt_out, false) then now() else null end, updated_at = now()
  where id = p_contact;
  if not found then raise exception 'CONTACT_NOT_FOUND'; end if;
  perform conv_private.audit('contact_opt_out', 'conv_contacts', p_contact::text, null, jsonb_build_object('opt_out', coalesce(p_opt_out, false)),
    jsonb_build_object('actor', 'admin'));
end $function$;
--@@ 45 funcao public.conv_set_status(p_conversation uuid, p_status text)
CREATE OR REPLACE FUNCTION public.conv_set_status(p_conversation uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare cv public.conv_conversations%rowtype;
begin
  perform conv_private.require_admin();
  if p_status not in ('open', 'closed') then raise exception 'INVALID_STATUS'; end if;
  select * into cv from public.conv_conversations where id = p_conversation for update;
  if not found then raise exception 'CONVERSATION_NOT_FOUND'; end if;
  if p_status = 'open' and exists (select 1 from public.conv_conversations o where o.status = 'open' and o.id <> cv.id and o.kind = cv.kind
      and ((cv.kind = 'direct' and o.contact_id = cv.contact_id) or (cv.kind = 'group' and o.group_id = cv.group_id))) then
    raise exception 'CONVERSATION_SUPERSEDED';
  end if;
  update public.conv_conversations set status = p_status where id = p_conversation;
  -- Encerrar fecha as sessões de IA daquela conversa.
  if p_status = 'closed' and to_regclass('public.conv_ai_sessions') is not null then
    update public.conv_ai_sessions set status = 'done' where conversation_id = p_conversation and status = 'open';
  end if;
end $function$;
--@@ 45 funcao public.conv_svc_admin_alert_claim(p_profile uuid, p_rule text, 
CREATE OR REPLACE FUNCTION public.conv_svc_admin_alert_claim(p_profile uuid, p_rule text, p_day date)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_n int;
begin
  insert into public.conv_admin_alert_log(profile_id, rule, day) values (p_profile, p_rule, p_day) on conflict do nothing;
  get diagnostics v_n = row_count;
  return v_n > 0;
end $function$;
--@@ 45 funcao public.conv_svc_admin_alert_data(p_profile uuid)
CREATE OR REPLACE FUNCTION public.conv_svc_admin_alert_data(p_profile uuid)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ select conv_private.admin_alert_data(p_profile) $function$;
--@@ 45 funcao public.conv_svc_admin_alert_release(p_profile uuid, p_rule text
CREATE OR REPLACE FUNCTION public.conv_svc_admin_alert_release(p_profile uuid, p_rule text, p_day date)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ delete from public.conv_admin_alert_log where profile_id = p_profile and rule = p_rule and day = p_day $function$;
--@@ 45 funcao public.conv_svc_admin_alert_targets()
CREATE OR REPLACE FUNCTION public.conv_svc_admin_alert_targets()
 RETURNS TABLE(profile_id uuid, name text, conversation_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
