--@@ 45 funcao public.conv_svc_admin_briefing_data(p_profile uuid)
CREATE OR REPLACE FUNCTION public.conv_svc_admin_briefing_data(p_profile uuid)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ select conv_private.admin_briefing_data(p_profile) $function$;
