--@@ 45 funcao public.fin_adjust_charge(p_request_id uuid, p_charge uuid, p_ki
CREATE OR REPLACE FUNCTION public.fin_adjust_charge(p_request_id uuid, p_charge uuid, p_kind text, p_amount_cents bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; c public.fin_member_charges%rowtype; st record; v_today date := fin_private.today(); v_id uuid;
  v_before jsonb; v_status text;
begin
  v_actor := fin_private.require_admin();
  if p_reason is null or length(trim(p_reason)) < 5 then raise exception 'REASON_REQUIRED'; end if;
  v_replay := fin_private.begin_op(p_request_id, 'charge_adjust_' || coalesce(p_kind, ''), p_reason);
  if v_replay is not null then return v_replay; end if;
  if p_kind not in ('discount', 'increase', 'fee_waiver') then raise exception 'INVALID_ADJUSTMENT'; end if;
  if p_amount_cents is null or p_amount_cents <= 0 or p_amount_cents > 1000000000 then raise exception 'INVALID_AMOUNT'; end if;
  select * into c from public.fin_member_charges where id = p_charge for update;
  if not found then raise exception 'CHARGE_NOT_FOUND'; end if;
  if c.status = 'canceled' then raise exception 'CHARGE_CANCELED'; end if;
  select * into st from fin_private.charge_statement(p_charge, v_today);
  v_before := fin_private.statement_json(p_charge, v_today);
  if p_kind = 'discount' and p_amount_cents > st.principal_remaining then raise exception 'DISCOUNT_EXCEEDS_BALANCE'; end if;
  if p_kind = 'fee_waiver' and p_amount_cents > st.fees_due then raise exception 'WAIVER_EXCEEDS_FEES'; end if;
  insert into public.fin_charge_adjustments(charge_id, kind, amount_cents, reason, before_data, actor_id, request_id)
  values (p_charge, p_kind, p_amount_cents, trim(p_reason), v_before, v_actor, p_request_id) returning id into v_id;
  update public.fin_charge_adjustments set after_data = fin_private.statement_json(p_charge, v_today) where id = v_id;
  v_status := fin_private.refresh_charge_status(p_charge);
  return fin_private.finish_op(p_request_id, jsonb_build_object('id', v_id, 'charge_status', v_status));
end $function$;
--@@ 45 funcao public.fin_approve_receipt(p_request_id uuid, p_submission_id u
CREATE OR REPLACE FUNCTION public.fin_approve_receipt(p_request_id uuid, p_submission_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; s public.fin_receipt_submissions%rowtype; a jsonb; w jsonb; v_res jsonb; v_ids uuid[] := '{}';
  v_paid_on date := (p_data->>'paid_on')::date; v_method text := coalesce(p_data->>'method', 'pix'); v_account uuid := (p_data->>'account_id')::uuid;
  v_total bigint := 0; v_i integer := 0; v_wres jsonb;
begin
  v_actor := fin_private.require_admin();
  v_replay := fin_private.begin_op(p_request_id, 'receipt_approve', p_data->>'note');
  if v_replay is not null then return v_replay; end if;
  select * into s from public.fin_receipt_submissions where id = p_submission_id for update;
  if not found then raise exception 'RECEIPT_NOT_FOUND'; end if;
  if s.status not in ('submitted', 'in_review') then raise exception 'RECEIPT_NOT_PENDING'; end if;
  if jsonb_typeof(p_data->'allocations') <> 'array' or jsonb_array_length(p_data->'allocations') = 0 then raise exception 'NO_CHARGES_SELECTED'; end if;

  -- Dispensas de encargo primeiro, para o pagamento já calcular com elas.
  for w in select * from jsonb_array_elements(coalesce(p_data->'waivers', '[]'::jsonb)) loop
    if not exists (select 1 from public.fin_member_charges c where c.id = (w->>'charge_id')::uuid and c.profile_id = s.profile_id) then
      raise exception 'INVALID_CHARGES';
    end if;
    perform fin_private.waive_fees((w->>'charge_id')::uuid, (w->>'amount_cents')::bigint, w->>'reason', v_paid_on, gen_random_uuid());
  end loop;

  for a in select * from jsonb_array_elements(p_data->'allocations') loop
    v_i := v_i + 1;
    -- Só cobranças do próprio sócio que enviou.
    if not exists (select 1 from public.fin_member_charges c where c.id = (a->>'charge_id')::uuid and c.profile_id = s.profile_id) then
      raise exception 'INVALID_CHARGES';
    end if;
    v_res := fin_private.apply_payment((a->>'charge_id')::uuid, (a->>'amount_cents')::bigint, v_paid_on, v_method, v_account,
      p_submission_id, null, 'Comprovante aprovado', gen_random_uuid());
    v_ids := v_ids || (v_res->>'payment_id')::uuid;
    v_total := v_total + (a->>'amount_cents')::bigint;
  end loop;

  update public.fin_receipt_submissions set status = 'approved', reviewed_by = v_actor, reviewed_at = now(),
    decision_reason = nullif(trim(p_data->>'note'), ''), approved_payment_ids = v_ids, version = version + 1, updated_at = now()
  where id = p_submission_id;
  return fin_private.finish_op(p_request_id, jsonb_build_object('id', p_submission_id, 'status', 'approved', 'payment_ids', to_jsonb(v_ids), 'total_cents', v_total));
end $function$;
--@@ 45 funcao public.fin_attach_file(p_request_id uuid, p_entry uuid, p_path 
CREATE OR REPLACE FUNCTION public.fin_attach_file(p_request_id uuid, p_entry uuid, p_path text, p_name text, p_content_type text, p_size integer)
