--@@ 45 funcao public.fin_cancel_charge(p_request_id uuid, p_charge uuid, p_re
CREATE OR REPLACE FUNCTION public.fin_cancel_charge(p_request_id uuid, p_charge uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; c public.fin_member_charges%rowtype;
begin
  v_actor := fin_private.require_admin();
  if p_reason is null or length(trim(p_reason)) < 5 then raise exception 'REASON_REQUIRED'; end if;
  v_replay := fin_private.begin_op(p_request_id, 'charge_cancel', p_reason);
  if v_replay is not null then return v_replay; end if;
  select * into c from public.fin_member_charges where id = p_charge for update;
  if not found then raise exception 'CHARGE_NOT_FOUND'; end if;
  if c.status = 'canceled' then raise exception 'CHARGE_CANCELED'; end if;
  if exists (select 1 from fin_private.charge_payments_effective where charge_id = p_charge) then raise exception 'CHARGE_HAS_PAYMENTS'; end if;
  update public.fin_member_charges set status = 'canceled', canceled_at = now(), canceled_by = v_actor, cancel_reason = trim(p_reason),
    version = version + 1, updated_at = now(), updated_by = v_actor where id = p_charge;
  -- Comprovantes ainda em análise para uma cobrança cancelada continuam rastreáveis; o admin decide.
  return fin_private.finish_op(p_request_id, jsonb_build_object('id', p_charge));
end $function$;
--@@ 45 funcao public.fin_cancel_entry(p_request_id uuid, p_id uuid, p_expecte
CREATE OR REPLACE FUNCTION public.fin_cancel_entry(p_request_id uuid, p_id uuid, p_expected_version integer, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; e public.fin_entries%rowtype;
begin
  v_actor := fin_private.require_admin();
  if p_reason is null or length(trim(p_reason)) < 3 then raise exception 'REASON_REQUIRED'; end if;
  v_replay := fin_private.begin_op(p_request_id, 'entry_cancel', p_reason);
  if v_replay is not null then return v_replay; end if;
  select * into e from public.fin_entries where id = p_id for update;
  if not found then raise exception 'ENTRY_NOT_FOUND'; end if;
  if e.version <> p_expected_version then raise exception 'VERSION_CONFLICT'; end if;
  if e.status = 'canceled' then raise exception 'ENTRY_CANCELED'; end if;
  if fin_private.entry_paid_cents(p_id) <> 0 then raise exception 'ENTRY_HAS_PAYMENTS'; end if;
  update public.fin_entries set status = 'canceled', canceled_at = now(), canceled_by = v_actor, cancel_reason = trim(p_reason),
    version = version + 1, updated_at = now(), updated_by = v_actor where id = p_id;
  return fin_private.finish_op(p_request_id, jsonb_build_object('id', p_id, 'version', e.version + 1));
end $function$;
--@@ 45 funcao public.fin_cash_flow(p_from date, p_to date, p_granularity text
CREATE OR REPLACE FUNCTION public.fin_cash_flow(p_from date, p_to date, p_granularity text DEFAULT 'day'::text, p_account uuid DEFAULT NULL::uuid)
 RETURNS TABLE(bucket_start date, bucket_end date, opening_cents bigint, inflow_cents bigint, outflow_cents bigint, net_cents bigint, closing_cents bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_step text;
begin
  perform fin_private.require_admin();
  perform fin_private.check_period(p_from, p_to);
  if p_granularity not in ('day', 'week', 'month') then raise exception 'INVALID_PERIOD'; end if;
  v_step := case p_granularity when 'day' then '1 day' when 'week' then '1 week' else '1 month' end;
  return query
  with cr as (
    select r.occurred_on d, r.amount_cents amt, r.flow from fin_private.cash_rows('1900-01-01'::date, p_to) r
    where (p_account is null and not r.is_transfer) or (p_account is not null and r.account_id = p_account)
  ), b as (
    select gs::date bs, least((gs + v_step::interval - interval '1 day')::date, p_to) be
    from generate_series(case p_granularity when 'week' then date_trunc('week', p_from::timestamp) when 'month' then date_trunc('month', p_from::timestamp) else p_from::timestamp end,
      p_to::timestamp, v_step::interval) gs
  )
  select b.bs, b.be,
    coalesce((select sum(amt) from cr where d < greatest(b.bs, p_from)), 0)::bigint,
    coalesce((select sum(amt) from cr where d between greatest(b.bs, p_from) and b.be and amt > 0 and flow <> 'opening'), 0)::bigint,
    coalesce((select sum(-amt) from cr where d between greatest(b.bs, p_from) and b.be and amt < 0 and flow <> 'opening'), 0)::bigint,
    coalesce((select sum(amt) from cr where d between greatest(b.bs, p_from) and b.be and flow <> 'opening'), 0)::bigint,
    coalesce((select sum(amt) from cr where d <= b.be), 0)::bigint
  from b order by b.bs;
end $function$;
