CREATE OR REPLACE FUNCTION public.fin_charge_statements(p_filters jsonb DEFAULT '{}'::jsonb, p_as_of date DEFAULT NULL::date, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
