 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform fin_private.require_admin();
  return query select * from fin_private.charge_rows(null, null, coalesce(p_filters, '{}'::jsonb), coalesce(p_as_of, fin_private.today()),
