--@@ 45 funcao public.fin_charge_statements_by_ids(p_ids uuid[], p_as_of date)
CREATE OR REPLACE FUNCTION public.fin_charge_statements_by_ids(p_ids uuid[], p_as_of date DEFAULT NULL::date)
 RETURNS TABLE(charge_id uuid, plan_id uuid, profile_id uuid, profile_name text, competence_month date, period_months smallint, due_date date, original_amount_cents bigint, stored_status text, display_status text, in_review boolean, principal_base_cents bigint, principal_paid_cents bigint, principal_remaining_cents bigint, days_late integer, fine_due_cents bigint, interest_due_cents bigint, fees_due_cents bigint, fees_paid_cents bigint, fees_waived_cents bigint, total_due_cents bigint, fees_configured boolean, overdue boolean, last_payment_on date, cancel_reason text, total_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null then raise exception 'FINANCE_FORBIDDEN' using errcode = '42501'; end if;
  if not public.is_admin() and exists (select 1 from public.fin_member_charges c where c.id = any(p_ids) and c.profile_id <> auth.uid()) then
    raise exception 'FINANCE_FORBIDDEN' using errcode = '42501';
  end if;
  return query select * from fin_private.charge_rows(null, p_ids, '{}'::jsonb, coalesce(p_as_of, fin_private.today()), 1000, 0);
end $function$;
--@@ 45 funcao public.fin_create_entry(p_request_id uuid, p_data jsonb)
CREATE OR REPLACE FUNCTION public.fin_create_entry(p_request_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; v_kind text := p_data->>'kind'; v_status text; v_id uuid; v_amount bigint;
  v_due date; v_comp date; v_paid_on date; v_account uuid; v_counter uuid; v_category uuid; v_desc text := trim(p_data->>'description');
  v_paid_amount bigint;
begin
  v_actor := fin_private.require_admin();
  v_replay := fin_private.begin_op(p_request_id, 'entry_create');
  if v_replay is not null then return v_replay; end if;
  if v_kind not in ('expense', 'revenue', 'contribution', 'withdrawal', 'transfer') then raise exception 'INVALID_ENTRY'; end if;
  if v_desc is null or length(v_desc) < 2 or length(v_desc) > 140 then raise exception 'INVALID_ENTRY'; end if;
  v_amount := (p_data->>'amount_cents')::bigint;
  if v_amount is null or v_amount <= 0 or v_amount > 100000000000 then raise exception 'INVALID_AMOUNT'; end if;
  v_status := coalesce(p_data->>'status', 'paid');
  if v_status not in ('pending', 'paid') or (v_kind not in ('expense', 'revenue') and v_status <> 'paid') then raise exception 'INVALID_ENTRY'; end if;
  v_due := (p_data->>'due_date')::date;
  v_paid_on := case when v_status = 'paid' then coalesce((p_data->>'paid_on')::date, fin_private.today()) end;
  v_comp := coalesce((p_data->>'competence_date')::date, v_paid_on, v_due, fin_private.today());
  v_account := (p_data->>'account_id')::uuid;
  v_counter := (p_data->>'counter_account_id')::uuid;
  v_category := (p_data->>'category_id')::uuid;
  if v_kind in ('expense', 'revenue') then perform fin_private.check_category(v_category, v_kind); else v_category := null; end if;
  if v_kind = 'transfer' then
    perform fin_private.check_account(v_counter);
    perform fin_private.check_account(v_account);
    if v_counter = v_account then raise exception 'SAME_ACCOUNT'; end if;
  else v_counter := null; end if;
  if v_status = 'pending' then
    if v_due is null then raise exception 'DUE_DATE_REQUIRED'; end if;
    if v_account is not null then perform fin_private.check_account(v_account); end if;
  end if;

  -- Despesa/receita quitada na hora nasce pendente (com vencimento = data do pagamento)
  -- e o pagamento a quita; aporte/retirada/transferência já nascem pagos.
  insert into public.fin_entries(kind, status, description, supplier, category_id, amount_cents, competence_date, due_date,
    account_id, counter_account_id, notes, request_id, settled_on, created_by, updated_by)
  values (v_kind, case when v_kind in ('expense', 'revenue') then 'pending' else 'paid' end, v_desc,
    nullif(trim(p_data->>'supplier'), ''), v_category, v_amount, v_comp, case when v_status = 'paid' then coalesce(v_due, v_paid_on) else v_due end,
    v_account, v_counter, nullif(trim(p_data->>'notes'), ''), p_request_id,
    case when v_kind in ('expense', 'revenue') then null else v_paid_on end, v_actor, v_actor)
  returning id into v_id;
  if v_status = 'paid' then
    v_paid_amount := coalesce((p_data->>'paid_amount_cents')::bigint, v_amount);
    if v_kind = 'transfer' then v_paid_amount := v_amount; end if;
    perform fin_private.add_entry_payment(v_id, v_paid_amount, v_paid_on, v_account, p_data->>'payment_note', true, gen_random_uuid());
  end if;
  return fin_private.finish_op(p_request_id, jsonb_build_object('id', v_id));
end $function$;
--@@ 45 funcao public.fin_create_member_pendency(p_request_id uuid, p_data jso
CREATE OR REPLACE FUNCTION public.fin_create_member_pendency(p_request_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid; v_replay jsonb; v_profile uuid; v_description text; v_amount bigint;
  v_comp date; v_due date; v_kind text; v_category uuid; v_guest text; v_guest_date date;
  v_collect boolean; v_send boolean; v_paid boolean; v_paid_on date; v_method text; v_account uuid;
  v_charge uuid; v_pay jsonb; v_rec uuid; v_raw_comp text; v_cat public.fin_categories%rowtype;
begin
  v_actor:=fin_private.require_admin();
  v_replay:=fin_private.begin_op(p_request_id,'member_pendency_create',p_data->>'description');
  if v_replay is not null then return v_replay; end if;

  v_profile:=(p_data->>'profile_id')::uuid;
  if not fin_private.is_active_member(v_profile) then raise exception 'MEMBER_NOT_ACTIVE'; end if;

  v_description:=trim(coalesce(p_data->>'description',''));
  if length(v_description) not between 3 and 300 then raise exception 'INVALID_DESCRIPTION'; end if;
  v_amount:=(p_data->>'amount_cents')::bigint;
  if v_amount is null or v_amount<=0 or v_amount>1000000000 then raise exception 'INVALID_AMOUNT'; end if;

  v_raw_comp:=coalesce(p_data->>'competence_month',p_data->>'competence');
  if v_raw_comp ~ '^\d{4}-\d{2}$' then v_comp:=to_date(v_raw_comp||'-01','YYYY-MM-DD');
  else v_comp:=date_trunc('month',v_raw_comp::date)::date; end if;
  v_due:=(p_data->>'due_date')::date;
  if v_comp is null or v_due is null then raise exception 'INVALID_DATE'; end if;

  v_kind:=coalesce(nullif(p_data->>'pendency_kind',''),'outros');
  if v_kind not in ('day_card','consumo','evento','multa','dano_reposicao','outros') then raise exception 'INVALID_PENDENCY_KIND'; end if;

  if nullif(p_data->>'category_id','') is not null then
    select * into v_cat from public.fin_categories where id=(p_data->>'category_id')::uuid and active and kind='revenue';
    if not found then raise exception 'INVALID_CATEGORY'; end if;
    v_category:=v_cat.id;
  elsif v_kind='day_card' then
    v_category:=fin_private.category_id('day_card');
  else
    v_category:=fin_private.category_id('member_pendency');
  end if;

  v_guest:=nullif(trim(coalesce(p_data->>'guest_name','')),'');
  v_guest_date:=nullif(p_data->>'guest_date','')::date;
  v_collect:=coalesce((p_data->>'collection_enabled')::boolean,true);
  v_send:=coalesce((p_data->>'send_now')::boolean,false);
  v_paid:=coalesce((p_data->>'already_paid')::boolean,false);

  insert into public.fin_member_charges(
    plan_id,profile_id,competence_month,period_months,due_date,original_amount_cents,status,source,notes,
    charge_type,description,pendency_kind,category_id,guest_name,guest_date,collection_enabled,created_by,updated_by
  ) values(
    null,v_profile,v_comp,1,v_due,v_amount,'open','manual',nullif(trim(coalesce(p_data->>'notes','')),''),
    'member_pendency',v_description,v_kind,v_category,v_guest,v_guest_date,v_collect,v_actor,v_actor
  ) returning id into v_charge;

  if v_paid then
    v_paid_on:=coalesce(nullif(p_data->>'paid_on','')::date,fin_private.today());
    v_method:=coalesce(nullif(p_data->>'method',''),'pix');
    v_account:=nullif(p_data->>'account_id','')::uuid;
    if v_method='credit' then raise exception 'INVALID_METHOD'; end if;
    if v_account is null then raise exception 'ACCOUNT_REQUIRED'; end if;
    v_pay:=fin_private.apply_payment(v_charge,v_amount,v_paid_on,v_method,v_account,null,null,
      'Pendência lançada como já paga',gen_random_uuid());
  elsif v_send and v_collect then
    v_rec:=conv_private.queue_member_pendency_now(v_profile,v_charge);
  end if;

  return fin_private.finish_op(p_request_id,jsonb_strip_nulls(jsonb_build_object(
    'id',v_charge,
    'status',case when v_paid then 'paid' else 'open' end,
    'payment',v_pay,
    'automation_recipient_id',v_rec
  )));
end $function$;
--@@ 45 funcao public.fin_create_member_plan(p_request_id uuid, p_data jsonb)
CREATE OR REPLACE FUNCTION public.fin_create_member_plan(p_request_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; v_profile uuid := (p_data->>'profile_id')::uuid; v_start date := (p_data->>'start_on')::date;
  v_amount bigint := (p_data->>'amount_cents')::bigint; v_period integer := coalesce((p_data->>'period_months')::integer, 1); v_id uuid;
begin
  v_actor := fin_private.require_admin();
  v_replay := fin_private.begin_op(p_request_id, 'member_plan_create');
  if v_replay is not null then return v_replay; end if;
  if v_profile is null or v_start is null then raise exception 'INVALID_PLAN'; end if;
  if v_amount is null or v_amount <= 0 or v_amount > 1000000000 then raise exception 'INVALID_AMOUNT'; end if;
  if v_period not in (1, 3, 6, 12) then raise exception 'INVALID_PLAN'; end if;
  -- Sócio ≠ aluno ≠ dependente ≠ usuário do app: só perfil de sócio (role socio/admin) e ativo tem plano.
  if not fin_private.is_active_member(v_profile) then raise exception 'NOT_A_MEMBER'; end if;
  if exists (select 1 from public.fin_member_plans where profile_id = v_profile and status <> 'ended') then raise exception 'PLAN_EXISTS'; end if;
  insert into public.fin_member_plans(profile_id, start_on, period_months, due_day, due_month_offset, notes, created_by, updated_by)
  values (v_profile, v_start, v_period::smallint, (p_data->>'due_day')::smallint, (p_data->>'due_month_offset')::smallint,
    nullif(trim(p_data->>'notes'), ''), v_actor, v_actor) returning id into v_id;
  insert into public.fin_member_plan_prices(plan_id, effective_from, amount_cents, reason, created_by)
  values (v_id, date_trunc('month', v_start::timestamp)::date, v_amount, 'Valor inicial', v_actor);
  return fin_private.finish_op(p_request_id, jsonb_build_object('id', v_id));
end $function$;
--@@ 45 funcao public.fin_day_card_rows(p_from date, p_to date)
CREATE OR REPLACE FUNCTION public.fin_day_card_rows(p_from date, p_to date)
 RETURNS TABLE(reservation_id uuid, occurred_on date, guest_name text, booked_by text, exempt boolean, charged_cents bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform fin_private.require_admin();
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 731 then raise exception 'INVALID_PERIOD'; end if;
  return query select * from fin_private.day_card_rows(p_from, p_to);
end $function$;
--@@ 45 funcao public.fin_delete_recurrence(p_request_id uuid, p_id uuid, p_ex
CREATE OR REPLACE FUNCTION public.fin_delete_recurrence(p_request_id uuid, p_id uuid, p_expected_version integer, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; r public.fin_recurrences%rowtype; v_canceled integer; v_kept integer;
begin
  v_actor := fin_private.require_admin();
  v_replay := fin_private.begin_op(p_request_id, 'recurrence_delete', p_data->>'reason');
  if v_replay is not null then return v_replay; end if;
  select * into r from public.fin_recurrences where id = p_id for update;
  if not found then raise exception 'RECURRENCE_NOT_FOUND'; end if;
  if r.version <> p_expected_version then raise exception 'VERSION_CONFLICT'; end if;

  -- O que ainda não foi pago deixa de existir como cobrança futura (cancelado, com rastro).
  update public.fin_entries set status = 'canceled', canceled_at = now(), canceled_by = v_actor,
    cancel_reason = 'Recorrência excluída', version = version + 1, updated_at = now(), updated_by = v_actor
  where recurrence_id = p_id and status = 'pending' and fin_private.entry_paid_cents(id) = 0;
  get diagnostics v_canceled = row_count;

  select count(*) into v_kept from public.fin_entries where recurrence_id = p_id and status <> 'canceled';

  -- O histórico fica: só perde o vínculo com o modelo que deixou de existir.
  update public.fin_entries set recurrence_id = null, version = version + 1, updated_at = now(), updated_by = v_actor
  where recurrence_id = p_id;

  perform set_config('fin.delete_recurrence', p_id::text, true);
  delete from public.fin_recurrences where id = p_id;
  perform set_config('fin.delete_recurrence', '', true);

  return fin_private.finish_op(p_request_id, jsonb_build_object('id', p_id, 'canceled', v_canceled, 'kept', v_kept));
end $function$;
--@@ 45 funcao public.fin_dre_detail(p_from date, p_to date, p_category uuid)
CREATE OR REPLACE FUNCTION public.fin_dre_detail(p_from date, p_to date, p_category uuid DEFAULT NULL::uuid)
 RETURNS TABLE(category_id uuid, category_name text, source_type text, source_id text, occurred_on date, description text, amount_cents bigint, profile_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform fin_private.require_admin();
  perform fin_private.check_period(p_from, p_to);
  return query
  select x.category_id, c.name, x.source_type, x.source_id, x.occurred_on, x.description, x.amount_cents, x.profile_id
  from fin_private.dre_rows(p_from, p_to) x join public.fin_categories c on c.id = x.category_id
  where c.dre_line <> 'none' and (p_category is null or x.category_id = p_category)
  order by x.occurred_on, x.description, x.source_id;
end $function$;
--@@ 45 funcao public.fin_dre_lines(p_from date, p_to date)
CREATE OR REPLACE FUNCTION public.fin_dre_lines(p_from date, p_to date)
 RETURNS TABLE(period text, line text, category_id uuid, name text, parent_name text, amount_cents bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_len integer;
begin
  perform fin_private.require_admin();
  perform fin_private.check_period(p_from, p_to);
  v_len := p_to - p_from + 1;
  return query
    select 'current'::text, l.line, l.category_id, l.name, l.parent_name, l.amount_cents from fin_private.dre_lines(p_from, p_to) l
    union all
    select 'previous'::text, l.line, l.category_id, l.name, l.parent_name, l.amount_cents from fin_private.dre_lines(p_from - v_len, p_from - 1) l;
end $function$;
--@@ 45 funcao public.fin_dre_memo(p_from date, p_to date)
CREATE OR REPLACE FUNCTION public.fin_dre_memo(p_from date, p_to date)
 RETURNS TABLE(contributions_cents bigint, withdrawals_cents bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform fin_private.require_admin();
  perform fin_private.check_period(p_from, p_to);
  return query select
    coalesce(sum(e.amount_cents) filter (where e.kind = 'contribution'), 0)::bigint,
    coalesce(sum(e.amount_cents) filter (where e.kind = 'withdrawal'), 0)::bigint
  from public.fin_entries e where e.status <> 'canceled' and e.competence_date between p_from and p_to;
end $function$;
--@@ 45 funcao public.fin_end_member_plan(p_request_id uuid, p_plan_id uuid, p
CREATE OR REPLACE FUNCTION public.fin_end_member_plan(p_request_id uuid, p_plan_id uuid, p_ended_on date, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_replay jsonb; v_res jsonb;
begin
  perform fin_private.require_admin();
  if p_reason is null or length(trim(p_reason)) < 3 then raise exception 'REASON_REQUIRED'; end if;
  v_replay := fin_private.begin_op(p_request_id, 'member_plan_end', p_reason);
  if v_replay is not null then return v_replay; end if;
  if p_ended_on is null then raise exception 'INVALID_DATE'; end if;
  v_res := fin_private.end_plan(p_plan_id, p_ended_on, trim(p_reason), false);
  return fin_private.finish_op(p_request_id, v_res);
end $function$;
--@@ 45 funcao public.fin_generate_member_charges(p_request_id uuid, p_plan_id
CREATE OR REPLACE FUNCTION public.fin_generate_member_charges(p_request_id uuid, p_plan_id uuid DEFAULT NULL::uuid, p_today date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
