--@@ 45 funcao public.fin_generate_recurrences(p_request_id uuid, p_until date
CREATE OR REPLACE FUNCTION public.fin_generate_recurrences(p_request_id uuid, p_until date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
