--@@ 45 funcao public.fin_is_active_member(p_profile uuid)
CREATE OR REPLACE FUNCTION public.fin_is_active_member(p_profile uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ select fin_private.is_active_member(p_profile) $function$;
--@@ 45 funcao public.fin_link_receipt_charges(p_request_id uuid, p_submission
CREATE OR REPLACE FUNCTION public.fin_link_receipt_charges(p_request_id uuid, p_submission_id uuid, p_charge_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; s public.fin_receipt_submissions%rowtype; v_ok integer; v_new integer; v_ids uuid[];
begin
  v_actor := fin_private.require_admin();
  v_replay := fin_private.begin_op(p_request_id, 'receipt_link_charges',
    'Cobranças ligadas ao comprovante pelo administrador');
  if v_replay is not null then return v_replay; end if;

  select * into s from public.fin_receipt_submissions where id = p_submission_id for update;
  if not found then raise exception 'RECEIPT_NOT_FOUND'; end if;
  if s.status not in ('submitted', 'in_review') then raise exception 'RECEIPT_NOT_PENDING'; end if;
  if p_charge_ids is null or cardinality(p_charge_ids) = 0 or cardinality(p_charge_ids) > 50 then raise exception 'NO_CHARGES_SELECTED'; end if;

  -- Só cobranças do próprio sócio que enviou, ainda em aberto.
  select count(*) into v_ok from public.fin_member_charges c
  where c.id = any(p_charge_ids) and c.profile_id = s.profile_id and c.status in ('open', 'partial');
  if v_ok <> (select count(distinct x) from unnest(p_charge_ids) x) then raise exception 'INVALID_CHARGES'; end if;

  insert into public.fin_receipt_charges(submission_id, charge_id)
  select p_submission_id, x from (select distinct unnest(p_charge_ids) x) u
  on conflict do nothing;
  get diagnostics v_new = row_count;

  if v_new > 0 then
    update public.fin_receipt_submissions set version = version + 1, updated_at = now() where id = p_submission_id;
  end if;

  select coalesce(array_agg(rc.charge_id), '{}') into v_ids from public.fin_receipt_charges rc where rc.submission_id = p_submission_id;
  return fin_private.finish_op(p_request_id, jsonb_build_object('id', p_submission_id, 'linked', v_new, 'charge_ids', to_jsonb(v_ids)));
end $function$;
--@@ 45 funcao public.fin_member_payment_settings()
CREATE OR REPLACE FUNCTION public.fin_member_payment_settings()
 RETURNS TABLE(pix_key text, pendency_automation_enabled boolean, pendency_reminder_days integer[], pendency_grace_days smallint, pendency_fine_fixed_cents bigint, pendency_fine_percent_bps integer, pendency_interest_daily_fixed_cents bigint, pendency_interest_daily_percent_bps integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select s.pix_key, s.pendency_automation_enabled, s.pendency_reminder_days,
    s.pendency_grace_days, s.pendency_fine_fixed_cents, s.pendency_fine_percent_bps,
    s.pendency_interest_daily_fixed_cents, s.pendency_interest_daily_percent_bps
  from public.fin_settings s
  where auth.uid() is not null
$function$;
--@@ 45 funcao public.fin_monthly_trend(p_to date, p_months integer)
CREATE OR REPLACE FUNCTION public.fin_monthly_trend(p_to date DEFAULT NULL::date, p_months integer DEFAULT 6)
 RETURNS TABLE(month_start date, revenue_cents bigint, expense_cents bigint, cash_in_cents bigint, cash_out_cents bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_to date := date_trunc('month', coalesce(p_to, fin_private.today())::timestamp)::date; v_from date;
begin
  perform fin_private.require_admin();
  if p_months < 1 or p_months > 36 then raise exception 'INVALID_PERIOD'; end if;
  v_from := (v_to - make_interval(months => p_months - 1))::date;
  return query
  with ms as (select gs::date m from generate_series(v_from::timestamp, v_to::timestamp, interval '1 month') gs),
  d as (select date_trunc('month', x.occurred_on::timestamp)::date m, x.amount_cents amt, c.dre_line
        from fin_private.dre_rows(v_from, (v_to + interval '1 month - 1 day')::date) x join public.fin_categories c on c.id = x.category_id
        where c.dre_line <> 'none'),
  k as (select date_trunc('month', r.occurred_on::timestamp)::date m, r.amount_cents amt
        from fin_private.cash_rows(v_from, (v_to + interval '1 month - 1 day')::date) r where not r.is_transfer and r.flow <> 'opening')
  select ms.m,
    coalesce((select sum(amt) from d where d.m = ms.m and dre_line in ('revenue', 'deduction') ), 0)::bigint,
    coalesce((select -sum(amt) from d where d.m = ms.m and dre_line not in ('revenue', 'deduction')), 0)::bigint,
    coalesce((select sum(amt) from k where k.m = ms.m and amt > 0), 0)::bigint,
    coalesce((select -sum(amt) from k where k.m = ms.m and amt < 0), 0)::bigint
  from ms order by ms.m;
end $function$;
--@@ 45 funcao public.fin_movements(p_from date, p_to date, p_filters jsonb, p
CREATE OR REPLACE FUNCTION public.fin_movements(p_from date, p_to date, p_filters jsonb DEFAULT '{}'::jsonb, p_limit integer DEFAULT 500, p_offset integer DEFAULT 0)
 RETURNS TABLE(source_type text, source_id text, leg text, occurred_on date, flow text, description text, category_id uuid, category_name text, account_id uuid, account_name text, amount_cents bigint, is_transfer boolean, origin text, profile_id uuid, total_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_flows text[];
begin
  perform fin_private.require_admin();
  perform fin_private.check_period(p_from, p_to);
  v_flows := case when p_filters ? 'flows' then array(select jsonb_array_elements_text(p_filters->'flows')) end;
  return query
  select m.source_type, m.source_id, m.leg, m.occurred_on, m.flow, m.description, m.category_id, c.name, m.account_id,
    coalesce(a.name, 'Sem conta definida'), m.amount_cents, m.is_transfer, m.origin, m.profile_id, count(*) over()
  from fin_private.cash_rows(p_from, p_to) m
  left join public.fin_categories c on c.id = m.category_id
  left join public.fin_accounts a on a.id = m.account_id
  where (v_flows is null or m.flow = any(v_flows))
    and (nullif(p_filters->>'account_id', '') is null or m.account_id = (p_filters->>'account_id')::uuid)
    and (nullif(p_filters->>'category_id', '') is null or m.category_id = (p_filters->>'category_id')::uuid)
    and (nullif(p_filters->>'origin', '') is null or m.origin = p_filters->>'origin')
    and (nullif(trim(coalesce(p_filters->>'search', '')), '') is null or m.description ilike '%' || trim(p_filters->>'search') || '%')
  order by m.occurred_on desc, m.description, m.source_id, m.leg
  limit least(greatest(p_limit, 0), 5000) offset greatest(p_offset, 0);
end $function$;
--@@ 45 funcao public.fin_my_charges(p_as_of date)
CREATE OR REPLACE FUNCTION public.fin_my_charges(p_as_of date DEFAULT NULL::date)
 RETURNS TABLE(charge_id uuid, plan_id uuid, profile_id uuid, profile_name text, competence_month date, period_months smallint, due_date date, original_amount_cents bigint, stored_status text, display_status text, in_review boolean, principal_base_cents bigint, principal_paid_cents bigint, principal_remaining_cents bigint, days_late integer, fine_due_cents bigint, interest_due_cents bigint, fees_due_cents bigint, fees_paid_cents bigint, fees_waived_cents bigint, total_due_cents bigint, fees_configured boolean, overdue boolean, last_payment_on date, cancel_reason text, total_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null then raise exception 'FINANCE_FORBIDDEN' using errcode = '42501'; end if;
  return query select * from fin_private.charge_rows(auth.uid(), null, '{}'::jsonb, coalesce(p_as_of, fin_private.today()), 500, 0);
end $function$;
--@@ 45 funcao public.fin_pay_entry(p_request_id uuid, p_id uuid, p_expected_v
CREATE OR REPLACE FUNCTION public.fin_pay_entry(p_request_id uuid, p_id uuid, p_expected_version integer, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_replay jsonb; e public.fin_entries%rowtype;
begin
  perform fin_private.require_admin();
  v_replay := fin_private.begin_op(p_request_id, 'entry_pay', p_data->>'note');
  if v_replay is not null then return v_replay; end if;
  select * into e from public.fin_entries where id = p_id for update;
  if not found then raise exception 'ENTRY_NOT_FOUND'; end if;
  if e.version <> p_expected_version then raise exception 'VERSION_CONFLICT'; end if;
  if e.kind not in ('expense', 'revenue') then raise exception 'INVALID_ENTRY'; end if;
  if e.status not in ('pending', 'partial') then raise exception 'ENTRY_NOT_PENDING'; end if;
  perform fin_private.add_entry_payment(p_id, (p_data->>'amount_cents')::bigint, (p_data->>'paid_on')::date,
    (p_data->>'account_id')::uuid, p_data->>'note', coalesce((p_data->>'settle')::boolean, false), p_request_id);
  return fin_private.finish_op(p_request_id, jsonb_build_object('id', p_id, 'paid_cents', fin_private.entry_paid_cents(p_id)));
end $function$;
--@@ 45 funcao public.fin_payables_summary(p_as_of date)
CREATE OR REPLACE FUNCTION public.fin_payables_summary(p_as_of date DEFAULT NULL::date)
 RETURNS TABLE(payable_open_cents bigint, payable_overdue_count bigint, payable_overdue_cents bigint, payable_due_7d_cents bigint, payable_due_30d_cents bigint, receivable_open_cents bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_asof date := coalesce(p_as_of, fin_private.today());
begin
  perform fin_private.require_admin();
  return query
  select coalesce(sum(remaining_cents) filter (where kind = 'expense'), 0)::bigint,
    count(*) filter (where kind = 'expense' and due_date < v_asof),
    coalesce(sum(remaining_cents) filter (where kind = 'expense' and due_date < v_asof), 0)::bigint,
    coalesce(sum(remaining_cents) filter (where kind = 'expense' and due_date >= v_asof and due_date <= v_asof + 7), 0)::bigint,
    coalesce(sum(remaining_cents) filter (where kind = 'expense' and due_date >= v_asof and due_date <= v_asof + 30), 0)::bigint,
    coalesce(sum(remaining_cents) filter (where kind = 'revenue'), 0)::bigint
  from public.fin_entries_v where status in ('pending', 'partial');
end $function$;
--@@ 45 funcao public.fin_public_settings()
CREATE OR REPLACE FUNCTION public.fin_public_settings()
 RETURNS TABLE(due_day smallint, due_month_offset smallint, non_business_rule text, saturday_is_business boolean, late_fee_confirmed boolean, grace_days smallint, fine_fixed_cents bigint, fine_percent_bps integer, interest_daily_fixed_cents bigint, interest_daily_percent_bps integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select s.due_day, s.due_month_offset, s.non_business_rule, s.saturday_is_business,
    (s.late_fee_confirmed_at is not null), s.grace_days,
    case when s.late_fee_confirmed_at is not null then s.fine_fixed_cents end,
    case when s.late_fee_confirmed_at is not null then s.fine_percent_bps end,
    case when s.late_fee_confirmed_at is not null then s.interest_daily_fixed_cents end,
    case when s.late_fee_confirmed_at is not null then s.interest_daily_percent_bps end
  from public.fin_settings s where auth.uid() is not null $function$;
--@@ 45 funcao public.fin_receipt_queue(p_status text, p_limit integer, p_offs
CREATE OR REPLACE FUNCTION public.fin_receipt_queue(p_status text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, profile_id uuid, profile_name text, status text, file_name text, content_type text, size_bytes integer, declared_amount_cents bigint, declared_paid_on date, ocr_status text, ocr jsonb, possible_duplicate boolean, charge_count bigint, created_at timestamp with time zone, reviewed_at timestamp with time zone, decision_reason text, total_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform fin_private.require_admin();
  return query
  select s.id, s.profile_id, p.name, s.status, s.file_name, s.content_type, s.size_bytes, s.declared_amount_cents, s.declared_paid_on,
    s.ocr_status, s.ocr, s.possible_duplicate, (select count(*) from public.fin_receipt_charges rc where rc.submission_id = s.id),
    s.created_at, s.reviewed_at, s.decision_reason, count(*) over()
  from public.fin_receipt_submissions s join public.profiles p on p.id = s.profile_id
  where (p_status is null or (p_status = 'pending' and s.status in ('submitted', 'in_review')) or s.status = p_status)
  order by case when s.status in ('submitted', 'in_review') then 0 else 1 end, s.created_at desc
  limit least(greatest(p_limit, 0), 500) offset greatest(p_offset, 0);
end $function$;
--@@ 45 funcao public.fin_receivables_summary(p_as_of date)
CREATE OR REPLACE FUNCTION public.fin_receivables_summary(p_as_of date DEFAULT NULL::date)
 RETURNS TABLE(open_count bigint, open_cents bigint, overdue_count bigint, overdue_cents bigint, due_7d_cents bigint, due_30d_cents bigint, forecast_cents bigint, fees_configured boolean, overdue_members bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_asof date := coalesce(p_as_of, fin_private.today());
begin
  perform fin_private.require_admin();
  return query
  with r as (select * from fin_private.charge_rows(null, null, '{}'::jsonb, v_asof, 100000, 0) where stored_status in ('open', 'partial'))
  select count(*), coalesce(sum(total_due_cents), 0)::bigint,
    count(*) filter (where overdue), coalesce(sum(total_due_cents) filter (where overdue), 0)::bigint,
    coalesce(sum(total_due_cents) filter (where not overdue and due_date <= v_asof + 7), 0)::bigint,
    coalesce(sum(total_due_cents) filter (where not overdue and due_date <= v_asof + 30), 0)::bigint,
    coalesce(sum(total_due_cents) filter (where display_status = 'forecast'), 0)::bigint,
    coalesce(bool_and(r.fees_configured), (select late_fee_confirmed_at is not null from public.fin_settings)),
    count(distinct profile_id) filter (where overdue)
  from r;
end $function$;
--@@ 45 funcao public.fin_register_payment(p_request_id uuid, p_charge uuid, p
CREATE OR REPLACE FUNCTION public.fin_register_payment(p_request_id uuid, p_charge uuid, p_amount_cents bigint, p_paid_on date, p_method text, p_account uuid, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_replay jsonb; v_res jsonb;
begin
  perform fin_private.require_admin();
  v_replay := fin_private.begin_op(p_request_id, 'charge_payment', p_note);
  if v_replay is not null then return v_replay; end if;
  v_res := fin_private.apply_payment(p_charge, p_amount_cents, p_paid_on, p_method, p_account, null, null, p_note, p_request_id);
  return fin_private.finish_op(p_request_id, v_res);
end $function$;
--@@ 45 funcao public.fin_reject_receipt(p_request_id uuid, p_submission_id uu
CREATE OR REPLACE FUNCTION public.fin_reject_receipt(p_request_id uuid, p_submission_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; s public.fin_receipt_submissions%rowtype;
begin
  v_actor := fin_private.require_admin();
  if p_reason is null or length(trim(p_reason)) < 5 then raise exception 'REASON_REQUIRED'; end if;
  v_replay := fin_private.begin_op(p_request_id, 'receipt_reject', p_reason);
  if v_replay is not null then return v_replay; end if;
  select * into s from public.fin_receipt_submissions where id = p_submission_id for update;
  if not found then raise exception 'RECEIPT_NOT_FOUND'; end if;
  if s.status not in ('submitted', 'in_review') then raise exception 'RECEIPT_NOT_PENDING'; end if;
  update public.fin_receipt_submissions set status = 'rejected', reviewed_by = v_actor, reviewed_at = now(),
    decision_reason = trim(p_reason), version = version + 1, updated_at = now() where id = p_submission_id;
  return fin_private.finish_op(p_request_id, jsonb_build_object('id', p_submission_id, 'status', 'rejected'));
end $function$;
--@@ 45 funcao public.fin_remove_attachment(p_request_id uuid, p_id uuid, p_re
CREATE OR REPLACE FUNCTION public.fin_remove_attachment(p_request_id uuid, p_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb;
begin
  v_actor := fin_private.require_admin();
  if p_reason is null or length(trim(p_reason)) < 3 then raise exception 'REASON_REQUIRED'; end if;
  v_replay := fin_private.begin_op(p_request_id, 'attachment_remove', p_reason);
  if v_replay is not null then return v_replay; end if;
  update public.fin_attachments set removed_at = now(), removed_by = v_actor where id = p_id and removed_at is null;
  if not found then raise exception 'ATTACHMENT_NOT_FOUND'; end if;
  return fin_private.finish_op(p_request_id, jsonb_build_object('id', p_id));
end $function$;
--@@ 45 funcao public.fin_resolve_credit(p_request_id uuid, p_credit uuid, p_a
CREATE OR REPLACE FUNCTION public.fin_resolve_credit(p_request_id uuid, p_credit uuid, p_action text, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; cr public.fin_member_credits%rowtype; ch public.fin_member_charges%rowtype; st record;
  v_amount bigint; v_res jsonb; v_entry uuid; v_name text; v_today date := fin_private.today();
begin
  v_actor := fin_private.require_admin();
  v_replay := fin_private.begin_op(p_request_id, 'credit_' || coalesce(p_action, ''), p_data->>'reason');
  if v_replay is not null then return v_replay; end if;
  select * into cr from public.fin_member_credits where id = p_credit for update;
  if not found then raise exception 'CREDIT_NOT_FOUND'; end if;
  if cr.status <> 'open' or cr.remaining_cents <= 0 then raise exception 'CREDIT_NOT_OPEN'; end if;
  if p_action = 'apply' then
    select * into ch from public.fin_member_charges where id = (p_data->>'charge_id')::uuid for update;
    if not found then raise exception 'CHARGE_NOT_FOUND'; end if;
    if ch.profile_id <> cr.profile_id then raise exception 'CREDIT_OWNER_MISMATCH'; end if;
    select * into st from fin_private.charge_statement(ch.id, v_today);
    v_amount := least(coalesce((p_data->>'amount_cents')::bigint, cr.remaining_cents), cr.remaining_cents, st.total_due);
    if v_amount <= 0 then raise exception 'NOTHING_TO_APPLY'; end if;
    v_res := fin_private.apply_payment(ch.id, v_amount, v_today, 'credit', null, null, cr.id, 'Aplicação de crédito do sócio', p_request_id);
    update public.fin_member_credits set remaining_cents = remaining_cents - v_amount,
      status = case when remaining_cents - v_amount = 0 then 'applied' else 'open' end,
      resolved_at = case when remaining_cents - v_amount = 0 then now() end, resolved_by = case when remaining_cents - v_amount = 0 then v_actor end
    where id = cr.id;
  elsif p_action = 'refund' then
    if p_data->>'reason' is null or length(trim(p_data->>'reason')) < 3 then raise exception 'REASON_REQUIRED'; end if;
    select name into v_name from public.profiles where id = cr.profile_id;
    insert into public.fin_entries(kind, status, description, amount_cents, competence_date, settled_on, request_id, created_by, updated_by)
    values ('member_refund', 'paid', left('Devolução de crédito — ' || coalesce(v_name, 'sócio'), 140), cr.remaining_cents, v_today, v_today,
      gen_random_uuid(), v_actor, v_actor) returning id into v_entry;
    perform fin_private.add_entry_payment(v_entry, cr.remaining_cents, coalesce((p_data->>'paid_on')::date, v_today),
      (p_data->>'account_id')::uuid, p_data->>'reason', true, gen_random_uuid());
    update public.fin_member_credits set remaining_cents = 0, status = 'refunded', refund_entry_id = v_entry,
      resolution_note = trim(p_data->>'reason'), resolved_at = now(), resolved_by = v_actor where id = cr.id;
    v_res := jsonb_build_object('entry_id', v_entry);
  elsif p_action = 'void' then
    if p_data->>'reason' is null or length(trim(p_data->>'reason')) < 5 then raise exception 'REASON_REQUIRED'; end if;
    update public.fin_member_credits set remaining_cents = 0, status = 'void', resolution_note = trim(p_data->>'reason'),
      resolved_at = now(), resolved_by = v_actor where id = cr.id;
    v_res := '{}'::jsonb;
  else
    raise exception 'INVALID_ACTION';
  end if;
  return fin_private.finish_op(p_request_id, jsonb_build_object('credit_id', p_credit, 'result', v_res));
end $function$;
--@@ 45 funcao public.fin_reverse_entry_payment(p_request_id uuid, p_payment_i
CREATE OR REPLACE FUNCTION public.fin_reverse_entry_payment(p_request_id uuid, p_payment_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; p public.fin_entry_payments%rowtype; e public.fin_entries%rowtype; v_paid bigint;
begin
  v_actor := fin_private.require_admin();
  if p_reason is null or length(trim(p_reason)) < 3 then raise exception 'REASON_REQUIRED'; end if;
  v_replay := fin_private.begin_op(p_request_id, 'entry_payment_reverse', p_reason);
  if v_replay is not null then return v_replay; end if;
  select * into p from public.fin_entry_payments where id = p_payment_id;
  if not found then raise exception 'PAYMENT_NOT_FOUND'; end if;
  if p.kind <> 'payment' then raise exception 'PAYMENT_NOT_FOUND'; end if;
  select * into e from public.fin_entries where id = p.entry_id for update;
  if exists (select 1 from public.fin_entry_payments where reverses_payment_id = p_payment_id) then raise exception 'PAYMENT_ALREADY_REVERSED'; end if;
  insert into public.fin_entry_payments(entry_id, kind, amount_cents, paid_on, account_id, reverses_payment_id, note, actor_id, request_id)
  values (p.entry_id, 'reversal', p.amount_cents, fin_private.today(), p.account_id, p.id, trim(p_reason), v_actor, p_request_id);
  v_paid := fin_private.entry_paid_cents(p.entry_id);
  if e.kind in ('expense', 'revenue') then
    update public.fin_entries set status = case when v_paid <= 0 then 'pending' when v_paid >= amount_cents then 'paid' else 'partial' end,
      settled_on = case when v_paid >= amount_cents then settled_on end,
      adjustment_cents = case when v_paid >= amount_cents then adjustment_cents else 0 end,
      version = version + 1, updated_at = now(), updated_by = v_actor where id = p.entry_id;
  else
    update public.fin_entries set status = 'canceled', canceled_at = now(), canceled_by = v_actor, cancel_reason = trim(p_reason),
      version = version + 1, updated_at = now(), updated_by = v_actor where id = p.entry_id;
  end if;
  return fin_private.finish_op(p_request_id, jsonb_build_object('id', p.entry_id));
end $function$;
--@@ 45 funcao public.fin_reverse_payment(p_request_id uuid, p_payment_id uuid
CREATE OR REPLACE FUNCTION public.fin_reverse_payment(p_request_id uuid, p_payment_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; p public.fin_charge_payments%rowtype; v_latest uuid; v_credit public.fin_member_credits%rowtype; v_status text;
begin
  v_actor := fin_private.require_admin();
  if p_reason is null or length(trim(p_reason)) < 5 then raise exception 'REASON_REQUIRED'; end if;
  v_replay := fin_private.begin_op(p_request_id, 'charge_payment_reverse', p_reason);
  if v_replay is not null then return v_replay; end if;
  select * into p from public.fin_charge_payments where id = p_payment_id and kind = 'payment';
  if not found then raise exception 'PAYMENT_NOT_FOUND'; end if;
  perform 1 from public.fin_member_charges where id = p.charge_id for update;
  if exists (select 1 from public.fin_charge_payments where reverses_payment_id = p_payment_id) then raise exception 'PAYMENT_ALREADY_REVERSED'; end if;
  select id into v_latest from fin_private.charge_payments_effective where charge_id = p.charge_id order by paid_on desc, created_at desc, id desc limit 1;
  if v_latest <> p_payment_id then raise exception 'ONLY_LAST_PAYMENT_REVERSIBLE'; end if;
  -- O excedente deste pagamento só some se ainda não foi usado.
  select * into v_credit from public.fin_member_credits where source_payment_id = p_payment_id for update;
  if found then
    if v_credit.status <> 'open' or v_credit.remaining_cents <> v_credit.amount_cents then raise exception 'CREDIT_ALREADY_USED'; end if;
    update public.fin_member_credits set status = 'void', remaining_cents = 0, resolution_note = 'Pagamento de origem estornado',
      resolved_at = now(), resolved_by = v_actor where id = v_credit.id;
  end if;
  -- Estornar uma aplicação de crédito devolve o valor ao crédito.
  if p.method = 'credit' and p.credit_id is not null then
    update public.fin_member_credits set remaining_cents = remaining_cents + p.amount_cents, status = 'open',
      resolved_at = null, resolved_by = null where id = p.credit_id;
  end if;
  insert into public.fin_charge_payments(charge_id, kind, amount_cents, paid_on, fine_cents, interest_cents, principal_cents, excess_cents,
    method, account_id, credit_id, reverses_payment_id, note, actor_id, request_id)
  values (p.charge_id, 'reversal', p.amount_cents, fin_private.today(), p.fine_cents, p.interest_cents, p.principal_cents, p.excess_cents,
    p.method, p.account_id, p.credit_id, p.id, trim(p_reason), v_actor, p_request_id);
  v_status := fin_private.refresh_charge_status(p.charge_id);
  return fin_private.finish_op(p_request_id, jsonb_build_object('charge_id', p.charge_id, 'charge_status', v_status));
end $function$;
--@@ 45 funcao public.fin_save_account(p_request_id uuid, p_id uuid, p_expecte
CREATE OR REPLACE FUNCTION public.fin_save_account(p_request_id uuid, p_id uuid, p_expected_version integer, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; a public.fin_accounts%rowtype; n public.fin_accounts%rowtype; v_id uuid;
begin
  v_actor := fin_private.require_admin();
  v_replay := fin_private.begin_op(p_request_id, case when p_id is null then 'account_create' else 'account_update' end);
  if v_replay is not null then return v_replay; end if;
  if p_id is null then
    n.active := true; n.position := 0; n.is_default_receipts := false; n.opening_balance_cents := 0;
    n.opening_date := fin_private.today();
  else
    select * into a from public.fin_accounts where id = p_id for update;
    if not found then raise exception 'ACCOUNT_NOT_FOUND'; end if;
    if a.version <> p_expected_version then raise exception 'VERSION_CONFLICT'; end if;
    n := a;
  end if;
  if p_data ? 'name' then n.name := trim(p_data->>'name'); end if;
  if p_data ? 'kind' then n.kind := p_data->>'kind'; end if;
  if p_data ? 'opening_balance_cents' then n.opening_balance_cents := (p_data->>'opening_balance_cents')::bigint; end if;
  if p_data ? 'opening_date' then n.opening_date := (p_data->>'opening_date')::date; end if;
  if p_data ? 'position' then n.position := (p_data->>'position')::integer; end if;
  if p_data ? 'active' then n.active := (p_data->>'active')::boolean; end if;
  if p_data ? 'is_default_receipts' then n.is_default_receipts := (p_data->>'is_default_receipts')::boolean; end if;
  if n.name is null or length(n.name) < 2 or length(n.name) > 60 or n.kind not in ('cash', 'bank', 'card', 'other')
     or n.opening_date is null or abs(n.opening_balance_cents) > 100000000000 then raise exception 'INVALID_ACCOUNT'; end if;
  if not n.active and n.is_default_receipts then raise exception 'ACCOUNT_LINKED'; end if;
  if n.is_default_receipts then
    update public.fin_accounts set is_default_receipts = false, version = version + 1, updated_at = now(), updated_by = v_actor
    where is_default_receipts and id is distinct from p_id;
  end if;
  begin
    if p_id is null then
      insert into public.fin_accounts(name, kind, opening_balance_cents, opening_date, is_default_receipts, active, position, created_by, updated_by)
      values (n.name, n.kind, n.opening_balance_cents, n.opening_date, n.is_default_receipts, n.active, coalesce(n.position, 0), v_actor, v_actor)
      returning id into v_id;
    else
      update public.fin_accounts set name = n.name, kind = n.kind, opening_balance_cents = n.opening_balance_cents,
        opening_date = n.opening_date, is_default_receipts = n.is_default_receipts, active = n.active, position = n.position,
        version = version + 1, updated_at = now(), updated_by = v_actor where id = p_id;
      v_id := p_id;
    end if;
  exception when unique_violation then raise exception 'ACCOUNT_NAME_TAKEN';
  end;
  return fin_private.finish_op(p_request_id, jsonb_build_object('id', v_id, 'version', coalesce(a.version, 0) + 1));
end $function$;
--@@ 45 funcao public.fin_save_category(p_request_id uuid, p_id uuid, p_expect
CREATE OR REPLACE FUNCTION public.fin_save_category(p_request_id uuid, p_id uuid, p_expected_version integer, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; c public.fin_categories%rowtype; n public.fin_categories%rowtype;
  v_parent public.fin_categories%rowtype; v_id uuid;
begin
  v_actor := fin_private.require_admin();
  v_replay := fin_private.begin_op(p_request_id, case when p_id is null then 'category_create' else 'category_update' end);
  if v_replay is not null then return v_replay; end if;
  if p_id is null then
    n.kind := p_data->>'kind'; n.parent_id := (p_data->>'parent_id')::uuid; n.active := true; n.position := 0;
    if n.kind not in ('expense', 'revenue') then raise exception 'INVALID_CATEGORY'; end if;
    if n.parent_id is not null then
      select * into v_parent from public.fin_categories where id = n.parent_id;
      if not found or v_parent.parent_id is not null or v_parent.kind <> n.kind or not v_parent.active then raise exception 'INVALID_CATEGORY'; end if;
      n.dre_line := v_parent.dre_line;
    end if;
  else
    select * into c from public.fin_categories where id = p_id for update;
    if not found then raise exception 'CATEGORY_NOT_FOUND'; end if;
    if c.version <> p_expected_version then raise exception 'VERSION_CONFLICT'; end if;
    n := c;
  end if;
  if p_data ? 'name' then n.name := trim(p_data->>'name'); end if;
  if p_data ? 'position' then n.position := (p_data->>'position')::integer; end if;
  if p_data ? 'dre_line' then
    if c.system_key is not null and p_data->>'dre_line' <> c.dre_line then raise exception 'CATEGORY_SYSTEM'; end if;
    n.dre_line := p_data->>'dre_line';
  end if;
  if p_data ? 'active' then n.active := (p_data->>'active')::boolean; end if;
  if n.name is null or length(n.name) < 2 or length(n.name) > 60 then raise exception 'INVALID_CATEGORY'; end if;
  if n.dre_line is null or not ((n.kind = 'revenue' and n.dre_line in ('revenue', 'deduction', 'none')) or
      (n.kind = 'expense' and n.dre_line in ('variable_cost', 'operational', 'administrative', 'commercial', 'financial', 'none')))
    then raise exception 'INVALID_CATEGORY'; end if;
  if p_id is not null and not n.active and c.active then
    if c.system_key is not null then raise exception 'CATEGORY_SYSTEM'; end if;
    if exists (select 1 from public.fin_categories where parent_id = p_id and active) then raise exception 'CATEGORY_HAS_ACTIVE_CHILDREN'; end if;
  end if;
  begin
    if p_id is null then
      insert into public.fin_categories(parent_id, name, kind, dre_line, position, created_by, updated_by)
      values (n.parent_id, n.name, n.kind, n.dre_line, coalesce(n.position, 0), v_actor, v_actor) returning id into v_id;
    else
      update public.fin_categories set name = n.name, dre_line = n.dre_line, active = n.active, position = n.position,
        version = version + 1, updated_at = now(), updated_by = v_actor where id = p_id;
      v_id := p_id;
    end if;
  exception when unique_violation then raise exception 'CATEGORY_NAME_TAKEN';
  end;
  return fin_private.finish_op(p_request_id, jsonb_build_object('id', v_id, 'version', coalesce(c.version, 0) + 1));
end $function$;
--@@ 45 funcao public.fin_save_holiday(p_request_id uuid, p_id uuid, p_data js
CREATE OR REPLACE FUNCTION public.fin_save_holiday(p_request_id uuid, p_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; h public.fin_holidays%rowtype; v_id uuid;
begin
  v_actor := fin_private.require_admin();
  v_replay := fin_private.begin_op(p_request_id, case when p_id is null then 'holiday_create' else 'holiday_update' end);
  if v_replay is not null then return v_replay; end if;
  if p_id is null then
    h.holiday_date := (p_data->>'holiday_date')::date; h.name := trim(p_data->>'name');
    h.scope := coalesce(p_data->>'scope', 'municipal'); h.kind := 'holiday'; h.active := coalesce((p_data->>'active')::boolean, true);
    if h.scope = 'national' then raise exception 'INVALID_HOLIDAY'; end if; -- nacionais vêm da semeadura por lei
    begin
      insert into public.fin_holidays(holiday_date, name, scope, kind, active, created_by, updated_by)
      values (h.holiday_date, h.name, h.scope, h.kind, h.active, v_actor, v_actor) returning id into v_id;
    exception when unique_violation then raise exception 'HOLIDAY_EXISTS';
    end;
  else
    select * into h from public.fin_holidays where id = p_id for update;
    if not found then raise exception 'HOLIDAY_NOT_FOUND'; end if;
    if p_data ? 'active' then h.active := (p_data->>'active')::boolean; end if;
    if p_data ? 'name' and h.scope <> 'national' then h.name := trim(p_data->>'name'); end if;
    update public.fin_holidays set active = h.active, name = h.name, updated_at = now(), updated_by = v_actor where id = p_id;
    v_id := p_id;
  end if;
  return fin_private.finish_op(p_request_id, jsonb_build_object('id', v_id));
end $function$;
--@@ 45 funcao public.fin_save_recurrence(p_request_id uuid, p_id uuid, p_expe
CREATE OR REPLACE FUNCTION public.fin_save_recurrence(p_request_id uuid, p_id uuid, p_expected_version integer, p_data jsonb, p_apply_from date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; r public.fin_recurrences%rowtype; n public.fin_recurrences%rowtype; v_from date; v_id uuid;
begin
  v_actor := fin_private.require_admin();
  v_replay := fin_private.begin_op(p_request_id, case when p_id is null then 'recurrence_create' else 'recurrence_update' end, p_data->>'reason');
  if v_replay is not null then return v_replay; end if;
  if p_id is not null then
    select * into r from public.fin_recurrences where id = p_id for update;
    if not found then raise exception 'RECURRENCE_NOT_FOUND'; end if;
    if r.version <> p_expected_version then raise exception 'VERSION_CONFLICT'; end if;
    n := r;
  else
    n.frequency := 'monthly'; n.due_month_offset := 0; n.active := true;
  end if;
  if p_data ? 'description' then n.description := trim(p_data->>'description'); end if;
  if p_data ? 'supplier' then n.supplier := nullif(trim(p_data->>'supplier'), ''); end if;
  if p_data ? 'notes' then n.notes := nullif(trim(p_data->>'notes'), ''); end if;
  if p_data ? 'category_id' then n.category_id := (p_data->>'category_id')::uuid; end if;
  if p_data ? 'amount_cents' then n.amount_cents := (p_data->>'amount_cents')::bigint; end if;
  if p_data ? 'frequency' then n.frequency := p_data->>'frequency'; end if;
  if p_data ? 'due_day' then n.due_day := (p_data->>'due_day')::smallint; end if;
  if p_data ? 'due_month_offset' then n.due_month_offset := (p_data->>'due_month_offset')::smallint; end if;
  if p_data ? 'start_month' and p_id is null then n.start_month := date_trunc('month', (p_data->>'start_month')::date::timestamp)::date; end if;
  if p_data ? 'end_month' then n.end_month := date_trunc('month', (p_data->>'end_month')::date::timestamp)::date; end if;
  if p_data ? 'account_id' then n.account_id := (p_data->>'account_id')::uuid; end if;
  if p_data ? 'active' then n.active := (p_data->>'active')::boolean; end if;
  if n.description is null or length(n.description) < 2 or length(n.description) > 140 then raise exception 'INVALID_RECURRENCE'; end if;
  if n.amount_cents is null or n.amount_cents <= 0 or n.amount_cents > 1000000000 then raise exception 'INVALID_AMOUNT'; end if;
  if n.frequency not in ('monthly', 'quarterly', 'yearly') or n.due_day is null or n.due_day not between 1 and 31
     or n.due_month_offset not between 0 and 2 or n.start_month is null
     or (n.end_month is not null and n.end_month < n.start_month) then raise exception 'INVALID_RECURRENCE'; end if;
  if p_id is null or n.category_id is distinct from r.category_id then perform fin_private.check_category(n.category_id, 'expense'); end if;
  if n.account_id is not null and (p_id is null or n.account_id is distinct from r.account_id) then perform fin_private.check_account(n.account_id); end if;

  if p_id is null then
    insert into public.fin_recurrences(description, supplier, category_id, amount_cents, frequency, due_day, due_month_offset,
      start_month, end_month, account_id, notes, active, created_by, updated_by)
    values (n.description, n.supplier, n.category_id, n.amount_cents, n.frequency, n.due_day, n.due_month_offset,
      n.start_month, n.end_month, n.account_id, n.notes, n.active, v_actor, v_actor) returning id into v_id;
    perform fin_private.generate_recurrences(v_id, null);
    return fin_private.finish_op(p_request_id, jsonb_build_object('id', v_id, 'version', 1));
  end if;

  v_from := date_trunc('month', coalesce(p_apply_from, fin_private.today())::timestamp)::date;
  update public.fin_recurrences set description = n.description, supplier = n.supplier, notes = n.notes, category_id = n.category_id,
    amount_cents = n.amount_cents, frequency = n.frequency, due_day = n.due_day, due_month_offset = n.due_month_offset,
    end_month = n.end_month, account_id = n.account_id, active = n.active, version = version + 1, updated_at = now(), updated_by = v_actor
  where id = p_id;
  -- Só competências a partir de `v_from`, ainda pendentes e sem pagamento.
  update public.fin_entries set description = n.description, supplier = n.supplier, category_id = n.category_id,
    amount_cents = n.amount_cents, account_id = n.account_id, notes = n.notes,
    due_date = fin_private.recurrence_due_date(competence_date, n.due_day, n.due_month_offset),
    version = version + 1, updated_at = now(), updated_by = v_actor
  where recurrence_id = p_id and status = 'pending' and competence_date >= v_from
    and fin_private.entry_paid_cents(id) = 0;
  -- Encerrada ou pausada: o pendente que ficaria fora é cancelado, nunca apagado.
  update public.fin_entries set status = 'canceled', canceled_at = now(), canceled_by = v_actor,
    cancel_reason = 'Recorrência encerrada ou pausada', version = version + 1, updated_at = now(), updated_by = v_actor
  where recurrence_id = p_id and status = 'pending' and fin_private.entry_paid_cents(id) = 0
    and ((n.end_month is not null and competence_date > n.end_month) or (not n.active and competence_date >= v_from));
  if n.active then perform fin_private.generate_recurrences(p_id, null); end if;
  return fin_private.finish_op(p_request_id, jsonb_build_object('id', p_id, 'version', r.version + 1));
end $function$;
--@@ 45 funcao public.fin_save_settings(p_request_id uuid, p_expected_version 
CREATE OR REPLACE FUNCTION public.fin_save_settings(p_request_id uuid, p_expected_version integer, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid; v_replay jsonb; s public.fin_settings%rowtype; n public.fin_settings%rowtype; v_confirm boolean;
  v_days integer[]; v_x integer;
begin
  v_actor := fin_private.require_admin();
  v_replay := fin_private.begin_op(p_request_id, 'settings_save', p_data->>'reason');
  if v_replay is not null then return v_replay; end if;
  select * into s from public.fin_settings for update;
  if s.version <> p_expected_version then raise exception 'VERSION_CONFLICT'; end if;
  n := s;

  if p_data ? 'due_day' then n.due_day := (p_data->>'due_day')::smallint; end if;
  if p_data ? 'due_month_offset' then n.due_month_offset := (p_data->>'due_month_offset')::smallint; end if;
  if p_data ? 'non_business_rule' then n.non_business_rule := p_data->>'non_business_rule'; end if;
  if p_data ? 'saturday_is_business' then n.saturday_is_business := (p_data->>'saturday_is_business')::boolean; end if;
  if p_data ? 'horizon_months' then n.horizon_months := (p_data->>'horizon_months')::smallint; end if;
  if p_data ? 'grace_days' then n.grace_days := (p_data->>'grace_days')::smallint; end if;
  if p_data ? 'fine_fixed_cents' then n.fine_fixed_cents := (p_data->>'fine_fixed_cents')::bigint; end if;
  if p_data ? 'fine_percent_bps' then n.fine_percent_bps := (p_data->>'fine_percent_bps')::integer; end if;
  if p_data ? 'interest_daily_fixed_cents' then n.interest_daily_fixed_cents := (p_data->>'interest_daily_fixed_cents')::bigint; end if;
  if p_data ? 'interest_daily_percent_bps' then n.interest_daily_percent_bps := (p_data->>'interest_daily_percent_bps')::integer; end if;
  if p_data ? 'day_card_price_cents' then n.day_card_price_cents := (p_data->>'day_card_price_cents')::bigint; end if;
  if p_data ? 'day_card_in_cash' then n.day_card_in_cash := (p_data->>'day_card_in_cash')::boolean; end if;
  if p_data ? 'payee_names' then
    n.payee_names := coalesce(array(select trim(x) from jsonb_array_elements_text(p_data->'payee_names') x where length(trim(x)) > 0), '{}');
  end if;

  if p_data ? 'pix_key' then
    n.pix_key := trim(coalesce(p_data->>'pix_key',''));
    if length(n.pix_key) < 3 or length(n.pix_key) > 120 then raise exception 'INVALID_PIX_KEY'; end if;
  end if;
  if p_data ? 'pendency_automation_enabled' then n.pendency_automation_enabled := (p_data->>'pendency_automation_enabled')::boolean; end if;
  if p_data ? 'pendency_reminder_days' then
    select coalesce(array_agg(distinct x order by x), '{}') into v_days
    from (select value::integer x from jsonb_array_elements_text(p_data->'pendency_reminder_days')) q;
    if cardinality(v_days) < 1 or cardinality(v_days) > 20 then raise exception 'INVALID_REMINDER_DAYS'; end if;
    foreach v_x in array v_days loop
      if v_x < 0 or v_x > 365 then raise exception 'INVALID_REMINDER_DAYS'; end if;
    end loop;
    n.pendency_reminder_days := v_days;
  end if;
  if p_data ? 'pendency_grace_days' then n.pendency_grace_days := (p_data->>'pendency_grace_days')::smallint; end if;
  if p_data ? 'pendency_fine_fixed_cents' then n.pendency_fine_fixed_cents := (p_data->>'pendency_fine_fixed_cents')::bigint; end if;
  if p_data ? 'pendency_fine_percent_bps' then n.pendency_fine_percent_bps := (p_data->>'pendency_fine_percent_bps')::integer; end if;
  if p_data ? 'pendency_interest_daily_fixed_cents' then n.pendency_interest_daily_fixed_cents := (p_data->>'pendency_interest_daily_fixed_cents')::bigint; end if;
  if p_data ? 'pendency_interest_daily_percent_bps' then n.pendency_interest_daily_percent_bps := (p_data->>'pendency_interest_daily_percent_bps')::integer; end if;

  if p_data ? 'late_fee_confirmed' then
    v_confirm := (p_data->>'late_fee_confirmed')::boolean;
    if v_confirm and s.late_fee_confirmed_at is null then n.late_fee_confirmed_at := now(); n.late_fee_confirmed_by := v_actor;
    elsif not v_confirm then n.late_fee_confirmed_at := null; n.late_fee_confirmed_by := null; end if;
  end if;

  if s.late_fee_confirmed_at is not null and (
      n.grace_days is distinct from s.grace_days or n.fine_fixed_cents is distinct from s.fine_fixed_cents
      or n.fine_percent_bps is distinct from s.fine_percent_bps
      or n.interest_daily_fixed_cents is distinct from s.interest_daily_fixed_cents
      or n.interest_daily_percent_bps is distinct from s.interest_daily_percent_bps)
     and (p_data->>'reason' is null or length(trim(p_data->>'reason')) < 5) then
    raise exception 'REASON_REQUIRED';
  end if;

  update public.fin_settings set
    due_day=n.due_day, due_month_offset=n.due_month_offset, non_business_rule=n.non_business_rule,
    saturday_is_business=n.saturday_is_business, horizon_months=n.horizon_months,
    grace_days=n.grace_days, fine_fixed_cents=n.fine_fixed_cents, fine_percent_bps=n.fine_percent_bps,
    interest_daily_fixed_cents=n.interest_daily_fixed_cents, interest_daily_percent_bps=n.interest_daily_percent_bps,
    day_card_price_cents=n.day_card_price_cents, day_card_in_cash=n.day_card_in_cash,
    payee_names=n.payee_names, late_fee_confirmed_at=n.late_fee_confirmed_at, late_fee_confirmed_by=n.late_fee_confirmed_by,
    pix_key=n.pix_key, pendency_automation_enabled=n.pendency_automation_enabled, pendency_reminder_days=n.pendency_reminder_days,
    pendency_grace_days=n.pendency_grace_days, pendency_fine_fixed_cents=n.pendency_fine_fixed_cents,
    pendency_fine_percent_bps=n.pendency_fine_percent_bps,
    pendency_interest_daily_fixed_cents=n.pendency_interest_daily_fixed_cents,
    pendency_interest_daily_percent_bps=n.pendency_interest_daily_percent_bps,
    version=version+1, updated_at=now(), updated_by=v_actor
  where id;

  return fin_private.finish_op(p_request_id, jsonb_build_object('version', s.version+1));
end $function$;
--@@ 45 funcao public.fin_seed_holidays(p_request_id uuid, p_year integer)
CREATE OR REPLACE FUNCTION public.fin_seed_holidays(p_request_id uuid, p_year integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_replay jsonb; v_n integer;
begin
  perform fin_private.require_admin();
  v_replay := fin_private.begin_op(p_request_id, 'holidays_seed');
  if v_replay is not null then return v_replay; end if;
  if p_year is null or p_year < 2000 or p_year > 2100 then raise exception 'INVALID_PERIOD'; end if;
  v_n := fin_private.seed_holidays(p_year);
  return fin_private.finish_op(p_request_id, jsonb_build_object('year', p_year, 'inserted', v_n));
end $function$;
--@@ 45 funcao public.fin_send_pendency_now(p_request_id uuid, p_charge uuid)
CREATE OR REPLACE FUNCTION public.fin_send_pendency_now(p_request_id uuid, p_charge uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; c public.fin_member_charges%rowtype; v_rec uuid; v_existing jsonb;
begin
  v_actor:=fin_private.require_admin();
  v_replay:=fin_private.begin_op(p_request_id,'member_pendency_send_now','Cobrança manual');
  if v_replay is not null then return v_replay; end if;
  select * into c from public.fin_member_charges where id=p_charge for update;
  if not found or c.charge_type<>'member_pendency' then raise exception 'PENDENCY_NOT_FOUND'; end if;
  if c.status not in ('open','partial') then raise exception 'PENDENCY_NOT_OPEN'; end if;
  if not c.collection_enabled then raise exception 'COLLECTION_PAUSED'; end if;
  perform pg_advisory_xact_lock(hashtextextended('pendency_send:'||c.profile_id::text,7));
  v_existing:=conv_private.pendency_send_existing(c.profile_id);
  if v_existing is not null then
    return fin_private.finish_op(p_request_id,jsonb_build_object('id',c.id,'automation_recipient_id',(v_existing->>'id')::uuid,
      'already',v_existing->>'status','already_hhmm',v_existing->>'hhmm'));
  end if;
  v_rec:=conv_private.queue_member_pendency_now(c.profile_id,c.id);
  return fin_private.finish_op(p_request_id,jsonb_build_object('id',c.id,'automation_recipient_id',v_rec));
end $function$;
--@@ 45 funcao public.fin_set_pendency_collection(p_request_id uuid, p_charge 
CREATE OR REPLACE FUNCTION public.fin_set_pendency_collection(p_request_id uuid, p_charge uuid, p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; c public.fin_member_charges%rowtype;
begin
  v_actor:=fin_private.require_admin();
  v_replay:=fin_private.begin_op(p_request_id,'member_pendency_collection',case when p_enabled then 'ativar cobrança' else 'pausar cobrança' end);
  if v_replay is not null then return v_replay; end if;
  select * into c from public.fin_member_charges where id=p_charge for update;
  if not found or c.charge_type<>'member_pendency' then raise exception 'PENDENCY_NOT_FOUND'; end if;
  update public.fin_member_charges set collection_enabled=p_enabled,version=version+1,updated_at=now(),updated_by=v_actor where id=p_charge;
  if not p_enabled then
    update public.conv_automation_recipients
      set status='canceled',skip_reason='COBRANCA_PAUSADA'
      where profile_id=c.profile_id and status in ('pending','review')
        and automation_id in (select id from public.conv_automations where source='finance_charge' and definition->>'stage'='member_pendency');
  end if;
  return fin_private.finish_op(p_request_id,jsonb_build_object('id',p_charge,'collection_enabled',p_enabled));
end $function$;
--@@ 45 funcao public.fin_set_plan_price(p_request_id uuid, p_plan_id uuid, p_
CREATE OR REPLACE FUNCTION public.fin_set_plan_price(p_request_id uuid, p_plan_id uuid, p_effective_from date, p_amount_cents bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; v_from date; v_n integer;
begin
  v_actor := fin_private.require_admin();
  if p_reason is null or length(trim(p_reason)) < 3 then raise exception 'REASON_REQUIRED'; end if;
  v_replay := fin_private.begin_op(p_request_id, 'member_price_set', p_reason);
  if v_replay is not null then return v_replay; end if;
  if p_amount_cents is null or p_amount_cents <= 0 or p_amount_cents > 1000000000 then raise exception 'INVALID_AMOUNT'; end if;
  perform 1 from public.fin_member_plans where id = p_plan_id for update;
  if not found then raise exception 'PLAN_NOT_FOUND'; end if;
  v_from := date_trunc('month', p_effective_from::timestamp)::date;
  begin
    insert into public.fin_member_plan_prices(plan_id, effective_from, amount_cents, reason, created_by)
    values (p_plan_id, v_from, p_amount_cents, trim(p_reason), v_actor);
  exception when unique_violation then raise exception 'PRICE_EXISTS';
  end;
  update public.fin_member_charges c set original_amount_cents = p_amount_cents, version = version + 1, updated_at = now(), updated_by = v_actor
  where c.plan_id = p_plan_id and c.competence_month >= v_from and c.status = 'open'
    and not exists (select 1 from fin_private.charge_payments_effective p where p.charge_id = c.id)
    and not exists (select 1 from public.fin_charge_adjustments a where a.charge_id = c.id)
    and (select amount_cents from public.fin_member_plan_prices x where x.plan_id = c.plan_id and x.effective_from <= c.competence_month
         order by x.effective_from desc limit 1) = p_amount_cents;
  get diagnostics v_n = row_count;
  return fin_private.finish_op(p_request_id, jsonb_build_object('plan_id', p_plan_id, 'repriced_charges', v_n));
end $function$;
--@@ 45 funcao public.fin_start_receipt_review(p_request_id uuid, p_submission
CREATE OR REPLACE FUNCTION public.fin_start_receipt_review(p_request_id uuid, p_submission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; s public.fin_receipt_submissions%rowtype;
begin
  v_actor := fin_private.require_admin();
  v_replay := fin_private.begin_op(p_request_id, 'receipt_review_start');
  if v_replay is not null then return v_replay; end if;
  select * into s from public.fin_receipt_submissions where id = p_submission_id for update;
  if not found then raise exception 'RECEIPT_NOT_FOUND'; end if;
  if s.status = 'in_review' then return fin_private.finish_op(p_request_id, jsonb_build_object('id', s.id, 'status', 'in_review')); end if;
  if s.status <> 'submitted' then raise exception 'RECEIPT_NOT_PENDING'; end if;
  update public.fin_receipt_submissions set status = 'in_review', reviewed_by = v_actor, version = version + 1, updated_at = now()
  where id = p_submission_id;
  return fin_private.finish_op(p_request_id, jsonb_build_object('id', s.id, 'status', 'in_review'));
end $function$;
--@@ 45 funcao public.fin_student_revenue(p_from date, p_to date)
CREATE OR REPLACE FUNCTION public.fin_student_revenue(p_from date, p_to date)
 RETURNS TABLE(source_type text, source_id text, occurred_on date, description text, amount_cents bigint, category_name text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform fin_private.require_admin();
  perform fin_private.check_period(p_from, p_to);
  return query
  select x.source_type, x.source_id, x.occurred_on, x.description, x.amount_cents, c.name
  from fin_private.dre_rows(p_from, p_to) x join public.fin_categories c on c.id = x.category_id
  where x.source_type in ('student_payment', 'day_card') order by x.occurred_on, x.description;
end $function$;
--@@ 45 funcao public.fin_submit_receipt(p_request_id uuid, p_submission_id uu
CREATE OR REPLACE FUNCTION public.fin_submit_receipt(p_request_id uuid, p_submission_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := auth.uid(); v_replay jsonb; v_path text := p_data->>'storage_path'; v_hash text := lower(p_data->>'content_sha256');
  v_charges uuid[]; v_dup uuid; v_old public.fin_receipt_submissions%rowtype; v_replaces uuid := (p_data->>'replaces')::uuid;
  v_declared bigint := (p_data->>'declared_amount_cents')::bigint; v_ocr jsonb := p_data->'ocr'; v_auto jsonb;
begin
  if v_uid is null then raise exception 'FINANCE_FORBIDDEN' using errcode = '42501'; end if;
  if not fin_private.is_active_member(v_uid) then raise exception 'NOT_A_MEMBER'; end if;
  v_replay := fin_private.begin_op(p_request_id, 'receipt_submit');
  if v_replay is not null then return v_replay; end if;
  -- O arquivo precisa estar na pasta do próprio sócio, na pasta deste envio.
  if v_path is null or v_path !~ ('^' || v_uid::text || '/' || p_submission_id::text || '/[^/]+$') then raise exception 'INVALID_ATTACHMENT'; end if;
  if v_hash is null or v_hash !~ '^[0-9a-f]{64}$' then raise exception 'INVALID_ATTACHMENT'; end if;
  if v_declared is not null and (v_declared <= 0 or v_declared > 1000000000) then raise exception 'INVALID_AMOUNT'; end if;
  if (p_data->>'declared_paid_on') is not null and (p_data->>'declared_paid_on')::date > fin_private.today() then raise exception 'INVALID_DATE'; end if;

  select coalesce(array_agg(x::uuid), '{}') into v_charges from jsonb_array_elements_text(coalesce(p_data->'charge_ids', '[]'::jsonb)) x;
  if cardinality(v_charges) = 0 then raise exception 'NO_CHARGES_SELECTED'; end if;
  -- Só cobranças do próprio sócio, ainda em aberto.
  if (select count(*) from public.fin_member_charges c where c.id = any(v_charges) and c.profile_id = v_uid and c.status in ('open', 'partial'))
     <> cardinality(v_charges) then raise exception 'INVALID_CHARGES'; end if;

  -- Possível duplicidade: mesmo arquivo (hash) já enviado e não substituído/rejeitado.
  -- Devolve só o aviso — nunca dados de outro sócio.
  select s.id into v_dup from public.fin_receipt_submissions s
  where s.content_sha256 = v_hash and s.status in ('submitted', 'in_review', 'approved') and s.id is distinct from v_replaces
  order by s.created_at limit 1;

  if v_replaces is not null then
    select * into v_old from public.fin_receipt_submissions where id = v_replaces for update;
    if not found or v_old.profile_id <> v_uid then raise exception 'FINANCE_FORBIDDEN' using errcode = '42501'; end if;
    if v_old.status not in ('submitted', 'in_review', 'rejected') then raise exception 'RECEIPT_NOT_REPLACEABLE'; end if;
  end if;

  insert into public.fin_receipt_submissions(id, profile_id, storage_path, file_name, content_type, size_bytes, content_sha256,
    declared_amount_cents, declared_paid_on, declared_reference, member_note, ocr_status, ocr, possible_duplicate, duplicate_of, request_id)
  values (p_submission_id, v_uid, v_path, p_data->>'file_name', p_data->>'content_type', (p_data->>'size_bytes')::integer, v_hash,
    v_declared, (p_data->>'declared_paid_on')::date, nullif(left(trim(coalesce(p_data->>'declared_reference', '')), 120), ''),
    nullif(left(trim(coalesce(p_data->>'member_note', '')), 500), ''), coalesce(p_data->>'ocr_status', 'not_run'),
    case when v_ocr is null then null else v_ocr - 'raw_text' - 'text' end, v_dup is not null, v_dup, p_request_id);
  insert into public.fin_receipt_charges(submission_id, charge_id) select p_submission_id, unnest(v_charges);

  if v_replaces is not null then
    update public.fin_receipt_submissions set status = 'superseded', superseded_by = p_submission_id, version = version + 1, updated_at = now()
    where id = v_replaces;
  end if;
  -- Pendências de sócio podem ser baixadas automaticamente, mas somente se o OCR
  -- estruturado tiver alta confiança e todas as validações financeiras passarem.
  v_auto := fin_private.auto_approve_pendency_receipt(p_submission_id);
  return fin_private.finish_op(p_request_id, jsonb_build_object(
    'id', p_submission_id,
    'status', case when coalesce((v_auto->>'approved')::boolean, false) then 'approved' else 'submitted' end,
    'possible_duplicate', v_dup is not null,
    'auto_approved', coalesce((v_auto->>'approved')::boolean, false),
    'auto_reason', v_auto->>'reason',
    'payment_ids', coalesce(v_auto->'payment_ids', '[]'::jsonb)
  ));
end $function$;
--@@ 45 funcao public.fin_submit_whatsapp_pendency_receipt(p_message uuid, p_s
CREATE OR REPLACE FUNCTION public.fin_submit_whatsapp_pendency_receipt(p_message uuid, p_submission uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_role text:=coalesce(auth.role(),'');
  v_profile uuid; v_media text; v_mime text; v_name text; v_existing uuid; v_ids uuid[];
  v_amount bigint; v_paid_on date; v_ocr jsonb; v_auto jsonb; v_hash text; v_size bigint; v_review_notice uuid;
  v_ocr_status text; v_generated integer;
begin
  if v_role <> 'service_role' then raise exception 'FORBIDDEN'; end if;

  select ct.profile_id,m.media_path,m.media_mime,coalesce(m.media_name,'comprovante')
    into v_profile,v_media,v_mime,v_name
  from public.conv_messages m
  join public.conv_conversations cv on cv.id=m.conversation_id and cv.kind='direct'
  join public.conv_contacts ct on ct.id=cv.contact_id
  where m.id=p_message and m.direction='inbound'
    and m.media_path is not null
    and ct.profile_id is not null
    and ct.link_status in ('linked','manual');
  if not found then raise exception 'WHATSAPP_RECEIPT_NOT_ELIGIBLE'; end if;

  select id into v_existing from public.fin_receipt_submissions where source_message_id=p_message;
  if v_existing is not null then
    return jsonb_build_object('id',v_existing,'duplicate',true,
      'status',(select status from public.fin_receipt_submissions where id=v_existing));
  end if;

  v_ocr_status:=coalesce(nullif(p_data->>'ocr_status',''),'not_run');
  -- Só gera mensalidade (inclusive a próxima, para pagamento adiantado) se o arquivo parece mesmo um comprovante.
  v_generated:=fin_private.ensure_member_charges(v_profile,v_ocr_status='ok');

  -- Mensalidades e pendências em aberto, da mais antiga para a mais nova.
  select coalesce(array_agg(c.id order by (c.due_date>=fin_private.today()),c.due_date,c.id),'{}')
    into v_ids
  from public.fin_member_charges c
  cross join lateral fin_private.charge_statement(c.id,fin_private.today()) st
  where c.profile_id=v_profile and c.charge_type in ('membership','member_pendency')
    and c.status in ('open','partial') and st.total_due>0;
  -- Nada em aberto e nada legível: provavelmente não é comprovante (foto qualquer).
  if cardinality(v_ids)=0 and v_ocr_status<>'ok' then
    return jsonb_build_object('skipped',true,'reason','NO_OPEN_CHARGES');
  end if;

  v_amount:=nullif(p_data->>'declared_amount_cents','')::bigint;
  v_paid_on:=nullif(p_data->>'declared_paid_on','')::date;
  v_ocr:=p_data->'ocr';
  v_hash:=lower(coalesce(p_data->>'content_sha256',''));
  v_size:=coalesce(nullif(p_data->>'size_bytes','')::bigint,0);

  if v_hash !~ '^[0-9a-f]{64}$' then raise exception 'INVALID_HASH'; end if;
  if v_size<=0 or v_size>10485760 then raise exception 'INVALID_SIZE'; end if;
  if coalesce(p_data->>'storage_path','')='' then raise exception 'INVALID_STORAGE_PATH'; end if;

  insert into public.fin_receipt_submissions(
    id,profile_id,status,storage_path,file_name,content_type,size_bytes,content_sha256,
    declared_amount_cents,declared_paid_on,declared_reference,member_note,
    ocr_status,ocr,possible_duplicate,request_id,source,source_message_id,created_at,updated_at
  ) values(
    p_submission,v_profile,'submitted',p_data->>'storage_path',
    coalesce(nullif(p_data->>'file_name',''),v_name),
    coalesce(nullif(p_data->>'content_type',''),v_mime,'application/octet-stream'),
    v_size,v_hash,v_amount,v_paid_on,nullif(p_data->>'declared_reference',''),
    'Comprovante recebido pelo WhatsApp institucional',
    v_ocr_status,v_ocr,false,p_submission,'whatsapp',p_message,now(),now()
  );

  insert into public.fin_receipt_charges(submission_id,charge_id)
  select p_submission,unnest(v_ids);

  update public.fin_receipt_submissions s set possible_duplicate=exists(
    select 1 from public.fin_receipt_submissions o
    where o.id<>s.id and o.profile_id=s.profile_id and o.content_sha256=s.content_sha256
  ) where s.id=p_submission;

  v_auto:=fin_private.auto_approve_pendency_receipt(p_submission);

  if not coalesce((v_auto->>'approved')::boolean,false) then
    v_review_notice:=conv_private.queue_pendency_receipt_review_notice(v_profile,p_submission);
  end if;

  return jsonb_build_object(
    'id',p_submission,
    'duplicate',false,
    'status',(select status from public.fin_receipt_submissions where id=p_submission),
    'auto_approved',coalesce((v_auto->>'approved')::boolean,false),
    'auto_reason',v_auto->>'reason',
    'profile_id',v_profile,
    'charge_ids',to_jsonb(v_ids),
    'generated_charges',v_generated,
    'payment_ids',coalesce(v_auto->'payment_ids','[]'::jsonb),
    'review_notice_recipient_id',v_review_notice
  );
end $function$;
--@@ 45 funcao public.fin_update_entry(p_request_id uuid, p_id uuid, p_expecte
CREATE OR REPLACE FUNCTION public.fin_update_entry(p_request_id uuid, p_id uuid, p_expected_version integer, p_data jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; e public.fin_entries%rowtype; n public.fin_entries%rowtype; v_paid bigint;
begin
  v_actor := fin_private.require_admin();
  v_replay := fin_private.begin_op(p_request_id, 'entry_update', p_reason);
  if v_replay is not null then return v_replay; end if;
  select * into e from public.fin_entries where id = p_id for update;
  if not found then raise exception 'ENTRY_NOT_FOUND'; end if;
  if e.version <> p_expected_version then raise exception 'VERSION_CONFLICT'; end if;
  if e.status = 'canceled' then raise exception 'ENTRY_CANCELED'; end if;
  v_paid := fin_private.entry_paid_cents(p_id);
  if v_paid > 0 and (p_reason is null or length(trim(p_reason)) < 3) then raise exception 'ENTRY_REASON_REQUIRED'; end if;
  n := e;
  if p_data ? 'description' then n.description := trim(p_data->>'description'); end if;
  if p_data ? 'supplier' then n.supplier := nullif(trim(p_data->>'supplier'), ''); end if;
  if p_data ? 'notes' then n.notes := nullif(trim(p_data->>'notes'), ''); end if;
  if p_data ? 'competence_date' then n.competence_date := coalesce((p_data->>'competence_date')::date, e.competence_date); end if;
  if p_data ? 'due_date' then n.due_date := (p_data->>'due_date')::date; end if;
  if p_data ? 'category_id' and e.kind in ('expense', 'revenue') then
    n.category_id := (p_data->>'category_id')::uuid;
    if n.category_id is distinct from e.category_id then perform fin_private.check_category(n.category_id, e.kind); end if;
  end if;
  if p_data ? 'amount_cents' then
    if v_paid > 0 then raise exception 'ENTRY_HAS_PAYMENTS'; end if; -- valor de documento com pagamento: estorne antes
    n.amount_cents := (p_data->>'amount_cents')::bigint;
  end if;
  if p_data ? 'account_id' and e.status in ('pending', 'partial') then
    n.account_id := (p_data->>'account_id')::uuid;
    if n.account_id is not null then perform fin_private.check_account(n.account_id); end if;
  end if;
  if n.description is null or length(n.description) < 2 or length(n.description) > 140 then raise exception 'INVALID_ENTRY'; end if;
  if n.amount_cents is null or n.amount_cents <= 0 or n.amount_cents > 100000000000 then raise exception 'INVALID_AMOUNT'; end if;
  if e.status in ('pending', 'partial') and n.due_date is null then raise exception 'DUE_DATE_REQUIRED'; end if;
  update public.fin_entries set description = n.description, supplier = n.supplier, notes = n.notes,
    amount_cents = n.amount_cents, competence_date = n.competence_date, due_date = n.due_date, category_id = n.category_id,
    account_id = n.account_id, version = version + 1, updated_at = now(), updated_by = v_actor where id = p_id;
  return fin_private.finish_op(p_request_id, jsonb_build_object('id', p_id, 'version', e.version + 1));
end $function$;
--@@ 45 funcao public.fin_update_member_plan(p_request_id uuid, p_plan_id uuid
CREATE OR REPLACE FUNCTION public.fin_update_member_plan(p_request_id uuid, p_plan_id uuid, p_expected_version integer, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_replay jsonb; pl public.fin_member_plans%rowtype; n public.fin_member_plans%rowtype;
begin
  v_actor := fin_private.require_admin();
  v_replay := fin_private.begin_op(p_request_id, 'member_plan_update', p_data->>'reason');
  if v_replay is not null then return v_replay; end if;
  select * into pl from public.fin_member_plans where id = p_plan_id for update;
  if not found then raise exception 'PLAN_NOT_FOUND'; end if;
  if pl.version <> p_expected_version then raise exception 'VERSION_CONFLICT'; end if;
  if pl.status = 'ended' then raise exception 'PLAN_ENDED'; end if;
  n := pl;
  if p_data ? 'status' then n.status := p_data->>'status'; end if;
  if n.status not in ('active', 'paused') then raise exception 'INVALID_PLAN'; end if;
  if p_data ? 'due_day' then n.due_day := (p_data->>'due_day')::smallint; end if;
  if p_data ? 'due_month_offset' then n.due_month_offset := (p_data->>'due_month_offset')::smallint; end if;
  if p_data ? 'notes' then n.notes := nullif(trim(p_data->>'notes'), ''); end if;
  update public.fin_member_plans set status = n.status, due_day = n.due_day, due_month_offset = n.due_month_offset, notes = n.notes,
    version = version + 1, updated_at = now(), updated_by = v_actor where id = p_plan_id;
  return fin_private.finish_op(p_request_id, jsonb_build_object('id', p_plan_id, 'version', pl.version + 1));
end $function$;
--@@ 45 funcao public.finish_championship(p_championship_id uuid)
CREATE OR REPLACE FUNCTION public.finish_championship(p_championship_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_champ            RECORD;
    v_is_resenha_open  BOOLEAN;
    v_applied_count    INTEGER := 0;
BEGIN
    -- 1. Fetch championship
    SELECT id, name, status, series_id, slug
    INTO v_champ
    FROM public.championships
    WHERE id = p_championship_id;

    IF v_champ.id IS NULL THEN
        RAISE EXCEPTION 'Campeonato % não encontrado.', p_championship_id;
    END IF;

    -- 2. Determine if Resenha Open
    v_is_resenha_open := (v_champ.name ILIKE '%resenha open%' OR COALESCE(v_champ.slug, '') ILIKE '%resenha-open%');

    -- 3. Resolve final phases
    IF v_is_resenha_open THEN
        PERFORM public.resolve_resenha_open_final_phases(p_championship_id);
    ELSE
        PERFORM public.resolve_championship_final_phases(p_championship_id);
    END IF;

    -- 4. Update status to 'finished'
    UPDATE public.championships
    SET status = 'finished'
    WHERE id = p_championship_id;

    -- 5. Apply edition points if linked to a series
    IF v_champ.series_id IS NOT NULL THEN
        SELECT COUNT(*) INTO v_applied_count
        FROM public.apply_championship_edition_points(p_championship_id);
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'championship_id', p_championship_id,
        'applied_points_count', v_applied_count,
        'message', 'Campeonato finalizado e pontos apurados com sucesso!'
    );
END;
$function$;
--@@ 45 funcao public.get_active_user_points()
CREATE OR REPLACE FUNCTION public.get_active_user_points()
 RETURNS TABLE(user_id uuid, total_points bigint)
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN QUERY
    SELECT 
        ph.user_id,
        COALESCE(SUM(ph.amount), 0) as total_points
    FROM 
        point_history ph
    WHERE 
        ph.status = 'active' 
        AND ph.expires_at > CURRENT_DATE
    GROUP BY 
        ph.user_id;
END;
$function$;
--@@ 45 funcao public.get_admin_push_subscriptions()
CREATE OR REPLACE FUNCTION public.get_admin_push_subscriptions()
 RETURNS TABLE(id uuid, user_id uuid, endpoint text, keys jsonb)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT s.id, s.user_id, s.endpoint, s.keys
    FROM public.push_subscriptions s
    INNER JOIN public.profiles p ON p.id = s.user_id
    WHERE p.role = 'admin';
$function$;
--@@ 45 funcao public.get_championship_phase_points(p_phase text)
CREATE OR REPLACE FUNCTION public.get_championship_phase_points(p_phase text)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
    SELECT points FROM public.championship_phase_points WHERE phase = p_phase;
$function$;
--@@ 45 funcao public.get_form_live_results(p_form_id uuid)
CREATE OR REPLACE FUNCTION public.get_form_live_results(p_form_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_form RECORD;
    v_result JSONB;
BEGIN
    SELECT id, title, is_secret_vote, show_live_results, is_active
    INTO v_form
    FROM public.club_forms
    WHERE id = p_form_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Formulário não encontrado.';
    END IF;

    -- Se não for admin e o formulário não permitir resultados ao vivo, bloqueia
    IF NOT v_form.show_live_results AND NOT public.is_admin() THEN
        RETURN jsonb_build_object(
            'allowed', false,
            'message', 'Os resultados desta votação não estão disponíveis publicamente.'
        );
    END IF;

    SELECT jsonb_build_object(
        'allowed', true,
        'form_id', v_form.id,
        'total_participants', (
            SELECT COUNT(DISTINCT r.id)
            FROM public.club_form_voter_receipts r
            WHERE r.form_id = p_form_id
        ),
        'questions', (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'question_id', q.id,
                    'title', q.title,
                    'question_type', q.question_type,
                    'total_votes', (
                        SELECT COUNT(*)
                        FROM public.club_form_responses res
                        WHERE res.question_id = q.id
                    ),
                    'options', (
                        SELECT jsonb_agg(
                            jsonb_build_object(
                                'option_id', o.id,
                                'label', o.label,
                                'display_order', o.display_order,
                                'votes', (
                                    SELECT COUNT(*)
                                    FROM public.club_form_responses res
                                    WHERE res.question_id = q.id
                                      AND res.option_id = o.id
                                )
                            ) ORDER BY o.display_order ASC
                        )
                        FROM public.club_form_options o
                        WHERE o.question_id = q.id
                    ),
                    'open_responses_count', (
                        SELECT COUNT(*)
                        FROM public.club_form_responses res
                        WHERE res.question_id = q.id
                          AND res.text_response IS NOT NULL
                          AND trim(res.text_response) <> ''
                    )
                ) ORDER BY q.display_order ASC
            )
            FROM public.club_form_questions q
            WHERE q.form_id = p_form_id
        )
    ) INTO v_result;

    RETURN v_result;
END;
$function$;
--@@ 45 funcao public.get_group_standings(p_group_id uuid)
CREATE OR REPLACE FUNCTION public.get_group_standings(p_group_id uuid)
 RETURNS TABLE(standing_position integer, registration_id uuid, points integer, h2h_wins integer, sets_won integer, sets_lost integer, games_won integer, games_lost integer, wins integer, losses integer, matches_played integer)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
WITH members AS (
    SELECT gm.registration_id
    FROM championship_group_members gm
    WHERE gm.group_id = p_group_id
),
finished_matches AS (
    SELECT
        m.id,
        m.registration_a_id,
        m.registration_b_id,
        m.winner_id,
        m.walkover_winner_id,
        m.walkover_winner_registration_id,
        ra.user_id AS reg_a_user_id,
        rb.user_id AS reg_b_user_id,
        m.score_a,
        m.score_b
    FROM matches m
    JOIN championship_rounds r ON r.id = m.round_id
    LEFT JOIN championship_registrations ra ON ra.id = m.registration_a_id
    LEFT JOIN championship_registrations rb ON rb.id = m.registration_b_id
    WHERE m.championship_group_id = p_group_id
      AND r.phase = 'classificatoria'
      AND m.status = 'finished'
      AND m.registration_a_id IS NOT NULL
      AND m.registration_b_id IS NOT NULL
),
set_sums AS (
    SELECT
        fm.id,
        fm.registration_a_id,
        fm.registration_b_id,
        fm.winner_id,
        fm.walkover_winner_id,
        fm.walkover_winner_registration_id,
        fm.reg_a_user_id,
        fm.reg_b_user_id,
        COALESCE(SUM(CASE WHEN COALESCE(fm.score_a[idx], 0) > COALESCE(fm.score_b[idx], 0) THEN 1 ELSE 0 END), 0)::INTEGER AS sets_a,
        COALESCE(SUM(CASE WHEN COALESCE(fm.score_b[idx], 0) > COALESCE(fm.score_a[idx], 0) THEN 1 ELSE 0 END), 0)::INTEGER AS sets_b,
        COALESCE(SUM(COALESCE(fm.score_a[idx], 0)), 0)::INTEGER AS games_a,
        COALESCE(SUM(COALESCE(fm.score_b[idx], 0)), 0)::INTEGER AS games_b
    FROM finished_matches fm
    LEFT JOIN LATERAL generate_series(
        1,
        GREATEST(
            COALESCE(array_length(fm.score_a, 1), 0),
            COALESCE(array_length(fm.score_b, 1), 0)
        )
    ) AS idx ON TRUE
    GROUP BY
        fm.id,
        fm.registration_a_id,
        fm.registration_b_id,
        fm.winner_id,
        fm.walkover_winner_id,
        fm.walkover_winner_registration_id,
        fm.reg_a_user_id,
        fm.reg_b_user_id
),
winner_per_match AS (
    SELECT
        ss.*,
        COALESCE(
            ss.walkover_winner_registration_id,
            CASE
                WHEN ss.winner_id IS NOT NULL AND ss.reg_a_user_id = ss.winner_id THEN ss.registration_a_id
                WHEN ss.winner_id IS NOT NULL AND ss.reg_b_user_id = ss.winner_id THEN ss.registration_b_id
                WHEN ss.sets_a > ss.sets_b THEN ss.registration_a_id
                WHEN ss.sets_b > ss.sets_a THEN ss.registration_b_id
                ELSE NULL
            END
        ) AS winner_reg_id
    FROM set_sums ss
),
stats_base AS (
    SELECT
        mem.registration_id,
        COALESCE(COUNT(wpm.id), 0)::INTEGER AS matches_played,
        COALESCE(SUM(CASE WHEN wpm.winner_reg_id = mem.registration_id THEN 1 ELSE 0 END), 0)::INTEGER AS wins,
        COALESCE(SUM(
            CASE
                WHEN (wpm.registration_a_id = mem.registration_id OR wpm.registration_b_id = mem.registration_id)
                 AND wpm.winner_reg_id IS NOT NULL
                 AND wpm.winner_reg_id <> mem.registration_id
                THEN 1
                ELSE 0
            END
        ), 0)::INTEGER AS losses,
        COALESCE(SUM(CASE WHEN wpm.registration_a_id = mem.registration_id THEN wpm.sets_a WHEN wpm.registration_b_id = mem.registration_id THEN wpm.sets_b ELSE 0 END), 0)::INTEGER AS sets_won,
        COALESCE(SUM(CASE WHEN wpm.registration_a_id = mem.registration_id THEN wpm.sets_b WHEN wpm.registration_b_id = mem.registration_id THEN wpm.sets_a ELSE 0 END), 0)::INTEGER AS sets_lost,
        COALESCE(SUM(CASE WHEN wpm.registration_a_id = mem.registration_id THEN wpm.games_a WHEN wpm.registration_b_id = mem.registration_id THEN wpm.games_b ELSE 0 END), 0)::INTEGER AS games_won,
        COALESCE(SUM(CASE WHEN wpm.registration_a_id = mem.registration_id THEN wpm.games_b WHEN wpm.registration_b_id = mem.registration_id THEN wpm.games_a ELSE 0 END), 0)::INTEGER AS games_lost,
        COALESCE(SUM(CASE WHEN wpm.winner_reg_id = mem.registration_id THEN 3 ELSE 0 END), 0)::INTEGER AS points
    FROM members mem
    LEFT JOIN winner_per_match wpm
      ON wpm.registration_a_id = mem.registration_id
      OR wpm.registration_b_id = mem.registration_id
    GROUP BY mem.registration_id
),
stats_h2h AS (
    SELECT
        sb.*,
        COALESCE((
            SELECT COUNT(*)::INTEGER
            FROM winner_per_match wpm
            JOIN stats_base opp
              ON opp.registration_id = CASE
                  WHEN wpm.registration_a_id = sb.registration_id THEN wpm.registration_b_id
                  ELSE wpm.registration_a_id
              END
            WHERE (wpm.registration_a_id = sb.registration_id OR wpm.registration_b_id = sb.registration_id)
              AND wpm.winner_reg_id = sb.registration_id
              AND opp.points = sb.points
        ), 0)::INTEGER AS h2h_wins
    FROM stats_base sb
),
ranked AS (
    SELECT
        ROW_NUMBER() OVER (
            ORDER BY
                sh.points DESC,
                sh.h2h_wins DESC,
                (sh.sets_won - sh.sets_lost) DESC,
                (sh.games_won - sh.games_lost) DESC,
                sh.registration_id
        )::INTEGER AS standing_position,
        sh.registration_id,
        sh.points,
        sh.h2h_wins,
        sh.sets_won,
        sh.sets_lost,
        sh.games_won,
        sh.games_lost,
        sh.wins,
        sh.losses,
        sh.matches_played
    FROM stats_h2h sh
)
SELECT
    ranked.standing_position,
    ranked.registration_id,
    ranked.points,
    ranked.h2h_wins,
    ranked.sets_won,
    ranked.sets_lost,
    ranked.games_won,
    ranked.games_lost,
    ranked.wins,
    ranked.losses,
    ranked.matches_played
FROM ranked
ORDER BY ranked.standing_position;
$function$;
--@@ 45 funcao public.get_lead_marketing_intelligence(p_lead_id uuid)
CREATE OR REPLACE FUNCTION public.get_lead_marketing_intelligence(p_lead_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_store_id UUID;
v_customer_id UUID;
v_phone TEXT;
-- Stats
v_total_spent NUMERIC(10, 2) := 0;
v_sales_count INTEGER := 0;
v_services_count INTEGER := 0;
v_last_purchase_at TIMESTAMPTZ;
v_stores_visited UUID [];
v_products_acquired TEXT [];
v_services_performed TEXT [];
v_abc_category TEXT;
-- Result
v_result JSONB;
BEGIN -- 1. Get Lead Info
SELECT store_id,
    customer_id,
    phone INTO v_store_id,
    v_customer_id,
    v_phone
FROM public.crm_leads
WHERE id = p_lead_id;
-- If no lead found, return null
IF NOT FOUND THEN RETURN NULL;
END IF;
-- 2. Aggregate SALES data
SELECT COALESCE(SUM(s.total_amount), 0),
    COUNT(s.id),
    MAX(s.sale_date),
    array_agg(DISTINCT s.store_id),
    array_agg(DISTINCT si.product_name) FILTER (
        WHERE si.product_name IS NOT NULL
    ) INTO v_total_spent,
    v_sales_count,
    v_last_purchase_at,
    v_stores_visited,
    v_products_acquired
FROM public.sales s
    LEFT JOIN public.sale_items si ON s.id = si.sale_id
    LEFT JOIN public.customers c ON s.customer_id = c.id
WHERE -- Match by explicit customer_id link on lead
    (
        v_customer_id IS NOT NULL
        AND s.customer_id = v_customer_id
    ) -- OR match by phone if customer_id link is missing/different
    OR (
        c.whatsapp = v_phone
        OR c.alt_phone = v_phone
    ) -- AND restrict to accessible stores
    AND s.store_id = ANY(public.get_user_store_ids());
-- Aggregate SERVICE ORDERS data
DECLARE v_os_total NUMERIC(10, 2);
v_os_count INTEGER;
v_os_last TIMESTAMPTZ;
v_os_stores UUID [];
v_os_services TEXT [];
BEGIN
SELECT COALESCE(SUM(so.total_value), 0),
    COUNT(so.id),
    MAX(so.finished_at),
    array_agg(DISTINCT so.store_id) INTO v_os_total,
    v_os_count,
    v_os_last,
    v_os_stores
FROM public.service_orders so
    LEFT JOIN public.customers c ON so.customer_id = c.id
WHERE (
        (
            v_customer_id IS NOT NULL
            AND so.customer_id = v_customer_id
        )
        OR (
            c.whatsapp = v_phone
            OR c.alt_phone = v_phone
        )
    )
    AND so.store_id = ANY(public.get_user_store_ids())
    AND so.status = 'finished';
v_total_spent := v_total_spent + v_os_total;
v_services_count := v_os_count;
IF v_os_last > v_last_purchase_at
OR v_last_purchase_at IS NULL THEN v_last_purchase_at := v_os_last;
END IF;
IF v_os_stores IS NOT NULL THEN v_stores_visited := ARRAY(
    SELECT DISTINCT unnest(v_stores_visited || v_os_stores)
);
END IF;
END;
-- 3. Calculate ABC Classification
IF v_total_spent >= 10000 THEN v_abc_category := 'A';
ELSIF v_total_spent >= 5000 THEN v_abc_category := 'B';
ELSE v_abc_category := 'C';
END IF;
-- 4. Build JSON Result
v_result := jsonb_build_object(
    'totalSpent',
    v_total_spent,
    'salesCount',
    v_sales_count,
    'servicesCount',
    v_services_count,
    'lastPurchaseAt',
    v_last_purchase_at,
    'storesVisited',
    v_stores_visited,
    'abcCategory',
    v_abc_category,
    'productsAcquired',
    COALESCE(v_products_acquired, '{}'::TEXT []),
    'servicesPerformed',
    '{}'::TEXT [] 
);
RETURN v_result;
END;
$function$;
--@@ 45 funcao public.get_ranking_cycle_start()
CREATE OR REPLACE FUNCTION public.get_ranking_cycle_start()
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_cycle_start TIMESTAMPTZ;
BEGIN
    SELECT r.executed_at
    INTO v_cycle_start
    FROM public.ranking_reset_events r
    ORDER BY r.executed_at DESC
    LIMIT 1;

    RETURN v_cycle_start;
END;
$function$;
--@@ 45 funcao public.get_stock_automator_config(p_store_id uuid)
CREATE OR REPLACE FUNCTION public.get_stock_automator_config(p_store_id uuid)
 RETURNS TABLE(id uuid, store_id uuid, config_type text, value text, sku_code text, aliases text[], active boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
    RETURN QUERY
    SELECT 
        sac.id,
        sac.store_id,
        sac.config_type,
        sac.value,
        sac.sku_code,
        sac.aliases,
        sac.active
    FROM public.stock_automator_config sac
    WHERE sac.store_id = p_store_id
    AND sac.active = true
    ORDER BY sac.config_type, sac.value;
END;
$function$;
--@@ 45 funcao public.get_user_h2h_points(p_user_id uuid)
CREATE OR REPLACE FUNCTION public.get_user_h2h_points(p_user_id uuid)
 RETURNS TABLE(opponent_id uuid, opponent_name text, match_type text, points integer, since timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
    SELECT
        CASE WHEN h.winner_id = p_user_id THEN h.loser_id ELSE h.winner_id END AS opponent_id,
        p.name                                                                   AS opponent_name,
        h.match_type,
        CASE WHEN h.winner_id = p_user_id THEN h.points ELSE 0 END             AS points,
        h.created_at                                                             AS since
    FROM   public.head_to_head_points h
    JOIN   public.profiles p
           ON p.id = CASE WHEN h.winner_id = p_user_id THEN h.loser_id ELSE h.winner_id END
    WHERE  h.is_active = TRUE
      AND  (h.winner_id = p_user_id OR h.loser_id = p_user_id)
    ORDER  BY h.points DESC, h.created_at DESC;
$function$;
--@@ 45 funcao public.get_user_store_ids()
CREATE OR REPLACE FUNCTION public.get_user_store_ids()
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
    RETURN (SELECT store_ids FROM public.profiles WHERE id = auth.uid());
END;
$function$;
--@@ 45 funcao public.ia_instagram_handle_echo()
CREATE OR REPLACE FUNCTION public.ia_instagram_handle_echo()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  -- se echo = 'false', marca janela de 6 horas
  if lower(NEW.echo) = 'false' then
    NEW.human_started_at := now();
    NEW.human_expires_at := now() + interval '6 hours';
  end if;
  return NEW;
end;
$function$;
--@@ 45 funcao public.ia_instagram_set_human_window()
CREATE OR REPLACE FUNCTION public.ia_instagram_set_human_window()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if NEW.atendimento_humano is true then
    NEW.human_started_at := now();
    NEW.human_expires_at := now() + interval '6 hours';
  end if;
  return NEW;
end;
$function$;
