--@@ 45 funcao public.log_championship_admin_action(p_championship_id uuid, p_
CREATE OR REPLACE FUNCTION public.log_championship_admin_action(p_championship_id uuid, p_entity_type text, p_entity_id uuid, p_action text, p_before_data jsonb DEFAULT NULL::jsonb, p_after_data jsonb DEFAULT NULL::jsonb, p_actor_user_id uuid DEFAULT auth.uid())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_id UUID;
BEGIN
    INSERT INTO public.championship_admin_audit_logs (
        championship_id,
        entity_type,
        entity_id,
        action,
        before_data,
        after_data,
        actor_user_id
    )
    VALUES (
        p_championship_id,
        p_entity_type,
        p_entity_id,
        p_action,
        p_before_data,
        p_after_data,
        p_actor_user_id
    )
    RETURNING id INTO v_id;

    RETURN v_id;
END;
$function$;
--@@ 45 funcao public.match_documents(query_embedding vector, match_count inte
CREATE OR REPLACE FUNCTION public.match_documents(query_embedding vector, match_count integer DEFAULT 5, filter jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(id uuid, content text, similarity double precision)
 LANGUAGE plpgsql
AS $function$
begin
  return query
  select
    e.id,
    e.content,
    1 - (e.embedding <=> query_embedding) as similarity
  from tbl_embedding e
  order by e.embedding <=> query_embedding
  limit match_count;
end;
$function$;
--@@ 45 funcao public.normalize_and_expand_models(input_text text)
CREATE OR REPLACE FUNCTION public.normalize_and_expand_models(input_text text)
 RETURNS text[]
 LANGUAGE plpgsql
AS $function$
DECLARE
  parts text[];
  cleaned text;
  token text;
  res text[] := ARRAY[]::text[];
  base text;
  nums text[];
  n text;
BEGIN
  IF input_text IS NULL OR trim(input_text) = '' THEN
    RETURN NULL;
  END IF;
  cleaned := regexp_replace(input_text, '\s+', ' ', 'g');
  -- Split by comma, semicolon, slash, ' e ' (case-insensitive)
  parts := regexp_split_to_array(cleaned, '\s*(,|;|/|\band\b|\be\b|\bE\b)\s*');
  FOREACH token IN ARRAY parts LOOP
    token := trim(token);
    IF token = '' THEN CONTINUE; END IF;
    -- If token contains digits only like '1' or '2' assume it's a suffix to previous base
    IF token ~ '^\d+$' OR token ~ '^[0-9]+[a-zA-Z]?$' THEN
      IF base IS NOT NULL THEN
        res := res || (base || ' ' || token);
      ELSE
        res := res || token;
      END IF;
    ELSE
      -- Detect patterns like 'Apple Watch ULTRA 1, 2 E 3' where first part has base + number
      IF token ~ '.*\d+.*' AND token ~ '.*[A-Za-z].*' THEN
        -- keep as-is
        res := res || initcap(token);
        -- set base by removing trailing numbers
        base := regexp_replace(token, '\s*[0-9,]+.*$', '');
        base := trim(base);
      ELSE
        res := res || initcap(token);
        base := token;
      END IF;
    END IF;
  END LOOP;
  -- Remove duplicates and empty, preserve order
  SELECT array_agg(distinct x) FROM unnest(res) x INTO nums;
  IF nums IS NULL THEN
    RETURN res;
  END IF;
  RETURN res;
END; $function$;
--@@ 45 funcao public.on_championship_finished_apply_points()
CREATE OR REPLACE FUNCTION public.on_championship_finished_apply_points()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NEW.status <> 'finished' OR OLD.status = 'finished' THEN
        RETURN NEW;
    END IF;

    -- Only editions linked to a championship series feed ranking points.
    IF NEW.series_id IS NULL THEN
        RETURN NEW;
    END IF;

    PERFORM public.resolve_championship_final_phases(NEW.id);
    PERFORM public.apply_championship_edition_points(NEW.id);

    RETURN NEW;
END;
$function$;
--@@ 45 funcao public.on_profile_class_change()
CREATE OR REPLACE FUNCTION public.on_profile_class_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_old_rank  INTEGER;
    v_new_rank  INTEGER;
    v_pts_now   INTEGER;
    v_halved    INTEGER;
BEGIN
    -- Only act on category changes
    IF NEW.category IS NOT DISTINCT FROM OLD.category THEN
        RETURN NEW;
    END IF;

    -- Primeira definição da classe (ou remoção dela) não é promoção: não há
    -- classe de origem para comparar, nem pontos acumulados nela para dividir.
    IF OLD.category IS NULL OR btrim(OLD.category) = ''
       OR NEW.category IS NULL OR btrim(NEW.category) = '' THEN
        RETURN NEW;
    END IF;

    v_old_rank := public.class_rank(OLD.category);
    v_new_rank := public.class_rank(NEW.category);

    -- Promotion = moving to a better (lower rank number) class
    IF v_new_rank >= v_old_rank THEN
        RETURN NEW; -- demotion or same — no adjustment
    END IF;

    -- Idempotency: avoid double-adjustment for the same class transition
    IF EXISTS (
        SELECT 1 FROM public.class_change_events
        WHERE  user_id    = NEW.id
          AND  from_class = OLD.category
          AND  to_class   = NEW.category
          AND  changed_at > NOW() - INTERVAL '5 seconds'
    ) THEN
        RETURN NEW;
    END IF;

    v_pts_now := COALESCE(NEW.legacy_points, 0);
    v_halved  := FLOOR(v_pts_now::NUMERIC / 2)::INTEGER;

    -- Insert audit entry
    INSERT INTO public.class_change_events (
        user_id, from_class, to_class, points_before, points_after, changed_by
    ) VALUES (
        NEW.id, OLD.category, NEW.category, v_pts_now, v_halved, auth.uid()
    );

    -- Insert adjustment in point_history
    INSERT INTO public.point_history (
        user_id, amount, event_type,
        description, earned_date, expires_at, reason, status
    ) VALUES (
        NEW.id,
        -(v_pts_now - v_halved),
        'Campeonato',
        'Promoção de classe: ' || OLD.category || ' → ' || NEW.category || ' (÷2)',
        NOW()::DATE,
        NOW()::DATE,
        'class_promotion_adjustment',
        'active'
    );

    -- Apply halving to the profile
    NEW.legacy_points := v_halved;

    RETURN NEW;
END;
$function$;
--@@ 45 funcao public.process_head_to_head_points()
CREATE OR REPLACE FUNCTION public.process_head_to_head_points()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_match_type    TEXT;
    v_points        INTEGER;
    v_winner_id     UUID;
    v_loser_id      UUID;
    v_existing      RECORD;
    v_winner_role   TEXT;
    v_loser_role    TEXT;
BEGIN
    -- Only process finished matches of relevant types
    IF NEW.status <> 'finished' OR NEW.winner_id IS NULL THEN
        RETURN NEW;
    END IF;
    IF OLD.status = 'finished' THEN
        RETURN NEW; -- already processed
    END IF;

    -- Map match type to H2H category and points
    IF NEW.type IN ('Desafio', 'Desafio Ranking') THEN
        v_match_type := 'challenge';
        v_points     := 8;
    ELSIF NEW.type = 'SuperSet' THEN
        v_match_type := 'superset';
        v_points     := 3;
    ELSE
        RETURN NEW; -- not a H2H type
    END IF;

    v_winner_id := NEW.winner_id;
    v_loser_id  := CASE
        WHEN NEW.player_a_id = v_winner_id THEN NEW.player_b_id
        ELSE NEW.player_a_id
    END;

    IF v_loser_id IS NULL THEN
        RETURN NEW; -- no loser (guest or missing data)
    END IF;

    -- Exclude guests: only socios/admins get H2H points
    SELECT role INTO v_winner_role FROM public.profiles WHERE id = v_winner_id;
    SELECT role INTO v_loser_role  FROM public.profiles WHERE id = v_loser_id;

    IF v_winner_role NOT IN ('socio', 'admin') THEN
        RETURN NEW;
    END IF;
    -- Loser can be guest — winner still earns, guest just doesn't get a record

    -- Invalidate any existing active record between this pair (either direction)
    FOR v_existing IN
        SELECT id, winner_id, points
        FROM   public.head_to_head_points
        WHERE  is_active = TRUE
          AND  match_type = v_match_type
          AND  (
              (winner_id = v_winner_id AND loser_id = v_loser_id) OR
              (winner_id = v_loser_id  AND loser_id = v_winner_id)
          )
    LOOP
        UPDATE public.head_to_head_points
        SET    is_active               = FALSE,
               invalidated_at          = NOW(),
               invalidated_by_match_id = NEW.id
        WHERE  id = v_existing.id;

        -- Remove points from the previous winner in point_history
        INSERT INTO public.point_history (
            user_id, amount, event_type, event_id,
            description, earned_date, expires_at, reason, status
        ) VALUES (
            v_existing.winner_id,
            -v_existing.points,
            CASE WHEN v_match_type = 'challenge' THEN 'Desafio' ELSE 'SuperSet' END,
            NEW.id,
            'H2H invalidado por novo confronto',
            NOW()::DATE,
            NOW()::DATE,
            'head_to_head_invalidation',
            'active'
        );

        UPDATE public.profiles
        SET    legacy_points = GREATEST(0, COALESCE(legacy_points, 0) - v_existing.points)
        WHERE  id = v_existing.winner_id;
    END LOOP;

    -- Create new active record for current winner
    INSERT INTO public.head_to_head_points (
        winner_id, loser_id, match_type, points, match_id, is_active
    ) VALUES (
        v_winner_id, v_loser_id, v_match_type, v_points, NEW.id, TRUE
    );

    -- Award points to winner (only if socio/admin)
    INSERT INTO public.point_history (
        user_id, amount, event_type, event_id,
        description, earned_date, expires_at, reason, status
    ) VALUES (
        v_winner_id,
        v_points,
        CASE WHEN v_match_type = 'challenge' THEN 'Desafio' ELSE 'SuperSet' END,
        NEW.id,
        CASE WHEN v_match_type = 'challenge'
             THEN 'Desafio: ' || v_points || ' pts (válido até próximo confronto)'
             ELSE 'SUPERSET: ' || v_points || ' pts (válido até próximo confronto)'
        END,
        NOW()::DATE,
        (NOW() + INTERVAL '2 years')::DATE,
        'head_to_head_earn',
        'active'
    );

    UPDATE public.profiles
    SET    legacy_points = COALESCE(legacy_points, 0) + v_points
    WHERE  id = v_winner_id;

    RETURN NEW;
END;
$function$;
--@@ 45 funcao public.propagate_bracket_winner()
CREATE OR REPLACE FUNCTION public.propagate_bracket_winner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_winner_reg_id  UUID;
    v_winner_user_id UUID;
BEGIN
    -- Only act when a match transitions to finished
    IF NEW.status <> 'finished' OR OLD.status = 'finished' THEN
        RETURN NEW;
    END IF;

    -- Determine effective winner registration id
    v_winner_reg_id := COALESCE(
        NEW.walkover_winner_registration_id,
        NEW.winner_registration_id
    );

    -- Rede de proteção: quem gravou só o perfil do vencedor ainda tem chave a
    -- avançar. A busca é limitada às duas inscrições da própria partida — sem
    -- isso um sócio inscrito em duas classes daria dois resultados e a escolha
    -- seria arbitrária.
    IF v_winner_reg_id IS NULL AND NEW.winner_id IS NOT NULL THEN
        SELECT cr.id INTO v_winner_reg_id
        FROM public.championship_registrations cr
        WHERE cr.user_id = NEW.winner_id
          AND cr.id IN (NEW.registration_a_id, NEW.registration_b_id);

        -- Deixa a linha coerente: vencedor definido nas duas identidades que o
        -- resto do sistema lê (pontuação e resolução de fases usam a inscrição).
        IF v_winner_reg_id IS NOT NULL THEN
            UPDATE public.matches
            SET winner_registration_id = v_winner_reg_id
            WHERE id = NEW.id
              AND winner_registration_id IS NULL;
        END IF;
    END IF;

    IF v_winner_reg_id IS NULL THEN
        RETURN NEW;
    END IF;

    -- Get winner's user_id (null for guests)
    SELECT user_id INTO v_winner_user_id
    FROM public.championship_registrations
    WHERE id = v_winner_reg_id;

    -- Fill slot A of any dependent match
    UPDATE public.matches
    SET
        registration_a_id = v_winner_reg_id,
        player_a_id       = v_winner_user_id
    WHERE player_a_source_match_id = NEW.id
      AND status = 'pending'
      AND registration_a_id IS NULL;

    -- Fill slot B of any dependent match
    UPDATE public.matches
    SET
        registration_b_id = v_winner_reg_id,
        player_b_id       = v_winner_user_id
    WHERE player_b_source_match_id = NEW.id
      AND status = 'pending'
      AND registration_b_id IS NULL;

    RETURN NEW;
END;
$function$;
--@@ 45 funcao public.record_student_level_change()
CREATE OR REPLACE FUNCTION public.record_student_level_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
    IF TG_OP = 'INSERT' AND NEW.technical_level IS NOT NULL THEN
        INSERT INTO public.student_level_history (
            student_profile_id, previous_level, new_level, changed_by
        ) VALUES (
            NEW.id, NULL, NEW.technical_level, auth.uid()
        );
    ELSIF TG_OP = 'UPDATE' AND NEW.technical_level IS DISTINCT FROM OLD.technical_level
          AND NEW.technical_level IS NOT NULL THEN
        INSERT INTO public.student_level_history (
            student_profile_id, previous_level, new_level, changed_by, observation
        ) VALUES (
            NEW.id,
            OLD.technical_level,
            NEW.technical_level,
            auth.uid(),
            NULLIF(current_setting('app.student_level_observation', true), '')
        );
    END IF;
    RETURN NEW;
END;
$function$;
--@@ 45 funcao public.refresh_familias_trigger()
CREATE OR REPLACE FUNCTION public.refresh_familias_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  arr text[];
BEGIN
  -- Build normalized array from NEW fields
  arr := public.normalize_and_expand_models(array_to_string(ARRAY[COALESCE(NEW.modelo_canonico,''), COALESCE(NEW.modelo_compativel,''), COALESCE(NEW.categoria,'')], ' '));
  IF arr IS NOT NULL THEN
    NEW.familias_backup := COALESCE(NEW.familias_backup, to_jsonb(NEW.familias)::text);
    NEW.familias := to_jsonb((SELECT array_agg(distinct trim(x)) FROM unnest(arr) x));
  END IF;
  RETURN NEW;
END; 
$function$;
--@@ 45 funcao public.resolve_championship_final_phases(p_championship_id uuid
CREATE OR REPLACE FUNCTION public.resolve_championship_final_phases(p_championship_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    WITH round_phase AS (
        -- Fase que um eliminado naquela rodada recebe. NULL = rodada não
        -- eliminatória (grupos, classificatória), que não define fase alcançada.
        SELECT
            r.id,
            CASE
                WHEN r.phase ILIKE 'mata-mata-final%'
                  OR r.phase IN ('final', 'Final')
                  OR r.name = 'Final'                  THEN 'finalist'
                WHEN r.phase ILIKE 'mata-mata-semifinal%'
                  OR r.phase IN ('semifinal', 'Semi')
                  OR r.name ILIKE 'Semifinal%'         THEN 'semifinal'
                WHEN r.phase IN ('quartas', 'quarterfinal')
                  OR r.name ILIKE 'Quartas%'           THEN 'quarterfinal'
                WHEN r.phase IN ('oitavas', 'round_of_16')
                  OR r.name ILIKE 'Oitavas%'           THEN 'round_of_16'
                WHEN r.phase IN ('16avos', 'round_of_32')
                  OR r.name ILIKE '16 avos%'           THEN 'round_of_32'
                WHEN r.phase IN ('qualify', 'preliminar')
                  OR r.name ILIKE 'Qualifica%'         THEN 'qualifying'
                ELSE NULL
            END AS loser_phase
        FROM public.championship_rounds r
        WHERE r.championship_id = p_championship_id
    ),
    resolved_matches AS (
        SELECT
            m.round_id,
            m.registration_a_id,
            m.registration_b_id,
            CASE
                WHEN m.walkover_winner_registration_id IS NOT NULL THEN m.walkover_winner_registration_id
                WHEN m.winner_registration_id IS NOT NULL THEN m.winner_registration_id
                WHEN reg_a.user_id = m.winner_id THEN m.registration_a_id
                WHEN reg_b.user_id = m.winner_id THEN m.registration_b_id
                ELSE NULL
            END AS winner_registration_id
        FROM public.matches m
        LEFT JOIN public.championship_registrations reg_a ON reg_a.id = m.registration_a_id
        LEFT JOIN public.championship_registrations reg_b ON reg_b.id = m.registration_b_id
        WHERE m.status = 'finished'
          AND m.round_id IN (SELECT id FROM round_phase WHERE loser_phase IS NOT NULL)
    ),
    champions AS (
        SELECT DISTINCT rm.winner_registration_id AS registration_id
        FROM resolved_matches rm
        JOIN round_phase rp ON rp.id = rm.round_id
        WHERE rp.loser_phase = 'finalist'
          AND rm.winner_registration_id IS NOT NULL
    ),
    losers AS (
        SELECT x.registration_id, rp.loser_phase
        FROM (
            SELECT rm.round_id, rm.registration_a_id AS registration_id, rm.winner_registration_id
            FROM resolved_matches rm
            UNION ALL
            SELECT rm.round_id, rm.registration_b_id AS registration_id, rm.winner_registration_id
            FROM resolved_matches rm
        ) x
        JOIN round_phase rp ON rp.id = x.round_id
        WHERE x.registration_id IS NOT NULL
          AND x.registration_id IS DISTINCT FROM x.winner_registration_id
    ),
    -- Perdeu em mais de uma fase (não deveria acontecer): fica com a melhor.
    best_loser AS (
        SELECT
            registration_id,
            (ARRAY_AGG(loser_phase ORDER BY
                CASE loser_phase
                    WHEN 'finalist'     THEN 1
                    WHEN 'semifinal'    THEN 2
                    WHEN 'quarterfinal' THEN 3
                    WHEN 'round_of_16'  THEN 4
                    WHEN 'round_of_32'  THEN 5
                    WHEN 'qualifying'   THEN 6
                    ELSE 7
                END))[1] AS loser_phase
        FROM losers
        GROUP BY registration_id
    ),
    resolved AS (
        SELECT
            cr.id AS registration_id,
            CASE
                WHEN cr.id IN (SELECT registration_id FROM champions) THEN 'champion'
                WHEN bl.loser_phase IS NOT NULL THEN bl.loser_phase
                WHEN cr.final_phase IS NOT NULL THEN cr.final_phase
                ELSE 'participation'
            END AS final_phase
        FROM public.championship_registrations cr
        LEFT JOIN best_loser bl ON bl.registration_id = cr.id
        WHERE cr.championship_id = p_championship_id
          AND cr.participant_type = 'socio'
          AND cr.user_id IS NOT NULL
    )
    UPDATE public.championship_registrations cr
    SET final_phase = resolved.final_phase
    FROM resolved
    WHERE cr.id = resolved.registration_id
      AND cr.championship_id = p_championship_id
      AND cr.participant_type = 'socio'
      AND cr.final_phase IS DISTINCT FROM resolved.final_phase;
END;
$function$;
--@@ 45 funcao public.resolve_match_winner_registration(p_match_id uuid)
CREATE OR REPLACE FUNCTION public.resolve_match_winner_registration(p_match_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_match RECORD;
    v_sets_a INTEGER := 0;
    v_sets_b INTEGER := 0;
BEGIN
    SELECT
        m.id,
        m.status,
        m.registration_a_id,
        m.registration_b_id,
        m.winner_id,
        m.walkover_winner_id,
        m.walkover_winner_registration_id,
        ra.user_id AS reg_a_user_id,
        rb.user_id AS reg_b_user_id,
        m.score_a,
        m.score_b
    INTO v_match
    FROM matches m
    LEFT JOIN championship_registrations ra ON ra.id = m.registration_a_id
    LEFT JOIN championship_registrations rb ON rb.id = m.registration_b_id
    WHERE m.id = p_match_id;

    IF NOT FOUND OR v_match.status <> 'finished' THEN
        RETURN NULL;
    END IF;

    IF v_match.walkover_winner_registration_id IS NOT NULL THEN
        RETURN v_match.walkover_winner_registration_id;
    END IF;

    IF v_match.winner_id IS NOT NULL THEN
        IF v_match.reg_a_user_id = v_match.winner_id THEN
            RETURN v_match.registration_a_id;
        ELSIF v_match.reg_b_user_id = v_match.winner_id THEN
            RETURN v_match.registration_b_id;
        END IF;
    END IF;

    SELECT
        COALESCE(SUM(CASE WHEN COALESCE(v_match.score_a[idx], 0) > COALESCE(v_match.score_b[idx], 0) THEN 1 ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN COALESCE(v_match.score_b[idx], 0) > COALESCE(v_match.score_a[idx], 0) THEN 1 ELSE 0 END), 0)
    INTO v_sets_a, v_sets_b
    FROM generate_series(
        1,
        GREATEST(
            COALESCE(array_length(v_match.score_a, 1), 0),
            COALESCE(array_length(v_match.score_b, 1), 0)
        )
    ) AS idx;

    IF v_sets_a > v_sets_b THEN
        RETURN v_match.registration_a_id;
    ELSIF v_sets_b > v_sets_a THEN
        RETURN v_match.registration_b_id;
    END IF;

    RETURN NULL;
END;
$function$;
--@@ 45 funcao public.resolve_resenha_open_final_phases(p_championship_id uuid
CREATE OR REPLACE FUNCTION public.resolve_resenha_open_final_phases(p_championship_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_reg   RECORD;
    v_phase TEXT;
    v_canonical TEXT;
BEGIN
    FOR v_reg IN
        SELECT cr.id AS reg_id, cr.user_id
        FROM public.championship_registrations cr
        WHERE cr.championship_id  = p_championship_id
          AND cr.participant_type = 'socio'
          AND cr.user_id          IS NOT NULL
    LOOP
        SELECT r.phase INTO v_phase
        FROM public.matches m
        JOIN public.championship_rounds r ON r.id = m.round_id
        WHERE r.championship_id = p_championship_id
          AND (m.registration_a_id = v_reg.reg_id OR m.registration_b_id = v_reg.reg_id)
          AND m.status = 'finished'
        ORDER BY
            CASE r.phase
                WHEN 'final'         THEN 10
                WHEN 'semifinal'     THEN 9
                WHEN 'quartas'       THEN 8
                WHEN 'oitavas'       THEN 7
                WHEN 'preliminar'    THEN 6
                WHEN 'segunda_fase'  THEN 5
                WHEN 'classifica_a'  THEN 5
                WHEN 'classifica_b'  THEN 5
                WHEN 'primeira_fase' THEN 4
                WHEN 'qualify'       THEN 3
                ELSE 1
            END DESC
        LIMIT 1;

        v_canonical := CASE v_phase
            WHEN 'final'         THEN 'champion'
            WHEN 'semifinal'     THEN 'semifinal'
            WHEN 'quartas'       THEN 'quarterfinal'
            WHEN 'oitavas'       THEN 'round_of_16'
            WHEN 'preliminar'    THEN 'round_of_16'
            WHEN 'segunda_fase'  THEN 'round_of_16'
            WHEN 'classifica_a'  THEN 'round_of_16'
            WHEN 'classifica_b'  THEN 'round_of_16'
            WHEN 'primeira_fase' THEN 'round_of_16'
            WHEN 'qualify'       THEN 'round_of_16'
            ELSE 'participation'
        END;

        UPDATE public.championship_registrations
        SET    final_phase = v_canonical
        WHERE  id = v_reg.reg_id;
    END LOOP;

    UPDATE public.championship_registrations cr
    SET    final_phase = 'finalist'
    FROM   public.matches m
    JOIN   public.championship_rounds r ON r.id = m.round_id
    WHERE  r.championship_id = p_championship_id
      AND  r.phase            = 'final'
      AND  m.status           = 'finished'
      AND  cr.championship_id = p_championship_id
      AND  cr.id IN (m.registration_a_id, m.registration_b_id)
      AND  cr.id IS DISTINCT FROM COALESCE(
               m.walkover_winner_registration_id,
               m.winner_registration_id
           );
END;
$function$;
--@@ 45 funcao public.revert_championship_edition_points(p_championship_id uui
CREATE OR REPLACE FUNCTION public.revert_championship_edition_points(p_championship_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_series_id     UUID;
    v_edition_year  INTEGER;
    v_prev_champ_id UUID;
    v_reg           RECORD;
    v_cancel_pts    INTEGER;
BEGIN
    -- Only admins
    IF NOT EXISTS (
        SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin'
    ) THEN
        RAISE EXCEPTION 'Permission denied.' USING ERRCODE = '42501';
    END IF;

    SELECT series_id, edition_year
    INTO   v_series_id, v_edition_year
    FROM   public.championships
    WHERE  id = p_championship_id;

    -- For each user who earned points in this edition, cancel them
    FOR v_reg IN
        SELECT user_id, SUM(amount) AS total_pts
        FROM   public.point_history
        WHERE  event_id = p_championship_id
          AND  reason IN ('championship_earn', 'championship_earn_lower_class')
          AND  status   = 'active'
        GROUP  BY user_id
    LOOP
        v_cancel_pts := v_reg.total_pts;

        INSERT INTO public.point_history (
            user_id, amount, event_type, event_id,
            description, earned_date, expires_at,
            series_id, edition_year, reason, status
        ) VALUES (
            v_reg.user_id,
            -v_cancel_pts,
            'Campeonato',
            p_championship_id,
            'Cancelamento da edição ' || v_edition_year,
            NOW()::DATE,
            NOW()::DATE,
            v_series_id,
            v_edition_year,
            'edition_cancelled',
            'active'
        );

        UPDATE public.point_history
        SET    status = 'revoked'
        WHERE  user_id  = v_reg.user_id
          AND  event_id = p_championship_id
          AND  reason IN ('championship_earn', 'championship_earn_lower_class');

        -- Restore defense_removal entry (if any) — re-activate prior edition points
        UPDATE public.point_history
        SET    status = 'active'
        WHERE  user_id   = v_reg.user_id
          AND  series_id = v_series_id
          AND  reason    IN ('championship_earn', 'championship_earn_lower_class')
          AND  status    = 'revoked'
          AND  edition_year = (
              SELECT MAX(edition_year)
              FROM   public.championships
              WHERE  series_id = v_series_id
                AND  edition_year < v_edition_year
          );

        UPDATE public.profiles
        SET    legacy_points = COALESCE(legacy_points, 0) - v_cancel_pts
        WHERE  id = v_reg.user_id;
    END LOOP;

    -- Auditoria: schema real é (executed_by, reason, reset_scope).
    INSERT INTO public.ranking_reset_events (executed_by, reason, reset_scope)
    VALUES (
        auth.uid(),
        'Cancelamento de edição: championship_id=' || p_championship_id::TEXT,
        'edition_cancellation'
    );
END;
$function$;
--@@ 45 funcao public.rollback_bootstrap_3_circuito()
CREATE OR REPLACE FUNCTION public.rollback_bootstrap_3_circuito()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin'
    ) THEN
        RAISE EXCEPTION 'Permission denied.' USING ERRCODE = '42501';
    END IF;

    -- Zero all championship points applied by the bootstrap
    UPDATE public.point_history
    SET    status = 'revoked'
    WHERE  reason IN ('championship_earn', 'championship_earn_lower_class', 'defense_removal')
      AND  created_at > (
          SELECT executed_at FROM public.ranking_reset_events
          WHERE  reason = 'refactor_points_from_3_circuito_inverno'
          ORDER  BY executed_at DESC LIMIT 1
      );

    -- Zero legacy_points for all
    UPDATE public.profiles
    SET    legacy_points = 0
    WHERE  role IN ('socio', 'admin');

    -- Remove the event marker
    DELETE FROM public.ranking_reset_events
    WHERE  reason = 'refactor_points_from_3_circuito_inverno';
END;
$function$;
--@@ 45 funcao public.set_credito_crm_timestamp()
CREATE OR REPLACE FUNCTION public.set_credito_crm_timestamp()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- If changed from false (or null) to true, set timestamp
  IF (OLD.credito_aniversário IS DISTINCT FROM TRUE) AND (NEW.credito_aniversário IS TRUE) THEN
    NEW.credito_crm_set_at := now();
    RETURN NEW;
  END IF;

  -- If changed from true to false, clear timestamp
  IF (OLD.credito_aniversário IS TRUE) AND (NEW.credito_aniversário IS DISTINCT FROM TRUE) THEN
    NEW.credito_crm_set_at := NULL;
    RETURN NEW;
  END IF;

  -- Otherwise, keep existing value
  RETURN NEW;
END;
$function$;
--@@ 45 funcao public.set_default_professor()
CREATE OR REPLACE FUNCTION public.set_default_professor()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.professor_id is null then
    new.professor_id := public.default_professor_id();
  end if;
  return new;
end;
$function$;
--@@ 45 funcao public.set_student_level(p_student_profile_id uuid, p_new_level
CREATE OR REPLACE FUNCTION public.set_student_level(p_student_profile_id uuid, p_new_level text, p_observation text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
    IF p_new_level IS NULL OR p_new_level NOT IN (
        'Iniciante',
        'Iniciante Avançado',
        'Intermediário',
        'Intermediário Avançado',
        'Avançado'
    ) THEN
        RAISE EXCEPTION 'Nível técnico inválido.' USING ERRCODE = '22023';
    END IF;

    PERFORM set_config('app.student_level_observation', COALESCE(p_observation, ''), true);
    UPDATE public.student_profiles
    SET technical_level = p_new_level,
        updated_at = now()
    WHERE id = p_student_profile_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Perfil de aluno não encontrado ou sem permissão.' USING ERRCODE = 'P0002';
    END IF;
END;
$function$;
--@@ 45 funcao public.sig_add_recipients(p_id uuid, p_profiles uuid[])
CREATE OR REPLACE FUNCTION public.sig_add_recipients(p_id uuid, p_profiles uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := sig_private.require_admin(); d public.sig_documents%rowtype; v_ids uuid[]; v_valid integer;
  v_new uuid[]; v_one uuid; v_queued integer := 0; v_skipped integer := 0; v_res text;
begin
  d := sig_private.get_document(p_id);
  if d.status <> 'published' then raise exception 'SIG_NOT_PUBLISHED'; end if;
  select coalesce(array_agg(distinct x), '{}') into v_ids from unnest(coalesce(p_profiles, '{}')) x;
  select count(*) into v_valid from public.profiles p
    where p.id = any (v_ids) and p.role::text in ('socio', 'admin') and coalesce(p.is_active, true);
  if v_valid <> coalesce(array_length(v_ids, 1), 0) then raise exception 'SIG_RECIPIENT_INVALID'; end if;
  with ins as (
    insert into public.sig_recipients(document_id, profile_id, source, added_by)
      select p_id, x, 'selected', v_actor from unnest(v_ids) x
      on conflict do nothing returning profile_id)
  select coalesce(array_agg(profile_id), '{}') into v_new from ins;
  foreach v_one in array v_new loop
    v_res := sig_private.enqueue_notification(p_id, v_one, 'publish');
    if v_res = 'queued' then v_queued := v_queued + 1; elsif v_res = 'skipped' then v_skipped := v_skipped + 1; end if;
  end loop;
  perform sig_private.audit('add_recipients', p_id, jsonb_build_object('added', coalesce(array_length(v_new, 1), 0)));
  return jsonb_build_object('added', coalesce(array_length(v_new, 1), 0), 'queued', v_queued, 'skipped_no_phone', v_skipped);
end $function$;
--@@ 45 funcao public.sig_admin_recipients(p_id uuid)
CREATE OR REPLACE FUNCTION public.sig_admin_recipients(p_id uuid)
 RETURNS TABLE(profile_id uuid, name text, phone text, source text, signed_at timestamp with time zone, signature_id uuid, notification_status text, notification_error text, last_notified_at timestamp with time zone, reminders_sent integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform sig_private.require_admin();
  return query
  select r.profile_id, p.name, p.phone, r.source, r.signed_at, r.signature_id,
    (select n.status from public.sig_notifications n where n.document_id = r.document_id and n.profile_id = r.profile_id
       and n.kind in ('publish', 'new_member') order by n.created_at desc limit 1),
    (select n.error from public.sig_notifications n where n.document_id = r.document_id and n.profile_id = r.profile_id
       and n.status = 'failed' order by n.created_at desc limit 1),
    (select max(n.sent_at) from public.sig_notifications n where n.document_id = r.document_id and n.profile_id = r.profile_id
       and n.status = 'sent'),
    (select count(*)::integer from public.sig_notifications n where n.document_id = r.document_id and n.profile_id = r.profile_id
       and n.kind = 'reminder' and n.status = 'sent')
  from public.sig_recipients r join public.profiles p on p.id = r.profile_id
  where r.document_id = p_id
  order by (r.signed_at is not null), p.name;
end $function$;
--@@ 45 funcao public.sig_archive(p_id uuid, p_reason text)
CREATE OR REPLACE FUNCTION public.sig_archive(p_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := sig_private.require_admin(); d public.sig_documents%rowtype;
begin
  d := sig_private.get_document(p_id);
  if d.status <> 'published' then raise exception 'SIG_NOT_PUBLISHED'; end if;
  perform sig_private.set_action('archive');
  update public.sig_documents set status = 'archived', archived_at = now(), archived_by = v_actor,
    archived_reason = coalesce(nullif(btrim(p_reason), ''), 'manual') where id = p_id;
  update public.sig_notifications set status = 'skipped', skip_reason = 'archived'
    where document_id = p_id and status = 'queued';
end $function$;
--@@ 45 funcao public.sig_can_delete_file(p_name text)
CREATE OR REPLACE FUNCTION public.sig_can_delete_file(p_name text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select public.is_admin() and not exists (select 1 from public.sig_documents d where d.storage_path = p_name and d.status <> 'draft') $function$;
--@@ 45 funcao public.sig_can_read_file(p_name text)
CREATE OR REPLACE FUNCTION public.sig_can_read_file(p_name text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (select 1 from public.sig_documents d
    join public.sig_recipients r on r.document_id = d.id and r.profile_id = (select auth.uid())
    where d.storage_path = p_name and (d.status = 'published' or (d.status = 'archived' and r.signed_at is not null))) $function$;
--@@ 45 funcao public.sig_can_upload_file(p_name text)
CREATE OR REPLACE FUNCTION public.sig_can_upload_file(p_name text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select public.is_admin() and exists (select 1 from public.sig_documents d where d.storage_path = p_name and d.status = 'draft') $function$;
--@@ 45 funcao public.sig_create_draft(p jsonb)
CREATE OR REPLACE FUNCTION public.sig_create_draft(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := sig_private.require_admin(); v_id uuid := gen_random_uuid();
  v_sha text := lower(p->>'content_sha256'); v_version integer := 1;
  v_replaces uuid := nullif(p->>'replaces_id', '')::uuid; v_mode text := coalesce(p->>'audience_mode', 'all');
begin
  if v_replaces is not null then
    select version + 1 into v_version from public.sig_documents where id = v_replaces and status in ('published', 'archived');
    if not found then raise exception 'SIG_REPLACES_INVALID'; end if;
  end if;
  perform sig_private.set_action('create_draft');
  insert into public.sig_documents(id, title, description, file_name, storage_path, size_bytes, page_count,
    content_sha256, version, replaces_id, audience_mode, applies_to_new_members, due_at, created_by)
  values (v_id, btrim(p->>'title'), nullif(btrim(p->>'description'), ''), p->>'file_name',
    v_id::text || '/' || v_sha || '.pdf', (p->>'size_bytes')::bigint, (p->>'page_count')::integer,
    v_sha, v_version, v_replaces, v_mode,
    v_mode = 'all' and coalesce((p->>'applies_to_new_members')::boolean, false),
    nullif(p->>'due_at', '')::timestamptz, v_actor);
  return jsonb_build_object('id', v_id, 'storage_path', v_id::text || '/' || v_sha || '.pdf', 'version', v_version);
end $function$;
--@@ 45 funcao public.sig_delete_draft(p_id uuid)
CREATE OR REPLACE FUNCTION public.sig_delete_draft(p_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.sig_documents%rowtype;
begin
  perform sig_private.require_admin();
  d := sig_private.get_document(p_id);
  if d.status <> 'draft' then raise exception 'SIG_DOCUMENT_IMMUTABLE'; end if;
  perform sig_private.set_action('delete_draft');
  delete from public.sig_documents where id = p_id;
  return d.storage_path;
end $function$;
--@@ 45 funcao public.sig_is_recipient(p_document uuid)
CREATE OR REPLACE FUNCTION public.sig_is_recipient(p_document uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (select 1 from public.sig_recipients r
    where r.document_id = p_document and r.profile_id = (select auth.uid())) $function$;
--@@ 45 funcao public.sig_log_event(p_document uuid, p_kind text, p_meta jsonb
CREATE OR REPLACE FUNCTION public.sig_log_event(p_document uuid, p_kind text, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := sig_private.require_member(); d public.sig_documents%rowtype; r public.sig_recipients%rowtype;
  v_meta jsonb := '{}'::jsonb; v_seen integer; v_total integer; v_at timestamptz := clock_timestamp();
begin
  if p_kind not in ('viewed', 'read_started', 'read_completed', 'consent_checked') then
    raise exception 'SIG_EVENT_INVALID';
  end if;
  select * into r from public.sig_recipients where document_id = p_document and profile_id = v_uid;
  if not found then raise exception 'SIG_NOT_FOUND'; end if;
  select * into d from public.sig_documents where id = p_document;
  if d.status <> 'published' then raise exception 'SIG_NOT_PUBLISHED'; end if;
  if r.signed_at is not null then raise exception 'SIG_ALREADY_SIGNED'; end if;

  if p_kind = 'read_completed' then
    if not exists (select 1 from public.sig_events e where e.document_id = p_document and e.profile_id = v_uid and e.kind = 'read_started') then
      raise exception 'SIG_READ_NOT_STARTED';
    end if;
    v_seen := case when p_meta->>'pages_seen' ~ '^[0-9]{1,4}$' then (p_meta->>'pages_seen')::integer end;
    v_total := case when p_meta->>'pages_total' ~ '^[0-9]{1,4}$' then (p_meta->>'pages_total')::integer end;
    if coalesce(v_seen, 0) < d.page_count or coalesce(v_total, 0) <> d.page_count then raise exception 'SIG_READ_INCOMPLETE'; end if;
    v_meta := jsonb_build_object('pages_seen', v_seen, 'pages_total', v_total);
  elsif p_kind = 'consent_checked' then
    if not exists (select 1 from public.sig_events e where e.document_id = p_document and e.profile_id = v_uid and e.kind = 'read_completed') then
      raise exception 'SIG_READ_REQUIRED';
    end if;
  end if;

  if exists (select 1 from public.sig_events e where e.document_id = p_document and e.profile_id = v_uid
             and e.kind = p_kind and e.occurred_at > v_at - interval '60 seconds') then
    return jsonb_build_object('ok', true, 'deduped', true);
  end if;
  insert into public.sig_events(occurred_at, document_id, profile_id, kind, ip, user_agent, meta)
  values (v_at, p_document, v_uid, p_kind, sig_private.request_ip(), left(sig_private.request_header('user-agent'), 400), v_meta);
  return jsonb_build_object('ok', true, 'occurred_at', v_at);
end $function$;
--@@ 45 funcao public.sig_member_can_see(p_document uuid)
CREATE OR REPLACE FUNCTION public.sig_member_can_see(p_document uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (select 1 from public.sig_documents d
    join public.sig_recipients r on r.document_id = d.id and r.profile_id = (select auth.uid())
    where d.id = p_document and (d.status = 'published' or (d.status = 'archived' and r.signed_at is not null))) $function$;
--@@ 45 funcao public.sig_my_documents()
CREATE OR REPLACE FUNCTION public.sig_my_documents()
 RETURNS TABLE(document_id uuid, title text, description text, version integer, page_count integer, size_bytes bigint, content_sha256 text, storage_path text, due_at timestamp with time zone, status text, published_at timestamp with time zone, consent_text text, signed_at timestamp with time zone, signature_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform sig_private.require_member();
  return query
  select d.id, d.title, d.description, d.version, d.page_count, d.size_bytes, d.content_sha256, d.storage_path,
    d.due_at, d.status, d.published_at, sig_private.consent_text(d.title, d.version), r.signed_at, r.signature_id
  from public.sig_recipients r join public.sig_documents d on d.id = r.document_id
  where r.profile_id = auth.uid() and (d.status = 'published' or (d.status = 'archived' and r.signed_at is not null))
  order by (r.signed_at is not null), d.due_at nulls last, d.published_at desc;
end $function$;
--@@ 45 funcao public.sig_my_pending_count()
CREATE OR REPLACE FUNCTION public.sig_my_pending_count()
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform sig_private.require_member();
  return (select count(*)::integer from public.sig_recipients r join public.sig_documents d on d.id = r.document_id
    where r.profile_id = auth.uid() and r.signed_at is null and d.status = 'published');
end $function$;
--@@ 45 funcao public.sig_publish(p_id uuid)
CREATE OR REPLACE FUNCTION public.sig_publish(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := sig_private.require_admin(); d public.sig_documents%rowtype;
  v_total integer; v_queued integer; v_skipped integer;
begin
  d := sig_private.get_document(p_id);
  if d.status <> 'draft' then raise exception 'SIG_ALREADY_PUBLISHED'; end if;
  if not exists (select 1 from storage.objects o where o.bucket_id = 'sig-docs' and o.name = d.storage_path) then
    raise exception 'SIG_FILE_MISSING';
  end if;
  if d.due_at is not null and d.due_at <= now() then raise exception 'SIG_DUE_IN_PAST'; end if;

  perform sig_private.set_action('publish');
  if d.audience_mode = 'all' then
    delete from public.sig_recipients where document_id = d.id;
    insert into public.sig_recipients(document_id, profile_id, source, added_by)
      select d.id, p.id, 'all', v_actor from public.profiles p
      where p.role::text in ('socio', 'admin') and coalesce(p.is_active, true);
  end if;
  select count(*) into v_total from public.sig_recipients where document_id = d.id;
  if v_total = 0 then raise exception 'SIG_NO_RECIPIENTS'; end if;

  update public.sig_documents set status = 'published', published_at = now(), published_by = v_actor where id = d.id;

  -- Nova versão: a anterior sai de circulação (as assinaturas dela continuam valendo).
  if d.replaces_id is not null then
    perform sig_private.set_action('archive_replaced');
    update public.sig_documents set status = 'archived', archived_at = now(), archived_by = v_actor,
      archived_reason = 'replaced' where id = d.replaces_id and status = 'published';
    update public.sig_notifications set status = 'skipped', skip_reason = 'replaced'
      where document_id = d.replaces_id and status = 'queued';
  end if;

  insert into public.sig_notifications(document_id, profile_id, kind, slot, status, skip_reason)
    select r.document_id, r.profile_id, 'publish', '',
      case when nullif(btrim(p.phone), '') is null then 'skipped' else 'queued' end,
      case when nullif(btrim(p.phone), '') is null then 'no_phone' end
    from public.sig_recipients r join public.profiles p on p.id = r.profile_id
    where r.document_id = d.id
    on conflict (document_id, profile_id, kind, slot) do nothing;

  select count(*) filter (where status = 'queued'), count(*) filter (where status = 'skipped')
    into v_queued, v_skipped from public.sig_notifications where document_id = d.id and kind = 'publish';
  perform sig_private.audit('publish_summary', d.id,
    jsonb_build_object('recipients', v_total, 'queued', v_queued, 'skipped_no_phone', v_skipped));
  return jsonb_build_object('id', d.id, 'recipients', v_total, 'queued', v_queued, 'skipped_no_phone', v_skipped);
end $function$;
--@@ 45 funcao public.sig_remove_recipient(p_id uuid, p_profile uuid)
CREATE OR REPLACE FUNCTION public.sig_remove_recipient(p_id uuid, p_profile uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.sig_recipients%rowtype;
begin
  perform sig_private.require_admin();
  perform sig_private.get_document(p_id);
  select * into r from public.sig_recipients where document_id = p_id and profile_id = p_profile for update;
  if not found then raise exception 'SIG_NOT_FOUND'; end if;
  if r.signed_at is not null then raise exception 'SIG_ALREADY_SIGNED'; end if;
  delete from public.sig_recipients where document_id = p_id and profile_id = p_profile;
  update public.sig_notifications set status = 'skipped', skip_reason = 'removed'
    where document_id = p_id and profile_id = p_profile and status = 'queued';
  perform sig_private.audit('remove_recipient', p_id, jsonb_build_object('profile_id', p_profile));
end $function$;
--@@ 45 funcao public.sig_resend_failed(p_id uuid)
CREATE OR REPLACE FUNCTION public.sig_resend_failed(p_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.sig_documents%rowtype; v_n integer;
begin
  perform sig_private.require_admin();
  d := sig_private.get_document(p_id);
  if d.status <> 'published' then raise exception 'SIG_NOT_PUBLISHED'; end if;
  update public.sig_notifications n set status = 'queued', attempts = 0, error = null, not_before = now(), claimed_at = null
    where n.document_id = p_id and n.status = 'failed'
      and exists (select 1 from public.sig_recipients r where r.document_id = n.document_id and r.profile_id = n.profile_id and r.signed_at is null);
  get diagnostics v_n = row_count;
  perform sig_private.audit('resend_failed', p_id, jsonb_build_object('requeued', v_n));
  return v_n;
end $function$;
--@@ 45 funcao public.sig_save_my_cpf(p_cpf text)
CREATE OR REPLACE FUNCTION public.sig_save_my_cpf(p_cpf text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := sig_private.require_member(); v_cpf text := regexp_replace(coalesce(p_cpf, ''), '\D', '', 'g'); v_old text;
begin
  if not sig_private.cpf_valid(v_cpf) then raise exception 'SIG_CPF_INVALID'; end if;
  select cpf into v_old from public.sig_member_identities where profile_id = v_uid;
  if v_old is not null and v_old <> v_cpf and exists (select 1 from public.sig_signatures where profile_id = v_uid) then
    raise exception 'SIG_CPF_LOCKED';
  end if;
  insert into public.sig_member_identities(profile_id, cpf) values (v_uid, v_cpf)
  on conflict (profile_id) do update set cpf = excluded.cpf, updated_at = now();
end $function$;
--@@ 45 funcao public.sig_set_new_members(p_id uuid, p_value boolean)
CREATE OR REPLACE FUNCTION public.sig_set_new_members(p_id uuid, p_value boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.sig_documents%rowtype;
begin
  perform sig_private.require_admin();
  d := sig_private.get_document(p_id);
  if d.status not in ('draft', 'published') then raise exception 'SIG_DOCUMENT_ARCHIVED'; end if;
  if p_value and d.audience_mode <> 'all' then raise exception 'SIG_NEW_MEMBERS_NEEDS_ALL'; end if;
  perform sig_private.set_action('set_new_members');
  update public.sig_documents set applies_to_new_members = coalesce(p_value, false) where id = p_id;
end $function$;
--@@ 45 funcao public.sig_set_recipients(p_id uuid, p_profiles uuid[])
CREATE OR REPLACE FUNCTION public.sig_set_recipients(p_id uuid, p_profiles uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.sig_documents%rowtype; v_actor uuid := sig_private.require_admin(); v_ids uuid[]; v_valid integer; v_n integer;
begin
  d := sig_private.get_document(p_id);
  if d.status <> 'draft' then raise exception 'SIG_DOCUMENT_IMMUTABLE'; end if;
  if d.audience_mode <> 'selected' then raise exception 'SIG_NOT_SELECTED_MODE'; end if;
  select coalesce(array_agg(distinct x), '{}') into v_ids from unnest(coalesce(p_profiles, '{}')) x;
  select count(*) into v_valid from public.profiles p
    where p.id = any (v_ids) and p.role::text in ('socio', 'admin') and coalesce(p.is_active, true);
  if v_valid <> coalesce(array_length(v_ids, 1), 0) then raise exception 'SIG_RECIPIENT_INVALID'; end if;
  delete from public.sig_recipients where document_id = p_id;
  insert into public.sig_recipients(document_id, profile_id, source, added_by)
    select p_id, x, 'selected', v_actor from unnest(v_ids) x;
  get diagnostics v_n = row_count;
  return v_n;
end $function$;
--@@ 45 funcao public.sig_svc_claim_notifications(p_limit integer)
CREATE OR REPLACE FUNCTION public.sig_svc_claim_notifications(p_limit integer DEFAULT 1)
 RETURNS TABLE(id uuid, document_id uuid, profile_id uuid, kind text, slot text, phone text, name text, title text, due_at timestamp with time zone, attempts integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_column
begin
  update public.sig_notifications n set status = 'skipped',
    skip_reason = case
      when not exists (select 1 from public.sig_documents d where d.id = n.document_id and d.status = 'published') then 'not_published'
      when not exists (select 1 from public.sig_recipients r where r.document_id = n.document_id and r.profile_id = n.profile_id) then 'removed'
      when exists (select 1 from public.sig_recipients r where r.document_id = n.document_id and r.profile_id = n.profile_id and r.signed_at is not null) then 'already_signed'
      else 'no_phone' end
  where n.status = 'queued' and n.not_before <= now() and (
    not exists (select 1 from public.sig_documents d where d.id = n.document_id and d.status = 'published')
    or not exists (select 1 from public.sig_recipients r where r.document_id = n.document_id and r.profile_id = n.profile_id and r.signed_at is null)
    or not exists (select 1 from public.profiles p where p.id = n.profile_id and nullif(btrim(p.phone), '') is not null));

  return query
  with picked as (
    select n.id from public.sig_notifications n
    where (n.status = 'queued' and n.not_before <= now())
       or (n.status = 'sending' and n.claimed_at < now() - interval '10 minutes')
    order by n.not_before, n.created_at
    limit greatest(coalesce(p_limit, 1), 1)
    for update skip locked),
  upd as (
    update public.sig_notifications n set status = 'sending', claimed_at = now(), attempts = n.attempts + 1
    from picked where n.id = picked.id returning n.*)
  select u.id, u.document_id, u.profile_id, u.kind, u.slot, btrim(p.phone), p.name, d.title, d.due_at, u.attempts
  from upd u join public.profiles p on p.id = u.profile_id join public.sig_documents d on d.id = u.document_id
  order by u.not_before, u.created_at;
end $function$;
--@@ 45 funcao public.sig_svc_enqueue_reminders()
CREATE OR REPLACE FUNCTION public.sig_svc_enqueue_reminders()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  d public.sig_documents%rowtype; v_slot text; v_start timestamptz; v_day text; v_total integer := 0; v_p uuid; v_res text; v_kind text;
begin
  for d in select * from public.sig_documents where status = 'published' and due_at is not null and due_at > now() loop
    v_day := to_char(d.due_at at time zone 'America/Fortaleza', 'YYYY-MM-DD');
    foreach v_kind in array array['d-3', 'd0'] loop
      v_start := case v_kind
        when 'd-3' then d.due_at - interval '3 days'
        else (date_trunc('day', d.due_at at time zone 'America/Fortaleza') + interval '8 hours') at time zone 'America/Fortaleza' end;
      continue when v_start > now() or v_start <= d.published_at + interval '12 hours';
      v_slot := v_kind || '@' || v_day;
      for v_p in
        select r.profile_id from public.sig_recipients r
        where r.document_id = d.id and r.signed_at is null
          and not exists (select 1 from public.sig_notifications n where n.document_id = d.id and n.profile_id = r.profile_id
            and n.kind in ('publish', 'new_member') and n.created_at > now() - interval '12 hours')
      loop
        v_res := sig_private.enqueue_notification(d.id, v_p, 'reminder', v_slot);
        if v_res = 'queued' then v_total := v_total + 1; end if;
      end loop;
    end loop;
  end loop;
  return v_total;
end $function$;
--@@ 45 funcao public.sig_svc_finish_notification(p_id uuid, p_sent boolean, p
CREATE OR REPLACE FUNCTION public.sig_svc_finish_notification(p_id uuid, p_sent boolean, p_provider_id text DEFAULT NULL::text, p_error text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n public.sig_notifications%rowtype;
begin
  select * into n from public.sig_notifications where id = p_id for update;
  if not found or n.status <> 'sending' then return; end if;
  if p_sent then
    update public.sig_notifications set status = 'sent', sent_at = now(), provider_message_id = p_provider_id, error = null where id = p_id;
    insert into public.sig_events(document_id, profile_id, kind, meta)
      values (n.document_id, n.profile_id, 'notified', jsonb_build_object('notification_kind', n.kind, 'slot', n.slot, 'provider_message_id', p_provider_id));
  else
    update public.sig_notifications set error = left(p_error, 500), claimed_at = null,
      status = case when n.attempts >= 3 then 'failed' else 'queued' end,
      not_before = case when n.attempts >= 3 then n.not_before else now() + (n.attempts * interval '5 minutes') end
      where id = p_id;
    insert into public.sig_events(document_id, profile_id, kind, meta)
      values (n.document_id, n.profile_id, 'notification_failed',
        jsonb_build_object('notification_kind', n.kind, 'slot', n.slot, 'attempts', n.attempts, 'error', left(p_error, 200)));
  end if;
end $function$;
--@@ 45 funcao public.sig_svc_issue_challenge(p_profile uuid, p_document uuid,
CREATE OR REPLACE FUNCTION public.sig_svc_issue_challenge(p_profile uuid, p_document uuid, p_code text, p_evidence jsonb DEFAULT '{}'::jsonb, p_ip text DEFAULT NULL::text, p_ua text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  d public.sig_documents%rowtype; r public.sig_recipients%rowtype; pr public.profiles%rowtype; v_phone text;
  v_read_done timestamptz; v_consent timestamptz; v_last timestamptz; v_salt text; v_id uuid; v_exp timestamptz;
  v_geo jsonb := '{}'::jsonb; v_lat numeric; v_lng numeric; v_evidence jsonb; v_device jsonb;
begin
  if p_code is null or p_code !~ '^[0-9]{6}$' then raise exception 'SIG_BAD_CODE_FORMAT'; end if;
  select * into d from public.sig_documents where id = p_document;
  if not found then return jsonb_build_object('ok', false, 'reason', 'not_found'); end if;
  if d.status <> 'published' then return jsonb_build_object('ok', false, 'reason', 'not_published'); end if;
  select * into r from public.sig_recipients where document_id = p_document and profile_id = p_profile for update;
  if not found then return jsonb_build_object('ok', false, 'reason', 'not_recipient'); end if;
  if r.signed_at is not null then return jsonb_build_object('ok', false, 'reason', 'already_signed'); end if;
  if not sig_private.is_active_member(p_profile) then return jsonb_build_object('ok', false, 'reason', 'not_member'); end if;
  select * into pr from public.profiles where id = p_profile;
  v_phone := nullif(btrim(pr.phone), '');
  if v_phone is null then return jsonb_build_object('ok', false, 'reason', 'no_phone'); end if;
  if not exists (select 1 from public.sig_member_identities where profile_id = p_profile) then
    return jsonb_build_object('ok', false, 'reason', 'cpf_required');
  end if;

  select min(occurred_at) into v_read_done from public.sig_events
    where document_id = p_document and profile_id = p_profile and kind = 'read_completed';
  if v_read_done is null then return jsonb_build_object('ok', false, 'reason', 'read_required'); end if;
  select max(occurred_at) into v_consent from public.sig_events
    where document_id = p_document and profile_id = p_profile and kind = 'consent_checked';
  if v_consent is null or v_consent < v_read_done then return jsonb_build_object('ok', false, 'reason', 'consent_required'); end if;

  select max(created_at) into v_last from sig_private.challenges where profile_id = p_profile and document_id = p_document;
  if v_last is not null and v_last > now() - interval '60 seconds' then
    return jsonb_build_object('ok', false, 'reason', 'too_soon',
      'retry_in_seconds', ceil(60 - extract(epoch from (now() - v_last)))::integer);
  end if;
  if (select count(*) from sig_private.challenges where profile_id = p_profile and document_id = p_document
      and created_at > now() - interval '1 hour') >= 5 then
    return jsonb_build_object('ok', false, 'reason', 'rate_limited');
  end if;

  v_lat := case when p_evidence #>> '{geo,lat}' ~ '^-?[0-9]{1,3}(\.[0-9]{1,10})?$' then (p_evidence #>> '{geo,lat}')::numeric end;
  v_lng := case when p_evidence #>> '{geo,lng}' ~ '^-?[0-9]{1,3}(\.[0-9]{1,10})?$' then (p_evidence #>> '{geo,lng}')::numeric end;
  if v_lat between -90 and 90 and v_lng between -180 and 180 then
    v_geo := jsonb_strip_nulls(jsonb_build_object('lat', v_lat, 'lng', v_lng, 'accuracy_m',
      case when p_evidence #>> '{geo,accuracy_m}' ~ '^[0-9]{1,7}(\.[0-9]{1,4})?$' then (p_evidence #>> '{geo,accuracy_m}')::numeric end));
  end if;
  v_device := p_evidence->'device';
  if jsonb_typeof(v_device) is distinct from 'object' or length(v_device::text) > 2000 then v_device := '{}'::jsonb; end if;
  v_evidence := jsonb_build_object('geo', v_geo, 'device', v_device);

  update sig_private.challenges set status = 'superseded'
    where profile_id = p_profile and document_id = p_document and status in ('pending', 'sent');
  v_salt := gen_random_uuid()::text; v_exp := now() + interval '10 minutes';
  insert into sig_private.challenges(document_id, profile_id, code_hash, salt, phone, expires_at, ip, user_agent, evidence)
  values (p_document, p_profile, sig_private.sha256_hex(v_salt || ':' || p_code), v_salt, v_phone, v_exp,
    p_ip, left(p_ua, 400), v_evidence)
  returning id into v_id;
  insert into public.sig_events(document_id, profile_id, kind, ip, user_agent, meta)
    values (p_document, p_profile, 'code_requested', p_ip, left(p_ua, 400), jsonb_build_object('challenge_id', v_id));
  return jsonb_build_object('ok', true, 'challenge_id', v_id, 'phone', v_phone, 'name', pr.name,
    'title', d.title, 'expires_at', v_exp);
end $function$;
--@@ 45 funcao public.sig_svc_mark_code_sent(p_challenge uuid, p_provider_id t
CREATE OR REPLACE FUNCTION public.sig_svc_mark_code_sent(p_challenge uuid, p_provider_id text DEFAULT NULL::text, p_error text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c sig_private.challenges%rowtype;
begin
  select * into c from sig_private.challenges where id = p_challenge for update;
  if not found or c.status <> 'pending' then return; end if;
  if p_error is null then
    update sig_private.challenges set status = 'sent', sent_at = now(), provider_message_id = p_provider_id where id = p_challenge;
    insert into public.sig_events(document_id, profile_id, kind, meta)
      values (c.document_id, c.profile_id, 'code_sent', jsonb_build_object('challenge_id', c.id, 'provider_message_id', p_provider_id));
  else
    update sig_private.challenges set status = 'failed', send_error = left(p_error, 500) where id = p_challenge;
    insert into public.sig_events(document_id, profile_id, kind, meta)
      values (c.document_id, c.profile_id, 'code_send_failed', jsonb_build_object('challenge_id', c.id, 'error', left(p_error, 200)));
  end if;
end $function$;
--@@ 45 funcao public.sig_svc_verify_code(p_challenge uuid, p_profile uuid, p_
CREATE OR REPLACE FUNCTION public.sig_svc_verify_code(p_challenge uuid, p_profile uuid, p_code text, p_ip text DEFAULT NULL::text, p_ua text DEFAULT NULL::text, p_geo jsonb DEFAULT '{}'::jsonb, p_device jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  c sig_private.challenges%rowtype; d public.sig_documents%rowtype; r public.sig_recipients%rowtype;
  pr public.profiles%rowtype; v_cpf text; s public.sig_signatures%rowtype; v_prev text; v_seq integer;
  v_read_started timestamptz; v_read_done timestamptz; v_consent timestamptz; v_meta jsonb; v_gps jsonb; v_left integer;
begin
  select * into c from sig_private.challenges where id = p_challenge;
  if not found or c.profile_id <> p_profile then return jsonb_build_object('ok', false, 'reason', 'not_found'); end if;
  perform 1 from public.sig_recipients where document_id = c.document_id and profile_id = p_profile for update;
  select * into c from sig_private.challenges where id = p_challenge for update;

  if c.status = 'verified' then
    select * into s from public.sig_signatures where challenge_id = c.id;
    return jsonb_build_object('ok', true, 'replayed', true, 'signature_id', s.id, 'signed_at', s.signed_at, 'seq', s.seq);
  end if;
  if c.status in ('superseded', 'failed', 'expired', 'locked') then
    return jsonb_build_object('ok', false, 'reason', c.status);
  end if;
  if c.expires_at <= now() then
    update sig_private.challenges set status = 'expired' where id = c.id;
    insert into public.sig_events(document_id, profile_id, kind, ip, user_agent, meta)
      values (c.document_id, c.profile_id, 'code_expired', p_ip, left(p_ua, 400), jsonb_build_object('challenge_id', c.id));
    return jsonb_build_object('ok', false, 'reason', 'expired');
  end if;

  if sig_private.sha256_hex(c.salt || ':' || coalesce(p_code, '')) <> c.code_hash then
    v_left := c.max_attempts - (c.attempts + 1);
    update sig_private.challenges set attempts = c.attempts + 1,
      status = case when c.attempts + 1 >= c.max_attempts then 'locked' else c.status end where id = c.id;
    insert into public.sig_events(document_id, profile_id, kind, ip, user_agent, meta)
      values (c.document_id, c.profile_id, case when v_left <= 0 then 'code_locked' else 'code_wrong' end, p_ip, left(p_ua, 400),
        jsonb_build_object('challenge_id', c.id, 'attempts', c.attempts + 1));
    return jsonb_build_object('ok', false, 'reason', case when v_left <= 0 then 'locked' else 'wrong_code' end,
      'attempts_left', greatest(v_left, 0));
  end if;

  select * into d from public.sig_documents where id = c.document_id;
  if d.status <> 'published' then return jsonb_build_object('ok', false, 'reason', 'not_published'); end if;
  select * into r from public.sig_recipients where document_id = c.document_id and profile_id = p_profile for update;
  if not found then return jsonb_build_object('ok', false, 'reason', 'not_recipient'); end if;
  if r.signed_at is not null then return jsonb_build_object('ok', false, 'reason', 'already_signed'); end if;
  if not sig_private.is_active_member(p_profile) then return jsonb_build_object('ok', false, 'reason', 'not_member'); end if;
  select * into pr from public.profiles where id = p_profile;
  select cpf into v_cpf from public.sig_member_identities where profile_id = p_profile;
  if v_cpf is null then return jsonb_build_object('ok', false, 'reason', 'cpf_required'); end if;

  select min(occurred_at) filter (where kind = 'read_started'), min(occurred_at) filter (where kind = 'read_completed'),
    max(occurred_at) filter (where kind = 'consent_checked')
    into v_read_started, v_read_done, v_consent
    from public.sig_events where document_id = c.document_id and profile_id = p_profile;
  if v_read_done is null then return jsonb_build_object('ok', false, 'reason', 'read_required'); end if;
  if v_consent is null or v_consent < v_read_done then return jsonb_build_object('ok', false, 'reason', 'consent_required'); end if;
  select meta into v_meta from public.sig_events
    where document_id = c.document_id and profile_id = p_profile and kind = 'read_completed' order by occurred_at limit 1;

  perform pg_advisory_xact_lock(hashtextextended(c.document_id::text, 0));
  select seq, chain_hash into v_seq, v_prev from public.sig_signatures where document_id = c.document_id order by seq desc limit 1;
  v_seq := coalesce(v_seq, 0) + 1;

  v_gps := c.evidence->'geo';
  s.id := gen_random_uuid(); s.document_id := c.document_id; s.profile_id := p_profile; s.seq := v_seq; s.signed_at := now();
  s.document_title := d.title; s.document_version := d.version; s.document_sha256 := d.content_sha256;
  s.signer_name := pr.name; s.signer_phone := c.phone; s.signer_cpf := v_cpf;
  s.consent_text := sig_private.consent_text(d.title, d.version); s.accepted_at := v_consent;
  s.read_started_at := v_read_started; s.read_completed_at := v_read_done;
  s.read_seconds := case when v_read_started is null then null else greatest(extract(epoch from (v_read_done - v_read_started))::integer, 0) end;
  s.pages_seen := nullif(v_meta->>'pages_seen', '')::integer; s.pages_total := nullif(v_meta->>'pages_total', '')::integer;
  s.challenge_id := c.id; s.code_sent_at := coalesce(c.sent_at, c.created_at); s.code_verified_at := now();
  s.code_attempts := c.attempts + 1; s.provider_message_id := c.provider_message_id;
  s.ip := p_ip; s.user_agent := left(p_ua, 400);
  s.geo := jsonb_strip_nulls(jsonb_build_object(
    'source', case when v_gps ? 'lat' then 'gps' else 'ip' end,
    'city', left(p_geo->>'city', 120), 'region', left(p_geo->>'region', 120), 'country', left(p_geo->>'country', 120),
    'lat', v_gps->'lat', 'lng', v_gps->'lng', 'accuracy_m', v_gps->'accuracy_m'));
  s.device := coalesce(c.evidence->'device', '{}'::jsonb)
    || case when jsonb_typeof(p_device) = 'object' and length(p_device::text) <= 2000 then p_device else '{}'::jsonb end;
  s.evidence_hash := sig_private.sha256_hex(sig_private.signature_evidence(s)::text);
  s.prev_chain_hash := v_prev;
  s.chain_hash := sig_private.sha256_hex(coalesce(v_prev, '') || s.evidence_hash);

  perform sig_private.set_action('sign');
  insert into public.sig_signatures values (s.*);
  update public.sig_recipients set signed_at = s.signed_at, signature_id = s.id where document_id = c.document_id and profile_id = p_profile;
  update sig_private.challenges set status = 'verified', attempts = c.attempts + 1 where id = c.id;
  insert into public.sig_events(document_id, profile_id, kind, ip, user_agent, meta)
    values (c.document_id, p_profile, 'signed', p_ip, left(p_ua, 400), jsonb_build_object('signature_id', s.id, 'seq', s.seq));
  update public.sig_notifications set status = 'skipped', skip_reason = 'already_signed'
    where document_id = c.document_id and profile_id = p_profile and status = 'queued';
  return jsonb_build_object('ok', true, 'signature_id', s.id, 'signed_at', s.signed_at, 'seq', s.seq, 'evidence_hash', s.evidence_hash);
end $function$;
--@@ 45 funcao public.sig_update_draft(p_id uuid, p jsonb)
CREATE OR REPLACE FUNCTION public.sig_update_draft(p_id uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  d public.sig_documents%rowtype; v_new_file boolean := p ? 'content_sha256';
  v_sha text; v_mode text; v_old_path text;
begin
  perform sig_private.require_admin();
  d := sig_private.get_document(p_id);
  if d.status <> 'draft' then raise exception 'SIG_DOCUMENT_IMMUTABLE'; end if;
  v_old_path := d.storage_path;
  v_mode := coalesce(p->>'audience_mode', d.audience_mode);
  v_sha := case when v_new_file then lower(p->>'content_sha256') else d.content_sha256 end;
  if v_new_file and (p->>'file_name' is null or p->>'size_bytes' is null or p->>'page_count' is null) then
    raise exception 'SIG_FILE_DATA_REQUIRED';
  end if;
  perform sig_private.set_action('update_draft');
  update public.sig_documents x set
    title = coalesce(nullif(btrim(p->>'title'), ''), x.title),
    description = case when p ? 'description' then nullif(btrim(p->>'description'), '') else x.description end,
    due_at = case when p ? 'due_at' then nullif(p->>'due_at', '')::timestamptz else x.due_at end,
    audience_mode = v_mode,
    applies_to_new_members = v_mode = 'all' and coalesce((p->>'applies_to_new_members')::boolean, x.applies_to_new_members),
    file_name = case when v_new_file then p->>'file_name' else x.file_name end,
    size_bytes = case when v_new_file then (p->>'size_bytes')::bigint else x.size_bytes end,
    page_count = case when v_new_file then (p->>'page_count')::integer else x.page_count end,
    content_sha256 = v_sha,
    storage_path = x.id::text || '/' || v_sha || '.pdf'
  where x.id = p_id;
  return jsonb_build_object('id', p_id, 'storage_path', p_id::text || '/' || v_sha || '.pdf',
    'previous_storage_path', case when v_old_path <> p_id::text || '/' || v_sha || '.pdf' then v_old_path end);
end $function$;
--@@ 45 funcao public.sig_update_due(p_id uuid, p_due timestamp with time zone
CREATE OR REPLACE FUNCTION public.sig_update_due(p_id uuid, p_due timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.sig_documents%rowtype;
begin
  perform sig_private.require_admin();
  d := sig_private.get_document(p_id);
  if d.status <> 'published' then raise exception 'SIG_NOT_PUBLISHED'; end if;
  if p_due is not null and p_due <= now() then raise exception 'SIG_DUE_IN_PAST'; end if;
  perform sig_private.set_action('update_due');
  update public.sig_documents set due_at = p_due where id = p_id;
end $function$;
--@@ 45 funcao public.sig_verify_integrity(p_id uuid)
CREATE OR REPLACE FUNCTION public.sig_verify_integrity(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  s public.sig_signatures%rowtype; v_prev text; v_expected_seq integer := 1; v_checked integer := 0;
  v_problems jsonb := '[]'::jsonb;
begin
  perform sig_private.require_admin();
  for s in select * from public.sig_signatures where document_id = p_id order by seq loop
    v_checked := v_checked + 1;
    if s.seq <> v_expected_seq then
      v_problems := v_problems || jsonb_build_object('seq', s.seq, 'problem', 'sequence_gap');
      v_expected_seq := s.seq;
    end if;
    if s.evidence_hash <> sig_private.sha256_hex(sig_private.signature_evidence(s)::text) then
      v_problems := v_problems || jsonb_build_object('seq', s.seq, 'problem', 'evidence_changed');
    end if;
    if s.prev_chain_hash is distinct from v_prev then
      v_problems := v_problems || jsonb_build_object('seq', s.seq, 'problem', 'chain_broken');
    end if;
    if s.chain_hash <> sig_private.sha256_hex(coalesce(s.prev_chain_hash, '') || s.evidence_hash) then
      v_problems := v_problems || jsonb_build_object('seq', s.seq, 'problem', 'chain_hash_changed');
    end if;
    v_prev := s.chain_hash;
    v_expected_seq := v_expected_seq + 1;
  end loop;
  return jsonb_build_object('checked', v_checked, 'ok', jsonb_array_length(v_problems) = 0, 'problems', v_problems);
end $function$;
--@@ 45 funcao public.submit_club_form(p_form_id uuid, p_answers jsonb)
CREATE OR REPLACE FUNCTION public.submit_club_form(p_form_id uuid, p_answers jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_form RECORD;
    v_answer JSONB;
    v_opt_id_text TEXT;
    v_batch_id UUID := gen_random_uuid();
    v_user_to_store UUID := NULL;
    v_has_voted BOOLEAN := false;
BEGIN
    -- 1. Validar existência e estado do formulário
    SELECT id, is_active, is_secret_vote, requires_auth, allow_multiple_submissions, starts_at, expires_at
    INTO v_form
    FROM public.club_forms
    WHERE id = p_form_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Formulário não encontrado.';
    END IF;

    IF NOT v_form.is_active THEN
        RAISE EXCEPTION 'Este formulário ou votação está encerrado.';
    END IF;

    IF v_form.starts_at IS NOT NULL AND NOW() < v_form.starts_at THEN
        RAISE EXCEPTION 'Esta votação ainda não foi iniciada.';
    END IF;

    IF v_form.expires_at IS NOT NULL AND NOW() > v_form.expires_at THEN
        RAISE EXCEPTION 'O prazo desta votação já expirou.';
    END IF;

    -- 2. Validar autenticação se requerida
    IF v_form.requires_auth AND v_user_id IS NULL THEN
        RAISE EXCEPTION 'É necessário estar autenticado como sócio para responder.';
    END IF;

    -- 3. Checar se já votou quando múltiplas submissões não são permitidas
    IF v_user_id IS NOT NULL THEN
        SELECT EXISTS (
            SELECT 1 FROM public.club_form_voter_receipts
            WHERE form_id = p_form_id AND user_id = v_user_id
        ) INTO v_has_voted;

        IF v_has_voted AND NOT v_form.allow_multiple_submissions THEN
            RAISE EXCEPTION 'Você já enviou sua resposta para este formulário.';
        END IF;

        -- Registrar recibo de votação (Garante bloqueio de re-voto)
        INSERT INTO public.club_form_voter_receipts (form_id, user_id, created_at)
        VALUES (p_form_id, v_user_id, NOW())
        ON CONFLICT (form_id, user_id) DO NOTHING;
    END IF;

    -- 4. Definir se o usuário será vinculado às respostas (Urna Cega: NULL se secreta)
    IF NOT v_form.is_secret_vote THEN
        v_user_to_store := v_user_id;
    ELSE
        v_user_to_store := NULL;
    END IF;

    -- 5. Inserir respostas iterando sobre o JSON
    FOR v_answer IN SELECT * FROM jsonb_array_elements(p_answers)
    LOOP
        -- Se vier opção única
        IF v_answer ? 'option_id' AND (v_answer->>'option_id') IS NOT NULL AND (v_answer->>'option_id') <> '' THEN
            INSERT INTO public.club_form_responses (
                form_id,
                question_id,
                option_id,
                text_response,
                user_id,
                submission_batch_id,
                created_at
            ) VALUES (
                p_form_id,
                (v_answer->>'question_id')::UUID,
                (v_answer->>'option_id')::UUID,
                NULL,
                v_user_to_store,
                v_batch_id,
                NOW()
            );
        END IF;

        -- Se vier múltiplas opções (checkbox)
        IF v_answer ? 'option_ids' AND jsonb_typeof(v_answer->'option_ids') = 'array' THEN
            FOR v_opt_id_text IN SELECT jsonb_array_elements_text(v_answer->'option_ids')
            LOOP
                IF v_opt_id_text IS NOT NULL AND v_opt_id_text <> '' THEN
                    INSERT INTO public.club_form_responses (
                        form_id,
                        question_id,
                        option_id,
                        text_response,
                        user_id,
                        submission_batch_id,
                        created_at
                    ) VALUES (
                        p_form_id,
                        (v_answer->>'question_id')::UUID,
                        v_opt_id_text::UUID,
                        NULL,
                        v_user_to_store,
                        v_batch_id,
                        NOW()
                    );
                END IF;
            END LOOP;
        END IF;

        -- Se vier resposta de texto
        IF v_answer ? 'text_response' AND (v_answer->>'text_response') IS NOT NULL AND trim(v_answer->>'text_response') <> '' THEN
            INSERT INTO public.club_form_responses (
                form_id,
                question_id,
                option_id,
                text_response,
                user_id,
                submission_batch_id,
                created_at
            ) VALUES (
                p_form_id,
                (v_answer->>'question_id')::UUID,
                NULL,
                trim(v_answer->>'text_response'),
                v_user_to_store,
                v_batch_id,
                NOW()
            );
        END IF;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'batch_id', v_batch_id,
        'message', 'Resposta registrada com sucesso!'
    );
END;
$function$;
--@@ 45 funcao public.sync_championship_registration_flags()
CREATE OR REPLACE FUNCTION public.sync_championship_registration_flags()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.registration_open := COALESCE(NEW.registration_open, TRUE);
        NEW.registration_closed := COALESCE(NEW.registration_closed, NOT NEW.registration_open);

        IF NEW.registration_closed THEN
            NEW.registration_closed_at := COALESCE(NEW.registration_closed_at, NOW());
        ELSE
            NEW.registration_closed_at := NULL;
        END IF;

        RETURN NEW;
    END IF;

    NEW.registration_open := COALESCE(NEW.registration_open, NOT COALESCE(NEW.registration_closed, FALSE));
    NEW.registration_closed := COALESCE(NEW.registration_closed, NOT NEW.registration_open);

    IF NEW.registration_open IS DISTINCT FROM OLD.registration_open THEN
        NEW.registration_closed := NOT NEW.registration_open;
    END IF;

    IF NEW.registration_closed IS DISTINCT FROM OLD.registration_closed THEN
        NEW.registration_open := NOT NEW.registration_closed;
    END IF;

    IF NEW.registration_closed = TRUE AND OLD.registration_closed IS DISTINCT FROM TRUE THEN
        NEW.registration_closed_at := COALESCE(NEW.registration_closed_at, NOW());
    ELSIF NEW.registration_closed = FALSE THEN
        NEW.registration_closed_at := NULL;
    END IF;

    RETURN NEW;
END;
$function$;
--@@ 45 funcao public.sync_group_knockout_for_class(p_championship_id uuid, p_
CREATE OR REPLACE FUNCTION public.sync_group_knockout_for_class(p_championship_id uuid, p_class text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_format TEXT;
    v_group_a_id UUID;
    v_group_b_id UUID;
    v_anchor_group_id UUID;
    v_semifinal_round_id UUID;
    v_final_round_id UUID;

    v_expected_a INTEGER := 0;
    v_expected_b INTEGER := 0;
    v_created_a INTEGER := 0;
    v_created_b INTEGER := 0;
    v_finished_a INTEGER := 0;
    v_finished_b INTEGER := 0;

    v_a1 UUID;
    v_a2 UUID;
    v_b1 UUID;
    v_b2 UUID;
    v_a1_user UUID;
    v_a2_user UUID;
    v_b1_user UUID;
    v_b2_user UUID;

    v_sf1_id UUID;
    v_sf2_id UUID;
    v_tmp_ra UUID;
    v_tmp_rb UUID;
    v_tmp_status TEXT;

    v_sf1_winner UUID;
    v_sf2_winner UUID;

    v_final_id UUID;
    v_final_status TEXT;
    v_final_ra UUID;
    v_final_rb UUID;
    v_final_user_a UUID;
    v_final_user_b UUID;
BEGIN
    IF p_championship_id IS NULL OR p_class IS NULL OR btrim(p_class) = '' THEN
        RETURN;
    END IF;

    PERFORM pg_advisory_xact_lock(hashtextextended(p_championship_id::TEXT || '|' || p_class, 0));

    SELECT c.format
    INTO v_format
    FROM championships c
    WHERE c.id = p_championship_id;

    IF v_format IS DISTINCT FROM 'grupo-mata-mata' THEN
        RETURN;
    END IF;

    SELECT g_a.id, g_b.id
    INTO v_group_a_id, v_group_b_id
    FROM championship_groups g_a
    JOIN championship_groups g_b
      ON g_b.championship_id = g_a.championship_id
     AND g_b.category = g_a.category
    WHERE g_a.championship_id = p_championship_id
      AND g_a.category = p_class
      AND g_a.group_name = 'A'
      AND g_b.group_name = 'B'
    LIMIT 1;

    IF v_group_a_id IS NULL OR v_group_b_id IS NULL THEN
        RETURN;
    END IF;

    v_anchor_group_id := v_group_a_id;

    SELECT semifinal_round_id, final_round_id
    INTO v_semifinal_round_id, v_final_round_id
    FROM public.ensure_knockout_rounds(p_championship_id);

    SELECT ((COUNT(*) * (COUNT(*) - 1)) / 2)::INTEGER
    INTO v_expected_a
    FROM championship_group_members
    WHERE group_id = v_group_a_id;

    SELECT ((COUNT(*) * (COUNT(*) - 1)) / 2)::INTEGER
    INTO v_expected_b
    FROM championship_group_members
    WHERE group_id = v_group_b_id;

    IF v_expected_a <= 0 OR v_expected_b <= 0 THEN
        RETURN;
    END IF;

    SELECT
        COUNT(*)::INTEGER,
        COUNT(*) FILTER (WHERE m.status = 'finished')::INTEGER
    INTO v_created_a, v_finished_a
    FROM matches m
    JOIN championship_rounds r ON r.id = m.round_id
    WHERE m.championship_group_id = v_group_a_id
      AND r.phase = 'classificatoria';

    SELECT
        COUNT(*)::INTEGER,
        COUNT(*) FILTER (WHERE m.status = 'finished')::INTEGER
    INTO v_created_b, v_finished_b
    FROM matches m
    JOIN championship_rounds r ON r.id = m.round_id
    WHERE m.championship_group_id = v_group_b_id
      AND r.phase = 'classificatoria';

    IF v_created_a < v_expected_a OR v_created_b < v_expected_b THEN
        RETURN;
    END IF;

    IF v_finished_a < v_expected_a OR v_finished_b < v_expected_b THEN
        RETURN;
    END IF;

    SELECT registration_id INTO v_a1
    FROM public.get_group_standings(v_group_a_id)
    WHERE standing_position = 1;

    SELECT registration_id INTO v_a2
    FROM public.get_group_standings(v_group_a_id)
    WHERE standing_position = 2;

    SELECT registration_id INTO v_b1
    FROM public.get_group_standings(v_group_b_id)
    WHERE standing_position = 1;

    SELECT registration_id INTO v_b2
    FROM public.get_group_standings(v_group_b_id)
    WHERE standing_position = 2;

    IF v_a1 IS NULL OR v_a2 IS NULL OR v_b1 IS NULL OR v_b2 IS NULL THEN
        RETURN;
    END IF;

    SELECT user_id INTO v_a1_user FROM championship_registrations WHERE id = v_a1;
    SELECT user_id INTO v_a2_user FROM championship_registrations WHERE id = v_a2;
    SELECT user_id INTO v_b1_user FROM championship_registrations WHERE id = v_b1;
    SELECT user_id INTO v_b2_user FROM championship_registrations WHERE id = v_b2;

    SELECT m.id
    INTO v_sf1_id
    FROM matches m
    WHERE m.championship_id = p_championship_id
      AND m.round_id = v_semifinal_round_id
      AND m.phase = 'Semi'
      AND m.championship_group_id = v_anchor_group_id
      AND m.status = 'finished'
      AND (
        (m.registration_a_id = v_a1 AND m.registration_b_id = v_b2) OR
        (m.registration_a_id = v_b2 AND m.registration_b_id = v_a1)
      )
    ORDER BY m.created_at, m.id
    LIMIT 1;

    IF v_sf1_id IS NULL THEN
        SELECT m.id
        INTO v_sf1_id
        FROM matches m
        WHERE m.championship_id = p_championship_id
          AND m.round_id = v_semifinal_round_id
          AND m.phase = 'Semi'
          AND m.championship_group_id = v_anchor_group_id
          AND m.status <> 'finished'
          AND (
            (m.registration_a_id = v_a1 AND m.registration_b_id = v_b2) OR
            (m.registration_a_id = v_b2 AND m.registration_b_id = v_a1)
          )
        ORDER BY m.created_at, m.id
        LIMIT 1;
    END IF;

    SELECT m.id
    INTO v_sf2_id
    FROM matches m
    WHERE m.championship_id = p_championship_id
      AND m.round_id = v_semifinal_round_id
      AND m.phase = 'Semi'
      AND m.championship_group_id = v_anchor_group_id
      AND m.status = 'finished'
      AND (
        (m.registration_a_id = v_a2 AND m.registration_b_id = v_b1) OR
        (m.registration_a_id = v_b1 AND m.registration_b_id = v_a2)
      )
    ORDER BY m.created_at, m.id
    LIMIT 1;

    IF v_sf2_id IS NULL THEN
        SELECT m.id
        INTO v_sf2_id
        FROM matches m
        WHERE m.championship_id = p_championship_id
          AND m.round_id = v_semifinal_round_id
          AND m.phase = 'Semi'
          AND m.championship_group_id = v_anchor_group_id
          AND m.status <> 'finished'
          AND (
            (m.registration_a_id = v_a2 AND m.registration_b_id = v_b1) OR
            (m.registration_a_id = v_b1 AND m.registration_b_id = v_a2)
          )
        ORDER BY m.created_at, m.id
        LIMIT 1;
    END IF;

    IF v_sf1_id IS NULL THEN
        SELECT m.id
        INTO v_sf1_id
        FROM matches m
        WHERE m.championship_id = p_championship_id
          AND m.round_id = v_semifinal_round_id
          AND m.phase = 'Semi'
          AND m.championship_group_id = v_anchor_group_id
          AND m.status <> 'finished'
          AND (v_sf2_id IS NULL OR m.id <> v_sf2_id)
        ORDER BY m.created_at, m.id
        LIMIT 1;

        IF v_sf1_id IS NULL THEN
            INSERT INTO matches (
                type,
                championship_id,
                championship_group_id,
                round_id,
                phase,
                player_a_id,
                player_b_id,
                registration_a_id,
                registration_b_id,
                score_a,
                score_b,
                status
            )
            VALUES (
                'Campeonato',
                p_championship_id,
                v_anchor_group_id,
                v_semifinal_round_id,
                'Semi',
                v_a1_user,
                v_b2_user,
                v_a1,
                v_b2,
                ARRAY[0, 0, 0],
                ARRAY[0, 0, 0],
                'pending'
            )
            RETURNING id INTO v_sf1_id;
        END IF;
    END IF;

    IF v_sf2_id IS NULL THEN
        SELECT m.id
        INTO v_sf2_id
        FROM matches m
        WHERE m.championship_id = p_championship_id
          AND m.round_id = v_semifinal_round_id
          AND m.phase = 'Semi'
          AND m.championship_group_id = v_anchor_group_id
          AND m.status <> 'finished'
          AND m.id <> v_sf1_id
        ORDER BY m.created_at, m.id
        LIMIT 1;

        IF v_sf2_id IS NULL THEN
            INSERT INTO matches (
                type,
                championship_id,
                championship_group_id,
                round_id,
                phase,
                player_a_id,
                player_b_id,
                registration_a_id,
                registration_b_id,
                score_a,
                score_b,
                status
            )
            VALUES (
                'Campeonato',
                p_championship_id,
                v_anchor_group_id,
                v_semifinal_round_id,
                'Semi',
                v_a2_user,
                v_b1_user,
                v_a2,
                v_b1,
                ARRAY[0, 0, 0],
                ARRAY[0, 0, 0],
                'pending'
            )
            RETURNING id INTO v_sf2_id;
        END IF;
    END IF;

    SELECT registration_a_id, registration_b_id, status
    INTO v_tmp_ra, v_tmp_rb, v_tmp_status
    FROM matches
    WHERE id = v_sf1_id;

    IF v_tmp_status <> 'finished'
       AND (v_tmp_ra IS DISTINCT FROM v_a1 OR v_tmp_rb IS DISTINCT FROM v_b2) THEN
        UPDATE matches
        SET
            registration_a_id = v_a1,
            registration_b_id = v_b2,
            player_a_id = v_a1_user,
            player_b_id = v_b2_user,
            winner_id = NULL,
            winner_registration_id = NULL,
            walkover_winner_id = NULL,
            walkover_winner_registration_id = NULL,
            score_a = ARRAY[0, 0, 0],
            score_b = ARRAY[0, 0, 0],
            status = 'pending',
            scheduled_date = NULL,
            scheduled_time = NULL,
            court_id = NULL,
            date = NULL
        WHERE id = v_sf1_id;
    END IF;

    SELECT registration_a_id, registration_b_id, status
    INTO v_tmp_ra, v_tmp_rb, v_tmp_status
    FROM matches
    WHERE id = v_sf2_id;

    IF v_tmp_status <> 'finished'
       AND (v_tmp_ra IS DISTINCT FROM v_a2 OR v_tmp_rb IS DISTINCT FROM v_b1) THEN
        UPDATE matches
        SET
            registration_a_id = v_a2,
            registration_b_id = v_b1,
            player_a_id = v_a2_user,
            player_b_id = v_b1_user,
            winner_id = NULL,
            winner_registration_id = NULL,
            walkover_winner_id = NULL,
            walkover_winner_registration_id = NULL,
            score_a = ARRAY[0, 0, 0],
            score_b = ARRAY[0, 0, 0],
            status = 'pending',
            scheduled_date = NULL,
            scheduled_time = NULL,
            court_id = NULL,
            date = NULL
        WHERE id = v_sf2_id;
    END IF;

    DELETE FROM matches
    WHERE championship_id = p_championship_id
      AND round_id = v_semifinal_round_id
      AND phase = 'Semi'
      AND championship_group_id = v_anchor_group_id
      AND id NOT IN (v_sf1_id, v_sf2_id)
      AND status <> 'finished';

    v_sf1_winner := public.resolve_match_winner_registration(v_sf1_id);
    v_sf2_winner := public.resolve_match_winner_registration(v_sf2_id);

    SELECT id, status, registration_a_id, registration_b_id
    INTO v_final_id, v_final_status, v_final_ra, v_final_rb
    FROM matches
    WHERE championship_id = p_championship_id
      AND round_id = v_final_round_id
      AND phase = 'Final'
      AND championship_group_id = v_anchor_group_id
    ORDER BY created_at, id
    LIMIT 1;

    IF v_sf1_winner IS NOT NULL AND v_sf2_winner IS NOT NULL THEN
        SELECT user_id INTO v_final_user_a FROM championship_registrations WHERE id = v_sf1_winner;
        SELECT user_id INTO v_final_user_b FROM championship_registrations WHERE id = v_sf2_winner;

        IF v_final_id IS NULL THEN
            INSERT INTO matches (
                type,
                championship_id,
                championship_group_id,
                round_id,
                phase,
                player_a_id,
                player_b_id,
                registration_a_id,
                registration_b_id,
                score_a,
                score_b,
                status
            )
            VALUES (
                'Campeonato',
                p_championship_id,
                v_anchor_group_id,
                v_final_round_id,
                'Final',
                v_final_user_a,
                v_final_user_b,
                v_sf1_winner,
                v_sf2_winner,
                ARRAY[0, 0, 0],
                ARRAY[0, 0, 0],
                'pending'
            )
            RETURNING id INTO v_final_id;
        ELSIF v_final_status <> 'finished' THEN
            UPDATE matches
            SET
                registration_a_id = v_sf1_winner,
                registration_b_id = v_sf2_winner,
                player_a_id = v_final_user_a,
                player_b_id = v_final_user_b,
                winner_id = NULL,
                winner_registration_id = NULL,
                walkover_winner_id = NULL,
                walkover_winner_registration_id = NULL,
                score_a = ARRAY[0, 0, 0],
                score_b = ARRAY[0, 0, 0],
                status = 'pending',
                scheduled_date = NULL,
                scheduled_time = NULL,
                court_id = NULL,
                date = NULL
            WHERE id = v_final_id;
        END IF;
    ELSE
        IF v_final_id IS NOT NULL AND v_final_status <> 'finished' THEN
            UPDATE matches
            SET
                registration_a_id = NULL,
                registration_b_id = NULL,
                player_a_id = NULL,
                player_b_id = NULL,
                winner_id = NULL,
                winner_registration_id = NULL,
                walkover_winner_id = NULL,
                walkover_winner_registration_id = NULL,
                score_a = ARRAY[0, 0, 0],
                score_b = ARRAY[0, 0, 0],
                status = 'pending',
                scheduled_date = NULL,
                scheduled_time = NULL,
                court_id = NULL,
                date = NULL
            WHERE id = v_final_id;
        END IF;
    END IF;

    IF v_final_id IS NOT NULL THEN
        DELETE FROM matches
        WHERE championship_id = p_championship_id
          AND round_id = v_final_round_id
          AND phase = 'Final'
          AND championship_group_id = v_anchor_group_id
          AND id <> v_final_id
          AND status <> 'finished';
    END IF;
END;
$function$;
--@@ 45 funcao public.sync_student_profile_status_to_legacy_student()
CREATE OR REPLACE FUNCTION public.sync_student_profile_status_to_legacy_student()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
    IF NEW.non_socio_student_id IS NOT NULL THEN
        UPDATE public.non_socio_students
        SET is_active = (NEW.student_status = 'active')
        WHERE id = NEW.non_socio_student_id
          AND is_active IS DISTINCT FROM (NEW.student_status = 'active');
    END IF;
    RETURN NEW;
END;
$function$;
--@@ 45 funcao public.trg_sync_group_knockout_on_match_change()
CREATE OR REPLACE FUNCTION public.trg_sync_group_knockout_on_match_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_championship_id UUID;
    v_format TEXT;
    v_class TEXT;
BEGIN
    IF pg_trigger_depth() > 1 THEN
        RETURN NEW;
    END IF;

    v_championship_id := COALESCE(NEW.championship_id, OLD.championship_id);
    IF v_championship_id IS NULL THEN
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE'
       AND NEW.status IS NOT DISTINCT FROM OLD.status
       AND NEW.score_a IS NOT DISTINCT FROM OLD.score_a
       AND NEW.score_b IS NOT DISTINCT FROM OLD.score_b
       AND NEW.winner_id IS NOT DISTINCT FROM OLD.winner_id
       AND NEW.walkover_winner_id IS NOT DISTINCT FROM OLD.walkover_winner_id
       AND NEW.walkover_winner_registration_id IS NOT DISTINCT FROM OLD.walkover_winner_registration_id
       AND NEW.registration_a_id IS NOT DISTINCT FROM OLD.registration_a_id
       AND NEW.registration_b_id IS NOT DISTINCT FROM OLD.registration_b_id
       AND NEW.championship_group_id IS NOT DISTINCT FROM OLD.championship_group_id
       AND NEW.round_id IS NOT DISTINCT FROM OLD.round_id
    THEN
        RETURN NEW;
    END IF;

    SELECT c.format
    INTO v_format
    FROM championships c
    WHERE c.id = v_championship_id;

    IF v_format IS DISTINCT FROM 'grupo-mata-mata' THEN
        RETURN NEW;
    END IF;

    SELECT cr.class
    INTO v_class
    FROM championship_registrations cr
    WHERE cr.id = COALESCE(NEW.registration_a_id, NEW.registration_b_id, OLD.registration_a_id, OLD.registration_b_id)
    LIMIT 1;

    IF v_class IS NULL THEN
        SELECT cg.category
        INTO v_class
        FROM championship_groups cg
        WHERE cg.id = COALESCE(NEW.championship_group_id, OLD.championship_group_id)
        LIMIT 1;
    END IF;

    IF v_class IS NULL THEN
        RETURN NEW;
    END IF;

    PERFORM public.sync_group_knockout_for_class(v_championship_id, v_class);
    RETURN NEW;
END;
$function$;
--@@ 45 funcao public.update_updated_at_column()
CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$;
--@@ 45 funcao public.upsert_crm_lead(p_store_id uuid, p_phone text, p_name te
CREATE OR REPLACE FUNCTION public.upsert_crm_lead(p_store_id uuid, p_phone text, p_name text DEFAULT NULL::text, p_contact_id text DEFAULT NULL::text, p_entity_id text DEFAULT NULL::text, p_channel_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_lead_id UUID;
v_customer_id UUID;
BEGIN -- Try to find existing lead by phone (normalized)
SELECT id INTO v_lead_id
FROM public.crm_leads
WHERE store_id = p_store_id
    AND public.compare_phones(phone, p_phone);
IF v_lead_id IS NULL THEN -- Create new lead (Trigger tr_link_lead_to_customer will handle customer linkage)
INSERT INTO public.crm_leads (
        store_id,
        phone,
        name,
        contact_id,
        entity_id,
        source_channel_id,
        last_interaction_at
    )
VALUES (
        p_store_id,
        p_phone,
        p_name,
        p_contact_id,
        p_entity_id,
        p_channel_id,
        now()
    )
RETURNING id INTO v_lead_id;
ELSE -- Update existing lead
SELECT customer_id INTO v_customer_id
FROM public.crm_leads
WHERE id = v_lead_id;
IF v_customer_id IS NULL THEN 
SELECT id INTO v_customer_id
FROM public.customers
WHERE (
        store_id = p_store_id
        OR store_id IS NULL
    )
    AND (
        public.compare_phones(whatsapp, p_phone)
        OR public.compare_phones(alt_phone, p_phone)
    );
END IF;
UPDATE public.crm_leads
SET name = COALESCE(p_name, name),
    contact_id = COALESCE(p_contact_id, contact_id),
    entity_id = COALESCE(p_entity_id, entity_id),
    customer_id = COALESCE(v_customer_id, customer_id),
    is_customer = (COALESCE(v_customer_id, customer_id) IS NOT NULL),
    last_message_at = now(),
    last_interaction_at = now(),
    updated_at = now()
WHERE id = v_lead_id;
END IF;
RETURN v_lead_id;
END;
$function$;
--@@ 45 funcao public.upsert_crm_lead(p_store_id uuid, p_phone text, p_name te
CREATE OR REPLACE FUNCTION public.upsert_crm_lead(p_store_id uuid, p_phone text, p_name text, p_contact_id text, p_entity_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_lead_id UUID;
BEGIN
    INSERT INTO public.crm_leads (store_id, phone, name, contact_id, entity_id, last_interaction_at)
    VALUES (p_store_id, p_phone, p_name, p_contact_id, p_entity_id, now())
    ON CONFLICT (store_id, phone) 
    DO UPDATE SET 
        name = COALESCE(EXCLUDED.name, public.crm_leads.name), -- Don't overwrite name with null
        contact_id = COALESCE(EXCLUDED.contact_id, public.crm_leads.contact_id),
        entity_id = COALESCE(EXCLUDED.entity_id, public.crm_leads.entity_id),
        last_interaction_at = now()
    RETURNING id INTO v_lead_id;

    RETURN v_lead_id;
END;
$function$;
--@@ 45 funcao public.validate_match_result_integrity()
CREATE OR REPLACE FUNCTION public.validate_match_result_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_round_phase TEXT;
    v_is_knockout BOOLEAN := FALSE;
BEGIN
    IF NEW.result_type IS NULL THEN
        NEW.result_type := 'played';
    END IF;

    IF NEW.status = 'finished' THEN
        IF NEW.result_type = 'played' THEN
            -- Modified: check if EITHER winner_id OR winner_registration_id is present
            IF (NEW.winner_id IS NULL AND NEW.winner_registration_id IS NULL)
               AND (
                    (SELECT COALESCE(SUM(v), 0) FROM unnest(COALESCE(NEW.score_a, ARRAY[]::INTEGER[])) v)
                  + (SELECT COALESCE(SUM(v), 0) FROM unnest(COALESCE(NEW.score_b, ARRAY[]::INTEGER[])) v)
               ) > 0 THEN
                RAISE EXCEPTION 'Played result requires winner_id or winner_registration_id';
            END IF;
        ELSIF NEW.result_type = 'walkover' THEN
            IF NEW.walkover_winner_id IS NULL
               AND NEW.walkover_winner_registration_id IS NULL THEN
                RAISE EXCEPTION 'Walkover result requires walkover winner';
            END IF;
        ELSIF NEW.result_type = 'technical_draw' THEN
            IF NEW.winner_id IS NOT NULL
               OR NEW.walkover_winner_id IS NOT NULL
               OR NEW.walkover_winner_registration_id IS NOT NULL THEN
                RAISE EXCEPTION 'Technical draw cannot define winner';
            END IF;
        END IF;
    END IF;

    IF NEW.result_type = 'technical_draw' THEN
        IF NEW.phase IN ('Oitavas', 'Quartas', 'Semi', 'Final', 'round_of_16', 'quarterfinal', 'semifinal', 'final') THEN
            v_is_knockout := TRUE;
        END IF;

        IF NEW.round_id IS NOT NULL THEN
            SELECT r.phase INTO v_round_phase
            FROM public.championship_rounds r
            WHERE r.id = NEW.round_id;

            IF v_round_phase LIKE 'mata-mata%' THEN
                v_is_knockout := TRUE;
            END IF;
        END IF;

        IF v_is_knockout THEN
            RAISE EXCEPTION 'technical_draw is not allowed in knockout phases';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$;
--@@ 45 funcao sig_private.audit(p_action text, p_document uuid, p_data jsonb)
CREATE OR REPLACE FUNCTION sig_private.audit(p_action text, p_document uuid, p_data jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform public.admin_audit_insert_log('sig.' || p_action, 'sig_documents', p_document::text, null, '{}'::uuid[],
    null, null, p_data, '{}'::jsonb, 'signatures', now());
end $function$;
--@@ 45 funcao sig_private.audit_row()
CREATE OR REPLACE FUNCTION sig_private.audit_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old jsonb; v_new jsonb; v_row jsonb; v_changed text[]; v_target uuid;
begin
  if tg_table_name = 'sig_signatures' then
    v_new := jsonb_build_object('id', new.id, 'document_id', new.document_id, 'seq', new.seq,
      'signed_at', new.signed_at, 'document_sha256', new.document_sha256, 'evidence_hash', new.evidence_hash);
    v_row := v_new; v_target := new.profile_id;
  else
    if tg_op = 'DELETE' then v_old := to_jsonb(old); v_row := v_old;
    elsif tg_op = 'UPDATE' then
      v_old := to_jsonb(old); v_new := to_jsonb(new); v_row := v_new;
      if v_old = v_new then return new; end if;
      v_changed := public.admin_audit_changed_fields(v_old, v_new);
    else v_new := to_jsonb(new); v_row := v_new; end if;
  end if;
  perform public.admin_audit_insert_log(
    'sig.' || coalesce(nullif(current_setting('sig.action', true), ''), lower(tg_op)),
    tg_table_name, v_row->>'id', v_target,
    case when v_target is null then '{}'::uuid[] else array[v_target] end,
    v_changed, v_old, v_new,
    jsonb_strip_nulls(jsonb_build_object('op', lower(tg_op))),
    'signatures', now());
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $function$;
