--@@ 45 funcao sig_private.cpf_valid(p text)
CREATE OR REPLACE FUNCTION sig_private.cpf_valid(p text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare s integer; i integer; r integer;
begin
  if p is null or p !~ '^[0-9]{11}$' then return false; end if;
  if p ~ '^(.)\1{10}$' then return false; end if;
  s := 0;
  for i in 1..9 loop s := s + substr(p, i, 1)::integer * (11 - i); end loop;
  r := (s * 10) % 11; if r = 10 then r := 0; end if;
  if r <> substr(p, 10, 1)::integer then return false; end if;
  s := 0;
  for i in 1..10 loop s := s + substr(p, i, 1)::integer * (12 - i); end loop;
  r := (s * 10) % 11; if r = 10 then r := 0; end if;
  return r = substr(p, 11, 1)::integer;
end $function$;
--@@ 45 funcao sig_private.enqueue_notification(p_doc uuid, p_profile uuid, p_
CREATE OR REPLACE FUNCTION sig_private.enqueue_notification(p_doc uuid, p_profile uuid, p_kind text, p_slot text DEFAULT ''::text, p_not_before timestamp with time zone DEFAULT now())
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_has_phone boolean;
begin
  select nullif(btrim(phone), '') is not null into v_has_phone from public.profiles where id = p_profile;
  insert into public.sig_notifications(document_id, profile_id, kind, slot, status, skip_reason, not_before)
  values (p_doc, p_profile, p_kind, p_slot,
    case when coalesce(v_has_phone, false) then 'queued' else 'skipped' end,
    case when coalesce(v_has_phone, false) then null else 'no_phone' end, p_not_before)
  on conflict (document_id, profile_id, kind, slot) do nothing;
  if not found then return 'exists'; end if;
  return case when coalesce(v_has_phone, false) then 'queued' else 'skipped' end;
end $function$;
--@@ 45 funcao sig_private.forbid_change()
CREATE OR REPLACE FUNCTION sig_private.forbid_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  raise exception 'SIG_APPEND_ONLY' using errcode = '23000';
end $function$;
--@@ 45 funcao sig_private.get_document(p_id uuid, p_lock boolean)
CREATE OR REPLACE FUNCTION sig_private.get_document(p_id uuid, p_lock boolean DEFAULT true)
 RETURNS sig_documents
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.sig_documents%rowtype;
begin
  if p_lock then select * into d from public.sig_documents where id = p_id for update;
  else select * into d from public.sig_documents where id = p_id; end if;
  if not found then raise exception 'SIG_NOT_FOUND'; end if;
  return d;
end $function$;
--@@ 45 funcao sig_private.guard_document()
CREATE OR REPLACE FUNCTION sig_private.guard_document()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'DELETE' then
    if old.status <> 'draft' then raise exception 'SIG_DOCUMENT_IMMUTABLE' using errcode = '23000'; end if;
    return old;
  end if;
  new.updated_at := now();
  if old.status = 'draft' then return new; end if;
  if (new.title, new.description, new.file_name, new.storage_path, new.size_bytes, new.page_count,
      new.content_sha256, new.version, new.replaces_id, new.audience_mode, new.created_at)
     is distinct from
     (old.title, old.description, old.file_name, old.storage_path, old.size_bytes, old.page_count,
      old.content_sha256, old.version, old.replaces_id, old.audience_mode, old.created_at) then
    raise exception 'SIG_DOCUMENT_IMMUTABLE' using errcode = '23000';
  end if;
  if old.status = 'archived' and (new.status <> 'archived' or new.due_at is distinct from old.due_at
     or new.applies_to_new_members is distinct from old.applies_to_new_members) then
    raise exception 'SIG_DOCUMENT_ARCHIVED' using errcode = '23000';
  end if;
  if old.status = 'published' and new.status = 'draft' then
    raise exception 'SIG_BAD_TRANSITION' using errcode = '23000';
  end if;
  return new;
end $function$;
--@@ 45 funcao sig_private.is_active_member(p_profile uuid)
CREATE OR REPLACE FUNCTION sig_private.is_active_member(p_profile uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (select 1 from public.profiles p
    where p.id = p_profile and p.role::text in ('socio', 'admin') and coalesce(p.is_active, true)) $function$;
--@@ 45 funcao sig_private.on_member_active()
CREATE OR REPLACE FUNCTION sig_private.on_member_active()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d record;
begin
  begin
    if new.role::text in ('socio', 'admin') and coalesce(new.is_active, true)
       and (tg_op = 'INSERT' or not (old.role::text in ('socio', 'admin') and coalesce(old.is_active, true))) then
      for d in select id from public.sig_documents where status = 'published' and audience_mode = 'all' and applies_to_new_members loop
        insert into public.sig_recipients(document_id, profile_id, source) values (d.id, new.id, 'new_member')
        on conflict do nothing;
        if found then perform sig_private.enqueue_notification(d.id, new.id, 'new_member'); end if;
      end loop;
    end if;
  exception when others then
    raise warning 'sig_private.on_member_active: %', sqlerrm;
  end;
  return new;
end $function$;
--@@ 45 funcao sig_private.request_header(p_name text)
CREATE OR REPLACE FUNCTION sig_private.request_header(p_name text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v_headers text := current_setting('request.headers', true);
begin
  if v_headers is null or v_headers = '' then return null; end if;
  return nullif(btrim(v_headers::json ->> lower(p_name)), '');
exception when others then
  return null;
end $function$;
--@@ 45 funcao sig_private.request_ip()
CREATE OR REPLACE FUNCTION sig_private.request_ip()
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select left(coalesce(
    sig_private.request_header('cf-connecting-ip'),
    sig_private.request_header('x-real-ip'),
    nullif(btrim(split_part(coalesce(sig_private.request_header('x-forwarded-for'), ''), ',', 1)), '')), 64) $function$;
--@@ 45 funcao sig_private.require_admin()
CREATE OR REPLACE FUNCTION sig_private.require_admin()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not public.is_admin() then
    raise exception 'SIG_FORBIDDEN' using errcode = '42501';
  end if;
  return auth.uid();
end $function$;
--@@ 45 funcao sig_private.require_member()
CREATE OR REPLACE FUNCTION sig_private.require_member()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not sig_private.is_active_member(auth.uid()) then
    raise exception 'SIG_FORBIDDEN' using errcode = '42501';
  end if;
  return auth.uid();
end $function$;
