--@@ 60 view fin_private.charge_payments_effective
create or replace view fin_private.charge_payments_effective as  SELECT id,
    charge_id,
    kind,
    amount_cents,
    paid_on,
    fine_cents,
    interest_cents,
    principal_cents,
    excess_cents,
    method,
    account_id,
    submission_id,
    credit_id,
    reverses_payment_id,
    note,
    actor_id,
    request_id,
    created_at
   FROM fin_charge_payments p
  WHERE kind = 'payment'::text AND NOT (EXISTS ( SELECT 1
           FROM fin_charge_payments r
          WHERE r.reverses_payment_id = p.id));
--@@ 60 view public.fin_entries_v
create or replace view public.fin_entries_v with (security_invoker=true) as  SELECT e.id,
    e.kind,
    e.status,
    e.description,
    e.supplier,
    e.category_id,
    e.amount_cents,
    e.competence_date,
    e.due_date,
    e.account_id,
    e.counter_account_id,
    e.recurrence_id,
    e.notes,
    e.adjustment_cents,
    e.settled_on,
    e.request_id,
    e.version,
    e.created_at,
    e.created_by,
    e.updated_at,
    e.updated_by,
    e.canceled_at,
    e.canceled_by,
    e.cancel_reason,
    COALESCE(p.paid_cents, 0::numeric)::bigint AS paid_cents,
    GREATEST(e.amount_cents::numeric - COALESCE(p.paid_cents, 0::numeric), 0::numeric)::bigint AS remaining_cents,
        CASE
            WHEN e.status = 'canceled'::text THEN 'canceled'::text
            WHEN e.status = 'paid'::text THEN 'paid'::text
            WHEN e.due_date < (now() AT TIME ZONE 'America/Fortaleza'::text)::date THEN 'overdue'::text
            ELSE e.status
        END AS display_status
   FROM fin_entries e
     LEFT JOIN LATERAL ( SELECT sum(
                CASE
                    WHEN x.kind = 'payment'::text THEN x.amount_cents
                    ELSE - x.amount_cents
                END) AS paid_cents
           FROM fin_entry_payments x
          WHERE x.entry_id = e.id) p ON true;
--@@ 60 view public.members
create or replace view public.members with (security_invoker=true) as  SELECT id,
    name,
    email,
    role,
    balance,
    avatar_url,
    category,
    is_professor,
    is_active,
    created_at,
    age,
    phone,
    legacy_wins,
    legacy_losses,
    legacy_sets_won,
    legacy_games_won,
    legacy_points,
    legacy_sets_lost,
    legacy_games_lost,
    legacy_tiebreaks_won,
    legacy_tiebreaks_lost,
    legacy_matches_played,
    legacy_matches_with_tiebreak,
    updated_at
   FROM profiles
  WHERE role::text = ANY (ARRAY['socio'::text, 'admin'::text]);
--@@ 60 view public.sig_documents_overview
create or replace view public.sig_documents_overview with (security_invoker=true) as  SELECT id,
    title,
    version,
    status,
    audience_mode,
    applies_to_new_members,
    page_count,
    due_at,
    created_at,
    published_at,
    ( SELECT count(*) AS count
           FROM sig_recipients r
          WHERE r.document_id = d.id) AS recipients,
    ( SELECT count(*) AS count
           FROM sig_recipients r
          WHERE r.document_id = d.id AND r.signed_at IS NOT NULL) AS signed,
    ( SELECT count(*) AS count
           FROM sig_notifications n
          WHERE n.document_id = d.id AND (n.status = ANY (ARRAY['queued'::text, 'sending'::text]))) AS notifications_pending,
    ( SELECT count(*) AS count
           FROM sig_notifications n
          WHERE n.document_id = d.id AND n.status = 'failed'::text) AS notifications_failed,
    ( SELECT count(*) AS count
           FROM sig_notifications n
          WHERE n.document_id = d.id AND n.status = 'skipped'::text AND n.skip_reason = 'no_phone'::text) AS no_phone
   FROM sig_documents d;
--@@ 60 view public.vw_familia_modelos_expandidos
create or replace view public.vw_familia_modelos_expandidos as  SELECT t.familia_id,
    t.modelo_canonico,
        CASE
            WHEN t.modelo_canonico = '__ALL_MODELOS__'::text THEN a.modelos_agregados
            ELSE t.modelo_canonico
        END AS modelo_canonico_expandidos
   FROM tabela_familia_iphone_map t
     LEFT JOIN ( SELECT tabela_familia_iphone_map.familia_id,
            string_agg(DISTINCT tabela_familia_iphone_map.modelo_canonico, ', '::text ORDER BY tabela_familia_iphone_map.modelo_canonico) AS modelos_agregados
           FROM tabela_familia_iphone_map
          WHERE tabela_familia_iphone_map.modelo_canonico IS NOT NULL AND tabela_familia_iphone_map.modelo_canonico <> '__ALL_MODELOS__'::text
          GROUP BY tabela_familia_iphone_map.familia_id) a USING (familia_id);
