--@@ 82 politica public.access_requests."Admins can manage access requests"
create policy "Admins can manage access requests" on public.access_requests as permissive for all to authenticated using ((EXISTS ( SELECT 1
   FROM profiles p
  WHERE ((p.id = auth.uid()) AND (p.role = 'admin'::user_role))))) with check ((EXISTS ( SELECT 1
   FROM profiles p
  WHERE ((p.id = auth.uid()) AND (p.role = 'admin'::user_role)))));
--@@ 82 politica public.access_requests."Admins can read access requests"
create policy "Admins can read access requests" on public.access_requests as permissive for select to authenticated using ((EXISTS ( SELECT 1
   FROM profiles p
  WHERE ((p.id = auth.uid()) AND (p.role = 'admin'::user_role)))));
--@@ 82 politica public.access_requests."Anon can resubmit access requests"
create policy "Anon can resubmit access requests" on public.access_requests as permissive for update to anon, authenticated using ((status = ANY (ARRAY['pending'::text, 'rejected'::text]))) with check (((status = 'pending'::text) AND (decided_by IS NULL) AND (decided_at IS NULL)));
--@@ 82 politica public.access_requests."Anon can submit access requests"
create policy "Anon can submit access requests" on public.access_requests as permissive for insert to anon, authenticated with check ((status = 'pending'::text));
